window.MT_DATA = window.MT_DATA || {};
window.MT_DATA['zh'] = [{"id":1,"name":"Niveau 1","freeLessonsPerModule":{"1":10,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours en Chine, en route et à la maison.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Pékin","phrases":[{"fr":"J'arrive de Paris.","tgt":"我从巴黎来。","ro":"Wǒ cóng Bālí lái.","lit":"je · depuis · Paris · venir"},{"fr":"Nous allons à Pékin.","tgt":"我们去北京。","ro":"Wǒmen qù Běijīng.","lit":"nous · aller · Pékin"},{"fr":"Ma femme vient avec moi.","tgt":"我太太跟我一起来。","ro":"Wǒ tàitai gēn wǒ yìqǐ lái.","lit":"je · épouse · avec · moi · ensemble · venir"},{"fr":"Il habite à Pékin.","tgt":"他住在北京。","ro":"Tā zhù zài Běijīng.","lit":"il · habiter · à · Pékin"},{"fr":"Moi, j'habite à Lyon.","tgt":"我住在里昂。","ro":"Wǒ zhù zài Lǐ'áng.","lit":"je · habiter · à · Lyon"},{"fr":"Vous allez aussi à l'hôtel ?","tgt":"你们也去酒店吗？","ro":"Nǐmen yě qù jiǔdiàn ma?","lit":"vous · aussi · aller · hôtel · [question] ?"},{"fr":"Je prends un taxi.","tgt":"我坐出租车。","ro":"Wǒ zuò chūzūchē.","lit":"je · s'asseoir · taxi"},{"fr":"Elle prend le métro.","tgt":"她坐地铁。","ro":"Tā zuò dìtiě.","lit":"elle · s'asseoir · métro"},{"fr":"Mon ami nous attend.","tgt":"我朋友等我们。","ro":"Wǒ péngyou děng wǒmen.","lit":"je · ami · attendre · nous"},{"fr":"Pékin, nous voilà !","tgt":"北京，我们来了！","ro":"Běijīng, wǒmen lái le!","lit":"Pékin · nous · venir · [accompli] !"}],"tip":{"title":"Pas de conjugaison : le verbe ne change jamais","example":"Il habite à Pékin. — 他<b>住</b>在北京。","body":"Bonne nouvelle pour commencer : en chinois, les verbes ne se conjuguent pas. En français, on dit j'habite, il habite, nous habitons ; en chinois, on dit toujours « zhù », habiter, quelle que soit la personne. Écoutez : « Wǒ zhù zài Lǐ'áng », j'habite à Lyon, et « Tā zhù zài Běijīng », il habite à Pékin. Mot à mot, cela donne : il, habiter, à, Pékin. Seul le sujet change, le verbe reste parfaitement identique. C'est pareil avec « qù », aller : « wǒ qù », je vais, « wǒmen qù », nous allons. Et le verbe ne change pas non plus avec le temps : hier, aujourd'hui ou demain, c'est toujours « qù ». Pour retenir, imaginez le verbe chinois comme une brique qui ne se déforme jamais : vous posez simplement le sujet devant.","exampleRo":"Tā zhù zài Běijīng.","lit":"il · habiter · à · Pékin","say":{"zhù":"住","Wǒ zhù zài Lǐ'áng":"我住在里昂","Tā zhù zài Běijīng":"他住在北京","qù":"去","wǒ qù":"我去","wǒmen qù":"我们去"}}},{"title":"Un thé dans un hutong","phrases":[{"fr":"Je voudrais une tasse de thé.","tgt":"我要一杯茶。","ro":"Wǒ yào yì bēi chá.","lit":"je · vouloir · un · tasse · thé"},{"fr":"Du thé vert, s'il vous plaît.","tgt":"请给我绿茶。","ro":"Qǐng gěi wǒ lǜchá.","lit":"s'il vous plaît · donner · moi · thé vert"},{"fr":"Ce thé sent très bon.","tgt":"这个茶很香。","ro":"Zhège chá hěn xiāng.","lit":"ce · [classificateur] · thé · très · parfumé"},{"fr":"Vous vendez du thé ?","tgt":"你们卖茶吗？","ro":"Nǐmen mài chá ma?","lit":"vous · vendre · thé · [question] ?"},{"fr":"J'ai envie d'acheter du thé.","tgt":"我想买茶。","ro":"Wǒ xiǎng mǎi chá.","lit":"je · vouloir · acheter · thé"},{"fr":"Combien coûte cette boîte ?","tgt":"这盒多少钱？","ro":"Zhè hé duōshao qián?","lit":"ce · boîte · combien · argent ?"},{"fr":"Trente kuai.","tgt":"三十块。","ro":"Sānshí kuài.","lit":"trois · dix · kuai"},{"fr":"C'est un peu cher.","tgt":"有点儿贵。","ro":"Yǒudiǎnr guì.","lit":"un peu · cher"},{"fr":"Ce hutong est très calme.","tgt":"这条胡同很安静。","ro":"Zhè tiáo hútòng hěn ānjìng.","lit":"ce · [classificateur] · hutong · très · calme"},{"fr":"Le patron est très aimable.","tgt":"老板很客气。","ro":"Lǎobǎn hěn kèqi.","lit":"patron · très · aimable"}],"tip":{"title":"Les quatre tons du mandarin","example":"Vous vendez du thé ? — 你们<b>卖</b>茶吗？","body":"En mandarin, chaque syllabe a une mélodie, et cette mélodie change le sens du mot. Il existe quatre tons. Le premier est haut et plat, comme une note tenue : « chā ». Le deuxième monte, comme quand on s'étonne en français : « chá », le thé. Le troisième descend puis remonte un peu, très bas dans la voix : « mǎi », acheter. Le quatrième tombe d'un coup, sec, comme un ordre : « mài », vendre. Écoutez la différence : « Wǒ xiǎng mǎi chá », j'ai envie d'acheter du thé, et « Nǐmen mài chá ma ? », vous vendez du thé ? Une erreur de ton, et l'acheteur devient vendeur ! Il existe aussi un ton neutre, court et léger, comme dans « ma » à la fin des questions. Astuce : exagérez les tons au début, en bougeant même la main, haut, montant, creux, descendant ; vous les adoucirez avec le temps.","exampleRo":"Nǐmen mài chá ma?","lit":"vous · vendre · thé · [question] ?","say":{"chá":"茶","mǎi":"买","mài":"卖","Wǒ xiǎng mǎi chá":"我想买茶","Nǐmen mài chá ma ?":"你们卖茶吗？","ma":"吗","chā":"插"}}},{"title":"La Cité interdite","phrases":[{"fr":"Voici la Cité interdite.","tgt":"这是故宫。","ro":"Zhè shì Gùgōng.","lit":"ceci · être · Cité interdite"},{"fr":"Je suis touriste.","tgt":"我是游客。","ro":"Wǒ shì yóukè.","lit":"je · être · touriste"},{"fr":"Lui, c'est notre guide.","tgt":"他是我们的导游。","ro":"Tā shì wǒmen de dǎoyóu.","lit":"il · être · nous · [possessif] · guide"},{"fr":"Elle est étudiante.","tgt":"她是学生。","ro":"Tā shì xuésheng.","lit":"elle · être · étudiant"},{"fr":"Voici nos billets.","tgt":"这是我们的票。","ro":"Zhè shì wǒmen de piào.","lit":"ceci · être · nous · [possessif] · billet"},{"fr":"Ici, c'est la porte sud.","tgt":"这是南门。","ro":"Zhè shì nánmén.","lit":"ceci · être · sud · porte"},{"fr":"Le palais est immense.","tgt":"故宫很大。","ro":"Gùgōng hěn dà.","lit":"Cité interdite · très · grand"},{"fr":"Il y a énormément de monde.","tgt":"人很多。","ro":"Rén hěn duō.","lit":"personne · très · nombreux"},{"fr":"Vous êtes de Paris ?","tgt":"您是巴黎人吗？","ro":"Nín shì Bālírén ma?","lit":"vous (poli) · être · Paris-personne · [question] ?"},{"fr":"Oui, je suis parisien.","tgt":"对，我是巴黎人。","ro":"Duì, wǒ shì Bālírén.","lit":"exact · je · être · Paris-personne"}],"tip":{"title":"« Shì » : être, entre deux noms","example":"Je suis touriste. — 我<b>是</b>游客。","body":"Le verbe « shì » veut dire être, mais attention, il sert surtout à relier deux noms : je suis touriste, elle est étudiante, ceci est la Cité interdite. Écoutez : « Wǒ shì yóukè ». Mot à mot : je, être, touriste. Pas d'article, pas de un ou de une : le chinois va droit au but. Pour présenter un lieu, on dit « Zhè shì Gùgōng », ceci est la Cité interdite. Et pour dire d'où l'on vient, on colle le mot « rén », personne, après la ville : « Wǒ shì Bālírén », je suis parisien. En revanche, devant un adjectif comme grand ou beau, on n'utilise pas « shì » : on dit « Gùgōng hěn dà », le palais est grand, sans le verbe être. Astuce : « shì » est un signe égal entre deux choses, comme dans une petite équation.","exampleRo":"Wǒ shì yóukè.","lit":"je · être · touriste","say":{"Shì":"是","shì":"是","Wǒ shì yóukè":"我是游客","Zhè shì Gùgōng":"这是故宫","rén":"人","Wǒ shì Bālírén":"我是巴黎人","Gùgōng hěn dà":"故宫很大"}}},{"title":"Pause au parc Jingshan","phrases":[{"fr":"Tu es fatigué, toi ?","tgt":"你累吗？","ro":"Nǐ lèi ma?","lit":"toi · fatigué · [question] ?"},{"fr":"Oui, un petit peu.","tgt":"有一点儿。","ro":"Yǒu yìdiǎnr.","lit":"avoir · un peu"},{"fr":"C'est bien le parc Jingshan ?","tgt":"这是景山公园吗？","ro":"Zhè shì Jǐngshān Gōngyuán ma?","lit":"ceci · être · Jingshan · parc · [question] ?"},{"fr":"Il y a des toilettes par ici ?","tgt":"这儿有厕所吗？","ro":"Zhèr yǒu cèsuǒ ma?","lit":"ici · avoir · toilettes · [question] ?"},{"fr":"Vous avez un plan du parc ?","tgt":"您有公园地图吗？","ro":"Nín yǒu gōngyuán dìtú ma?","lit":"vous (poli) · avoir · parc · carte · [question] ?"},{"fr":"Le paysage est joli ?","tgt":"风景好看吗？","ro":"Fēngjǐng hǎokàn ma?","lit":"paysage · beau à voir · [question] ?"},{"fr":"Magnifique !","tgt":"非常美！","ro":"Fēicháng měi!","lit":"extrêmement · beau !"},{"fr":"Tu as faim ?","tgt":"你饿吗？","ro":"Nǐ è ma?","lit":"toi · affamé · [question] ?"},{"fr":"Tu veux de l'eau ?","tgt":"你要水吗？","ro":"Nǐ yào shuǐ ma?","lit":"toi · vouloir · eau · [question] ?"},{"fr":"Oui, merci.","tgt":"要，谢谢。","ro":"Yào, xièxie.","lit":"vouloir · merci"}],"tip":{"title":"« Ma » : transformer une phrase en question","example":"Tu as faim ? — 你饿<b>吗</b>？","body":"Poser une question en chinois est d'une simplicité étonnante. Vous prenez une phrase normale et vous ajoutez la petite syllabe « ma » à la fin, prononcée courte et légère, sans ton. « Nǐ è », tu as faim. « Nǐ è ma ? », tu as faim ? Mot à mot : toi, affamé, question. Rien ne bouge dans la phrase, pas d'inversion, pas de est-ce que. Autre exemple : « Nǐ yào shuǐ », tu veux de l'eau, devient « Nǐ yào shuǐ ma ? ». Et pour répondre oui, le chinois n'aime pas trop le mot oui : on répète simplement le verbe. À « Nǐ yào shuǐ ma ? », on répond « Yào », je veux. Astuce : pensez au « ma » comme à un point d'interrogation que l'on prononce à voix haute.","exampleRo":"Nǐ è ma?","lit":"toi · affamé · [question] ?","say":{"Ma":"吗","ma":"吗","Nǐ è":"你饿","Nǐ è ma ?":"你饿吗？","Nǐ yào shuǐ":"你要水","Nǐ yào shuǐ ma ?":"你要水吗？","Yào":"要"}}},{"title":"Un dîner de canard laqué","phrases":[{"fr":"Je ne mange pas épicé.","tgt":"我不吃辣。","ro":"Wǒ bù chī là.","lit":"je · ne pas · manger · piquant"},{"fr":"Ce canard n'est pas cher.","tgt":"这只烤鸭不贵。","ro":"Zhè zhī kǎoyā bú guì.","lit":"ce · [classificateur] · canard laqué · ne pas · cher"},{"fr":"Ce plat n'est pas à nous.","tgt":"这个菜不是我们的。","ro":"Zhège cài bú shì wǒmen de.","lit":"ce · [classificateur] · plat · ne pas · être · nous · [possessif]"},{"fr":"Merci, je ne bois pas d'alcool.","tgt":"谢谢，我不喝酒。","ro":"Xièxie, wǒ bù hē jiǔ.","lit":"merci · je · ne pas · boire · alcool"},{"fr":"Je ne veux pas de riz.","tgt":"我不要米饭。","ro":"Wǒ bú yào mǐfàn.","lit":"je · ne pas · vouloir · riz"},{"fr":"La sauce n'est pas trop sucrée.","tgt":"酱不太甜。","ro":"Jiàng bú tài tián.","lit":"sauce · ne pas · trop · sucré"},{"fr":"La peau est croustillante.","tgt":"皮很脆。","ro":"Pí hěn cuì.","lit":"peau · très · croustillant"},{"fr":"Le canard laqué est délicieux.","tgt":"烤鸭很好吃。","ro":"Kǎoyā hěn hǎochī.","lit":"canard laqué · très · bon à manger"},{"fr":"Tu n'as pas faim ?","tgt":"你不饿吗？","ro":"Nǐ bú è ma?","lit":"toi · ne pas · affamé · [question] ?"},{"fr":"Je ne suis pas pressé.","tgt":"我不急。","ro":"Wǒ bù jí.","lit":"je · ne pas · pressé"}],"tip":{"title":"« Bù » : la négation","example":"Je ne veux pas de riz. — 我<b>不</b>要米饭。","body":"Pour dire non en chinois, il suffit d'un petit mot : « bù », placé juste devant le verbe ou l'adjectif. En français, la négation entoure le verbe avec ne et pas ; en chinois, un seul mot, toujours devant. « Wǒ chī là », je mange épicé, devient « Wǒ bù chī là », je ne mange pas épicé. Mot à mot : je, ne pas, manger, piquant. Attention à une petite règle de prononciation : devant un quatrième ton, le mot qui tombe, « bù » devient montant et se dit « bú ». On dit donc « bú yào », je ne veux pas, « bú shì », ce n'est pas, « bú guì », pas cher. Mais « bù chī », « bù hē », « bù jí » gardent le ton descendant. Astuce : deux tons qui tombent d'affilée, c'est trop lourd, alors le premier remonte pour faire respirer la phrase.","exampleRo":"Wǒ bú yào mǐfàn.","lit":"je · ne pas · vouloir · riz","say":{"Bù":"不","bù":"不","Wǒ chī là":"我吃辣","Wǒ bù chī là":"我不吃辣","bú yào":"不要","bú shì":"不是","bú guì":"不贵","bù chī":"不吃","bù hē":"不喝","bù jí":"不急"}}},{"title":"Louer un appartement","phrases":[{"fr":"Nous cherchons un appartement.","tgt":"我们找房子。","ro":"Wǒmen zhǎo fángzi.","lit":"nous · chercher · logement"},{"fr":"Elle, c'est la propriétaire.","tgt":"她是房东。","ro":"Tā shì fángdōng.","lit":"elle · être · propriétaire"},{"fr":"Ils habitent à l'étage du dessus.","tgt":"他们住在楼上。","ro":"Tāmen zhù zài lóushàng.","lit":"ils · habiter · à · étage-dessus"},{"fr":"Vous êtes combien ?","tgt":"你们几个人？","ro":"Nǐmen jǐ ge rén?","lit":"vous · combien · [classificateur] · personne ?"},{"fr":"Nous sommes deux.","tgt":"我们两个人。","ro":"Wǒmen liǎng ge rén.","lit":"nous · deux · [classificateur] · personne"},{"fr":"Ça te plaît, cet appartement ?","tgt":"你喜欢这套房子吗？","ro":"Nǐ xǐhuan zhè tào fángzi ma?","lit":"toi · aimer · ce · [classificateur] · logement · [question] ?"},{"fr":"Oui, il me plaît beaucoup.","tgt":"我很喜欢。","ro":"Wǒ hěn xǐhuan.","lit":"je · très · aimer"},{"fr":"Elle n'aime pas la cuisine.","tgt":"她不喜欢厨房。","ro":"Tā bù xǐhuan chúfáng.","lit":"elle · ne pas · aimer · cuisine"},{"fr":"Nous prenons celui-ci.","tgt":"我们租这套。","ro":"Wǒmen zū zhè tào.","lit":"nous · louer · ce · [classificateur]"},{"fr":"Signez ici, s'il vous plaît.","tgt":"请您在这儿签字。","ro":"Qǐng nín zài zhèr qiānzì.","lit":"s'il vous plaît · vous (poli) · à · ici · signer"}],"tip":{"title":"Les pronoms : « wǒ, nǐ, tā », et le pluriel en « men »","example":"Ils habitent à l'étage du dessus. — <b>他们</b>住在楼上。","body":"Les pronoms chinois sont très peu nombreux et très réguliers. « Wǒ » veut dire je ou moi, « nǐ » veut dire tu ou toi, et « tā » veut dire il ou elle : à l'oral, il n'y a aucune différence entre lui et elle, c'est le contexte qui décide. Pour le pluriel, on ajoute simplement « men », sans ton : « wǒmen », nous, « nǐmen », vous, « tāmen », ils ou elles. Écoutez : « Tāmen zhù zài lóushàng ». Mot à mot : ils, habiter, à, étage du dessus. Et comme le verbe ne change pas, « wǒ zhù », « tāmen zhù » restent identiques. Pour vouvoyer une seule personne avec respect, une propriétaire par exemple, on dit « nín » au lieu de « nǐ ». Astuce : retenez « men » comme une petite étiquette qui veut dire plusieurs.","exampleRo":"Tāmen zhù zài lóushàng.","lit":"ils · habiter · à · étage-dessus","say":{"Wǒ":"我","nǐ":"你","tā":"他","wǒmen":"我们","nǐmen":"你们","tāmen":"他们","Tāmen zhù zài lóushàng":"他们住在楼上","wǒ zhù":"我住","tāmen zhù":"他们住","nín":"您","wǒ, nǐ, tā":"我、你、他","men":"们"}}},{"title":"S'installer dans l'appartement","phrases":[{"fr":"Voici ma chambre.","tgt":"这是我的房间。","ro":"Zhè shì wǒ de fángjiān.","lit":"ceci · être · je · [possessif] · chambre"},{"fr":"C'est ta valise ?","tgt":"这是你的箱子吗？","ro":"Zhè shì nǐ de xiāngzi ma?","lit":"ceci · être · toi · [possessif] · valise · [question] ?"},{"fr":"Non, c'est celle de ma femme.","tgt":"不是，是我太太的。","ro":"Bú shì, shì wǒ tàitai de.","lit":"ne pas · être · être · je · épouse · [possessif]"},{"fr":"Notre salon est petit.","tgt":"我们的客厅很小。","ro":"Wǒmen de kètīng hěn xiǎo.","lit":"nous · [possessif] · salon · très · petit"},{"fr":"Mon lit est confortable.","tgt":"我的床很舒服。","ro":"Wǒ de chuáng hěn shūfu.","lit":"je · [possessif] · lit · très · confortable"},{"fr":"Et tes clés ?","tgt":"你的钥匙呢？","ro":"Nǐ de yàoshi ne?","lit":"toi · [possessif] · clé · [et alors] ?"},{"fr":"Quel est le code de la porte ?","tgt":"门的密码是多少？","ro":"Mén de mìmǎ shì duōshao?","lit":"porte · [possessif] · code · être · combien ?"},{"fr":"La fenêtre de la cuisine est cassée.","tgt":"厨房的窗户坏了。","ro":"Chúfáng de chuānghu huài le.","lit":"cuisine · [possessif] · fenêtre · abîmé · [accompli]"},{"fr":"Mes amis viennent ce soir.","tgt":"我的朋友今天晚上来。","ro":"Wǒ de péngyou jīntiān wǎnshang lái.","lit":"je · [possessif] · ami · aujourd'hui · soir · venir"},{"fr":"Ma mère est contente.","tgt":"我妈妈很高兴。","ro":"Wǒ māma hěn gāoxìng.","lit":"je · maman · très · content"}],"tip":{"title":"« De » : le possessif, « wǒ de »","example":"Voici ma chambre. — 这是我<b>的</b>房间。","body":"En chinois, il n'existe pas de mots comme mon, ton ou notre. On prend le pronom et on ajoute la petite syllabe « de », légère et sans ton : « wǒ de », à moi, donc mon ou ma ; « nǐ de », ton ou ta ; « wǒmen de », notre. Écoutez : « Zhè shì wǒ de fángjiān ». Mot à mot : ceci, être, moi, possessif, chambre. Le propriétaire vient toujours en premier, puis l'objet, à l'inverse du français la chambre de Paul. Cela marche aussi avec les choses : « chúfáng de chuānghu », la fenêtre de la cuisine. Pour la famille et les proches, on supprime souvent « de » : on dit « wǒ māma », ma mère, ou « wǒ tàitai », ma femme. Astuce : lisez « de » comme une petite apostrophe, à la façon de l'expression la chambre à moi.","exampleRo":"Zhè shì wǒ de fángjiān.","lit":"ceci · être · je · [possessif] · chambre","say":{"De":"的","de":"的","wǒ de":"我的","nǐ de":"你的","wǒmen de":"我们的","Zhè shì wǒ de fángjiān":"这是我的房间","chúfáng de chuānghu":"厨房的窗户","wǒ māma":"我妈妈","wǒ tàitai":"我太太"}}},{"title":"La météo du jour","phrases":[{"fr":"Aujourd'hui, il fait très chaud.","tgt":"今天很热。","ro":"Jīntiān hěn rè.","lit":"aujourd'hui · très · chaud"},{"fr":"Le ciel est tout bleu.","tgt":"天很蓝。","ro":"Tiān hěn lán.","lit":"ciel · très · bleu"},{"fr":"Le vent souffle fort.","tgt":"风很大。","ro":"Fēng hěn dà.","lit":"vent · très · grand"},{"fr":"L'air est sec.","tgt":"空气很干。","ro":"Kōngqì hěn gān.","lit":"air · très · sec"},{"fr":"Demain, il fera froid.","tgt":"明天很冷。","ro":"Míngtiān hěn lěng.","lit":"demain · très · froid"},{"fr":"Tiens, il pleut.","tgt":"下雨了。","ro":"Xià yǔ le.","lit":"tomber · pluie · [accompli]"},{"fr":"Il ne fait pas froid ce matin.","tgt":"今天早上不冷。","ro":"Jīntiān zǎoshang bù lěng.","lit":"aujourd'hui · matin · ne pas · froid"},{"fr":"L'été à Pékin est très chaud.","tgt":"北京的夏天很热。","ro":"Běijīng de xiàtiān hěn rè.","lit":"Pékin · [possessif] · été · très · chaud"},{"fr":"L'automne est très agréable.","tgt":"秋天很舒服。","ro":"Qiūtiān hěn shūfu.","lit":"automne · très · confortable"},{"fr":"Il fait beau dehors ?","tgt":"外面天气好吗？","ro":"Wàimiàn tiānqì hǎo ma?","lit":"dehors · temps · bon · [question] ?"}],"tip":{"title":"« Hěn » + adjectif : pas besoin du verbe être","example":"L'air est sec. — 空气<b>很</b>干。","body":"En français, on dit l'air est sec, avec le verbe être. En chinois, les adjectifs fonctionnent un peu comme des verbes : ils n'ont pas besoin de être. On ne dit donc pas « shì » devant un adjectif. À la place, on met presque toujours le petit mot « hěn », qui veut dire très, mais qui ici sert surtout de liaison. Écoutez : « Kōngqì hěn gān ». Mot à mot : air, très, sec, mais le sens est simplement l'air est sec. De même, « Jīntiān hěn rè », aujourd'hui il fait chaud, et « Fēng hěn dà », le vent est fort. Sans « hěn », la phrase semble incomplète, comme si l'on comparait avec autre chose. Pour la négation, en revanche, on enlève « hěn » et on met « bù » : « Bù lěng », il ne fait pas froid. Astuce : retenez la formule sujet, « hěn », adjectif, comme un petit trio qui va toujours ensemble.","exampleRo":"Kōngqì hěn gān.","lit":"air · très · sec","say":{"Hěn":"很","shì":"是","hěn":"很","Kōngqì hěn gān":"空气很干","Jīntiān hěn rè":"今天很热","Fēng hěn dà":"风很大","bù":"不","Bù lěng":"不冷"}}},{"title":"Au marché","phrases":[{"fr":"C'est combien, ça ?","tgt":"这个多少钱？","ro":"Zhège duōshao qián?","lit":"ce · [classificateur] · combien · argent ?"},{"fr":"Et celui-là ?","tgt":"那个呢？","ro":"Nàge ne?","lit":"ce-là · [classificateur] · [et alors] ?"},{"fr":"Ces pommes sont bien fraîches.","tgt":"这些苹果很新鲜。","ro":"Zhèxiē píngguǒ hěn xīnxiān.","lit":"ces · pomme · très · frais"},{"fr":"Ces fraises-là sont belles.","tgt":"那些草莓很好看。","ro":"Nàxiē cǎoméi hěn hǎokàn.","lit":"ces-là · fraise · très · beau à voir"},{"fr":"Je vais prendre celui-ci.","tgt":"我要这个。","ro":"Wǒ yào zhège.","lit":"je · vouloir · ce · [classificateur]"},{"fr":"Non, pas celui-là.","tgt":"不是那个。","ro":"Bú shì nàge.","lit":"ne pas · être · ce-là · [classificateur]"},{"fr":"Qu'est-ce que c'est, ce fruit ?","tgt":"这是什么水果？","ro":"Zhè shì shénme shuǐguǒ?","lit":"ceci · être · quel · fruit ?"},{"fr":"Ce sont des litchis.","tgt":"这是荔枝。","ro":"Zhè shì lìzhī.","lit":"ceci · être · litchi"},{"fr":"Ce marché est très animé.","tgt":"这个市场很热闹。","ro":"Zhège shìchǎng hěn rènao.","lit":"ce · [classificateur] · marché · très · animé"},{"fr":"Ce marchand-là est sympathique.","tgt":"那个老板很好。","ro":"Nàge lǎobǎn hěn hǎo.","lit":"ce-là · [classificateur] · patron · très · bien"}],"tip":{"title":"« Zhè » et « nà » : ceci et cela","example":"Je vais prendre celui-ci. — 我要<b>这个</b>。","body":"Au marché, deux petits mots vous sauveront : « zhè », ceci, pour ce qui est près de vous, et « nà », cela, pour ce qui est plus loin. Ils se prononcent tous les deux avec un ton qui tombe, comme si l'on pointait du doigt. Pour désigner un objet, on ajoute souvent « ge » : « zhège », celui-ci, « nàge », celui-là. Écoutez : « Wǒ yào zhège ». Mot à mot : je, vouloir, ce, classificateur, c'est-à-dire je prends celui-ci. Au pluriel, on dit « zhèxiē », ces choses-ci, et « nàxiē », ces choses-là : « Zhèxiē píngguǒ hěn xīnxiān », ces pommes sont fraîches. Et pour une question rapide, « Nàge ne ? », et celui-là ? Astuce : « zh » comme près de moi, « n » comme là-bas, plus loin ; avec ces deux mots et un doigt tendu, vous pouvez déjà faire vos courses.","exampleRo":"Wǒ yào zhège.","lit":"je · vouloir · ce · [classificateur]","say":{"Zhè":"这","nà":"那","zhè":"这","ge":"个","zhège":"这个","nàge":"那个","Wǒ yào zhège":"我要这个","zhèxiē":"这些","nàxiē":"那些","Zhèxiē píngguǒ hěn xīnxiān":"这些苹果很新鲜","Nàge ne ?":"那个呢？"}}},{"title":"Prendre le métro","phrases":[{"fr":"Je prends le métro tous les jours.","tgt":"我每天坐地铁。","ro":"Wǒ měitiān zuò dìtiě.","lit":"je · chaque jour · s'asseoir · métro"},{"fr":"Demain, je vais à la Cité interdite.","tgt":"我明天去故宫。","ro":"Wǒ míngtiān qù Gùgōng.","lit":"je · demain · aller · Cité interdite"},{"fr":"Je change à la station Xidan.","tgt":"我在西单换车。","ro":"Wǒ zài Xīdān huàn chē.","lit":"je · à · Xidan · changer · véhicule"},{"fr":"Elle achète un ticket au guichet.","tgt":"她在窗口买票。","ro":"Tā zài chuāngkǒu mǎi piào.","lit":"elle · à · guichet · acheter · billet"},{"fr":"Ce soir, nous mangeons dehors.","tgt":"我们今天晚上在外面吃饭。","ro":"Wǒmen jīntiān wǎnshang zài wàimiàn chī fàn.","lit":"nous · aujourd'hui · soir · à · dehors · manger · repas"},{"fr":"Je descends à la prochaine.","tgt":"我下一站下车。","ro":"Wǒ xià yí zhàn xià chē.","lit":"je · suivant · un · station · descendre · véhicule"},{"fr":"Le matin, le métro est bondé.","tgt":"早上地铁人很多。","ro":"Zǎoshang dìtiě rén hěn duō.","lit":"matin · métro · personne · très · nombreux"},{"fr":"Il lit dans le métro.","tgt":"他在地铁上看书。","ro":"Tā zài dìtiě shang kàn shū.","lit":"il · à · métro · dessus · lire · livre"},{"fr":"Je t'attends à la sortie.","tgt":"我在出口等你。","ro":"Wǒ zài chūkǒu děng nǐ.","lit":"je · à · sortie · attendre · toi"},{"fr":"Le métro de Pékin est pratique.","tgt":"北京的地铁很方便。","ro":"Běijīng de dìtiě hěn fāngbiàn.","lit":"Pékin · [possessif] · métro · très · pratique"}],"tip":{"title":"L'ordre des mots : sujet, temps, lieu, verbe","example":"Ce soir, nous mangeons dehors. — 我们<b>今天晚上</b><b>在外面</b>吃饭。","body":"Comme le verbe chinois ne change jamais, c'est l'ordre des mots qui porte le sens, et cet ordre est très stable. On dit d'abord qui, puis quand, puis où, et enfin ce que l'on fait. En français, on peut dire nous mangeons dehors ce soir ; en chinois, le temps et le lieu passent obligatoirement avant le verbe. Écoutez : « Wǒmen jīntiān wǎnshang zài wàimiàn chī fàn ». Mot à mot : nous, aujourd'hui soir, à dehors, manger repas. Autre exemple : « Wǒ míngtiān qù Gùgōng », je vais demain à la Cité interdite, et « Wǒ zài chūkǒu děng nǐ », je t'attends à la sortie, littéralement moi, à la sortie, attendre toi. Le mot de temps peut aussi venir tout au début : « Míngtiān wǒ qù Gùgōng ». Astuce : retenez la petite chanson qui, quand, où, quoi, et posez les briques dans cet ordre.","exampleRo":"Wǒmen jīntiān wǎnshang zài wàimiàn chī fàn.","lit":"nous · aujourd'hui · soir · à · dehors · manger · repas","say":{"Wǒmen jīntiān wǎnshang zài wàimiàn chī fàn":"我们今天晚上在外面吃饭","Wǒ míngtiān qù Gùgōng":"我明天去故宫","Wǒ zài chūkǒu děng nǐ":"我在出口等你","Míngtiān wǒ qù Gùgōng":"明天我去故宫"}}},{"title":"Les nombres au quotidien","phrases":[{"fr":"Un, deux, trois, quatre, cinq !","tgt":"一，二，三，四，五！","ro":"Yī, èr, sān, sì, wǔ!","lit":"un · deux · trois · quatre · cinq !"},{"fr":"J'ai trente ans.","tgt":"我三十岁。","ro":"Wǒ sānshí suì.","lit":"je · trois-dix · an d'âge"},{"fr":"J'habite au huitième étage.","tgt":"我家在八楼。","ro":"Wǒ jiā zài bā lóu.","lit":"je · maison · être à · huit · étage"},{"fr":"Ça fait quinze kuai.","tgt":"十五块。","ro":"Shíwǔ kuài.","lit":"dix-cinq · kuai"},{"fr":"Ça coûte cent yuans.","tgt":"一百块。","ro":"Yìbǎi kuài.","lit":"un · cent · kuai"},{"fr":"Je prends la ligne dix.","tgt":"我坐十号线。","ro":"Wǒ zuò shí hào xiàn.","lit":"je · s'asseoir · dix · numéro · ligne"},{"fr":"Nous sommes onze.","tgt":"我们十一个人。","ro":"Wǒmen shíyī ge rén.","lit":"nous · dix-un · [classificateur] · personne"},{"fr":"Ma chambre, c'est la deux cent un.","tgt":"我的房间是二零一。","ro":"Wǒ de fángjiān shì èr líng yāo.","lit":"je · [possessif] · chambre · être · deux · zéro · un"},{"fr":"Je voudrais deux billets.","tgt":"我要两张票。","ro":"Wǒ yào liǎng zhāng piào.","lit":"je · vouloir · deux · [classificateur] · billet"},{"fr":"Mon fils a six ans.","tgt":"我儿子六岁。","ro":"Wǒ érzi liù suì.","lit":"je · fils · six · an d'âge"}],"tip":{"title":"Compter de un à dix, et au-delà","example":"J'ai trente ans. — 我<b>三十</b>岁。","body":"Les nombres chinois sont un vrai cadeau pour les francophones, car ils sont parfaitement logiques. Apprenez d'abord les dix premiers : « yī, èr, sān, sì, wǔ, liù, qī, bā, jiǔ, shí ». Ensuite, tout se construit comme un jeu de construction. Onze se dit dix-un, « shíyī » ; vingt se dit deux-dix, « èrshí » ; trente-cinq se dit trois-dix-cinq, « sānshíwǔ ». Écoutez : « Wǒ sānshí suì ». Mot à mot : je, trois-dix, années d'âge. Pas de verbe avoir pour l'âge ! Cent se dit « yìbǎi », un cent. Deux pièges seulement : devant un objet que l'on compte, deux se dit « liǎng » et non « èr », comme dans « liǎng zhāng piào », deux billets ; et dans les numéros de chambre ou de téléphone, le un se dit souvent « yāo » pour ne pas le confondre avec sept. Astuce : comptez à voix haute les marches, les stations, tout ce qui passe.","exampleRo":"Wǒ sānshí suì.","lit":"je · trois-dix · an d'âge","say":{"yī, èr, sān, sì, wǔ, liù, qī, bā, jiǔ, shí":"一，二，三，四，五，六，七，八，九，十","shíyī":"十一","èrshí":"二十","sānshíwǔ":"三十五","Wǒ sānshí suì":"我三十岁","yìbǎi":"一百","liǎng":"两","èr":"二","liǎng zhāng piào":"两张票","yāo":"幺"}}},{"title":"Jiaozi et baozi","phrases":[{"fr":"Je voudrais deux baozi.","tgt":"我要两个包子。","ro":"Wǒ yào liǎng ge bāozi.","lit":"je · vouloir · deux · [classificateur] · baozi"},{"fr":"Une assiette de jiaozi, s'il vous plaît.","tgt":"来一盘饺子。","ro":"Lái yì pán jiǎozi.","lit":"venir · un · assiette · jiaozi"},{"fr":"Et encore un bol de soupe.","tgt":"再来一碗汤。","ro":"Zài lái yì wǎn tāng.","lit":"encore · venir · un · bol · soupe"},{"fr":"Il y a combien de jiaozi par assiette ?","tgt":"一盘有多少个饺子？","ro":"Yì pán yǒu duōshao ge jiǎozi?","lit":"un · assiette · avoir · combien · [classificateur] · jiaozi ?"},{"fr":"Il y en a vingt.","tgt":"二十个。","ro":"Èrshí ge.","lit":"deux-dix · [classificateur]"},{"fr":"Trois bouteilles d'eau, aussi.","tgt":"还要三瓶水。","ro":"Hái yào sān píng shuǐ.","lit":"encore · vouloir · trois · bouteille · eau"},{"fr":"Vous avez une table libre ?","tgt":"有一张空桌子吗？","ro":"Yǒu yì zhāng kòng zhuōzi ma?","lit":"avoir · un · [classificateur] · libre · table · [question] ?"},{"fr":"Ces baozi sont à la viande ?","tgt":"这些包子是肉的吗？","ro":"Zhèxiē bāozi shì ròu de ma?","lit":"ces · baozi · être · viande · [possessif] · [question] ?"},{"fr":"Une paire de baguettes, s'il vous plaît.","tgt":"请给我一双筷子。","ro":"Qǐng gěi wǒ yì shuāng kuàizi.","lit":"s'il vous plaît · donner · moi · un · paire · baguettes"},{"fr":"Ce petit restaurant est excellent.","tgt":"这家小饭馆真不错。","ro":"Zhè jiā xiǎo fànguǎn zhēn búcuò.","lit":"ce · [classificateur] · petit · restaurant · vraiment · pas mal"}],"tip":{"title":"Les classificateurs : « ge » et ses amis","example":"Je voudrais deux baozi. — 我要两<b>个</b>包子。","body":"En chinois, on ne peut pas coller un nombre directement devant un nom. Il faut glisser entre les deux un petit mot qu'on appelle un classificateur. Le français fait parfois pareil : on dit une tasse de thé, une paire de baguettes. En chinois, c'est obligatoire tout le temps. Le plus courant, et le plus pratique, est « ge », sans ton : « liǎng ge bāozi », deux baozi. Mot à mot : deux, classificateur, baozi. Il en existe d'autres, plus précis : « zhāng » pour les choses plates comme une table ou un billet, « píng » pour une bouteille, « wǎn » pour un bol, « shuāng » pour une paire. Après « zhè » et « nà », on le met aussi : « zhè jiā fànguǎn », ce restaurant. Astuce : si vous ne savez pas lequel choisir, dites « ge » ; on vous comprendra presque toujours, avec un sourire.","exampleRo":"Wǒ yào liǎng ge bāozi.","lit":"je · vouloir · deux · [classificateur] · baozi","say":{"ge":"个","liǎng ge bāozi":"两个包子","zhāng":"张","píng":"瓶","wǎn":"碗","shuāng":"双","zhè":"这","nà":"那","zhè jiā fànguǎn":"这家饭馆"}}},{"title":"Faire les courses","phrases":[{"fr":"Vous avez des œufs ?","tgt":"你们有鸡蛋吗？","ro":"Nǐmen yǒu jīdàn ma?","lit":"vous · avoir · œuf de poule · [question] ?"},{"fr":"Non, il n'y en a plus.","tgt":"没有了。","ro":"Méiyǒu le.","lit":"ne pas · avoir · [accompli]"},{"fr":"Il y a du tofu ?","tgt":"有豆腐吗？","ro":"Yǒu dòufu ma?","lit":"avoir · tofu · [question] ?"},{"fr":"Je n'ai pas de sac.","tgt":"我没有袋子。","ro":"Wǒ méiyǒu dàizi.","lit":"je · ne pas · avoir · sac"},{"fr":"J'ai de la petite monnaie.","tgt":"我有零钱。","ro":"Wǒ yǒu língqián.","lit":"je · avoir · petite monnaie"},{"fr":"Vous n'avez pas de lait ?","tgt":"你们没有牛奶吗？","ro":"Nǐmen méiyǒu niúnǎi ma?","lit":"vous · ne pas · avoir · lait · [question] ?"},{"fr":"Ici, il y a beaucoup de légumes.","tgt":"这儿有很多菜。","ro":"Zhèr yǒu hěn duō cài.","lit":"ici · avoir · très · nombreux · légume"},{"fr":"Je n'ai pas d'espèces.","tgt":"我没有现金。","ro":"Wǒ méiyǒu xiànjīn.","lit":"je · ne pas · avoir · espèces"},{"fr":"On peut payer avec le téléphone ?","tgt":"可以用手机付钱吗？","ro":"Kěyǐ yòng shǒujī fù qián ma?","lit":"pouvoir · utiliser · téléphone · payer · argent · [question] ?"},{"fr":"Aucun souci, monsieur.","tgt":"没问题，先生。","ro":"Méi wèntí, xiānsheng.","lit":"ne pas · problème · monsieur"}],"tip":{"title":"« Yǒu » et « méiyǒu » : avoir et ne pas avoir","example":"Je n'ai pas de sac. — 我<b>没有</b>袋子。","body":"Le verbe « yǒu » a deux sens très utiles : avoir, et il y a. « Wǒ yǒu língqián », j'ai de la monnaie ; « Zhèr yǒu hěn duō cài », ici il y a beaucoup de légumes. Pour demander au marché si un produit est disponible, rien de plus simple : « Yǒu dòufu ma ? », il y a du tofu ? Mais attention, voici la seule exception à la règle de « bù » : on ne dit jamais « bù yǒu ». La négation de « yǒu » est « méi », ce qui donne « méiyǒu ». Écoutez : « Wǒ méiyǒu dàizi ». Mot à mot : je, ne pas, avoir, sac. Le marchand vous répondra souvent simplement « Méiyǒu », il n'y en a pas, ou « Méiyǒu le », il n'y en a plus. Astuce : « yǒu » et « méiyǒu » vont toujours en couple, comme oui et non ; répétez-les ensemble, « yǒu, méiyǒu », jusqu'à ce qu'ils sonnent comme une évidence.","exampleRo":"Wǒ méiyǒu dàizi.","lit":"je · ne pas · avoir · sac","say":{"Yǒu":"有","méiyǒu":"没有","yǒu":"有","Wǒ yǒu língqián":"我有零钱","Zhèr yǒu hěn duō cài":"这儿有很多菜","Yǒu dòufu ma ?":"有豆腐吗？","bù":"不","bù yǒu":"不有","méi":"没","Wǒ méiyǒu dàizi":"我没有袋子","Méiyǒu":"没有","Méiyǒu le":"没有了","yǒu, méiyǒu":"有，没有"}}},{"title":"Se repérer dans les hutongs","phrases":[{"fr":"Où es-tu ?","tgt":"你在哪儿？","ro":"Nǐ zài nǎr?","lit":"toi · être à · où ?"},{"fr":"Je suis dans un hutong.","tgt":"我在胡同里。","ro":"Wǒ zài hútòng li.","lit":"je · être à · hutong · dedans"},{"fr":"Où sont les toilettes publiques ?","tgt":"公共厕所在哪儿？","ro":"Gōnggòng cèsuǒ zài nǎr?","lit":"public · toilettes · être à · où ?"},{"fr":"C'est sur la gauche.","tgt":"在左边。","ro":"Zài zuǒbian.","lit":"être à · gauche-côté"},{"fr":"Le café est juste en face.","tgt":"咖啡馆就在对面。","ro":"Kāfēiguǎn jiù zài duìmiàn.","lit":"café · justement · être à · en face"},{"fr":"J'habite tout près.","tgt":"我家就在附近。","ro":"Wǒ jiā jiù zài fùjìn.","lit":"je · maison · justement · être à · alentours"},{"fr":"Le parc n'est pas loin.","tgt":"公园不远。","ro":"Gōngyuán bù yuǎn.","lit":"parc · ne pas · loin"},{"fr":"La tour du Tambour est au nord.","tgt":"鼓楼在北边。","ro":"Gǔlóu zài běibian.","lit":"tour du Tambour · être à · nord-côté"},{"fr":"Ton vélo est dehors.","tgt":"你的自行车在外面。","ro":"Nǐ de zìxíngchē zài wàimiàn.","lit":"toi · [possessif] · vélo · être à · dehors"},{"fr":"Je ne suis pas à la maison.","tgt":"我不在家。","ro":"Wǒ bú zài jiā.","lit":"je · ne pas · être à · maison"}],"tip":{"title":"« Zài » : être à un endroit","example":"Où es-tu ? — 你<b>在</b>哪儿？","body":"Le chinois a un verbe spécial pour dire où se trouve quelqu'un ou quelque chose : « zài », être à, se trouver. On ne dit pas « shì » pour un lieu, on dit « zài ». Écoutez : « Nǐ zài nǎr ? ». Mot à mot : toi, être à, où ? Et la réponse se construit exactement de la même façon : « Wǒ zài hútòng li », je suis dans le hutong, littéralement moi, être à, hutong, dedans. Remarquez que le petit mot de position, dedans, dessus, se place après le lieu. Pour dire que quelqu'un n'est pas là, on ajoute « bù », qui devient « bú » devant ce quatrième ton : « Wǒ bú zài jiā », je ne suis pas à la maison. Pour indiquer un côté, on dit « zài zuǒbian », à gauche, ou « zài běibian », au nord. Astuce : « shì » dit ce que l'on est, « zài » dit où l'on est.","exampleRo":"Nǐ zài nǎr?","lit":"toi · être à · où ?","say":{"Zài":"在","zài":"在","shì":"是","Nǐ zài nǎr ?":"你在哪儿？","Wǒ zài hútòng li":"我在胡同里","bù":"不","Wǒ bú zài jiā":"我不在家","zài zuǒbian":"在左边","zài běibian":"在北边"}}},{"title":"La routine du matin","phrases":[{"fr":"Je me lève à sept heures.","tgt":"我七点起床。","ro":"Wǒ qī diǎn qǐchuáng.","lit":"je · sept · heure · se lever"},{"fr":"Il est quelle heure maintenant ?","tgt":"现在几点？","ro":"Xiànzài jǐ diǎn?","lit":"maintenant · combien · heure ?"},{"fr":"Il est huit heures et demie.","tgt":"八点半。","ro":"Bā diǎn bàn.","lit":"huit · heure · demi"},{"fr":"Je prends mon petit-déjeuner à sept heures et quart.","tgt":"我七点一刻吃早饭。","ro":"Wǒ qī diǎn yí kè chī zǎofàn.","lit":"je · sept · heure · un · quart · manger · petit-déjeuner"},{"fr":"Il est neuf heures dix.","tgt":"九点十分。","ro":"Jiǔ diǎn shí fēn.","lit":"neuf · heure · dix · minute"},{"fr":"Mon métro arrive à huit heures cinq.","tgt":"我的地铁八点零五分到。","ro":"Wǒ de dìtiě bā diǎn líng wǔ fēn dào.","lit":"je · [possessif] · métro · huit · heure · zéro · cinq · minute · arriver"},{"fr":"Je commence le travail à neuf heures.","tgt":"我九点上班。","ro":"Wǒ jiǔ diǎn shàngbān.","lit":"je · neuf · heure · aller au travail"},{"fr":"Le matin, je bois du thé au jasmin.","tgt":"我早上喝茉莉花茶。","ro":"Wǒ zǎoshang hē mòlìhuāchá.","lit":"je · matin · boire · jasmin-thé"},{"fr":"Il est deux heures moins cinq.","tgt":"差五分两点。","ro":"Chà wǔ fēn liǎng diǎn.","lit":"manquer · cinq · minute · deux · heure"},{"fr":"Zut, je suis en retard !","tgt":"糟了，我迟到了！","ro":"Zāo le, wǒ chídào le!","lit":"fichu · [accompli] · je · arriver en retard · [accompli] !"}],"tip":{"title":"L'heure : « diǎn » et « fēn »","example":"Il est neuf heures dix. — 九<b>点</b>十<b>分</b>。","body":"Pour dire l'heure en chinois, il suffit de connaître les nombres et deux mots : « diǎn », l'heure, et « fēn », la minute. On dit le chiffre puis « diǎn » : « qī diǎn », sept heures. On ajoute ensuite les minutes : « Jiǔ diǎn shí fēn ». Mot à mot : neuf, heure, dix, minute. Pas besoin de dire il est : l'heure seule suffit comme phrase. Pour la demie, on dit « bàn » : « bā diǎn bàn », huit heures et demie. Pour le quart, « yí kè ». Petit piège : deux heures se dit « liǎng diǎn », et pas « èr diǎn ». Pour demander, on remplace le nombre par « jǐ », combien : « Xiànzài jǐ diǎn ? », quelle heure est-il ? Et rappelez-vous l'ordre des mots : l'heure se place avant le verbe, « Wǒ qī diǎn qǐchuáng », je me lève à sept heures. Astuce : dites l'heure en chinois chaque fois que vous regardez votre montre.","exampleRo":"Jiǔ diǎn shí fēn.","lit":"neuf · heure · dix · minute","say":{"diǎn":"点","fēn":"分","qī diǎn":"七点","Jiǔ diǎn shí fēn":"九点十分","bàn":"半","bā diǎn bàn":"八点半","yí kè":"一刻","liǎng diǎn":"两点","èr diǎn":"二点","jǐ":"几","Xiànzài jǐ diǎn ?":"现在几点？","Wǒ qī diǎn qǐchuáng":"我七点起床"}}},{"title":"Un appel téléphonique","phrases":[{"fr":"Allô, c'est qui ?","tgt":"喂，你是谁？","ro":"Wéi, nǐ shì shéi?","lit":"allô · toi · être · qui ?"},{"fr":"C'est moi, Paul.","tgt":"是我，保罗。","ro":"Shì wǒ, Bǎoluó.","lit":"être · moi · Paul"},{"fr":"Tu es où, là ?","tgt":"你现在在哪儿？","ro":"Nǐ xiànzài zài nǎr?","lit":"toi · maintenant · être à · où ?"},{"fr":"Tu fais quoi ce soir ?","tgt":"你今天晚上做什么？","ro":"Nǐ jīntiān wǎnshang zuò shénme?","lit":"toi · aujourd'hui · soir · faire · quoi ?"},{"fr":"Tu rentres à quelle heure ?","tgt":"你几点回家？","ro":"Nǐ jǐ diǎn huí jiā?","lit":"toi · combien · heure · rentrer · maison ?"},{"fr":"Quel est ton numéro ?","tgt":"你的电话号码是多少？","ro":"Nǐ de diànhuà hàomǎ shì duōshao?","lit":"toi · [possessif] · téléphone · numéro · être · combien ?"},{"fr":"Tu viens avec qui ?","tgt":"你跟谁一起来？","ro":"Nǐ gēn shéi yìqǐ lái?","lit":"toi · avec · qui · ensemble · venir ?"},{"fr":"Tu as envie de manger quoi ?","tgt":"你想吃什么？","ro":"Nǐ xiǎng chī shénme?","lit":"toi · vouloir · manger · quoi ?"},{"fr":"Combien de personnes viennent ?","tgt":"几个人来？","ro":"Jǐ ge rén lái?","lit":"combien · [classificateur] · personne · venir ?"},{"fr":"Je te rappelle plus tard.","tgt":"我等一下再打给你。","ro":"Wǒ děng yíxià zài dǎ gěi nǐ.","lit":"je · attendre · un moment · à nouveau · appeler · donner · toi"}],"tip":{"title":"Les mots interrogatifs : « shénme, nǎr, shéi, jǐ »","example":"Tu fais quoi ce soir ? — 你今天晚上做<b>什么</b>？","body":"Voici quatre mots pour poser presque toutes les questions : « shénme », quoi, « nǎr », où, « shéi », qui, et « jǐ », combien, pour les petits nombres. Le secret, c'est qu'en chinois le mot interrogatif reste exactement à la place de la réponse. Pas de déplacement en début de phrase comme en français. Écoutez : « Nǐ jīntiān wǎnshang zuò shénme ? ». Mot à mot : toi, aujourd'hui soir, faire, quoi ? La réponse prend la même forme : « Wǒ jīntiān wǎnshang kàn diànyǐng », ce soir je regarde un film. De même, « Nǐ zài nǎr ? », tu es où, et « Wǒ zài jiā », je suis à la maison. Pour l'heure, « jǐ diǎn », à quelle heure. Attention, avec ces mots, on n'ajoute pas « ma » à la fin : la question est déjà là. Astuce : construisez d'abord la réponse dans votre tête, puis remplacez le mot inconnu par le mot interrogatif.","exampleRo":"Nǐ jīntiān wǎnshang zuò shénme?","lit":"toi · aujourd'hui · soir · faire · quoi ?","say":{"shénme":"什么","nǎr":"哪儿","shéi":"谁","jǐ":"几","Nǐ jīntiān wǎnshang zuò shénme ?":"你今天晚上做什么？","Wǒ jīntiān wǎnshang kàn diànyǐng":"我今天晚上看电影","Nǐ zài nǎr ?":"你在哪儿？","Wǒ zài jiā":"我在家","jǐ diǎn":"几点","ma":"吗","shénme, nǎr, shéi, jǐ":"什么、哪儿、谁、几"}}},{"title":"À vélo dans Pékin","phrases":[{"fr":"Nous prenons tous un vélo en libre-service.","tgt":"我们都骑共享单车。","ro":"Wǒmen dōu qí gòngxiǎng dānchē.","lit":"nous · tous · enfourcher · partagé · vélo"},{"fr":"Moi aussi, je fais du vélo.","tgt":"我也骑自行车。","ro":"Wǒ yě qí zìxíngchē.","lit":"je · aussi · enfourcher · vélo"},{"fr":"Elle vient aussi.","tgt":"她也来。","ro":"Tā yě lái.","lit":"elle · aussi · venir"},{"fr":"Ces vélos sont tous jaunes.","tgt":"这些自行车都是黄色的。","ro":"Zhèxiē zìxíngchē dōu shì huángsè de.","lit":"ces · vélo · tous · être · jaune · [possessif]"},{"fr":"Nous sommes tous contents aussi.","tgt":"我们也都很高兴。","ro":"Wǒmen yě dōu hěn gāoxìng.","lit":"nous · aussi · tous · très · content"},{"fr":"Ici, toutes les rues sont plates.","tgt":"这儿的路都很平。","ro":"Zhèr de lù dōu hěn píng.","lit":"ici · [possessif] · route · tous · très · plat"},{"fr":"Mes amis font tous du vélo.","tgt":"我的朋友都骑车。","ro":"Wǒ de péngyou dōu qí chē.","lit":"je · [possessif] · ami · tous · enfourcher · vélo"},{"fr":"Le vélo, c'est pratique et pas cher.","tgt":"骑车很方便，也很便宜。","ro":"Qí chē hěn fāngbiàn, yě hěn piányi.","lit":"enfourcher · vélo · très · pratique · aussi · très · bon marché"},{"fr":"Tu n'as pas peur ?","tgt":"你不怕吗？","ro":"Nǐ bú pà ma?","lit":"toi · ne pas · avoir peur · [question] ?"},{"fr":"Moi non plus, je n'ai pas peur.","tgt":"我也不怕。","ro":"Wǒ yě bú pà.","lit":"je · aussi · ne pas · avoir peur"}],"tip":{"title":"« Yě » et « dōu » : aussi et tous","example":"Ces vélos sont tous jaunes. — 这些自行车<b>都</b>是黄色的。","body":"En français, on peut dire aussi ou tous presque n'importe où dans la phrase. En chinois, « yě », aussi, et « dōu », tous, ont une place fixe : juste après le sujet, juste avant le verbe. Jamais à la fin de la phrase. Écoutez : « Zhèxiē zìxíngchē dōu shì huángsè de ». Mot à mot : ces vélos, tous, être, jaunes. Avec « yě » : « Wǒ yě qí zìxíngchē », moi aussi je fais du vélo, littéralement moi, aussi, enfourcher, vélo. Et pour dire moi non plus, c'est très simple : « Wǒ yě bú pà », moi non plus je n'ai pas peur, mot à mot moi, aussi, ne pas, avoir peur. Quand on a besoin des deux, l'ordre est toujours le même : « yě » puis « dōu », comme dans « Wǒmen yě dōu hěn gāoxìng ». Astuce : imaginez une petite case devant le verbe, réservée à ces deux mots.","exampleRo":"Zhèxiē zìxíngchē dōu shì huángsè de.","lit":"ces · vélo · tous · être · jaune · [possessif]","say":{"Yě":"也","dōu":"都","yě":"也","Zhèxiē zìxíngchē dōu shì huángsè de":"这些自行车都是黄色的","Wǒ yě qí zìxíngchē":"我也骑自行车","Wǒ yě bú pà":"我也不怕","Wǒmen yě dōu hěn gāoxìng":"我们也都很高兴"}}},{"title":"Acheter des vêtements","phrases":[{"fr":"Je voudrais acheter une veste.","tgt":"我想买一件外套。","ro":"Wǒ xiǎng mǎi yí jiàn wàitào.","lit":"je · vouloir · acheter · un · [classificateur] · veste"},{"fr":"Je veux essayer ce pull.","tgt":"我要试试这件毛衣。","ro":"Wǒ yào shìshi zhè jiàn máoyī.","lit":"je · vouloir · essayer · ce · [classificateur] · pull"},{"fr":"Quelle taille voulez-vous ?","tgt":"您要多大号的？","ro":"Nín yào duō dà hào de?","lit":"vous (poli) · vouloir · combien · grand · taille · [possessif] ?"},{"fr":"Une taille au-dessus, s'il vous plaît.","tgt":"请给我大一号的。","ro":"Qǐng gěi wǒ dà yí hào de.","lit":"s'il vous plaît · donner · moi · grand · un · taille · [possessif]"},{"fr":"Je veux la rouge.","tgt":"我要红色的。","ro":"Wǒ yào hóngsè de.","lit":"je · vouloir · rouge · [possessif]"},{"fr":"Elle a envie d'acheter une jupe.","tgt":"她想买裙子。","ro":"Tā xiǎng mǎi qúnzi.","lit":"elle · vouloir · acheter · jupe"},{"fr":"Je ne veux pas de sac, merci.","tgt":"我不要袋子，谢谢。","ro":"Wǒ bú yào dàizi, xièxie.","lit":"je · ne pas · vouloir · sac · merci"},{"fr":"Tu as envie d'aller au marché ?","tgt":"你想去市场吗？","ro":"Nǐ xiǎng qù shìchǎng ma?","lit":"toi · vouloir · aller · marché · [question] ?"},{"fr":"Ce manteau est trop cher.","tgt":"这件大衣太贵了。","ro":"Zhè jiàn dàyī tài guì le.","lit":"ce · [classificateur] · manteau · trop · cher · [exclamation]"},{"fr":"Bon, je prends celui-là.","tgt":"好，我要那件。","ro":"Hǎo, wǒ yào nà jiàn.","lit":"bien · je · vouloir · ce-là · [classificateur]"}],"tip":{"title":"« Xiǎng » et « yào » : vouloir","example":"Je voudrais acheter une veste. — 我<b>想</b>买一件外套。","body":"Le chinois a deux façons courantes de dire vouloir. « Xiǎng », avec un troisième ton bien creux, exprime une envie, un souhait : c'est notre je voudrais, j'aimerais, j'ai envie de. « Yào », avec un ton qui tombe, est plus direct et plus décidé : je veux, je prends. Écoutez : « Wǒ xiǎng mǎi yí jiàn wàitào ». Mot à mot : je, vouloir, acheter, une, classificateur, veste. Dans une boutique, une fois votre choix fait, vous direz plutôt « Wǒ yào zhè jiàn », je prends celui-ci. Les deux se placent devant le verbe : « xiǎng qù », avoir envie d'aller, « yào shìshi », vouloir essayer. Et « yào » peut aussi s'employer seul devant un objet, comme une commande. Pour refuser poliment, on dit « bú yào », je n'en veux pas. Astuce : « xiǎng » rêve, « yào » décide.","exampleRo":"Wǒ xiǎng mǎi yí jiàn wàitào.","lit":"je · vouloir · acheter · un · [classificateur] · veste","say":{"Xiǎng":"想","yào":"要","Yào":"要","Wǒ xiǎng mǎi yí jiàn wàitào":"我想买一件外套","Wǒ yào zhè jiàn":"我要这件","xiǎng qù":"想去","yào shìshi":"要试试","bú yào":"不要","xiǎng":"想"}}},{"title":"Une balade au parc Jingshan","phrases":[{"fr":"Allons au parc Jingshan !","tgt":"我们去景山公园吧！","ro":"Wǒmen qù Jǐngshān Gōngyuán ba!","lit":"nous · aller · Jingshan · parc · [suggestion] !"},{"fr":"Montons jusqu'au sommet.","tgt":"我们爬到山顶吧。","ro":"Wǒmen pá dào shāndǐng ba.","lit":"nous · grimper · arriver · sommet · [suggestion]"},{"fr":"Reposons-nous un peu.","tgt":"休息一下吧。","ro":"Xiūxi yíxià ba.","lit":"se reposer · un moment · [suggestion]"},{"fr":"Prenons une photo !","tgt":"拍张照片吧！","ro":"Pāi zhāng zhàopiàn ba!","lit":"prendre · [classificateur] · photo · [suggestion] !"},{"fr":"Très bien, en route !","tgt":"好的，走吧！","ro":"Hǎo de, zǒu ba!","lit":"d'accord · partir · [suggestion] !"},{"fr":"Regarde, la Cité interdite est en bas.","tgt":"你看，故宫在下面。","ro":"Nǐ kàn, Gùgōng zài xiàmiàn.","lit":"toi · regarder · Cité interdite · être à · dessous"},{"fr":"Asseyons-nous ici.","tgt":"我们坐这儿吧。","ro":"Wǒmen zuò zhèr ba.","lit":"nous · s'asseoir · ici · [suggestion]"},{"fr":"Tu dois être fatiguée, non ?","tgt":"你累了吧？","ro":"Nǐ lèi le ba?","lit":"toi · fatigué · [accompli] · [suggestion] ?"},{"fr":"Rentrons en métro.","tgt":"我们坐地铁回去吧。","ro":"Wǒmen zuò dìtiě huíqu ba.","lit":"nous · s'asseoir · métro · retourner · [suggestion]"},{"fr":"C'est une bonne idée, ça !","tgt":"这个主意不错！","ro":"Zhège zhǔyi búcuò!","lit":"ce · [classificateur] · idée · pas mal !"}],"tip":{"title":"« Ba » : proposer, suggérer","example":"Prenons une photo ! — 拍张照片<b>吧</b>！","body":"La petite syllabe « ba », légère et sans ton, posée à la fin d'une phrase, la transforme en proposition. C'est l'équivalent de notre et si on, ou de la forme allons, prenons, montons. Écoutez : « Pāi zhāng zhàopiàn ba ! ». Mot à mot : prendre, une, photo, suggestion. Sans « ba », la phrase sonnerait comme un ordre un peu sec ; avec « ba », elle devient douce et amicale. On peut commencer par « wǒmen », nous : « Wǒmen qù Jǐngshān Gōngyuán ba », allons au parc Jingshan. Le célèbre « Zǒu ba ! », on y va, vous l'entendrez partout. « Ba » sert aussi à demander une confirmation, comme notre non ? à la fin : « Nǐ lèi le ba ? », tu es fatiguée, non ? Astuce : « ma » pose une vraie question, « ba » propose ou suppose avec un sourire.","exampleRo":"Pāi zhāng zhàopiàn ba!","lit":"prendre · [classificateur] · photo · [suggestion] !","say":{"Ba":"吧","ba":"吧","Pāi zhāng zhàopiàn ba !":"拍张照片吧！","wǒmen":"我们","Wǒmen qù Jǐngshān Gōngyuán ba":"我们去景山公园吧","Zǒu ba !":"走吧！","Nǐ lèi le ba ?":"你累了吧？","ma":"吗"}}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Bonjour à tous !","tgt":"大家好！","ro":"Dàjiā hǎo!","lit":"tout le monde · bien !"},{"fr":"Merci, professeur !","tgt":"谢谢老师！","ro":"Xièxie lǎoshī!","lit":"merci · professeur !"},{"fr":"Pardon, mon chinois n'est pas encore très bon.","tgt":"对不起，我的中文还不太好。","ro":"Duìbuqǐ, wǒ de Zhōngwén hái bú tài hǎo.","lit":"pardon · je · [possessif] · chinois · encore · ne pas · trop · bien"},{"fr":"Ça ne fait rien !","tgt":"没关系！","ro":"Méi guānxi!","lit":"ne pas · lien !"},{"fr":"Le chinois n'est pas si difficile.","tgt":"中文不太难。","ro":"Zhōngwén bú tài nán.","lit":"chinois · ne pas · trop · difficile"},{"fr":"Je parle un peu chinois.","tgt":"我会说一点儿中文。","ro":"Wǒ huì shuō yìdiǎnr Zhōngwén.","lit":"je · savoir · parler · un peu · chinois"},{"fr":"J'aime beaucoup Pékin.","tgt":"我很喜欢北京。","ro":"Wǒ hěn xǐhuan Běijīng.","lit":"je · très · aimer · Pékin"},{"fr":"Je connais déjà les quatre tons.","tgt":"我已经知道四个声调了。","ro":"Wǒ yǐjīng zhīdào sì ge shēngdiào le.","lit":"je · déjà · savoir · quatre · [classificateur] · ton · [accompli]"},{"fr":"Je sais compter jusqu'à cent.","tgt":"我会数到一百。","ro":"Wǒ huì shǔ dào yìbǎi.","lit":"je · savoir · compter · arriver · un · cent"},{"fr":"Au revoir, et à bientôt !","tgt":"再见，回头见！","ro":"Zàijiàn, huítóu jiàn!","lit":"à nouveau · voir · tourner la tête · voir !"}],"tip":{"title":"Les formules magiques : « nǐ hǎo, xièxie, duìbuqǐ, méi guānxi »","example":"Ça ne fait rien ! — <b>没关系</b>！","body":"Pour finir ce premier module, voici quatre formules qui ouvrent toutes les portes. « Nǐ hǎo », bonjour, mot à mot toi, bien ; à un groupe, on dit « Dàjiā hǎo », bonjour à tous. Ici, deux troisièmes tons se suivent : dans la bouche, le premier remonte un peu, et l'on entend presque « ní hǎo ». « Xièxie », merci, avec un ton qui tombe puis une syllabe légère. « Duìbuqǐ », pardon, excusez-moi, quand on bouscule quelqu'un ou qu'on se trompe. Et la réponse idéale : « Méi guānxi », ce n'est rien, mot à mot pas de lien, aucune conséquence. Écoutez ce petit dialogue : « Duìbuqǐ ! », « Méi guānxi ! ». Vous remarquerez que le chinois utilise moins souvent merci et pardon que le français entre proches, mais avec des inconnus, ces formules font toujours plaisir. Astuce : utilisez-les dès demain, même au milieu d'une phrase en français, pour les ancrer dans votre bouche.","exampleRo":"Méi guānxi!","lit":"ne pas · lien !","say":{"Nǐ hǎo":"你好","Dàjiā hǎo":"大家好","ní hǎo":"你好","Xièxie":"谢谢","Duìbuqǐ":"对不起","Méi guānxi":"没关系","Duìbuqǐ !":"对不起！","Méi guānxi !":"没关系！","nǐ hǎo, xièxie, duìbuqǐ, méi guānxi":"你好、谢谢、对不起、没关系"}}}]},{"id":2,"name":"En voyage","desc":"Se déplacer, découvrir et gérer les imprévus en Chine.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à l'aéroport de Pékin","phrases":[{"fr":"Bienvenue à Pékin !","tgt":"欢迎来北京！","ro":"Huānyíng lái Běijīng!","lit":"bienvenue · venir · Pékin !"},{"fr":"Tenez, voici mon passeport.","tgt":"这是我的护照。","ro":"Zhè shì wǒ de hùzhào.","lit":"ceci · être · moi · [possessif] · passeport"},{"fr":"Vous êtes de quelle nationalité ?","tgt":"您是哪国人？","ro":"Nín shì nǎ guó rén?","lit":"vous · être · quel · pays · personne ?"},{"fr":"Je suis française, je viens en touriste.","tgt":"我是法国人，我来旅游。","ro":"Wǒ shì fǎguórén, wǒ lái lǚyóu.","lit":"je · être · France-personne, je · venir · voyager"},{"fr":"Où sont les bagages ?","tgt":"行李在哪儿？","ro":"Xíngli zài nǎr?","lit":"bagages · se trouver · où ?"},{"fr":"J'ai une seule valise.","tgt":"我只有一个箱子。","ro":"Wǒ zhǐ yǒu yí ge xiāngzi.","lit":"je · seulement · avoir · un · [classificateur] · valise"},{"fr":"Il y a des taxis ici ?","tgt":"这儿有出租车吗？","ro":"Zhèr yǒu chūzūchē ma?","lit":"ici · avoir · taxi · [question] ?"},{"fr":"Les taxis sont dehors.","tgt":"出租车在外面。","ro":"Chūzūchē zài wàimiàn.","lit":"taxi · se trouver · dehors"},{"fr":"Je vais à cet hôtel.","tgt":"我去这个酒店。","ro":"Wǒ qù zhège jiǔdiàn.","lit":"je · aller · ce · [classificateur] · hôtel"},{"fr":"Pékin, c'est immense !","tgt":"北京真大！","ro":"Běijīng zhēn dà!","lit":"Pékin · vraiment · grand !"}]},{"title":"Le programme des jours à venir","phrases":[{"fr":"Aujourd'hui, nous sommes à Pékin.","tgt":"今天我们在北京。","ro":"Jīntiān wǒmen zài Běijīng.","lit":"aujourd'hui · nous · se trouver · Pékin"},{"fr":"Demain, nous allons à la Grande Muraille.","tgt":"明天我们去长城。","ro":"Míngtiān wǒmen qù Chángchéng.","lit":"demain · nous · aller · Grande Muraille"},{"fr":"Hier, j'étais encore à Paris.","tgt":"昨天我还在巴黎。","ro":"Zuótiān wǒ hái zài Bālí.","lit":"hier · je · encore · se trouver · Paris"},{"fr":"Aujourd'hui, il fait très beau.","tgt":"今天天气很好。","ro":"Jīntiān tiānqì hěn hǎo.","lit":"aujourd'hui · temps · très · bon"},{"fr":"Il fera froid demain ?","tgt":"明天冷吗？","ro":"Míngtiān lěng ma?","lit":"demain · froid · [question] ?"},{"fr":"On est quel jour, aujourd'hui ?","tgt":"今天星期几？","ro":"Jīntiān xīngqī jǐ?","lit":"aujourd'hui · semaine · combien ?"},{"fr":"Aujourd'hui, c'est samedi.","tgt":"今天星期六。","ro":"Jīntiān xīngqīliù.","lit":"aujourd'hui · semaine-six"},{"fr":"Demain matin, on part à huit heures.","tgt":"明天早上八点出发。","ro":"Míngtiān zǎoshang bā diǎn chūfā.","lit":"demain · matin · huit · heure · partir"},{"fr":"Après-demain, nous allons à Xi'an.","tgt":"后天我们去西安。","ro":"Hòutiān wǒmen qù Xī'ān.","lit":"après-demain · nous · aller · Xi'an"},{"fr":"Tu es libre ce soir ?","tgt":"你今天晚上有空吗？","ro":"Nǐ jīntiān wǎnshang yǒu kòng ma?","lit":"toi · aujourd'hui · soir · avoir · temps libre · [question] ?"}],"tip":{"title":"« Jīntiān, míngtiān, zuótiān » : aujourd'hui, demain, hier","example":"Demain, nous allons à la Grande Muraille. — <b>明天</b>我们去长城。","body":"En chinois, le verbe ne change jamais : pas de futur, pas de passé, pas de conjugaison. Pour situer une action dans le temps, on ajoute simplement un mot de temps, et on le place tout au début de la phrase ou juste après le sujet. Les trois mots clés finissent tous par « tiān », qui veut dire jour : « jīntiān » pour aujourd'hui, « míngtiān » pour demain, « zuótiān » pour hier. Décomposons « Míngtiān wǒmen qù Chángchéng » : demain, nous, aller, Grande Muraille. Le verbe « qù » reste identique, que l'on parle d'hier ou de demain. Comparez « Zuótiān wǒ zài Bālí », hier j'étais à Paris, et « Jīntiān wǒ zài Běijīng », aujourd'hui je suis à Pékin : seul le mot de temps change. Vous pouvez aussi dire « hòutiān » pour après-demain. Pour retenir, pensez que « míng » évoque la lumière du jour qui vient, demain, tandis que « zuó » sonne comme un jour déjà passé.","exampleRo":"Míngtiān wǒmen qù Chángchéng.","lit":"demain · nous · aller · Grande Muraille","say":{"Jīntiān, míngtiān, zuótiān":"今天，明天，昨天","tiān":"天","jīntiān":"今天","míngtiān":"明天","zuótiān":"昨天","Míngtiān wǒmen qù Chángchéng":"明天我们去长城","qù":"去","Zuótiān wǒ zài Bālí":"昨天我在巴黎","Jīntiān wǒ zài Běijīng":"今天我在北京","hòutiān":"后天","míng":"明","zuó":"昨"}}},{"title":"À la réception de l'hôtel","phrases":[{"fr":"Bonjour, nous avons une réservation.","tgt":"您好，我们有预订。","ro":"Nín hǎo, wǒmen yǒu yùdìng.","lit":"vous · bien, nous · avoir · réservation"},{"fr":"Vous vous appelez comment ?","tgt":"您叫什么名字？","ro":"Nín jiào shénme míngzi?","lit":"vous · s'appeler · quoi · nom ?"},{"fr":"Je m'appelle Martin.","tgt":"我叫马丁。","ro":"Wǒ jiào Mǎdīng.","lit":"je · s'appeler · Martin"},{"fr":"Votre chambre est au huitième étage.","tgt":"您的房间在八楼。","ro":"Nín de fángjiān zài bā lóu.","lit":"vous · [possessif] · chambre · se trouver · huit · étage"},{"fr":"Voici la carte de votre chambre.","tgt":"这是您的房卡。","ro":"Zhè shì nín de fángkǎ.","lit":"ceci · être · vous · [possessif] · carte-chambre"},{"fr":"Le petit-déjeuner, c'est à quelle heure ?","tgt":"早饭几点？","ro":"Zǎofàn jǐ diǎn?","lit":"petit-déjeuner · combien · heure ?"},{"fr":"Le petit-déjeuner commence à sept heures.","tgt":"早饭七点开始。","ro":"Zǎofàn qī diǎn kāishǐ.","lit":"petit-déjeuner · sept · heure · commencer"},{"fr":"Il y a internet dans la chambre ?","tgt":"房间里有网吗？","ro":"Fángjiān li yǒu wǎng ma?","lit":"chambre · dedans · avoir · réseau · [question] ?"},{"fr":"Oui, le mot de passe est sur la carte.","tgt":"有，密码在卡上。","ro":"Yǒu, mìmǎ zài kǎ shang.","lit":"avoir, mot de passe · se trouver · carte · dessus"},{"fr":"L'ascenseur, il est où ?","tgt":"电梯在哪儿？","ro":"Diàntī zài nǎr?","lit":"ascenseur · se trouver · où ?"}]},{"title":"Un service à l'hôtel","phrases":[{"fr":"Veuillez patienter un instant.","tgt":"请稍等。","ro":"Qǐng shāo děng.","lit":"veuillez · un peu · attendre"},{"fr":"Entrez, je vous en prie.","tgt":"请进。","ro":"Qǐng jìn.","lit":"veuillez · entrer"},{"fr":"Asseyez-vous, s'il vous plaît.","tgt":"请坐。","ro":"Qǐng zuò.","lit":"veuillez · s'asseoir"},{"fr":"Réveillez-moi à six heures, s'il vous plaît.","tgt":"请六点叫醒我。","ro":"Qǐng liù diǎn jiàoxǐng wǒ.","lit":"veuillez · six · heure · appeler-réveiller · moi"},{"fr":"Dans la salle de bain, il n'y a pas d'eau chaude.","tgt":"浴室没有热水。","ro":"Yùshì méiyǒu rèshuǐ.","lit":"salle de bain · ne pas · avoir · chaud-eau"},{"fr":"Je voudrais encore une serviette.","tgt":"我还要一条毛巾。","ro":"Wǒ hái yào yì tiáo máojīn.","lit":"je · encore · vouloir · un · [classificateur] · serviette"},{"fr":"Appelez-moi un taxi, s'il vous plaît.","tgt":"请帮我叫一辆出租车。","ro":"Qǐng bāng wǒ jiào yí liàng chūzūchē.","lit":"veuillez · aider · moi · appeler · un · [classificateur] · taxi"},{"fr":"Parlez plus lentement, s'il vous plaît.","tgt":"请说慢一点儿。","ro":"Qǐng shuō màn yìdiǎnr.","lit":"veuillez · parler · lent · un peu"},{"fr":"Merci infiniment !","tgt":"非常感谢！","ro":"Fēicháng gǎnxiè!","lit":"extrêmement · remercier !"},{"fr":"Il n'y a pas de quoi.","tgt":"不客气。","ro":"Bú kèqi.","lit":"ne pas · cérémonieux"}],"tip":{"title":"« Qǐng » : s'il vous plaît, veuillez","example":"Entrez, je vous en prie. — <b>请</b>进。","body":"Le petit mot « qǐng », prononcé avec le troisième ton qui descend puis remonte, est la clé de la politesse en chinois. Contrairement au français, où « s'il vous plaît » se met souvent à la fin, « qǐng » se place tout au début, juste devant le verbe, comme notre « veuillez ». Prenons « Qǐng jìn » : veuillez, entrer, c'est-à-dire entrez, je vous en prie. De la même façon, « Qǐng zuò » veut dire asseyez-vous, et « Qǐng shāo děng » veut dire veuillez patienter un instant. Avec « qǐng », un ordre devient aussitôt une invitation aimable. Vous entendrez aussi très souvent « qǐngwèn », littéralement je vous prie de me permettre de demander, pour dire excusez-moi avant une question. Pour retenir, imaginez que « qǐng » ouvre la porte de la phrase avec le sourire : on le dit en premier, puis on demande ce que l'on veut.","exampleRo":"Qǐng jìn.","lit":"veuillez · entrer","say":{"Qǐng":"请","qǐng":"请","Qǐng jìn":"请进","Qǐng zuò":"请坐","Qǐng shāo děng":"请稍等","qǐngwèn":"请问"}}},{"title":"Acheter un billet de train","phrases":[{"fr":"Je voudrais acheter un billet de train.","tgt":"我想买一张火车票。","ro":"Wǒ xiǎng mǎi yì zhāng huǒchēpiào.","lit":"je · vouloir · acheter · un · [classificateur] · train-billet"},{"fr":"Pour Xi'an, demain matin.","tgt":"去西安，明天上午。","ro":"Qù Xī'ān, míngtiān shàngwǔ.","lit":"aller · Xi'an, demain · matinée"},{"fr":"Vous voulez un billet de train à grande vitesse ?","tgt":"您要高铁票吗？","ro":"Nín yào gāotiě piào ma?","lit":"vous · vouloir · grande vitesse · billet · [question] ?"},{"fr":"Oui, j'en voudrais deux.","tgt":"对，请给我两张。","ro":"Duì, qǐng gěi wǒ liǎng zhāng.","lit":"exact, veuillez · donner · moi · deux · [classificateur]"},{"fr":"Il me faut votre passeport.","tgt":"请给我您的护照。","ro":"Qǐng gěi wǒ nín de hùzhào.","lit":"veuillez · donner · moi · vous · [possessif] · passeport"},{"fr":"Il reste des places assises ?","tgt":"还有座位吗？","ro":"Hái yǒu zuòwèi ma?","lit":"encore · avoir · place · [question] ?"},{"fr":"Il reste deux places côté fenêtre.","tgt":"还有两个靠窗的座位。","ro":"Hái yǒu liǎng ge kào chuāng de zuòwèi.","lit":"encore · avoir · deux · [classificateur] · contre · fenêtre · [possessif] · place"},{"fr":"Le train part à quelle heure ?","tgt":"火车几点开？","ro":"Huǒchē jǐ diǎn kāi?","lit":"train · combien · heure · démarrer ?"},{"fr":"Il part à neuf heures et demie.","tgt":"九点半开。","ro":"Jiǔ diǎn bàn kāi.","lit":"neuf · heure · demi · démarrer"},{"fr":"Où est la salle d'attente ?","tgt":"候车室在哪儿？","ro":"Hòuchēshì zài nǎr?","lit":"attendre-train-salle · se trouver · où ?"}]},{"title":"Acheter des souvenirs","phrases":[{"fr":"Combien coûte ce chapeau ?","tgt":"这个帽子多少钱？","ro":"Zhège màozi duōshao qián?","lit":"ce · [classificateur] · chapeau · combien · argent ?"},{"fr":"Cinquante yuans.","tgt":"五十块。","ro":"Wǔshí kuài.","lit":"cinquante · kuai"},{"fr":"Oh, c'est trop cher !","tgt":"太贵了！","ro":"Tài guì le!","lit":"trop · cher · [exclamation] !"},{"fr":"Trente yuans, ça vous va ?","tgt":"三十块，行吗？","ro":"Sānshí kuài, xíng ma?","lit":"trente · kuai, ça va · [question] ?"},{"fr":"Disons quarante.","tgt":"四十吧。","ro":"Sìshí ba.","lit":"quarante · [suggestion]"},{"fr":"Et cette carte postale, c'est combien ?","tgt":"这张明信片多少钱？","ro":"Zhè zhāng míngxìnpiàn duōshao qián?","lit":"ce · [classificateur] · carte postale · combien · argent ?"},{"fr":"Trois yuans pièce.","tgt":"三块一张。","ro":"Sān kuài yì zhāng.","lit":"trois · kuai · un · [classificateur]"},{"fr":"J'en prends cinq.","tgt":"我要五张。","ro":"Wǒ yào wǔ zhāng.","lit":"je · vouloir · cinq · [classificateur]"},{"fr":"Et au total, ça fait combien ?","tgt":"一共多少钱？","ro":"Yígòng duōshao qián?","lit":"au total · combien · argent ?"},{"fr":"Je vais payer avec mon téléphone.","tgt":"我用手机付钱。","ro":"Wǒ yòng shǒujī fù qián.","lit":"je · utiliser · téléphone · payer · argent"}],"tip":{"title":"« Duōshao qián » : demander un prix, les yuans","example":"Combien coûte ce chapeau ? — 这个帽子<b>多少钱</b>？","body":"Pour demander un prix, retenez la formule « duōshao qián », littéralement beaucoup-peu argent, c'est-à-dire combien d'argent. « Duō » veut dire beaucoup, « shao » veut dire peu, et ensemble ils forment notre mot combien. On place simplement l'objet devant : « Zhège màozi duōshao qián ? », ce chapeau, combien d'argent ? En chinois, le mot interrogatif reste à l'endroit exact où viendra la réponse, il n'y a pas d'inversion comme en français. Le vendeur répondra par exemple « Wǔshí kuài », cinquante kuai. La monnaie officielle s'appelle le yuan, mais à l'oral tout le monde dit « kuài ». Pour le total, demandez « Yígòng duōshao qián ? », ça fait combien en tout. Et si c'est trop cher, lancez avec le sourire « Tài guì le ! ». Astuce : « duōshao » sonne un peu comme dos chaud, imaginez un vendeur au soleil qui vous annonce son prix.","exampleRo":"Zhège màozi duōshao qián?","lit":"ce · [classificateur] · chapeau · combien · argent ?","say":{"Duōshao qián":"多少钱","duōshao qián":"多少钱","Duō":"多","Zhège màozi duōshao qián ?":"这个帽子多少钱？","Wǔshí kuài":"五十块","kuài":"块","Yígòng duōshao qián ?":"一共多少钱？","Tài guì le !":"太贵了！","duōshao":"多少"}}},{"title":"La Grande Muraille à Mutianyu","phrases":[{"fr":"Voici la Grande Muraille !","tgt":"这就是长城！","ro":"Zhè jiù shì Chángchéng!","lit":"ceci · justement · être · Grande Muraille !"},{"fr":"Mutianyu est magnifique.","tgt":"慕田峪很美。","ro":"Mùtiányù hěn měi.","lit":"Mutianyu · très · beau"},{"fr":"Il y a énormément de marches.","tgt":"台阶很多。","ro":"Táijiē hěn duō.","lit":"marches · très · nombreux"},{"fr":"Je suis épuisé.","tgt":"我很累。","ro":"Wǒ hěn lèi.","lit":"je · très · fatigué"},{"fr":"On fait une petite pause ?","tgt":"我们休息一下吧。","ro":"Wǒmen xiūxi yíxià ba.","lit":"nous · se reposer · un coup · [suggestion]"},{"fr":"Le paysage d'ici est vraiment beau.","tgt":"这儿的风景真美。","ro":"Zhèr de fēngjǐng zhēn měi.","lit":"ici · [possessif] · paysage · vraiment · beau"},{"fr":"Prends-moi en photo, s'il te plaît.","tgt":"请帮我拍张照片。","ro":"Qǐng bāng wǒ pāi zhāng zhàopiàn.","lit":"veuillez · aider · moi · prendre · [classificateur] · photo"},{"fr":"Là-haut, il y a beaucoup de vent.","tgt":"上面风很大。","ro":"Shàngmiàn fēng hěn dà.","lit":"en haut · vent · très · grand"},{"fr":"Tu as de l'eau ?","tgt":"你有水吗？","ro":"Nǐ yǒu shuǐ ma?","lit":"toi · avoir · eau · [question] ?"},{"fr":"La Grande Muraille est vraiment longue !","tgt":"长城真长！","ro":"Chángchéng zhēn cháng!","lit":"Grande Muraille · vraiment · long !"}]},{"title":"Le train de Pékin à Xi'an","phrases":[{"fr":"Ce train va de Pékin à Xi'an.","tgt":"这趟车从北京到西安。","ro":"Zhè tàng chē cóng Běijīng dào Xī'ān.","lit":"ce · [classificateur] · train · depuis · Pékin · jusqu'à · Xi'an"},{"fr":"De Pékin à Xi'an, il faut combien d'heures ?","tgt":"从北京到西安要几个小时？","ro":"Cóng Běijīng dào Xī'ān yào jǐ ge xiǎoshí?","lit":"depuis · Pékin · jusqu'à · Xi'an · falloir · combien · [classificateur] · heure ?"},{"fr":"Environ quatre heures et demie.","tgt":"大概四个半小时。","ro":"Dàgài sì ge bàn xiǎoshí.","lit":"environ · quatre · [classificateur] · demi · heure"},{"fr":"Le train à grande vitesse est très rapide.","tgt":"高铁很快。","ro":"Gāotiě hěn kuài.","lit":"grande vitesse · très · rapide"},{"fr":"Où est la voiture numéro cinq ?","tgt":"五号车厢在哪儿？","ro":"Wǔ hào chēxiāng zài nǎr?","lit":"cinq · numéro · voiture · se trouver · où ?"},{"fr":"J'ai une place côté fenêtre.","tgt":"我的座位靠窗。","ro":"Wǒ de zuòwèi kào chuāng.","lit":"moi · [possessif] · place · contre · fenêtre"},{"fr":"Du lundi au vendredi, il y a toujours du monde.","tgt":"从星期一到星期五人都很多。","ro":"Cóng xīngqīyī dào xīngqīwǔ rén dōu hěn duō.","lit":"depuis · lundi · jusqu'à · vendredi · gens · tous · très · nombreux"},{"fr":"Le train arrive à Xi'an à deux heures.","tgt":"火车两点到西安。","ro":"Huǒchē liǎng diǎn dào Xī'ān.","lit":"train · deux · heure · arriver · Xi'an"},{"fr":"De Paris à Pékin, c'est très loin.","tgt":"从巴黎到北京很远。","ro":"Cóng Bālí dào Běijīng hěn yuǎn.","lit":"depuis · Paris · jusqu'à · Pékin · très · loin"},{"fr":"Je regarde le paysage par la fenêtre.","tgt":"我看窗外的风景。","ro":"Wǒ kàn chuāng wài de fēngjǐng.","lit":"je · regarder · fenêtre · dehors · [possessif] · paysage"}],"tip":{"title":"« Cóng... dào... » : de... à...","example":"Ce train va de Pékin à Xi'an. — 这趟车<b>从</b>北京<b>到</b>西安。","body":"Pour dire de tel endroit à tel autre, le chinois utilise un duo très simple : « cóng », depuis, et « dào », jusqu'à. La construction ressemble beaucoup au français : « cóng Běijīng dào Xī'ān », de Pékin à Xi'an. Mot à mot, la phrase « Zhè tàng chē cóng Běijīng dào Xī'ān » donne : ce train, depuis Pékin, jusqu'à Xi'an. Remarquez qu'on n'a même pas besoin du verbe aller, le duo suffit. Et ce duo marche aussi pour le temps : « cóng xīngqīyī dào xīngqīwǔ », du lundi au vendredi, ou « cóng jiǔ diǎn dào shí diǎn », de neuf heures à dix heures. Pour demander la durée, ajoutez à la fin « yào jǐ ge xiǎoshí ? », il faut combien d'heures. Les deux mots ont un ton montant puis un ton descendant, « cóng » qui monte comme le train qui démarre, « dào » qui tombe comme le train qui arrive en gare. C'est une belle image pour les retenir.","exampleRo":"Zhè tàng chē cóng Běijīng dào Xī'ān.","lit":"ce · [classificateur] · train · depuis · Pékin · jusqu'à · Xi'an","say":{"Cóng... dào...":"从……到……","cóng":"从","dào":"到","cóng Běijīng dào Xī'ān":"从北京到西安","Zhè tàng chē cóng Běijīng dào Xī'ān":"这趟车从北京到西安","cóng xīngqīyī dào xīngqīwǔ":"从星期一到星期五","cóng jiǔ diǎn dào shí diǎn":"从九点到十点","yào jǐ ge xiǎoshí ?":"要几个小时？"}}},{"title":"Les guerriers de terre cuite","phrases":[{"fr":"Les guerriers de terre cuite sont à Xi'an.","tgt":"兵马俑在西安。","ro":"Bīngmǎyǒng zài Xī'ān.","lit":"guerriers de terre cuite · se trouver · Xi'an"},{"fr":"Deux entrées, s'il vous plaît.","tgt":"请给我两张票。","ro":"Qǐng gěi wǒ liǎng zhāng piào.","lit":"veuillez · donner · moi · deux · [classificateur] · billet"},{"fr":"Combien coûte une entrée ?","tgt":"一张票多少钱？","ro":"Yì zhāng piào duōshao qián?","lit":"un · [classificateur] · billet · combien · argent ?"},{"fr":"Il y a un guide qui parle français ?","tgt":"有法语导游吗？","ro":"Yǒu Fǎyǔ dǎoyóu ma?","lit":"avoir · français · guide · [question] ?"},{"fr":"Il y a tellement de guerriers !","tgt":"好多兵马俑啊！","ro":"Hǎo duō bīngmǎyǒng a!","lit":"très · nombreux · guerriers de terre cuite · [exclamation] !"},{"fr":"Chaque visage est différent.","tgt":"每张脸都不一样。","ro":"Měi zhāng liǎn dōu bù yíyàng.","lit":"chaque · [classificateur] · visage · tous · ne pas · pareil"},{"fr":"Ils sont très anciens.","tgt":"它们很古老。","ro":"Tāmen hěn gǔlǎo.","lit":"eux · très · ancien"},{"fr":"C'est le musée le plus célèbre de Xi'an.","tgt":"这是西安最有名的博物馆。","ro":"Zhè shì Xī'ān zuì yǒumíng de bówùguǎn.","lit":"ceci · être · Xi'an · le plus · célèbre · [possessif] · musée"},{"fr":"Notre guide est très chaleureux.","tgt":"我们的导游很热情。","ro":"Wǒmen de dǎoyóu hěn rèqíng.","lit":"nous · [possessif] · guide · très · chaleureux"},{"fr":"Cet endroit me plaît beaucoup.","tgt":"我很喜欢这个地方。","ro":"Wǒ hěn xǐhuan zhège dìfang.","lit":"je · très · aimer · ce · [classificateur] · endroit"}]},{"title":"À vélo sur les remparts de Xi'an","phrases":[{"fr":"Nous voici sur les remparts.","tgt":"我们到城墙了。","ro":"Wǒmen dào chéngqiáng le.","lit":"nous · arriver · remparts · [accompli]"},{"fr":"J'ai loué un vélo.","tgt":"我租了一辆自行车。","ro":"Wǒ zū le yí liàng zìxíngchē.","lit":"je · louer · [accompli] · un · [classificateur] · vélo"},{"fr":"Tu as acheté de l'eau ?","tgt":"你买水了吗？","ro":"Nǐ mǎi shuǐ le ma?","lit":"toi · acheter · eau · [accompli] · [question] ?"},{"fr":"Oui, j'ai pris deux bouteilles.","tgt":"买了，买了两瓶。","ro":"Mǎi le, mǎi le liǎng píng.","lit":"acheter · [accompli], acheter · [accompli] · deux · [classificateur]"},{"fr":"Les remparts sont très longs.","tgt":"城墙很长。","ro":"Chéngqiáng hěn cháng.","lit":"remparts · très · long"},{"fr":"Nous avons fait un tour complet à vélo.","tgt":"我们骑了一圈。","ro":"Wǒmen qí le yì quān.","lit":"nous · pédaler · [accompli] · un · tour"},{"fr":"J'ai pris plein de photos.","tgt":"我拍了很多照片。","ro":"Wǒ pāi le hěn duō zhàopiàn.","lit":"je · photographier · [accompli] · très · nombreux · photo"},{"fr":"Il est déjà six heures.","tgt":"已经六点了。","ro":"Yǐjīng liù diǎn le.","lit":"déjà · six · heure · [accompli]"},{"fr":"Tu as déjà dîné ?","tgt":"你吃晚饭了吗？","ro":"Nǐ chī wǎnfàn le ma?","lit":"toi · manger · dîner · [accompli] · [question] ?"},{"fr":"Pas encore, et j'ai très faim.","tgt":"还没有，我很饿。","ro":"Hái méiyǒu, wǒ hěn è.","lit":"encore · ne pas avoir, je · très · affamé"}],"tip":{"title":"« Le » : l'action accomplie","example":"J'ai loué un vélo. — 我租<b>了</b>一辆自行车。","body":"Puisque le verbe chinois ne se conjugue pas, comment dire qu'une action est faite ? On ajoute la petite syllabe « le », toute légère, sans ton, juste après le verbe. Elle signale que l'action est accomplie, un peu comme notre passé composé. Décomposons « Wǒ zū le yí liàng zìxíngchē » : je, louer, action faite, un, vélo, donc j'ai loué un vélo. Pour poser la question, on ajoute « ma » à la fin : « Nǐ mǎi shuǐ le ma ? », tu as acheté de l'eau ? Et pour répondre oui, on répète simplement le verbe avec « le » : « Mǎi le ». Attention au piège : à la forme négative, « le » disparaît, on dit « méiyǒu » ou « méi » devant le verbe, comme dans « Hái méiyǒu », pas encore. Enfin, « le » en fin de phrase peut aussi marquer un changement, comme dans « Yǐjīng liù diǎn le », il est déjà six heures. Retenez l'image d'une case que l'on coche : « le », c'est fait.","exampleRo":"Wǒ zū le yí liàng zìxíngchē.","lit":"je · louer · [accompli] · un · [classificateur] · vélo","say":{"Le":"了","le":"了","Wǒ zū le yí liàng zìxíngchē":"我租了一辆自行车","ma":"吗","Nǐ mǎi shuǐ le ma ?":"你买水了吗？","Mǎi le":"买了","méiyǒu":"没有","méi":"没","Hái méiyǒu":"还没有","Yǐjīng liù diǎn le":"已经六点了"}}},{"title":"Une valise égarée","phrases":[{"fr":"Ma valise n'est toujours pas arrivée.","tgt":"我的箱子还没到。","ro":"Wǒ de xiāngzi hái méi dào.","lit":"moi · [possessif] · valise · encore · ne pas · arriver"},{"fr":"Quel est votre numéro de vol ?","tgt":"您的航班号是多少？","ro":"Nín de hángbān hào shì duōshao?","lit":"vous · [possessif] · vol · numéro · être · combien ?"},{"fr":"Je viens de Paris.","tgt":"我从巴黎来。","ro":"Wǒ cóng Bālí lái.","lit":"je · depuis · Paris · venir"},{"fr":"C'est une grande valise rouge.","tgt":"是一个红色的大箱子。","ro":"Shì yí ge hóngsè de dà xiāngzi.","lit":"être · un · [classificateur] · rouge · [possessif] · grand · valise"},{"fr":"Qu'est-ce qu'il y a dedans ?","tgt":"里面有什么？","ro":"Lǐmiàn yǒu shénme?","lit":"dedans · avoir · quoi ?"},{"fr":"Des vêtements et des médicaments.","tgt":"衣服和药。","ro":"Yīfu hé yào.","lit":"vêtements · et · médicament"},{"fr":"Ne vous inquiétez pas.","tgt":"您别担心。","ro":"Nín bié dānxīn.","lit":"vous · ne pas · s'inquiéter"},{"fr":"Nous allons la chercher pour vous.","tgt":"我们帮您找。","ro":"Wǒmen bāng nín zhǎo.","lit":"nous · aider · vous · chercher"},{"fr":"Voici mon numéro de téléphone.","tgt":"这是我的电话号码。","ro":"Zhè shì wǒ de diànhuà hàomǎ.","lit":"ceci · être · moi · [possessif] · téléphone · numéro"},{"fr":"Je loge dans un hôtel près de la gare.","tgt":"我住在火车站旁边的酒店。","ro":"Wǒ zhù zài huǒchēzhàn pángbiān de jiǔdiàn.","lit":"je · loger · à · gare · à côté · [possessif] · hôtel"}]},{"title":"Demander son chemin","phrases":[{"fr":"Excusez-moi, comment va-t-on à la gare ?","tgt":"请问，火车站怎么走？","ro":"Qǐngwèn, huǒchēzhàn zěnme zǒu?","lit":"veuillez-demander, gare · comment · marcher ?"},{"fr":"Allez tout droit.","tgt":"一直走。","ro":"Yìzhí zǒu.","lit":"tout droit · marcher"},{"fr":"Après, vous tournez à gauche.","tgt":"然后往左拐。","ro":"Ránhòu wǎng zuǒ guǎi.","lit":"ensuite · vers · gauche · tourner"},{"fr":"Et pour aller au musée, c'est par où ?","tgt":"去博物馆怎么走？","ro":"Qù bówùguǎn zěnme zǒu?","lit":"aller · musée · comment · marcher ?"},{"fr":"Ce mot-là, on le dit comment en chinois ?","tgt":"这个用中文怎么说？","ro":"Zhège yòng Zhōngwén zěnme shuō?","lit":"ce · [classificateur] · utiliser · chinois · comment · dire ?"},{"fr":"Montrez-moi l'endroit sur le plan, s'il vous plaît.","tgt":"请在地图上指给我看。","ro":"Qǐng zài dìtú shang zhǐ gěi wǒ kàn.","lit":"veuillez · à · plan · dessus · montrer · à · moi · voir"},{"fr":"C'est ici, à côté du parc.","tgt":"在这儿，公园旁边。","ro":"Zài zhèr, gōngyuán pángbiān.","lit":"se trouver · ici, parc · à côté"},{"fr":"Je ne sais pas comment y aller.","tgt":"我不知道怎么去。","ro":"Wǒ bù zhīdào zěnme qù.","lit":"je · ne pas · savoir · comment · aller"},{"fr":"À pied, c'est loin ?","tgt":"走路远吗？","ro":"Zǒulù yuǎn ma?","lit":"marcher · loin · [question] ?"},{"fr":"Non, c'est à cinq minutes à pied.","tgt":"不远，走路五分钟。","ro":"Bù yuǎn, zǒulù wǔ fēnzhōng.","lit":"ne pas · loin, marcher · cinq · minute"}],"tip":{"title":"« Zěnme » : comment, et comment aller quelque part","example":"Excusez-moi, comment va-t-on à la gare ? — 请问，火车站<b>怎么</b>走？","body":"Le mot « zěnme » veut dire comment, et il se place juste devant le verbe dont on parle. C'est votre meilleur ami en voyage, grâce à la formule « zěnme zǒu », littéralement comment marcher, c'est-à-dire par où faut-il passer. On dit d'abord le lieu, puis la formule : « Huǒchēzhàn zěnme zǒu ? », la gare, comment marcher ? Pour être poli, commencez par « qǐngwèn », excusez-moi. Vous pouvez aussi dire « Qù bówùguǎn zěnme zǒu ? », pour aller au musée, comment fait-on. Avec d'autres verbes, « zěnme » marche pareil : « zěnme shuō », comment dire, ou « zěnme qù », comment y aller. Côté prononciation, le « z » se dit comme « dz », et « me » est très léger, sans ton. Pour retenir, pensez à un voyageur perdu qui se gratte la tête en disant « dzeune-me », comment je fais ?","exampleRo":"Qǐngwèn, huǒchēzhàn zěnme zǒu?","lit":"veuillez-demander, gare · comment · marcher ?","say":{"Zěnme":"怎么","zěnme":"怎么","zěnme zǒu":"怎么走","Huǒchēzhàn zěnme zǒu ?":"火车站怎么走？","qǐngwèn":"请问","Qù bówùguǎn zěnme zǒu ?":"去博物馆怎么走？","zěnme shuō":"怎么说","zěnme qù":"怎么去"}}},{"title":"À la pharmacie","phrases":[{"fr":"Où y a-t-il une pharmacie ?","tgt":"哪儿有药店？","ro":"Nǎr yǒu yàodiàn?","lit":"où · avoir · pharmacie ?"},{"fr":"Je ne me sens pas bien.","tgt":"我不舒服。","ro":"Wǒ bù shūfu.","lit":"je · ne pas · confortable"},{"fr":"J'ai mal à la tête.","tgt":"我头疼。","ro":"Wǒ tóu téng.","lit":"je · tête · douloureux"},{"fr":"J'ai un peu de fièvre.","tgt":"我有点儿发烧。","ro":"Wǒ yǒudiǎnr fāshāo.","lit":"je · un peu · avoir de la fièvre"},{"fr":"J'ai aussi mal au ventre.","tgt":"我肚子也疼。","ro":"Wǒ dùzi yě téng.","lit":"je · ventre · aussi · douloureux"},{"fr":"Prenez donc ce médicament.","tgt":"您吃这个药吧。","ro":"Nín chī zhège yào ba.","lit":"vous · manger · ce · [classificateur] · médicament · [suggestion]"},{"fr":"Deux fois par jour.","tgt":"一天两次。","ro":"Yì tiān liǎng cì.","lit":"un · jour · deux · fois"},{"fr":"À prendre après le repas.","tgt":"饭后吃。","ro":"Fàn hòu chī.","lit":"repas · après · manger"},{"fr":"Buvez beaucoup d'eau.","tgt":"多喝水。","ro":"Duō hē shuǐ.","lit":"beaucoup · boire · eau"},{"fr":"Et reposez-vous bien.","tgt":"好好休息。","ro":"Hǎohǎo xiūxi.","lit":"bien-bien · se reposer"}]},{"title":"Faire connaissance dans le train","phrases":[{"fr":"Je peux m'asseoir ici ?","tgt":"我可以坐这儿吗？","ro":"Wǒ kěyǐ zuò zhèr ma?","lit":"je · pouvoir · s'asseoir · ici · [question] ?"},{"fr":"Bien sûr, asseyez-vous.","tgt":"当然可以，请坐。","ro":"Dāngrán kěyǐ, qǐng zuò.","lit":"bien sûr · pouvoir, veuillez · s'asseoir"},{"fr":"Vous savez parler chinois ?","tgt":"您会说中文吗？","ro":"Nín huì shuō Zhōngwén ma?","lit":"vous · savoir · parler · chinois · [question] ?"},{"fr":"Je le parle un tout petit peu.","tgt":"我会说一点儿。","ro":"Wǒ huì shuō yìdiǎnr.","lit":"je · savoir · parler · un peu"},{"fr":"Vous pouvez parler un peu plus lentement ?","tgt":"您能说慢一点儿吗？","ro":"Nín néng shuō màn yìdiǎnr ma?","lit":"vous · pouvoir · parler · lent · un peu · [question] ?"},{"fr":"Tu sais te servir des baguettes ?","tgt":"你会用筷子吗？","ro":"Nǐ huì yòng kuàizi ma?","lit":"toi · savoir · utiliser · baguettes · [question] ?"},{"fr":"Je peux regarder votre plan ?","tgt":"我能看看您的地图吗？","ro":"Wǒ néng kànkan nín de dìtú ma?","lit":"je · pouvoir · regarder-regarder · vous · [possessif] · plan · [question] ?"},{"fr":"Ici, on n'a pas le droit de fumer.","tgt":"这儿不能抽烟。","ro":"Zhèr bù néng chōuyān.","lit":"ici · ne pas · pouvoir · fumer"},{"fr":"Je ne sais pas conduire.","tgt":"我不会开车。","ro":"Wǒ bú huì kāichē.","lit":"je · ne pas · savoir · conduire"},{"fr":"On peut échanger nos numéros ?","tgt":"我们可以交换电话号码吗？","ro":"Wǒmen kěyǐ jiāohuàn diànhuà hàomǎ ma?","lit":"nous · pouvoir · échanger · téléphone · numéro · [question] ?"}],"tip":{"title":"« Néng », « kěyǐ », « huì » : pouvoir et savoir","example":"Je peux m'asseoir ici ? — 我<b>可以</b>坐这儿吗？","body":"Là où le français n'a que pouvoir et savoir, le chinois distingue trois petits verbes, tous placés devant l'action. « Kěyǐ » sert à demander ou donner une permission : « Wǒ kěyǐ zuò zhèr ma ? », je, pouvoir, m'asseoir, ici, question, donc je peux m'asseoir ici ? On répond volontiers « Kěyǐ », c'est possible. « Néng » parle plutôt de capacité ou de possibilité concrète, comme dans « Nín néng shuō màn yìdiǎnr ma ? », vous pouvez parler un peu plus lentement ? Au négatif, « bù néng » signifie souvent c'est interdit : « Zhèr bù néng chōuyān », ici, on ne peut pas fumer. Enfin « huì » désigne ce qu'on a appris, un savoir-faire : « Wǒ huì shuō yìdiǎnr », je sais parler un peu. Attention, devant « huì », la négation « bù » se prononce « bú » : « Wǒ bú huì kāichē ». Pour retenir : « huì » pour ce que j'ai appris, « kěyǐ » pour ce qu'on m'autorise, « néng » pour ce qui est possible.","exampleRo":"Wǒ kěyǐ zuò zhèr ma?","lit":"je · pouvoir · s'asseoir · ici · [question] ?","say":{"Néng":"能","kěyǐ":"可以","huì":"会","Kěyǐ":"可以","Wǒ kěyǐ zuò zhèr ma ?":"我可以坐这儿吗？","Nín néng shuō màn yìdiǎnr ma ?":"您能说慢一点儿吗？","bù néng":"不能","Zhèr bù néng chōuyān":"这儿不能抽烟","Wǒ huì shuō yìdiǎnr":"我会说一点儿","bù":"不","Wǒ bú huì kāichē":"我不会开车","néng":"能"}}},{"title":"Shanghai : le soir sur le Bund","phrases":[{"fr":"Nous voici enfin à Shanghai !","tgt":"我们到上海了！","ro":"Wǒmen dào Shànghǎi le!","lit":"nous · arriver · Shanghai · [accompli] !"},{"fr":"Ce soir, on va sur le Bund.","tgt":"今天晚上我们去外滩。","ro":"Jīntiān wǎnshang wǒmen qù Wàitān.","lit":"aujourd'hui · soir · nous · aller · Bund"},{"fr":"Le Bund longe le fleuve.","tgt":"外滩在江边。","ro":"Wàitān zài jiāng biān.","lit":"Bund · se trouver · fleuve · bord"},{"fr":"Il y a beaucoup de monde ce soir.","tgt":"今晚人很多。","ro":"Jīnwǎn rén hěn duō.","lit":"ce soir · gens · très · nombreux"},{"fr":"Ces vieux bâtiments sont superbes.","tgt":"这些老建筑很漂亮。","ro":"Zhèxiē lǎo jiànzhù hěn piàoliang.","lit":"ces · vieux · bâtiment · très · beau"},{"fr":"En face, c'est Pudong.","tgt":"对面是浦东。","ro":"Duìmiàn shì Pǔdōng.","lit":"en face · être · Pudong"},{"fr":"Les lumières sont magnifiques.","tgt":"灯光真美。","ro":"Dēngguāng zhēn měi.","lit":"lumière · vraiment · beau"},{"fr":"Faisons une petite promenade.","tgt":"我们散散步吧。","ro":"Wǒmen sànsan bù ba.","lit":"nous · se promener un peu · [suggestion]"},{"fr":"Il fait un peu chaud.","tgt":"有点儿热。","ro":"Yǒudiǎnr rè.","lit":"un peu · chaud"},{"fr":"Shanghai est vraiment moderne.","tgt":"上海真现代。","ro":"Shànghǎi zhēn xiàndài.","lit":"Shanghai · vraiment · moderne"}]},{"title":"Prendre le métro à Shanghai","phrases":[{"fr":"Prenons le métro.","tgt":"我们坐地铁吧。","ro":"Wǒmen zuò dìtiě ba.","lit":"nous · prendre · métro · [suggestion]"},{"fr":"Je vais à Pudong en métro.","tgt":"我坐地铁去浦东。","ro":"Wǒ zuò dìtiě qù Pǔdōng.","lit":"je · prendre · métro · aller · Pudong"},{"fr":"Quelle ligne faut-il prendre ?","tgt":"坐几号线？","ro":"Zuò jǐ hào xiàn?","lit":"prendre · combien · numéro · ligne ?"},{"fr":"Prenez la ligne deux.","tgt":"坐二号线。","ro":"Zuò èr hào xiàn.","lit":"prendre · deux · numéro · ligne"},{"fr":"On peut aussi prendre le bus.","tgt":"也可以坐公交车。","ro":"Yě kěyǐ zuò gōngjiāochē.","lit":"aussi · pouvoir · prendre · bus"},{"fr":"Le bus, c'est lent.","tgt":"公交车很慢。","ro":"Gōngjiāochē hěn màn.","lit":"bus · très · lent"},{"fr":"Demain, je prends le train pour Hangzhou.","tgt":"明天我坐火车去杭州。","ro":"Míngtiān wǒ zuò huǒchē qù Hángzhōu.","lit":"demain · je · prendre · train · aller · Hangzhou"},{"fr":"En taxi, ce serait plus rapide.","tgt":"坐出租车更快。","ro":"Zuò chūzūchē gèng kuài.","lit":"prendre · taxi · plus · rapide"},{"fr":"Je prends l'avion après-demain.","tgt":"我后天坐飞机。","ro":"Wǒ hòutiān zuò fēijī.","lit":"je · après-demain · prendre · avion"},{"fr":"Où est la station de métro ?","tgt":"地铁站在哪儿？","ro":"Dìtiězhàn zài nǎr?","lit":"métro-station · se trouver · où ?"}],"tip":{"title":"« Zuò » + moyen de transport : prendre le train, le bus","example":"Je vais à Pudong en métro. — 我<b>坐</b>地铁去浦东。","body":"En chinois, on ne prend pas le métro, on s'y assoit ! Le verbe « zuò », avec un ton descendant, veut d'abord dire s'asseoir, et on l'utilise pour tous les transports où l'on est passager : « zuò dìtiě », le métro, « zuò gōngjiāochē », le bus, « zuò huǒchē », le train, « zuò fēijī », l'avion. L'ordre des mots est très logique : d'abord le moyen, ensuite le déplacement. Décomposons « Wǒ zuò dìtiě qù Pǔdōng » : je, prendre le métro, aller, Pudong. On dit donc comment on y va avant de dire où l'on va, alors qu'en français on dit je vais à Pudong en métro. Le mot de temps, lui, se place toujours devant : « Míngtiān wǒ zuò huǒchē qù Hángzhōu ». Pour le vélo, en revanche, on l'enfourche, on dit « qí zìxíngchē ». Pour retenir, imaginez-vous bien assis dans un wagon : « zuò », je m'assois, et c'est parti.","exampleRo":"Wǒ zuò dìtiě qù Pǔdōng.","lit":"je · prendre · métro · aller · Pudong","say":{"Zuò":"坐","zuò":"坐","zuò dìtiě":"坐地铁","zuò gōngjiāochē":"坐公交车","zuò huǒchē":"坐火车","zuò fēijī":"坐飞机","Wǒ zuò dìtiě qù Pǔdōng":"我坐地铁去浦东","Míngtiān wǒ zuò huǒchē qù Hángzhōu":"明天我坐火车去杭州","qí zìxíngchē":"骑自行车"}}},{"title":"Pudong vu d'en haut","phrases":[{"fr":"Cette tour est très haute.","tgt":"这座楼很高。","ro":"Zhè zuò lóu hěn gāo.","lit":"ce · [classificateur] · bâtiment · très · haut"},{"fr":"Montons voir là-haut.","tgt":"我们上去看看吧。","ro":"Wǒmen shàngqu kànkan ba.","lit":"nous · monter · regarder-regarder · [suggestion]"},{"fr":"L'ascenseur va très vite.","tgt":"电梯很快。","ro":"Diàntī hěn kuài.","lit":"ascenseur · très · rapide"},{"fr":"On voit toute la ville.","tgt":"能看到整个城市。","ro":"Néng kàndào zhěnggè chéngshì.","lit":"pouvoir · voir · entier · ville"},{"fr":"Regarde, là-bas, c'est le Bund !","tgt":"你看，那边是外滩！","ro":"Nǐ kàn, nàbiān shì Wàitān!","lit":"toi · regarder, là-bas · être · Bund !"},{"fr":"Le fleuve Huangpu est très beau.","tgt":"黄浦江很美。","ro":"Huángpǔ Jiāng hěn měi.","lit":"Huangpu · fleuve · très · beau"},{"fr":"Ça me fait un peu peur.","tgt":"我有点儿害怕。","ro":"Wǒ yǒudiǎnr hàipà.","lit":"je · un peu · avoir peur"},{"fr":"N'aie pas peur, c'est sans danger.","tgt":"别怕，很安全。","ro":"Bié pà, hěn ānquán.","lit":"ne pas · avoir peur, très · sûr"},{"fr":"Il y a un café tout en haut.","tgt":"上面有一家咖啡馆。","ro":"Shàngmiàn yǒu yì jiā kāfēiguǎn.","lit":"en haut · avoir · un · [classificateur] · café"},{"fr":"Je voudrais un café chaud.","tgt":"我要一杯热咖啡。","ro":"Wǒ yào yì bēi rè kāfēi.","lit":"je · vouloir · un · [classificateur] · chaud · café"}]},{"title":"Hangzhou et le lac de l'Ouest","phrases":[{"fr":"Le lac de l'Ouest se trouve à Hangzhou.","tgt":"西湖在杭州。","ro":"Xīhú zài Hángzhōu.","lit":"lac de l'Ouest · se trouver · Hangzhou"},{"fr":"Hangzhou est tout près de Shanghai.","tgt":"杭州离上海很近。","ro":"Hángzhōu lí Shànghǎi hěn jìn.","lit":"Hangzhou · distant de · Shanghai · très · proche"},{"fr":"L'hôtel est loin du lac ?","tgt":"酒店离西湖远吗？","ro":"Jiǔdiàn lí Xīhú yuǎn ma?","lit":"hôtel · distant de · lac de l'Ouest · loin · [question] ?"},{"fr":"Non, il est juste à côté.","tgt":"不远，很近。","ro":"Bù yuǎn, hěn jìn.","lit":"ne pas · loin, très · proche"},{"fr":"C'est loin d'ici ?","tgt":"离这儿远吗？","ro":"Lí zhèr yuǎn ma?","lit":"distant de · ici · loin · [question] ?"},{"fr":"La gare est à deux kilomètres d'ici.","tgt":"火车站离这儿两公里。","ro":"Huǒchēzhàn lí zhèr liǎng gōnglǐ.","lit":"gare · distant de · ici · deux · kilomètre"},{"fr":"Louons une barque.","tgt":"我们租一条船吧。","ro":"Wǒmen zū yì tiáo chuán ba.","lit":"nous · louer · un · [classificateur] · bateau · [suggestion]"},{"fr":"Le lac est si calme.","tgt":"湖面很平静。","ro":"Húmiàn hěn píngjìng.","lit":"lac-surface · très · calme"},{"fr":"Chez moi, c'est très loin de la Chine.","tgt":"我家离中国很远。","ro":"Wǒ jiā lí Zhōngguó hěn yuǎn.","lit":"je · maison · distant de · Chine · très · loin"},{"fr":"Le thé Longjing vient d'ici.","tgt":"龙井茶是这儿的。","ro":"Lóngjǐng chá shì zhèr de.","lit":"Longjing · thé · être · ici · [possessif]"}],"tip":{"title":"« Lí » : la distance, c'est loin d'ici","example":"Hangzhou est tout près de Shanghai. — 杭州<b>离</b>上海很近。","body":"Pour parler de distance, le chinois utilise le petit mot « lí », au ton montant, qui veut dire être éloigné de. La phrase se construit toujours dans le même ordre : le premier lieu, puis « lí », puis le second lieu, puis loin ou près. Loin se dit « yuǎn », près se dit « jìn ». Décomposons « Hángzhōu lí Shànghǎi hěn jìn » : Hangzhou, distant de, Shanghai, très, proche. Notez le petit « hěn » devant l'adjectif, il ne veut pas vraiment dire très ici, il rend simplement la phrase naturelle. La question la plus utile en voyage est « Lí zhèr yuǎn ma ? », c'est loin d'ici ? On peut aussi donner une distance précise : « Huǒchēzhàn lí zhèr liǎng gōnglǐ », la gare est à deux kilomètres d'ici. Attention, ne confondez pas « lí », la distance, et « cóng », le point de départ d'un trajet. Pour retenir, pensez à une ligne tendue entre deux villes : « lí » est ce fil qui les relie.","exampleRo":"Hángzhōu lí Shànghǎi hěn jìn.","lit":"Hangzhou · distant de · Shanghai · très · proche","say":{"Lí":"离","lí":"离","yuǎn":"远","jìn":"近","Hángzhōu lí Shànghǎi hěn jìn":"杭州离上海很近","hěn":"很","Lí zhèr yuǎn ma ?":"离这儿远吗？","Huǒchēzhàn lí zhèr liǎng gōnglǐ":"火车站离这儿两公里","cóng":"从"}}},{"title":"Un vol retardé","phrases":[{"fr":"Mon vol a du retard.","tgt":"我的航班晚点了。","ro":"Wǒ de hángbān wǎndiǎn le.","lit":"moi · [possessif] · vol · en retard · [accompli]"},{"fr":"Combien de temps de retard ?","tgt":"要晚多久？","ro":"Yào wǎn duō jiǔ?","lit":"falloir · en retard · combien · longtemps ?"},{"fr":"Environ deux heures.","tgt":"大概两个小时。","ro":"Dàgài liǎng ge xiǎoshí.","lit":"environ · deux · [classificateur] · heure"},{"fr":"Pas de chance !","tgt":"真倒霉！","ro":"Zhēn dǎoméi!","lit":"vraiment · malchanceux !"},{"fr":"La porte d'embarquement a changé.","tgt":"登机口换了。","ro":"Dēngjīkǒu huàn le.","lit":"embarquer-porte · changer · [accompli]"},{"fr":"Maintenant, c'est la porte vingt.","tgt":"现在是二十号登机口。","ro":"Xiànzài shì èrshí hào dēngjīkǒu.","lit":"maintenant · être · vingt · numéro · porte d'embarquement"},{"fr":"Où est-ce que je peux recharger mon téléphone ?","tgt":"哪儿可以给手机充电？","ro":"Nǎr kěyǐ gěi shǒujī chōngdiàn?","lit":"où · pouvoir · pour · téléphone · charger-électricité ?"},{"fr":"J'ai faim, allons grignoter quelque chose.","tgt":"我饿了，我们去吃点儿东西吧。","ro":"Wǒ è le, wǒmen qù chī diǎnr dōngxi ba.","lit":"je · affamé · [accompli], nous · aller · manger · un peu · chose · [suggestion]"},{"fr":"L'embarquement commence.","tgt":"开始登机了。","ro":"Kāishǐ dēngjī le.","lit":"commencer · embarquer · [accompli]"},{"fr":"Enfin, on décolle !","tgt":"终于出发了！","ro":"Zhōngyú chūfā le!","lit":"enfin · partir · [accompli] !"}]},{"title":"Fin du module : un bilan de voyage","phrases":[{"fr":"J'ai visité beaucoup d'endroits en Chine.","tgt":"我在中国去过很多地方。","ro":"Wǒ zài Zhōngguó qù guo hěn duō dìfang.","lit":"je · à · Chine · aller · [expérience] · très · nombreux · endroit"},{"fr":"Je suis déjà allé à la Grande Muraille.","tgt":"我去过长城。","ro":"Wǒ qù guo Chángchéng.","lit":"je · aller · [expérience] · Grande Muraille"},{"fr":"Tu es déjà allé à Hangzhou ?","tgt":"你去过杭州吗？","ro":"Nǐ qù guo Hángzhōu ma?","lit":"toi · aller · [expérience] · Hangzhou · [question] ?"},{"fr":"Avant, je n'avais jamais mangé de canard laqué.","tgt":"我以前没吃过烤鸭。","ro":"Wǒ yǐqián méi chī guo kǎoyā.","lit":"je · avant · ne pas · manger · [expérience] · canard rôti"},{"fr":"Maintenant, je sais demander mon chemin en chinois.","tgt":"现在我会用中文问路了。","ro":"Xiànzài wǒ huì yòng Zhōngwén wèn lù le.","lit":"maintenant · je · savoir · utiliser · chinois · demander · chemin · [accompli]"},{"fr":"Je sais aussi acheter des billets.","tgt":"我也会买票了。","ro":"Wǒ yě huì mǎi piào le.","lit":"je · aussi · savoir · acheter · billet · [accompli]"},{"fr":"Ce voyage a été génial !","tgt":"这次旅行太棒了！","ro":"Zhè cì lǚxíng tài bàng le!","lit":"ce · fois · voyage · trop · génial · [exclamation] !"},{"fr":"Le prochain module parle d'amitié et de rencontres.","tgt":"下一个单元讲交朋友。","ro":"Xià yí ge dānyuán jiǎng jiāo péngyou.","lit":"prochain · un · [classificateur] · unité · parler de · se faire · amis"},{"fr":"Tu as fait de grands progrès !","tgt":"你进步很大！","ro":"Nǐ jìnbù hěn dà!","lit":"toi · progrès · très · grand !"},{"fr":"À la prochaine fois !","tgt":"下次见！","ro":"Xià cì jiàn!","lit":"prochain · fois · se voir !"}],"tip":{"title":"« Guo » : l'expérience, j'y suis déjà allé","example":"Je suis déjà allé à la Grande Muraille. — 我去<b>过</b>长城。","body":"Pour raconter une expérience vécue, le chinois place la petite syllabe « guo », sans ton, juste après le verbe. Elle répond à la question : est-ce que cela vous est déjà arrivé au moins une fois dans la vie ? Décomposons « Wǒ qù guo Chángchéng » : je, aller, déjà vécu, Grande Muraille, donc je suis déjà allé à la Grande Muraille. Pour interroger quelqu'un, on ajoute « ma » : « Nǐ qù guo Hángzhōu ma ? », tu es déjà allé à Hangzhou ? Pour dire jamais, on met « méi » devant le verbe et on garde « guo » : « Wǒ méi chī guo kǎoyā », je n'ai jamais mangé de canard laqué. Quelle différence avec « le » ? « Le » dit qu'une action précise est terminée, alors que « guo » parle de votre expérience en général. Pour retenir, imaginez que « guo » est un tampon sur votre passeport : la preuve que vous y êtes déjà passé.","exampleRo":"Wǒ qù guo Chángchéng.","lit":"je · aller · [expérience] · Grande Muraille","say":{"Guo":"过","guo":"过","Wǒ qù guo Chángchéng":"我去过长城","ma":"吗","Nǐ qù guo Hángzhōu ma ?":"你去过杭州吗？","méi":"没","Wǒ méi chī guo kǎoyā":"我没吃过烤鸭","le":"了","Le":"了"}}}]},{"id":3,"name":"Conversation sociale","desc":"Faire connaissance, se présenter, échanger avec aisance.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Se présenter à Chengdu","phrases":[{"fr":"Bonjour, moi, c'est Paul.","tgt":"你好，我是保罗。","ro":"Nǐ hǎo, wǒ shì Bǎoluó.","lit":"toi · bien, je · être · Paul"},{"fr":"Je suis français, de Lyon.","tgt":"我是法国里昂人。","ro":"Wǒ shì Fǎguó Lǐ'áng rén.","lit":"je · être · France · Lyon · personne"},{"fr":"Je travaille ici, à Chengdu.","tgt":"我在成都工作。","ro":"Wǒ zài Chéngdū gōngzuò.","lit":"je · à · Chengdu · travailler"},{"fr":"Et toi, tu viens d'où ?","tgt":"你呢？你是哪里人？","ro":"Nǐ ne? Nǐ shì nǎlǐ rén?","lit":"toi · [et ... ?] ? toi · être · où · personne ?"},{"fr":"Moi, je suis de Chengdu.","tgt":"我是成都人。","ro":"Wǒ shì Chéngdū rén.","lit":"je · être · Chengdu · personne"},{"fr":"Je suis content de te rencontrer.","tgt":"很高兴认识你。","ro":"Hěn gāoxìng rènshi nǐ.","lit":"très · content · connaître · toi"},{"fr":"Ton chinois est vraiment bon !","tgt":"你的中文很好！","ro":"Nǐ de Zhōngwén hěn hǎo!","lit":"toi · [possessif] · chinois · très · bien !"},{"fr":"Oh non, je parle juste un petit peu.","tgt":"哪里，我只会说一点儿。","ro":"Nǎlǐ, wǒ zhǐ huì shuō yìdiǎnr.","lit":"où (= mais non), je · seulement · savoir · parler · un peu"},{"fr":"Tu es en Chine depuis longtemps ?","tgt":"你来中国很久了吗？","ro":"Nǐ lái Zhōngguó hěn jiǔ le ma?","lit":"toi · venir · Chine · très · longtemps · [accompli] · [question] ?"},{"fr":"Non, je suis là depuis un mois seulement.","tgt":"不，我刚来一个月。","ro":"Bù, wǒ gāng lái yí ge yuè.","lit":"non, je · juste · venir · un · [classificateur] · mois"}]},{"title":"Mon nom, mon prénom","phrases":[{"fr":"Bonjour, quel est votre nom de famille ?","tgt":"您好，您贵姓？","ro":"Nín hǎo, nín guìxìng?","lit":"vous · bien, vous · précieux · nom de famille ?"},{"fr":"Mon nom de famille, c'est Wang.","tgt":"我姓王。","ro":"Wǒ xìng Wáng.","lit":"je · avoir pour nom de famille · Wang"},{"fr":"Je m'appelle Wang Lei.","tgt":"我叫王磊。","ro":"Wǒ jiào Wáng Lěi.","lit":"je · s'appeler · Wang · Lei"},{"fr":"Et toi, c'est quoi ton nom ?","tgt":"你叫什么名字？","ro":"Nǐ jiào shénme míngzi?","lit":"toi · s'appeler · quel · nom ?"},{"fr":"Moi, je m'appelle Marie.","tgt":"我叫玛丽。","ro":"Wǒ jiào Mǎlì.","lit":"je · s'appeler · Marie"},{"fr":"Mon nom chinois, c'est Ma Li.","tgt":"我的中文名字叫马丽。","ro":"Wǒ de Zhōngwén míngzi jiào Mǎ Lì.","lit":"je · [possessif] · chinois · nom · s'appeler · Ma · Li"},{"fr":"Alors ton nom de famille, c'est Ma ?","tgt":"你姓马吗？","ro":"Nǐ xìng Mǎ ma?","lit":"toi · avoir pour nom de famille · Ma · [question] ?"},{"fr":"Monsieur Wang, ravi de vous connaître.","tgt":"王先生，认识您很高兴。","ro":"Wáng xiānsheng, rènshi nín hěn gāoxìng.","lit":"Wang · monsieur, connaître · vous · très · content"},{"fr":"Comment s'appelle ton ami ?","tgt":"你朋友叫什么？","ro":"Nǐ péngyou jiào shénme?","lit":"toi · ami · s'appeler · quoi ?"},{"fr":"Il s'appelle Zhang Wei.","tgt":"他叫张伟。","ro":"Tā jiào Zhāng Wěi.","lit":"il · s'appeler · Zhang · Wei"}],"tip":{"title":"Se présenter : « jiào », « xìng », et le nom de famille en premier","example":"Mon nom de famille, c'est Wang. — 我<b>姓</b>王。","body":"Pour dire son nom en chinois, on utilise deux verbes différents. « Jiào » veut dire « s'appeler » et se dit avec le nom complet : « Wǒ jiào Wáng Lěi », mot à mot « je s'appeler Wang Lei ». « Xìng » veut dire « avoir pour nom de famille » : « Wǒ xìng Wáng » signifie « mon nom de famille est Wang ». Attention, en chinois le nom de famille vient toujours en premier, puis le prénom : dans « Wáng Lěi », Wang est le nom de famille et Lei le prénom. C'est comme l'appel en classe en français, quand le professeur dit « Martin Claire ». Pour demander poliment le nom de quelqu'un, on dit « Nín guìxìng ? », littéralement « votre précieux nom de famille ? ». Entre amis, on demande plutôt « Nǐ jiào shénme míngzi ? », « tu t'appelles quel nom ? ». Pour retenir : « jiào » pour le nom entier, « xìng » pour la famille seulement.","exampleRo":"Wǒ xìng Wáng.","lit":"je · avoir pour nom de famille · Wang","say":{"jiào":"叫","xìng":"姓","Jiào":"叫","Wǒ jiào Wáng Lěi":"我叫王磊","Xìng":"姓","Wǒ xìng Wáng":"我姓王","Wáng Lěi":"王磊","Nín guìxìng ?":"您贵姓？","Nǐ jiào shénme míngzi ?":"你叫什么名字？"}}},{"title":"Faire connaissance au parc","phrases":[{"fr":"Quel beau temps aujourd'hui !","tgt":"今天天气真好！","ro":"Jīntiān tiānqì zhēn hǎo!","lit":"aujourd'hui · temps · vraiment · bien !"},{"fr":"Tu viens souvent dans ce parc ?","tgt":"你常来这个公园吗？","ro":"Nǐ cháng lái zhège gōngyuán ma?","lit":"toi · souvent · venir · ce · [classificateur] · parc · [question] ?"},{"fr":"Oui, je viens tous les matins.","tgt":"对，我每天早上都来。","ro":"Duì, wǒ měitiān zǎoshang dōu lái.","lit":"oui, je · chaque jour · matin · tous · venir"},{"fr":"Le parc du Peuple est très grand.","tgt":"人民公园很大。","ro":"Rénmín Gōngyuán hěn dà.","lit":"peuple · parc · très · grand"},{"fr":"Ici, beaucoup de gens dansent.","tgt":"这里很多人跳舞。","ro":"Zhèlǐ hěn duō rén tiàowǔ.","lit":"ici · très · nombreux · gens · danser"},{"fr":"Tu es étudiant, toi ?","tgt":"你是学生吗？","ro":"Nǐ shì xuésheng ma?","lit":"toi · être · étudiant · [question] ?"},{"fr":"Non, je travaille déjà.","tgt":"不是，我已经工作了。","ro":"Bú shì, wǒ yǐjīng gōngzuò le.","lit":"ne pas · être, je · déjà · travailler · [accompli]"},{"fr":"Tu habites près d'ici ?","tgt":"你住在这附近吗？","ro":"Nǐ zhù zài zhè fùjìn ma?","lit":"toi · habiter · à · ici · environs · [question] ?"},{"fr":"Oui, à cinq minutes à pied.","tgt":"对，走路五分钟。","ro":"Duì, zǒulù wǔ fēnzhōng.","lit":"oui, marcher · cinq · minute"},{"fr":"On échange nos numéros ?","tgt":"我们留个电话吧？","ro":"Wǒmen liú ge diànhuà ba?","lit":"nous · laisser · [classificateur] · téléphone · [suggestion] ?"}]},{"title":"Ce que j'aime","phrases":[{"fr":"J'aime beaucoup Chengdu.","tgt":"我很喜欢成都。","ro":"Wǒ hěn xǐhuan Chéngdū.","lit":"je · très · aimer · Chengdu"},{"fr":"Tu aimes la cuisine du Sichuan ?","tgt":"你喜欢川菜吗？","ro":"Nǐ xǐhuan chuāncài ma?","lit":"toi · aimer · Sichuan-plat · [question] ?"},{"fr":"Oui, j'adore manger épicé.","tgt":"对，我特别喜欢吃辣的。","ro":"Duì, wǒ tèbié xǐhuan chī là de.","lit":"oui, je · particulièrement · aimer · manger · épicé · [chose]"},{"fr":"Je n'aime pas trop le café.","tgt":"我不喜欢喝咖啡。","ro":"Wǒ bù xǐhuan hē kāfēi.","lit":"je · ne pas · aimer · boire · café"},{"fr":"Moi, ce que j'aime, c'est le thé.","tgt":"我喜欢喝茶。","ro":"Wǒ xǐhuan hē chá.","lit":"je · aimer · boire · thé"},{"fr":"Qu'est-ce que tu aimes faire ?","tgt":"你喜欢做什么？","ro":"Nǐ xǐhuan zuò shénme?","lit":"toi · aimer · faire · quoi ?"},{"fr":"J'aime me promener au parc.","tgt":"我喜欢在公园散步。","ro":"Wǒ xǐhuan zài gōngyuán sànbù.","lit":"je · aimer · à · parc · se promener"},{"fr":"Ma femme adore les pandas.","tgt":"我太太喜欢熊猫。","ro":"Wǒ tàitai xǐhuan xióngmāo.","lit":"je · épouse · aimer · panda"},{"fr":"Qui n'aime pas les pandas ?","tgt":"谁不喜欢熊猫呢？","ro":"Shéi bù xǐhuan xióngmāo ne?","lit":"qui · ne pas · aimer · panda · [question] ?"},{"fr":"Tu aimes jouer au mahjong ?","tgt":"你喜欢打麻将吗？","ro":"Nǐ xǐhuan dǎ májiàng ma?","lit":"toi · aimer · jouer · mahjong · [question] ?"}],"tip":{"title":"« Xǐhuan » : aimer","example":"J'aime beaucoup Chengdu. — 我很<b>喜欢</b>成都。","body":"« Xǐhuan » signifie « aimer », au sens d'apprécier quelque chose ou quelqu'un. Il se prononce en deux syllabes : « xǐ », qui descend puis remonte, et « huan », très léger, sans ton. Comme tous les verbes chinois, il ne se conjugue jamais : « wǒ xǐhuan », « nǐ xǐhuan », « tā xǐhuan », c'est toujours la même forme. Après « xǐhuan », on peut mettre une chose, comme « Wǒ xǐhuan xióngmāo », j'aime les pandas, ou une action : « Wǒ xǐhuan hē chá », mot à mot « je aimer boire thé ». Pour dire qu'on n'aime pas, on ajoute simplement « bù » devant : « Wǒ bù xǐhuan kāfēi ». Pour dire qu'on aime beaucoup, on place « hěn » devant : « Wǒ hěn xǐhuan Chéngdū ». Et pour poser la question, il suffit d'ajouter « ma » à la fin : « Nǐ xǐhuan dǎ májiàng ma ? ». Astuce : retenez la formule « moi, xǐhuan, ce que j'aime », dans le même ordre qu'en français.","exampleRo":"Wǒ hěn xǐhuan Chéngdū.","lit":"je · très · aimer · Chengdu","say":{"Xǐhuan":"喜欢","xǐ":"喜","wǒ xǐhuan":"我喜欢","nǐ xǐhuan":"你喜欢","tā xǐhuan":"他喜欢","xǐhuan":"喜欢","Wǒ xǐhuan xióngmāo":"我喜欢熊猫","Wǒ xǐhuan hē chá":"我喜欢喝茶","bù":"不","Wǒ bù xǐhuan kāfēi":"我不喜欢咖啡","hěn":"很","Wǒ hěn xǐhuan Chéngdū":"我很喜欢成都","ma":"吗","Nǐ xǐhuan dǎ májiàng ma ?":"你喜欢打麻将吗？"}}},{"title":"Une matinée chez les pandas","phrases":[{"fr":"Demain, on va voir les pandas ?","tgt":"明天我们去看熊猫吧？","ro":"Míngtiān wǒmen qù kàn xióngmāo ba?","lit":"demain · nous · aller · voir · panda · [suggestion] ?"},{"fr":"La base des pandas, c'est loin ?","tgt":"熊猫基地远吗？","ro":"Xióngmāo jīdì yuǎn ma?","lit":"panda · base · loin · [question] ?"},{"fr":"Pas trop, une heure en voiture.","tgt":"不远，开车一个小时。","ro":"Bù yuǎn, kāichē yí ge xiǎoshí.","lit":"ne pas · loin, conduire · un · [classificateur] · heure"},{"fr":"Le mieux, c'est d'y aller le matin.","tgt":"最好早上去。","ro":"Zuìhǎo zǎoshang qù.","lit":"le mieux · matin · aller"},{"fr":"Le matin, les pandas mangent.","tgt":"早上熊猫吃东西。","ro":"Zǎoshang xióngmāo chī dōngxi.","lit":"matin · panda · manger · chose"},{"fr":"L'après-midi, ils dorment.","tgt":"下午它们睡觉。","ro":"Xiàwǔ tāmen shuìjiào.","lit":"après-midi · eux (animaux) · dormir"},{"fr":"Regarde, un bébé panda !","tgt":"你看，熊猫宝宝！","ro":"Nǐ kàn, xióngmāo bǎobao!","lit":"toi · regarder, panda · bébé !"},{"fr":"Qu'il est mignon !","tgt":"真可爱！","ro":"Zhēn kě'ài!","lit":"vraiment · mignon !"},{"fr":"Je peux prendre une photo ?","tgt":"我可以拍照吗？","ro":"Wǒ kěyǐ pāizhào ma?","lit":"je · pouvoir · prendre photo · [question] ?"},{"fr":"Il y a combien de pandas ici ?","tgt":"这里有多少只熊猫？","ro":"Zhèlǐ yǒu duōshao zhī xióngmāo?","lit":"ici · avoir · combien · [classificateur] · panda ?"}]},{"title":"Ma famille","phrases":[{"fr":"Dans ta famille, vous êtes combien ?","tgt":"你家有几口人？","ro":"Nǐ jiā yǒu jǐ kǒu rén?","lit":"toi · famille · avoir · combien · [classificateur] · personne ?"},{"fr":"Chez moi, on est quatre.","tgt":"我家有四口人。","ro":"Wǒ jiā yǒu sì kǒu rén.","lit":"je · famille · avoir · quatre · [classificateur] · personne"},{"fr":"Papa, maman, ma grande sœur et moi.","tgt":"爸爸、妈妈、姐姐和我。","ro":"Bàba, māma, jiějie hé wǒ.","lit":"papa, maman, grande sœur · et · moi"},{"fr":"Mon grand frère habite à Pékin.","tgt":"我哥哥住在北京。","ro":"Wǒ gēge zhù zài Běijīng.","lit":"je · grand frère · habiter · à · Pékin"},{"fr":"Que fait ta grande sœur comme travail ?","tgt":"你姐姐做什么工作？","ro":"Nǐ jiějie zuò shénme gōngzuò?","lit":"toi · grande sœur · faire · quel · travail ?"},{"fr":"Elle est prof dans un lycée.","tgt":"她是高中老师。","ro":"Tā shì gāozhōng lǎoshī.","lit":"elle · être · lycée · professeur"},{"fr":"Mon papa adore le mahjong.","tgt":"我爸爸喜欢打麻将。","ro":"Wǒ bàba xǐhuan dǎ májiàng.","lit":"je · papa · aimer · jouer · mahjong"},{"fr":"Ma maman cuisine très bien.","tgt":"我妈妈做饭很好吃。","ro":"Wǒ māma zuò fàn hěn hǎochī.","lit":"je · maman · faire · repas · très · bon"},{"fr":"Tu as une photo de ta famille ?","tgt":"你有家人的照片吗？","ro":"Nǐ yǒu jiārén de zhàopiàn ma?","lit":"toi · avoir · famille · [possessif] · photo · [question] ?"},{"fr":"Voici mon grand frère et sa femme.","tgt":"这是我哥哥和嫂子。","ro":"Zhè shì wǒ gēge hé sǎozi.","lit":"ceci · être · je · grand frère · et · belle-sœur"}],"tip":{"title":"La famille : « bàba, māma, gēge, jiějie »","example":"Mon grand frère habite à Pékin. — 我<b>哥哥</b>住在北京。","body":"Les mots de la famille en chinois sont faciles à dire, car la plupart répètent simplement une syllabe. « Bàba » veut dire papa et « māma » maman, presque comme en français ! Pour les frères et sœurs, le chinois précise toujours s'ils sont plus âgés ou plus jeunes : « gēge » est le grand frère, « jiějie » la grande sœur, « dìdi » le petit frère et « mèimei » la petite sœur. Il n'y a donc pas de mot courant pour dire juste « frère » ou « sœur ». La deuxième syllabe se prononce toujours légèrement, sans ton. Pour dire « mon papa », on dit simplement « wǒ bàba », mot à mot « moi papa », sans rien entre les deux quand il s'agit de proches. Par exemple, « Wǒ gēge zhù zài Běijīng » signifie « mon grand frère habite à Pékin ». Astuce : « dìdi » et « mèimei », les cadets, commencent par un ton qui descend, comme si l'on se penchait vers les plus petits.","exampleRo":"Wǒ gēge zhù zài Běijīng.","lit":"je · grand frère · habiter · à · Pékin","say":{"Bàba":"爸爸","māma":"妈妈","gēge":"哥哥","jiějie":"姐姐","dìdi":"弟弟","mèimei":"妹妹","wǒ bàba":"我爸爸","Wǒ gēge zhù zài Běijīng":"我哥哥住在北京","bàba, māma, gēge, jiějie":"爸爸、妈妈、哥哥、姐姐"}}},{"title":"Parler de son travail","phrases":[{"fr":"Tu travailles dans quoi ?","tgt":"你做什么工作？","ro":"Nǐ zuò shénme gōngzuò?","lit":"toi · faire · quel · travail ?"},{"fr":"Moi, je suis ingénieur.","tgt":"我是工程师。","ro":"Wǒ shì gōngchéngshī.","lit":"je · être · ingénieur"},{"fr":"Je travaille dans une entreprise française.","tgt":"我在一家法国公司工作。","ro":"Wǒ zài yì jiā Fǎguó gōngsī gōngzuò.","lit":"je · à · un · [classificateur] · France · entreprise · travailler"},{"fr":"Ton bureau se trouve où ?","tgt":"你的办公室在哪儿？","ro":"Nǐ de bàngōngshì zài nǎr?","lit":"toi · [possessif] · bureau · se trouver · où ?"},{"fr":"Près de la rue Chunxi.","tgt":"在春熙路附近。","ro":"Zài Chūnxī Lù fùjìn.","lit":"se trouver · Chunxi · rue · environs"},{"fr":"Tu vas au travail tous les jours ?","tgt":"你每天都上班吗？","ro":"Nǐ měitiān dōu shàngbān ma?","lit":"toi · chaque jour · tous · aller au travail · [question] ?"},{"fr":"Du lundi au vendredi.","tgt":"星期一到星期五。","ro":"Xīngqīyī dào xīngqīwǔ.","lit":"lundi · jusqu'à · vendredi"},{"fr":"Je commence à neuf heures.","tgt":"我九点上班。","ro":"Wǒ jiǔ diǎn shàngbān.","lit":"je · neuf · heure · aller au travail"},{"fr":"Ton travail est intéressant ?","tgt":"你的工作有意思吗？","ro":"Nǐ de gōngzuò yǒu yìsi ma?","lit":"toi · [possessif] · travail · avoir · intérêt · [question] ?"},{"fr":"Oui, mais c'est un peu fatigant.","tgt":"有意思，可是有点儿累。","ro":"Yǒu yìsi, kěshì yǒudiǎnr lèi.","lit":"avoir · intérêt, mais · un peu · fatigué"}]},{"title":"Un coup de téléphone","phrases":[{"fr":"Allô, tu fais quoi, là ?","tgt":"喂，你在干什么？","ro":"Wèi, nǐ zài gàn shénme?","lit":"allô, toi · [en cours] · faire · quoi ?"},{"fr":"Je suis en train de manger.","tgt":"我正在吃饭。","ro":"Wǒ zhèngzài chīfàn.","lit":"je · [en cours] · manger (repas)"},{"fr":"Là, je bois un thé à la maison de thé.","tgt":"我正在茶馆喝茶。","ro":"Wǒ zhèngzài cháguǎn hē chá.","lit":"je · [en cours] · maison de thé · boire · thé"},{"fr":"Mon père joue au mahjong en ce moment.","tgt":"我爸爸正在打麻将。","ro":"Wǒ bàba zhèngzài dǎ májiàng.","lit":"je · papa · [en cours] · jouer · mahjong"},{"fr":"Tu es au travail en ce moment ?","tgt":"你正在上班吗？","ro":"Nǐ zhèngzài shàngbān ma?","lit":"toi · [en cours] · travailler · [question] ?"},{"fr":"Non, je suis en train de faire les courses.","tgt":"没有，我正在买东西。","ro":"Méiyǒu, wǒ zhèngzài mǎi dōngxi.","lit":"non, je · [en cours] · acheter · chose"},{"fr":"Il pleut à Chengdu en ce moment ?","tgt":"成都正在下雨吗？","ro":"Chéngdū zhèngzài xià yǔ ma?","lit":"Chengdu · [en cours] · tomber · pluie · [question] ?"},{"fr":"Ma petite sœur regarde la télé en ce moment.","tgt":"我妹妹正在看电视。","ro":"Wǒ mèimei zhèngzài kàn diànshì.","lit":"je · petite sœur · [en cours] · regarder · télévision"},{"fr":"Je te rappelle dans un moment.","tgt":"我一会儿再打。","ro":"Wǒ yíhuìr zài dǎ.","lit":"je · un moment · de nouveau · appeler"},{"fr":"D'accord, à tout à l'heure !","tgt":"好的，一会儿见！","ro":"Hǎo de, yíhuìr jiàn!","lit":"bien · [d'accord], un moment · se voir !"}],"tip":{"title":"« Zhèngzài » : être en train de","example":"Je suis en train de manger. — 我<b>正在</b>吃饭。","body":"Le chinois ne conjugue pas ses verbes : pour dire qu'une action est en cours, on place simplement « zhèngzài » juste avant le verbe. C'est l'équivalent exact de « être en train de » en français. « Wǒ chīfàn » veut dire « je mange », et « Wǒ zhèngzài chīfàn », « je suis en train de manger ». Décomposons : « wǒ », je, « zhèngzài », en train de, « chīfàn », manger. À l'oral, on raccourcit très souvent en « zài » tout seul : « Nǐ zài gàn shénme ? », tu fais quoi, là ? Pour poser la question, ajoutez « ma » à la fin : « Nǐ zhèngzài shàngbān ma ? ». On peut aussi glisser un lieu juste après : « Wǒ zhèngzài cháguǎn hē chá », je suis en train de boire du thé à la maison de thé. Astuce : « zhèng » veut dire « juste », et « zài » veut dire « être là », donc « juste là, en plein dedans ».","exampleRo":"Wǒ zhèngzài chīfàn.","lit":"je · [en cours] · manger (repas)","say":{"Zhèngzài":"正在","zhèngzài":"正在","Wǒ chīfàn":"我吃饭","Wǒ zhèngzài chīfàn":"我正在吃饭","wǒ":"我","chīfàn":"吃饭","zài":"在","Nǐ zài gàn shénme ?":"你在干什么？","ma":"吗","Nǐ zhèngzài shàngbān ma ?":"你正在上班吗？","Wǒ zhèngzài cháguǎn hē chá":"我正在茶馆喝茶","zhèng":"正"}}},{"title":"À la maison de thé","phrases":[{"fr":"Allons à la maison de thé !","tgt":"我们去茶馆吧！","ro":"Wǒmen qù cháguǎn ba!","lit":"nous · aller · maison de thé · [suggestion] !"},{"fr":"Cette maison de thé est très ancienne.","tgt":"这家茶馆很老。","ro":"Zhè jiā cháguǎn hěn lǎo.","lit":"ce · [classificateur] · maison de thé · très · vieux"},{"fr":"On s'assoit dehors ?","tgt":"我们坐外面吧？","ro":"Wǒmen zuò wàimian ba?","lit":"nous · s'asseoir · dehors · [suggestion] ?"},{"fr":"Tu prends quel thé ?","tgt":"你喝什么茶？","ro":"Nǐ hē shénme chá?","lit":"toi · boire · quel · thé ?"},{"fr":"Un thé au jasmin, merci.","tgt":"一杯茉莉花茶，谢谢。","ro":"Yì bēi mòlìhuā chá, xièxie.","lit":"un · [classificateur : tasse] · jasmin · thé, merci"},{"fr":"Les gens de Chengdu adorent la maison de thé.","tgt":"成都人很喜欢泡茶馆。","ro":"Chéngdū rén hěn xǐhuan pào cháguǎn.","lit":"Chengdu · gens · très · aimer · tremper · maison de thé"},{"fr":"Attention, le thé est brûlant.","tgt":"小心，茶很烫。","ro":"Xiǎoxīn, chá hěn tàng.","lit":"attention, thé · très · brûlant"},{"fr":"Ici, on peut même se faire nettoyer les oreilles.","tgt":"这里还可以掏耳朵。","ro":"Zhèlǐ hái kěyǐ tāo ěrduo.","lit":"ici · aussi · pouvoir · curer · oreille"},{"fr":"Il coûte combien, ce thé ?","tgt":"这个茶多少钱？","ro":"Zhège chá duōshao qián?","lit":"ce · [classificateur] · thé · combien · argent ?"},{"fr":"Vingt yuans la tasse.","tgt":"二十块一杯。","ro":"Èrshí kuài yì bēi.","lit":"vingt · kuai · un · [classificateur : tasse]"}]},{"title":"Comparer","phrases":[{"fr":"Chengdu est plus grande que Lyon.","tgt":"成都比里昂大。","ro":"Chéngdū bǐ Lǐ'áng dà.","lit":"Chengdu · comparé à · Lyon · grand"},{"fr":"Pour moi, le thé est meilleur que le café.","tgt":"我觉得茶比咖啡好喝。","ro":"Wǒ juéde chá bǐ kāfēi hǎohē.","lit":"je · trouver · thé · comparé à · café · bon à boire"},{"fr":"Mon grand frère est plus grand que moi.","tgt":"我哥哥比我高。","ro":"Wǒ gēge bǐ wǒ gāo.","lit":"je · grand frère · comparé à · moi · grand (taille)"},{"fr":"Aujourd'hui, il fait plus chaud qu'hier.","tgt":"今天比昨天热。","ro":"Jīntiān bǐ zuótiān rè.","lit":"aujourd'hui · comparé à · hier · chaud"},{"fr":"Ici, le métro va plus vite que le bus.","tgt":"这里地铁比公交车快。","ro":"Zhèlǐ dìtiě bǐ gōngjiāochē kuài.","lit":"ici · métro · comparé à · bus · rapide"},{"fr":"Ce restaurant-ci est moins cher que celui-là.","tgt":"这家比那家便宜。","ro":"Zhè jiā bǐ nà jiā piányi.","lit":"ce · [classificateur] · comparé à · ce-là · [classificateur] · bon marché"},{"fr":"Tu es plus jeune que moi ?","tgt":"你比我小吗？","ro":"Nǐ bǐ wǒ xiǎo ma?","lit":"toi · comparé à · moi · petit · [question] ?"},{"fr":"Oui, j'ai deux ans de moins que toi.","tgt":"对，我比你小两岁。","ro":"Duì, wǒ bǐ nǐ xiǎo liǎng suì.","lit":"oui, je · comparé à · toi · petit · deux · an"},{"fr":"Le chinois est plus difficile que le français ?","tgt":"中文比法语难吗？","ro":"Zhōngwén bǐ Fǎyǔ nán ma?","lit":"chinois · comparé à · français · difficile · [question] ?"},{"fr":"Non, c'est le français qui est plus dur !","tgt":"不，法语比中文难！","ro":"Bù, Fǎyǔ bǐ Zhōngwén nán!","lit":"non, français · comparé à · chinois · difficile !"}],"tip":{"title":"Comparer avec « bǐ »","example":"Mon grand frère est plus grand que moi. — 我哥哥<b>比</b>我高。","body":"Pour comparer en chinois, on utilise le petit mot « bǐ », qui veut dire « comparé à ». La structure est toujours la même : A, puis « bǐ », puis B, puis l'adjectif. « Chéngdū bǐ Lǐ'áng dà » se décompose ainsi : Chengdu, comparé à Lyon, grand. Autrement dit, Chengdu est plus grande que Lyon. Contrairement au français, on ne dit pas « plus » : le mot « bǐ » suffit, et surtout on n'ajoute pas « hěn », très, devant l'adjectif. Pour préciser la différence, on la place tout à la fin : « Wǒ bǐ nǐ xiǎo liǎng suì », j'ai deux ans de moins que toi. Pour poser la question, on ajoute « ma » : « Zhōngwén bǐ Fǎyǔ nán ma ? ». Astuce : imaginez une balance, avec celui qui l'emporte toujours placé en premier, avant « bǐ ».","exampleRo":"Wǒ gēge bǐ wǒ gāo.","lit":"je · grand frère · comparé à · moi · grand (taille)","say":{"bǐ":"比","Chéngdū bǐ Lǐ'áng dà":"成都比里昂大","hěn":"很","Wǒ bǐ nǐ xiǎo liǎng suì":"我比你小两岁","ma":"吗","Zhōngwén bǐ Fǎyǔ nán ma ?":"中文比法语难吗？"}}},{"title":"Entre collègues","phrases":[{"fr":"Voici ma nouvelle collègue.","tgt":"这是我的新同事。","ro":"Zhè shì wǒ de xīn tóngshì.","lit":"ceci · être · je · [possessif] · nouveau · collègue"},{"fr":"Elle est de Shanghai.","tgt":"她是上海人。","ro":"Tā shì Shànghǎi rén.","lit":"elle · être · Shanghai · personne"},{"fr":"Bienvenue dans notre entreprise !","tgt":"欢迎你来我们公司！","ro":"Huānyíng nǐ lái wǒmen gōngsī!","lit":"bienvenue · toi · venir · nous · entreprise !"},{"fr":"On déjeune ensemble à midi ?","tgt":"中午一起吃饭吧？","ro":"Zhōngwǔ yìqǐ chīfàn ba?","lit":"midi · ensemble · manger · [suggestion] ?"},{"fr":"En bas, il y a une bonne cantine.","tgt":"楼下有一个很好的食堂。","ro":"Lóuxià yǒu yí ge hěn hǎo de shítáng.","lit":"en bas · avoir · un · [classificateur] · très · bien · [possessif] · cantine"},{"fr":"Mon chef est quelqu'un de très bien.","tgt":"我的老板人很好。","ro":"Wǒ de lǎobǎn rén hěn hǎo.","lit":"je · [possessif] · patron · personne · très · bien"},{"fr":"Tu as une réunion cet après-midi ?","tgt":"你今天下午开会吗？","ro":"Nǐ jīntiān xiàwǔ kāihuì ma?","lit":"toi · aujourd'hui · après-midi · tenir réunion · [question] ?"},{"fr":"Oui, la réunion est à trois heures.","tgt":"对，三点开会。","ro":"Duì, sān diǎn kāihuì.","lit":"oui, trois · heure · tenir réunion"},{"fr":"Après le travail, tu rentres directement ?","tgt":"下班以后你直接回家吗？","ro":"Xiàbān yǐhòu nǐ zhíjiē huí jiā ma?","lit":"quitter le travail · après · toi · directement · rentrer · maison · [question] ?"},{"fr":"Non, je vais à la salle de sport.","tgt":"不，我去健身房。","ro":"Bù, wǒ qù jiànshēnfáng.","lit":"non, je · aller · salle de sport"}]},{"title":"Pourquoi le chinois ?","phrases":[{"fr":"Pourquoi tu apprends le chinois ?","tgt":"你为什么学中文？","ro":"Nǐ wèishénme xué Zhōngwén?","lit":"toi · pourquoi · apprendre · chinois ?"},{"fr":"Parce que je travaille en Chine.","tgt":"因为我在中国工作。","ro":"Yīnwèi wǒ zài Zhōngguó gōngzuò.","lit":"parce que · je · à · Chine · travailler"},{"fr":"J'aime Chengdu, donc j'apprends le chinois.","tgt":"因为我喜欢成都，所以我学中文。","ro":"Yīnwèi wǒ xǐhuan Chéngdū, suǒyǐ wǒ xué Zhōngwén.","lit":"parce que · je · aimer · Chengdu, donc · je · apprendre · chinois"},{"fr":"Il pleut, donc on reste à la maison de thé.","tgt":"因为下雨，所以我们待在茶馆。","ro":"Yīnwèi xià yǔ, suǒyǐ wǒmen dāi zài cháguǎn.","lit":"parce que · tomber · pluie, donc · nous · rester · à · maison de thé"},{"fr":"J'ai beaucoup de travail, donc je suis fatigué.","tgt":"因为工作很忙，所以我很累。","ro":"Yīnwèi gōngzuò hěn máng, suǒyǐ wǒ hěn lèi.","lit":"parce que · travail · très · occupé, donc · je · très · fatigué"},{"fr":"Pourquoi tu ne viens pas ce soir ?","tgt":"你今天晚上为什么不来？","ro":"Nǐ jīntiān wǎnshang wèishénme bù lái?","lit":"toi · aujourd'hui · soir · pourquoi · ne pas · venir ?"},{"fr":"Parce que mon fils est malade.","tgt":"因为我儿子病了。","ro":"Yīnwèi wǒ érzi bìng le.","lit":"parce que · je · fils · malade · [accompli]"},{"fr":"J'ai peur du piment, donc je prends peu épicé.","tgt":"因为我怕辣，所以我吃微辣。","ro":"Yīnwèi wǒ pà là, suǒyǐ wǒ chī wēilà.","lit":"parce que · je · craindre · piquant, donc · je · manger · légèrement épicé"},{"fr":"Il y a des bouchons, donc il est en retard.","tgt":"因为堵车，所以他迟到了。","ro":"Yīnwèi dǔchē, suǒyǐ tā chídào le.","lit":"parce que · embouteillage, donc · il · arriver en retard · [accompli]"},{"fr":"J'ai beaucoup d'amis ici, donc je suis heureux.","tgt":"因为这里朋友很多，所以我很开心。","ro":"Yīnwèi zhèlǐ péngyou hěn duō, suǒyǐ wǒ hěn kāixīn.","lit":"parce que · ici · ami · très · nombreux, donc · je · très · heureux"}],"tip":{"title":"« Yīnwèi... suǒyǐ... » : parce que... donc...","example":"Il pleut, donc on reste à la maison de thé. — <b>因为</b>下雨，<b>所以</b>我们待在茶馆。","body":"Pour expliquer une cause et sa conséquence, le chinois aime utiliser une paire de mots : « yīnwèi », parce que, et « suǒyǐ », donc. On les met tous les deux dans la même phrase, ce qui paraîtrait lourd en français, mais sonne très naturel en chinois. Par exemple, « Yīnwèi xià yǔ, suǒyǐ wǒmen dāi zài cháguǎn » se dit mot à mot « parce que tomber pluie, donc nous rester à maison de thé ». L'ordre est toujours le même : d'abord la cause, ensuite la conséquence. Pour répondre à « wèishénme », pourquoi, on peut dire juste la première moitié : « Yīnwèi wǒ zài Zhōngguó gōngzuò ». À l'oral, on garde aussi parfois seulement « suǒyǐ » : « Wǒ pà là, suǒyǐ chī wēilà ». Astuce : pensez à un pont, avec « yīnwèi » au départ et « suǒyǐ » à l'arrivée.","exampleRo":"Yīnwèi xià yǔ, suǒyǐ wǒmen dāi zài cháguǎn.","lit":"parce que · tomber · pluie, donc · nous · rester · à · maison de thé","say":{"Yīnwèi... suǒyǐ...":"因为……所以……","yīnwèi":"因为","suǒyǐ":"所以","Yīnwèi xià yǔ, suǒyǐ wǒmen dāi zài cháguǎn":"因为下雨，所以我们待在茶馆","wèishénme":"为什么","Yīnwèi wǒ zài Zhōngguó gōngzuò":"因为我在中国工作","Wǒ pà là, suǒyǐ chī wēilà":"我怕辣，所以吃微辣"}}},{"title":"Le mahjong au parc","phrases":[{"fr":"Beaucoup de personnes âgées jouent au mahjong au parc.","tgt":"很多老人在公园打麻将。","ro":"Hěn duō lǎorén zài gōngyuán dǎ májiàng.","lit":"très · nombreux · personne âgée · à · parc · jouer · mahjong"},{"fr":"Tu sais jouer au mahjong ?","tgt":"你会打麻将吗？","ro":"Nǐ huì dǎ májiàng ma?","lit":"toi · savoir · jouer · mahjong · [question] ?"},{"fr":"Non, je ne sais pas encore.","tgt":"不会，我还不会。","ro":"Bú huì, wǒ hái bú huì.","lit":"ne pas · savoir, je · encore · ne pas · savoir"},{"fr":"Ce n'est pas dur, je t'apprends.","tgt":"不难，我教你。","ro":"Bù nán, wǒ jiāo nǐ.","lit":"ne pas · difficile, je · enseigner · toi"},{"fr":"Il faut être quatre.","tgt":"要四个人。","ro":"Yào sì ge rén.","lit":"falloir · quatre · [classificateur] · personne"},{"fr":"À toi de jouer !","tgt":"该你了！","ro":"Gāi nǐ le!","lit":"être le tour de · toi · [changement] !"},{"fr":"J'ai gagné !","tgt":"我赢了！","ro":"Wǒ yíng le!","lit":"je · gagner · [accompli] !"},{"fr":"On fait encore une partie ?","tgt":"再打一局吧？","ro":"Zài dǎ yì jú ba?","lit":"encore · jouer · un · [classificateur : partie] · [suggestion] ?"},{"fr":"Les règles de Chengdu sont spéciales.","tgt":"成都麻将的规则很特别。","ro":"Chéngdū májiàng de guīzé hěn tèbié.","lit":"Chengdu · mahjong · [possessif] · règle · très · spécial"},{"fr":"Jouer au mahjong, c'est vraiment marrant !","tgt":"打麻将很好玩儿！","ro":"Dǎ májiàng hěn hǎowánr!","lit":"jouer · mahjong · très · amusant !"}]},{"title":"Goûter, essayer","phrases":[{"fr":"Goûte un peu ce thé.","tgt":"你尝尝这个茶。","ro":"Nǐ chángchang zhège chá.","lit":"toi · goûter-goûter · ce · [classificateur] · thé"},{"fr":"Je peux essayer ?","tgt":"我可以试试吗？","ro":"Wǒ kěyǐ shìshi ma?","lit":"je · pouvoir · essayer-essayer · [question] ?"},{"fr":"Regarde un peu cette photo.","tgt":"你看看这张照片。","ro":"Nǐ kànkan zhè zhāng zhàopiàn.","lit":"toi · regarder-regarder · ce · [classificateur] · photo"},{"fr":"Laisse-moi réfléchir un peu.","tgt":"让我想想。","ro":"Ràng wǒ xiǎngxiang.","lit":"laisser · je · penser-penser"},{"fr":"On va se balader un peu au parc ?","tgt":"我们去公园走走吧？","ro":"Wǒmen qù gōngyuán zǒuzou ba?","lit":"nous · aller · parc · marcher-marcher · [suggestion] ?"},{"fr":"Je vais voir avec ma collègue.","tgt":"我问问我的同事。","ro":"Wǒ wènwen wǒ de tóngshì.","lit":"je · demander-demander · je · [possessif] · collègue"},{"fr":"Repose-toi un peu.","tgt":"你休息休息吧。","ro":"Nǐ xiūxi xiūxi ba.","lit":"toi · se reposer-se reposer · [suggestion]"},{"fr":"Tu veux goûter le tofu mapo ?","tgt":"你想尝尝麻婆豆腐吗？","ro":"Nǐ xiǎng chángchang mápó dòufu ma?","lit":"toi · vouloir · goûter-goûter · mapo · tofu · [question] ?"},{"fr":"Écoute un peu cette chanson.","tgt":"你听听这首歌。","ro":"Nǐ tīngting zhè shǒu gē.","lit":"toi · écouter-écouter · ce · [classificateur] · chanson"},{"fr":"C'est délicieux, essaie toi aussi !","tgt":"很好吃，你也试试！","ro":"Hěn hǎochī, nǐ yě shìshi!","lit":"très · bon, toi · aussi · essayer-essayer !"}],"tip":{"title":"Le redoublement des verbes : « kànkan, shìshi »","example":"Je peux essayer ? — 我可以<b>试试</b>吗？","body":"En chinois, on peut répéter un verbe pour adoucir une action : cela veut dire « un petit peu », « rapidement » ou « pour voir ». « Kàn » signifie regarder, et « kànkan », jeter un coup d'œil. « Shì » veut dire essayer, et « shìshi », essayer un peu. La deuxième syllabe se prononce légèrement, sans ton. Décomposons « Nǐ chángchang zhège chá » : toi, goûter-goûter, ce thé, c'est-à-dire « goûte un peu ce thé ». Cette forme rend une demande plus douce et plus polie, un peu comme quand on dit « tiens, goûte voir » en français. Pour les verbes de deux syllabes, on répète le tout : « xiūxi xiūxi », se reposer un peu. Autres exemples très courants : « xiǎngxiang », réfléchir un peu, et « zǒuzou », faire quelques pas. Astuce : quand vous doublez un verbe, imaginez que vous souriez à votre interlocuteur.","exampleRo":"Wǒ kěyǐ shìshi ma?","lit":"je · pouvoir · essayer-essayer · [question] ?","say":{"Kàn":"看","kànkan":"看看","Shì":"试","shìshi":"试试","Nǐ chángchang zhège chá":"你尝尝这个茶","xiūxi xiūxi":"休息休息","xiǎngxiang":"想想","zǒuzou":"走走","kànkan, shìshi":"看看、试试"}}},{"title":"Les loisirs du week-end","phrases":[{"fr":"Le week-end, tu fais quoi d'habitude ?","tgt":"你周末一般做什么？","ro":"Nǐ zhōumò yìbān zuò shénme?","lit":"toi · week-end · en général · faire · quoi ?"},{"fr":"Je fais du vélo au bord de la rivière.","tgt":"我在河边骑自行车。","ro":"Wǒ zài hé biān qí zìxíngchē.","lit":"je · à · rivière · bord · monter · vélo"},{"fr":"Parfois, je vais marcher en montagne.","tgt":"有时候我去爬山。","ro":"Yǒu shíhou wǒ qù pá shān.","lit":"avoir · moment · je · aller · grimper · montagne"},{"fr":"Le mont Qingcheng est magnifique.","tgt":"青城山很漂亮。","ro":"Qīngchéng Shān hěn piàoliang.","lit":"Qingcheng · montagne · très · beau"},{"fr":"Tu aimes chanter ?","tgt":"你喜欢唱歌吗？","ro":"Nǐ xǐhuan chàng gē ma?","lit":"toi · aimer · chanter · chanson · [question] ?"},{"fr":"Ce soir, on va chanter au karaoké.","tgt":"今晚我们去唱歌。","ro":"Jīnwǎn wǒmen qù chàng gē.","lit":"ce soir · nous · aller · chanter · chanson"},{"fr":"Moi, je vais souvent au cinéma.","tgt":"我常去看电影。","ro":"Wǒ cháng qù kàn diànyǐng.","lit":"je · souvent · aller · voir · film"},{"fr":"Le dimanche, je fais la grasse matinée.","tgt":"星期天我睡懒觉。","ro":"Xīngqītiān wǒ shuì lǎnjiào.","lit":"dimanche · je · dormir · paresseux-sommeil"},{"fr":"Tu fais un peu de sport ?","tgt":"你平时运动吗？","ro":"Nǐ píngshí yùndòng ma?","lit":"toi · d'habitude · faire du sport · [question] ?"},{"fr":"Oui, je joue au badminton.","tgt":"对，我打羽毛球。","ro":"Duì, wǒ dǎ yǔmáoqiú.","lit":"oui, je · jouer · badminton"}]},{"title":"Offrir un cadeau","phrases":[{"fr":"C'est un cadeau pour toi.","tgt":"这是给你的礼物。","ro":"Zhè shì gěi nǐ de lǐwù.","lit":"ceci · être · donner · toi · [possessif] · cadeau"},{"fr":"Je t'offre ce livre.","tgt":"我给你这本书。","ro":"Wǒ gěi nǐ zhè běn shū.","lit":"je · donner · toi · ce · [classificateur] · livre"},{"fr":"Merci, c'est vraiment gentil !","tgt":"谢谢，你真好！","ro":"Xièxie, nǐ zhēn hǎo!","lit":"merci, toi · vraiment · bien !"},{"fr":"J'achète du thé pour ma maman.","tgt":"我给妈妈买茶。","ro":"Wǒ gěi māma mǎi chá.","lit":"je · pour · maman · acheter · thé"},{"fr":"Donne-moi ton numéro, s'il te plaît.","tgt":"请给我你的电话号码。","ro":"Qǐng gěi wǒ nǐ de diànhuà hàomǎ.","lit":"s'il te plaît · donner · moi · toi · [possessif] · téléphone · numéro"},{"fr":"Je t'appelle ce soir.","tgt":"我今天晚上给你打电话。","ro":"Wǒ jīntiān wǎnshang gěi nǐ dǎ diànhuà.","lit":"je · aujourd'hui · soir · pour · toi · frapper · téléphone"},{"fr":"Elle prépare une fondue pour ses amis.","tgt":"她给朋友做火锅。","ro":"Tā gěi péngyou zuò huǒguō.","lit":"elle · pour · ami · faire · fondue"},{"fr":"Quel cadeau offrir à un ami chinois ?","tgt":"送中国朋友什么礼物好？","ro":"Sòng Zhōngguó péngyou shénme lǐwù hǎo?","lit":"offrir · Chine · ami · quel · cadeau · bien ?"},{"fr":"Un vin rouge français, c'est très bien.","tgt":"法国红酒很好。","ro":"Fǎguó hóngjiǔ hěn hǎo.","lit":"France · vin rouge · très · bien"},{"fr":"Je donne un panda en peluche à ma fille.","tgt":"我给女儿一个熊猫玩具。","ro":"Wǒ gěi nǚ'ér yí ge xióngmāo wánjù.","lit":"je · donner · fille · un · [classificateur] · panda · jouet"}],"tip":{"title":"« Gěi » : donner, et pour quelqu'un","example":"J'achète du thé pour ma maman. — 我<b>给</b>妈妈买茶。","body":"« Gěi » est un mot très utile qui a deux emplois. D'abord, c'est un verbe qui veut dire « donner » : « Wǒ gěi nǐ zhè běn shū », je te donne ce livre. Remarquez l'ordre : on dit d'abord à qui l'on donne, puis la chose, sans petit mot comme « à ». Ensuite, « gěi » sert à dire « pour quelqu'un » ou « à quelqu'un », et dans ce cas il se place avant le verbe. « Wǒ gěi māma mǎi chá » se décompose ainsi : je, pour maman, acheter, thé. C'est l'inverse du français, où l'on dit « j'achète du thé pour maman ». On l'entend tous les jours dans « gěi nǐ dǎ diànhuà », t'appeler au téléphone. Attention à bien faire descendre puis remonter la voix sur « gěi ». Astuce : quand quelqu'un vous tend un objet, il dit souvent simplement « Gěi nǐ ! », tiens, c'est pour toi.","exampleRo":"Wǒ gěi māma mǎi chá.","lit":"je · pour · maman · acheter · thé","say":{"Gěi":"给","Wǒ gěi nǐ zhè běn shū":"我给你这本书","gěi":"给","Wǒ gěi māma mǎi chá":"我给妈妈买茶","gěi nǐ dǎ diànhuà":"给你打电话","Gěi nǐ !":"给你！"}}},{"title":"Inviter à une fondue","phrases":[{"fr":"Tu es libre samedi soir ?","tgt":"你星期六晚上有空吗？","ro":"Nǐ xīngqīliù wǎnshang yǒu kòng ma?","lit":"toi · samedi · soir · avoir · temps libre · [question] ?"},{"fr":"Je t'invite à manger une fondue.","tgt":"我请你吃火锅。","ro":"Wǒ qǐng nǐ chī huǒguō.","lit":"je · inviter · toi · manger · fondue"},{"fr":"D'accord, aucun problème !","tgt":"好的，没问题！","ro":"Hǎo de, méi wèntí!","lit":"bien · [d'accord], ne pas avoir · problème !"},{"fr":"Tu connais une bonne adresse de fondue ?","tgt":"你知道好吃的火锅店吗？","ro":"Nǐ zhīdào hǎochī de huǒguō diàn ma?","lit":"toi · savoir · bon · [possessif] · fondue · restaurant · [question] ?"},{"fr":"Il y en a une près de chez moi.","tgt":"我家附近有一家。","ro":"Wǒ jiā fùjìn yǒu yì jiā.","lit":"je · maison · environs · avoir · un · [classificateur]"},{"fr":"On se retrouve à sept heures ?","tgt":"我们七点见吧？","ro":"Wǒmen qī diǎn jiàn ba?","lit":"nous · sept · heure · se voir · [suggestion] ?"},{"fr":"Je peux venir avec mon mari ?","tgt":"我可以带我先生来吗？","ro":"Wǒ kěyǐ dài wǒ xiānsheng lái ma?","lit":"je · pouvoir · amener · je · mari · venir · [question] ?"},{"fr":"Bien sûr, plus on est nombreux, plus c'est animé !","tgt":"当然，人多热闹！","ro":"Dāngrán, rén duō rènao!","lit":"bien sûr, gens · nombreux · animé !"},{"fr":"On doit réserver une table ?","tgt":"要订位吗？","ro":"Yào dìngwèi ma?","lit":"falloir · réserver place · [question] ?"},{"fr":"Oui, le samedi, il y a beaucoup de monde.","tgt":"要，星期六人很多。","ro":"Yào, xīngqīliù rén hěn duō.","lit":"falloir, samedi · gens · très · nombreux"}]},{"title":"Autour de la fondue épicée","phrases":[{"fr":"Cette fondue est trop épicée !","tgt":"这个火锅太辣了！","ro":"Zhège huǒguō tài là le!","lit":"ce · [classificateur] · fondue · trop · épicé · [exclamation] !"},{"fr":"C'est vraiment très bon.","tgt":"非常好吃。","ro":"Fēicháng hǎochī.","lit":"extrêmement · bon"},{"fr":"Le bouillon sent extrêmement bon.","tgt":"汤非常香。","ro":"Tāng fēicháng xiāng.","lit":"bouillon · extrêmement · parfumé"},{"fr":"J'ai beaucoup trop chaud !","tgt":"我太热了！","ro":"Wǒ tài rè le!","lit":"je · trop · chaud · [exclamation] !"},{"fr":"Le poivre du Sichuan fait fourmiller la langue.","tgt":"花椒很麻。","ro":"Huājiāo hěn má.","lit":"poivre du Sichuan · très · engourdissant"},{"fr":"Bois un peu de lait de soja.","tgt":"喝点儿豆奶吧。","ro":"Hē diǎnr dòunǎi ba.","lit":"boire · un peu · lait de soja · [suggestion]"},{"fr":"Ce restaurant est très connu.","tgt":"这家店非常有名。","ro":"Zhè jiā diàn fēicháng yǒumíng.","lit":"ce · [classificateur] · restaurant · extrêmement · célèbre"},{"fr":"Il y a trop de monde ce soir.","tgt":"今天晚上人太多了。","ro":"Jīntiān wǎnshang rén tài duō le.","lit":"aujourd'hui · soir · gens · trop · nombreux · [exclamation]"},{"fr":"Oh, tu es trop gentil !","tgt":"你太客气了！","ro":"Nǐ tài kèqi le!","lit":"toi · trop · poli · [exclamation] !"},{"fr":"Ce soir, je suis vraiment très heureux.","tgt":"今天晚上我非常开心。","ro":"Jīntiān wǎnshang wǒ fēicháng kāixīn.","lit":"aujourd'hui · soir · je · extrêmement · heureux"}],"tip":{"title":"« Tài... le » et « fēicháng » : trop et très","example":"Cette fondue est trop épicée ! — 这个火锅<b>太</b>辣<b>了</b>！","body":"Pour dire « trop », le chinois utilise un cadre en deux morceaux : « tài » avant l'adjectif, et « le » tout à la fin. « Zhège huǒguō tài là le ! » se décompose ainsi : cette fondue, trop, épicée, puis le petit « le » qui ferme l'exclamation. Ce « le » est indispensable à l'oral, sinon la phrase sonne coupée. Attention, « tài... le » n'est pas toujours négatif : « Tài hǎo le ! » veut dire « super ! », et « Nǐ tài kèqi le ! » signifie « tu es trop gentil ». Pour dire « très », avec plus de force que le simple « hěn », on utilise « fēicháng », qui veut dire « extraordinairement ». Il se place devant l'adjectif, sans rien à la fin : « Fēicháng hǎochī », vraiment très bon. Astuce : « tài » ouvre la porte et « le » la referme, alors que « fēicháng » entre tout seul.","exampleRo":"Zhège huǒguō tài là le!","lit":"ce · [classificateur] · fondue · trop · épicé · [exclamation] !","say":{"Tài... le":"太……了","fēicháng":"非常","tài":"太","le":"了","Zhège huǒguō tài là le !":"这个火锅太辣了！","tài... le":"太……了","Tài hǎo le !":"太好了！","Nǐ tài kèqi le !":"你太客气了！","hěn":"很","Fēicháng hǎochī":"非常好吃"}}},{"title":"Se dire au revoir","phrases":[{"fr":"Il est tard, je dois rentrer.","tgt":"很晚了，我得回家了。","ro":"Hěn wǎn le, wǒ děi huí jiā le.","lit":"très · tard · [changement], je · devoir · rentrer · maison · [changement]"},{"fr":"Merci pour ton accueil ce soir.","tgt":"谢谢你今天晚上的招待。","ro":"Xièxie nǐ jīntiān wǎnshang de zhāodài.","lit":"merci · toi · aujourd'hui · soir · [possessif] · accueil"},{"fr":"On s'est bien amusés aujourd'hui.","tgt":"今天玩得很开心。","ro":"Jīntiān wán de hěn kāixīn.","lit":"aujourd'hui · s'amuser · [manière] · très · content"},{"fr":"Fais attention sur la route !","tgt":"路上小心！","ro":"Lùshang xiǎoxīn!","lit":"route-sur · attention !"},{"fr":"Tu rentres en taxi ?","tgt":"你打车回去吗？","ro":"Nǐ dǎchē huíqu ma?","lit":"toi · prendre un taxi · rentrer · [question] ?"},{"fr":"Non, je prends le métro.","tgt":"不，我坐地铁。","ro":"Bù, wǒ zuò dìtiě.","lit":"non, je · s'asseoir (prendre) · métro"},{"fr":"Envoie-moi un message en arrivant.","tgt":"到家给我发个信息。","ro":"Dào jiā gěi wǒ fā ge xìnxī.","lit":"arriver · maison · pour · moi · envoyer · [classificateur] · message"},{"fr":"On se refait ça un autre jour !","tgt":"改天再聚吧！","ro":"Gǎitiān zài jù ba!","lit":"un autre jour · de nouveau · se réunir · [suggestion] !"},{"fr":"La prochaine fois, c'est moi qui invite.","tgt":"下次我请客。","ro":"Xià cì wǒ qǐngkè.","lit":"prochaine · fois · je · inviter"},{"fr":"Au revoir, et bonne nuit !","tgt":"再见，晚安！","ro":"Zàijiàn, wǎn'ān!","lit":"à nouveau · se voir, soir · paix !"}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Tu parles bien chinois maintenant !","tgt":"你现在中文说得很好啊！","ro":"Nǐ xiànzài Zhōngwén shuō de hěn hǎo a!","lit":"toi · maintenant · chinois · parler · [manière] · très · bien · [exclamation] !"},{"fr":"On a fini ce module, non ?","tgt":"这个单元学完了吧？","ro":"Zhège dānyuán xué wán le ba?","lit":"ce · [classificateur] · module · étudier · fini · [accompli] · [n'est-ce pas] ?"},{"fr":"Je sais me présenter en chinois.","tgt":"我会用中文介绍自己。","ro":"Wǒ huì yòng Zhōngwén jièshào zìjǐ.","lit":"je · savoir · utiliser · chinois · présenter · soi-même"},{"fr":"Je peux parler un peu de ma famille.","tgt":"我可以说说我的家人。","ro":"Wǒ kěyǐ shuōshuo wǒ de jiārén.","lit":"je · pouvoir · parler-parler · je · [possessif] · famille"},{"fr":"Et toi, qu'est-ce que tu aimes le plus ?","tgt":"你呢？你最喜欢什么？","ro":"Nǐ ne? Nǐ zuì xǐhuan shénme?","lit":"toi · [et ... ?] ? toi · le plus · aimer · quoi ?"},{"fr":"La fondue, bien sûr !","tgt":"当然是火锅啊！","ro":"Dāngrán shì huǒguō a!","lit":"bien sûr · être · fondue · [exclamation] !"},{"fr":"Et ta collègue Ma Li, elle est où ?","tgt":"你的同事马丽呢？","ro":"Nǐ de tóngshì Mǎ Lì ne?","lit":"toi · [possessif] · collègue · Ma · Li · [et ... ?] ?"},{"fr":"Allez, on passe au module suivant !","tgt":"我们继续学下一个单元吧！","ro":"Wǒmen jìxù xué xià yí ge dānyuán ba!","lit":"nous · continuer · étudier · suivant · un · [classificateur] · module · [suggestion] !"},{"fr":"Le chinois, c'est difficile, mais passionnant.","tgt":"中文很难，可是很有意思啊。","ro":"Zhōngwén hěn nán, kěshì hěn yǒu yìsi a.","lit":"chinois · très · difficile, mais · très · avoir · intérêt · [exclamation]"},{"fr":"Tu es génial, courage pour la suite !","tgt":"你真棒，加油吧！","ro":"Nǐ zhēn bàng, jiāyóu ba!","lit":"toi · vraiment · super, faire le plein · [suggestion] !"}],"tip":{"title":"Les petites particules de fin : a, ne, ba","example":"Et toi, qu'est-ce que tu aimes le plus ? — 你<b>呢</b>？你最喜欢什么？","body":"Le chinois aime terminer ses phrases par de petites particules qui donnent le ton, un peu comme « hein », « alors » ou « allez » en français. « Ba » adoucit une proposition ou une supposition : « Wǒmen zǒu ba », allons-y, ou « Nǐ lèi le ba », tu es fatigué, non ? « Ne » sert à renvoyer une question : « Nǐ ne ? », et toi ? Il suffit de dire un nom suivi de « ne » pour demander où est la personne, ou ce qu'elle en pense. « A » ajoute de la chaleur ou de l'enthousiasme : « Hǎo a ! », d'accord, avec plaisir ! Ces trois particules se prononcent toujours légèrement, sans ton. Par exemple, « Nǐ ne ? Nǐ zuì xǐhuan shénme ? » se décompose ainsi : toi, « ne », puis toi, le plus, aimer, quoi. Astuce : sans particule, une phrase chinoise reste correcte, mais avec elle, elle devient vivante.","exampleRo":"Nǐ ne? Nǐ zuì xǐhuan shénme?","lit":"toi · [et ... ?] ? toi · le plus · aimer · quoi ?","say":{"Ba":"吧","Wǒmen zǒu ba":"我们走吧","Nǐ lèi le ba":"你累了吧","Ne":"呢","Nǐ ne ?":"你呢？","ne":"呢","A":"啊","Hǎo a !":"好啊！","Nǐ ne ? Nǐ zuì xǐhuan shénme ?":"你呢？你最喜欢什么？"}}}]}]},{"id":2,"name":"Niveau 2","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"La vie de tous les jours, avec un vocabulaire plus riche.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Emménager dans un nouvel appartement","phrases":[{"fr":"Je viens d'emménager dans un nouvel appartement à Shanghai.","tgt":"我刚在上海搬进了一套新公寓。","ro":"Wǒ gāng zài Shànghǎi bānjìnle yí tào xīn gōngyù."},{"fr":"L'appartement est au douzième étage.","tgt":"公寓在十二楼。","ro":"Gōngyù zài shí'èr lóu."},{"fr":"Le loyer est de six mille yuans par mois.","tgt":"房租每个月六千块。","ro":"Fángzū měi ge yuè liùqiān kuài."},{"fr":"Il faut payer trois mois de loyer d'avance.","tgt":"要先付三个月的房租。","ro":"Yào xiān fù sān ge yuè de fángzū."},{"fr":"L'agent immobilier m'a remis les clés ce matin.","tgt":"中介今天早上给了我钥匙。","ro":"Zhōngjiè jīntiān zǎoshang gěile wǒ yàoshi."},{"fr":"La cuisine n'est pas grande, mais elle est très claire.","tgt":"厨房很小，但是很亮。","ro":"Chúfáng hěn xiǎo, dànshì hěn liàng."},{"fr":"Je n'ai pas encore internet chez moi.","tgt":"我家还没有网。","ro":"Wǒ jiā hái méiyǒu wǎng."},{"fr":"La climatisation de la chambre marche mal.","tgt":"卧室的空调不太好用。","ro":"Wòshì de kōngtiáo bú tài hǎoyòng."},{"fr":"Le propriétaire dit qu'il viendra la réparer demain.","tgt":"房东说他明天来修。","ro":"Fángdōng shuō tā míngtiān lái xiū."},{"fr":"Ici, je me sens déjà un peu chez moi.","tgt":"我在这儿已经有点儿家的感觉了。","ro":"Wǒ zài zhèr yǐjīng yǒudiǎnr jiā de gǎnjué le."}]},{"title":"Ouvrir un compte à la banque","phrases":[{"fr":"Je voudrais ouvrir un compte dans votre banque.","tgt":"我想开一个银行账户。","ro":"Wǒ xiǎng kāi yí ge yínháng zhànghù."},{"fr":"Quand êtes-vous arrivé à Shanghai ?","tgt":"您是什么时候来上海的？","ro":"Nín shì shénme shíhou lái Shànghǎi de?"},{"fr":"Je suis arrivé le mois dernier.","tgt":"我是上个月来的。","ro":"Wǒ shì shàng ge yuè lái de."},{"fr":"Vous êtes venu ici pour travailler ?","tgt":"您是来这儿工作的吗？","ro":"Nín shì lái zhèr gōngzuò de ma?"},{"fr":"Oui, c'est mon entreprise qui m'a envoyé ici.","tgt":"对，是我们公司派我来的。","ro":"Duì, shì wǒmen gōngsī pài wǒ lái de."},{"fr":"Comment avez-vous connu notre agence ?","tgt":"您是怎么找到我们银行的？","ro":"Nín shì zěnme zhǎodào wǒmen yínháng de?"},{"fr":"C'est un collègue qui me l'a conseillée.","tgt":"是一个同事介绍的。","ro":"Shì yí ge tóngshì jièshào de."},{"fr":"Remplissez ce formulaire, s'il vous plaît.","tgt":"请填一下这张表。","ro":"Qǐng tián yíxià zhè zhāng biǎo."},{"fr":"Où avez-vous fait faire ce passeport ?","tgt":"这本护照是在哪儿办的？","ro":"Zhè běn hùzhào shì zài nǎr bàn de?"},{"fr":"Je l'ai fait faire à Paris.","tgt":"是在巴黎办的。","ro":"Shì zài Bālí bàn de."}],"tip":{"title":"« Shì... de » : insister sur quand, où, comment","example":"Je suis arrivé le mois dernier. — 我<b>是</b>上个月来<b>的</b>。","body":"Quand une action est déjà passée et que l'on veut mettre l'accent sur un détail, quand, où, comment ou avec qui, on encadre ce détail avec « shì » devant et « de » à la toute fin, un peu comme le français « c'est ... que ». Décomposons « Wǒ shì shàng ge yuè lái de » : « wǒ », je, « shì », c'est, « shàng ge yuè », le mois dernier, « lái », venir, et « de » qui referme la phrase ; littéralement, c'est le mois dernier que je suis venu. On dit de même « Shì zài Bālí bàn de », c'est à Paris que je l'ai fait faire, ou « Nǐ shì zěnme lái de ? », comment es-tu venu ? À l'oral, le « shì » est souvent léger, parfois même avalé, mais le « de » final ne disparaît jamais. Astuce : dès qu'on vous demande quand, où ou comment pour un fait passé, pensez à refermer votre réponse avec « de ».","exampleRo":"Wǒ shì shàng ge yuè lái de.","lit":"je · [insistance] · mois dernier · venir · [insistance]","say":{"Shì... de":"是……的","shì":"是","de":"的","Wǒ shì shàng ge yuè lái de":"我是上个月来的","wǒ":"我","shàng ge yuè":"上个月","lái":"来","Shì zài Bālí bàn de":"是在巴黎办的","Nǐ shì zěnme lái de ?":"你是怎么来的？"}}},{"title":"Payer avec son téléphone","phrases":[{"fr":"Ici, presque tout le monde paie avec son téléphone.","tgt":"在这儿，差不多人人都用手机付钱。","ro":"Zài zhèr, chàbuduō rénrén dōu yòng shǒujī fù qián."},{"fr":"On peut payer par téléphone chez vous ?","tgt":"可以用手机付款吗？","ro":"Kěyǐ yòng shǒujī fùkuǎn ma?"},{"fr":"Scannez ce code, s'il vous plaît.","tgt":"请扫这个码。","ro":"Qǐng sǎo zhège mǎ."},{"fr":"Je n'ai presque jamais d'espèces sur moi.","tgt":"我身上几乎不带现金。","ro":"Wǒ shēnshang jīhū bú dài xiànjīn."},{"fr":"Ma carte bancaire est déjà liée à mon téléphone.","tgt":"我的银行卡已经绑好了。","ro":"Wǒ de yínhángkǎ yǐjīng bǎng hǎo le."},{"fr":"Le paiement n'est pas passé, je réessaie.","tgt":"付款没成功，我再试一次。","ro":"Fùkuǎn méi chénggōng, wǒ zài shì yí cì."},{"fr":"Zut, mon téléphone est presque déchargé.","tgt":"我的手机快没电了。","ro":"Wǒ de shǒujī kuài méi diàn le."},{"fr":"Tu peux aussi me faire un virement.","tgt":"你也可以转账给我。","ro":"Nǐ yě kěyǐ zhuǎnzhàng gěi wǒ."},{"fr":"Je t'ai déjà envoyé l'argent du dîner d'hier.","tgt":"昨天晚饭的钱我已经转给你了。","ro":"Zuótiān wǎnfàn de qián wǒ yǐjīng zhuǎn gěi nǐ le."},{"fr":"C'est vraiment pratique, plus besoin de portefeuille.","tgt":"真方便，不用带钱包了。","ro":"Zhēn fāngbiàn, bú yòng dài qiánbāo le."}]},{"title":"Se faire livrer un repas","phrases":[{"fr":"Je n'ai pas envie de faire la cuisine ce soir.","tgt":"今天晚上我不想做饭。","ro":"Jīntiān wǎnshang wǒ bù xiǎng zuò fàn."},{"fr":"Et si on se faisait livrer quelque chose ?","tgt":"我们叫个外卖吧？","ro":"Wǒmen jiào ge wàimài ba?"},{"fr":"Tu as envie de nouilles ou de riz sauté ?","tgt":"你想吃面条还是炒饭？","ro":"Nǐ xiǎng chī miàntiáo háishi chǎofàn?"},{"fr":"Ce restaurant livre en une demi-heure.","tgt":"这家饭馆半个小时就能送到。","ro":"Zhè jiā fànguǎn bàn ge xiǎoshí jiù néng sòngdào."},{"fr":"Il faut bien préciser le bâtiment et le numéro de l'appartement.","tgt":"地址要写清楚，几号楼几室。","ro":"Dìzhǐ yào xiě qīngchu, jǐ hào lóu jǐ shì."},{"fr":"J'ai mis en commentaire : pas trop épicé.","tgt":"我在备注里写了：不要太辣。","ro":"Wǒ zài bèizhù li xiěle: búyào tài là."},{"fr":"Le livreur est déjà en bas de l'immeuble.","tgt":"外卖员已经到楼下了。","ro":"Wàimàiyuán yǐjīng dào lóu xià le."},{"fr":"Il m'a appelé, mais je n'ai pas entendu.","tgt":"他给我打电话了，可是我没听见。","ro":"Tā gěi wǒ dǎ diànhuà le, kěshì wǒ méi tīngjiàn."},{"fr":"Un peu de soupe s'est renversée.","tgt":"汤洒出来了一点儿。","ro":"Tāng sǎ chūlai le yìdiǎnr."},{"fr":"Ce n'est pas grave, c'est encore chaud.","tgt":"没关系，还是热的。","ro":"Méi guānxi, hái shì rè de."}]},{"title":"Hier au bureau","phrases":[{"fr":"Hier, j'ai couru toute la journée au bureau.","tgt":"昨天我在公司忙了一整天。","ro":"Zuótiān wǒ zài gōngsī mángle yì zhěng tiān."},{"fr":"Le matin, j'ai lu tous mes mails.","tgt":"早上我看完了所有的邮件。","ro":"Zǎoshang wǒ kàn wánle suǒyǒu de yóujiàn."},{"fr":"Le rapport, tu as fini de l'écrire ?","tgt":"报告你写完了吗？","ro":"Bàogào nǐ xiě wán le ma?"},{"fr":"Pas encore, je n'en ai écrit que la moitié.","tgt":"还没写完，我只写了一半。","ro":"Hái méi xiě wán, wǒ zhǐ xiěle yíbàn."},{"fr":"Pendant la réunion, je n'ai pas tout compris.","tgt":"开会的时候，我没全听懂。","ro":"Kāihuì de shíhou, wǒ méi quán tīng dǒng."},{"fr":"Le patron parlait beaucoup trop vite.","tgt":"老板说得太快了。","ro":"Lǎobǎn shuō de tài kuài le."},{"fr":"Tu as bien entendu le nom du client ?","tgt":"你听清楚客户的名字了吗？","ro":"Nǐ tīng qīngchu kèhù de míngzi le ma?"},{"fr":"Je n'ai pas trouvé le fichier sur l'ordinateur.","tgt":"我在电脑上没找到那个文件。","ro":"Wǒ zài diànnǎo shang méi zhǎodào nàge wénjiàn."},{"fr":"Et en plus, j'ai mal écrit son nom.","tgt":"而且他的名字我还写错了。","ro":"Érqiě tā de míngzi wǒ hái xiě cuò le."},{"fr":"Je ne suis rentré qu'à neuf heures, épuisé.","tgt":"我九点才回到家，累坏了。","ro":"Wǒ jiǔ diǎn cái huí dào jiā, lèi huài le."}],"tip":{"title":"Le complément de résultat : « kàn wán, tīng dǒng »","example":"Le matin, j'ai lu tous mes mails. — 早上我<b>看完</b>了所有的邮件。","body":"En chinois, un verbe seul dit seulement qu'on a fait l'action, pas qu'elle a abouti. Pour dire le résultat, on colle juste après le verbe un second mot : « kàn », regarder, devient « kàn wán », finir de lire, et « tīng », écouter, devient « tīng dǒng », comprendre ce qu'on entend. Dans « Zǎoshang wǒ kàn wánle suǒyǒu de yóujiàn », on a mot à mot : matin, je, lire-fini, tous les mails. Pour la négation, on emploie « méi » : « Wǒ méi tīng dǒng », je n'ai pas compris, alors que « Wǒ méi tīng » voudrait dire que je n'ai même pas écouté. D'autres résultats très utiles : « xiě cuò », se tromper en écrivant, et « zhǎo dào », trouver ce qu'on cherchait. Astuce : pensez verbe plus résultat, deux briques que l'on prononce d'un seul souffle.","exampleRo":"Zǎoshang wǒ kàn wánle suǒyǒu de yóujiàn.","lit":"matin · je · lire-finir · [accompli] · tous · [possessif] · mail","say":{"kàn":"看","kàn wán":"看完","tīng":"听","tīng dǒng":"听懂","Zǎoshang wǒ kàn wánle suǒyǒu de yóujiàn":"早上我看完了所有的邮件","méi":"没","Wǒ méi tīng dǒng":"我没听懂","Wǒ méi tīng":"我没听","xiě cuò":"写错","zhǎo dào":"找到","kàn wán, tīng dǒng":"看完、听懂"}}},{"title":"Le grand ménage","phrases":[{"fr":"Ce week-end, on fait le grand ménage.","tgt":"这个周末我们大扫除。","ro":"Zhège zhōumò wǒmen dà sǎochú."},{"fr":"Mets les livres sur l'étagère, s'il te plaît.","tgt":"请把书放到书架上。","ro":"Qǐng bǎ shū fàng dào shūjià shang."},{"fr":"J'ai déjà lavé tout le linge.","tgt":"我已经把衣服都洗好了。","ro":"Wǒ yǐjīng bǎ yīfu dōu xǐ hǎo le."},{"fr":"Tu peux descendre la poubelle ?","tgt":"你能把垃圾拿下去吗？","ro":"Nǐ néng bǎ lājī ná xiàqu ma?"},{"fr":"Ferme la fenêtre, il y a trop de vent.","tgt":"把窗户关上吧，风太大了。","ro":"Bǎ chuānghu guānshang ba, fēng tài dà le."},{"fr":"Où as-tu mis les clés ?","tgt":"你把钥匙放在哪儿了？","ro":"Nǐ bǎ yàoshi fàng zài nǎr le?"},{"fr":"Je les ai mises dans le tiroir.","tgt":"我把钥匙放在抽屉里了。","ro":"Wǒ bǎ yàoshi fàng zài chōuti li le."},{"fr":"Et si on poussait le canapé contre le mur ?","tgt":"我们把沙发推到墙边吧？","ro":"Wǒmen bǎ shāfā tuī dào qiáng biān ba?"},{"fr":"Toi, range d'abord la cuisine.","tgt":"你先把厨房收拾一下。","ro":"Nǐ xiān bǎ chúfáng shōushi yíxià."},{"fr":"Voilà, maintenant l'appartement est propre.","tgt":"好了，现在家里很干净了。","ro":"Hǎo le, xiànzài jiā li hěn gānjìng le."}],"tip":{"title":"« Bǎ » : mettre l'objet devant le verbe","example":"Mets les livres sur l'étagère, s'il te plaît. — 请<b>把</b>书放到书架上。","body":"Le français dit « mets les livres sur l'étagère », dans l'ordre verbe puis objet. Le chinois, avec « bǎ », fait passer l'objet devant le verbe pour dire ce qu'on en fait et où il finit : « Qǐng bǎ shū fàng dào shūjià shang », mot à mot s'il te plaît, les livres, poser jusqu'à l'étagère, dessus. La phrase suit toujours le même moule : « bǎ », l'objet, le verbe, puis une suite qui dit le résultat ou le lieu. On ne s'arrête jamais sur le verbe nu : on dit « Bǎ chuānghu guānshang », ferme la fenêtre, ou « Bǎ yīfu xǐ hǎo le », le linge est lavé. Astuce : « bǎ » voulait dire au départ prendre en main ; imaginez que vous saisissez l'objet avant d'agir dessus.","exampleRo":"Qǐng bǎ shū fàng dào shūjià shang.","lit":"s'il te plaît · [objet devant] · livre · poser · arriver · étagère · dessus","say":{"Bǎ":"把","bǎ":"把","Qǐng bǎ shū fàng dào shūjià shang":"请把书放到书架上","Bǎ chuānghu guānshang":"把窗户关上","Bǎ yīfu xǐ hǎo le":"把衣服洗好了"}}},{"title":"À la clinique du quartier","phrases":[{"fr":"Je ne me sens pas bien depuis hier soir.","tgt":"我从昨天晚上开始就不舒服。","ro":"Wǒ cóng zuótiān wǎnshang kāishǐ jiù bù shūfu."},{"fr":"Il faut d'abord s'enregistrer à l'accueil.","tgt":"先要在前台挂号。","ro":"Xiān yào zài qiántái guàhào."},{"fr":"Où avez-vous mal ?","tgt":"您哪儿不舒服？","ro":"Nín nǎr bù shūfu?"},{"fr":"J'ai mal à la gorge et un peu de fièvre.","tgt":"我嗓子疼，还有点儿发烧。","ro":"Wǒ sǎngzi téng, hái yǒudiǎnr fāshāo."},{"fr":"Ça dure depuis combien de jours ?","tgt":"几天了？","ro":"Jǐ tiān le?"},{"fr":"Ça fait déjà deux jours.","tgt":"已经两天了。","ro":"Yǐjīng liǎng tiān le."},{"fr":"Ouvrez la bouche, s'il vous plaît.","tgt":"请张开嘴。","ro":"Qǐng zhāngkāi zuǐ."},{"fr":"C'est juste un rhume, rien de grave.","tgt":"只是感冒，不严重。","ro":"Zhǐshì gǎnmào, bù yánzhòng."},{"fr":"Reposez-vous bien et buvez beaucoup d'eau.","tgt":"好好休息，多喝水。","ro":"Hǎohǎo xiūxi, duō hē shuǐ."},{"fr":"Si la fièvre ne baisse pas, revenez me voir.","tgt":"如果烧不退，再来找我。","ro":"Rúguǒ shāo bú tuì, zài lái zhǎo wǒ."}]},{"title":"À la pharmacie","phrases":[{"fr":"Je cherche un médicament contre la toux.","tgt":"我想买点儿治咳嗽的药。","ro":"Wǒ xiǎng mǎi diǎnr zhì késou de yào."},{"fr":"C'est pour un adulte ou pour un enfant ?","tgt":"是大人用还是小孩儿用？","ro":"Shì dàren yòng háishi xiǎoháir yòng?"},{"fr":"C'est pour moi-même.","tgt":"是我自己用。","ro":"Shì wǒ zìjǐ yòng."},{"fr":"Ce sirop marche plutôt bien.","tgt":"这种糖浆效果不错。","ro":"Zhè zhǒng tángjiāng xiàoguǒ búcuò."},{"fr":"Combien de fois par jour faut-il le prendre ?","tgt":"一天吃几次？","ro":"Yì tiān chī jǐ cì?"},{"fr":"Trois fois par jour, à prendre après manger.","tgt":"一天三次，饭后吃。","ro":"Yì tiān sān cì, fàn hòu chī."},{"fr":"Ce médicament, il faut une ordonnance ?","tgt":"这个药要处方吗？","ro":"Zhège yào yào chǔfāng ma?"},{"fr":"Non, vous pouvez l'acheter directement.","tgt":"不用，可以直接买。","ro":"Bú yòng, kěyǐ zhíjiē mǎi."},{"fr":"Vous avez aussi des pansements ?","tgt":"有创可贴吗？","ro":"Yǒu chuāngkětiē ma?"},{"fr":"Je peux utiliser ma carte d'assurance maladie ?","tgt":"可以用医保卡吗？","ro":"Kěyǐ yòng yībǎokǎ ma?"}]},{"title":"Les voisins de l'immeuble","phrases":[{"fr":"Je ne connais pas encore bien mes voisins.","tgt":"我跟邻居还不太熟。","ro":"Wǒ gēn línjū hái bú tài shú."},{"fr":"La dame d'en face est très gentille.","tgt":"对门的阿姨人很好。","ro":"Duìmén de āyí rén hěn hǎo."},{"fr":"Elle m'a apporté des raviolis faits maison.","tgt":"她给我送了一些自己包的饺子。","ro":"Tā gěi wǒ sòngle yìxiē zìjǐ bāo de jiǎozi."},{"fr":"Les voisins du dessus sont bruyants le soir.","tgt":"楼上的邻居晚上很吵。","ro":"Lóu shàng de línjū wǎnshang hěn chǎo."},{"fr":"Je vais aller leur en parler gentiment.","tgt":"我去跟他们好好说说。","ro":"Wǒ qù gēn tāmen hǎohǎo shuōshuo."},{"fr":"Votre colis a été déposé chez moi.","tgt":"您的快递放在我家了。","ro":"Nín de kuàidì fàng zài wǒ jiā le."},{"fr":"Merci mille fois, c'est trop gentil.","tgt":"太谢谢您了，您太客气了。","ro":"Tài xièxie nín le, nín tài kèqi le."},{"fr":"Si vous avez besoin de quoi que ce soit, frappez chez moi.","tgt":"有事就来敲我的门。","ro":"Yǒu shì jiù lái qiāo wǒ de mén."},{"fr":"Le soir, les voisins dansent sur la place en bas.","tgt":"晚上邻居们在楼下的广场上跳舞。","ro":"Wǎnshang línjūmen zài lóu xià de guǎngchǎng shang tiàowǔ."},{"fr":"Petit à petit, nous sommes devenus amis.","tgt":"慢慢地，我们成了朋友。","ro":"Mànmàn de, wǒmen chéngle péngyou."}]},{"title":"Au supermarché","phrases":[{"fr":"Il me faut des œufs, du lait et du pain.","tgt":"我要买鸡蛋、牛奶和面包。","ro":"Wǒ yào mǎi jīdàn, niúnǎi hé miànbāo."},{"fr":"Pardon, où se trouvent les fruits ?","tgt":"请问，水果在哪儿？","ro":"Qǐngwèn, shuǐguǒ zài nǎr?"},{"fr":"Aujourd'hui, les légumes sont en promotion.","tgt":"今天蔬菜打折。","ro":"Jīntiān shūcài dǎzhé."},{"fr":"Ces pommes sont plus chères qu'au marché.","tgt":"这些苹果比菜市场的贵。","ro":"Zhèxiē píngguǒ bǐ càishìchǎng de guì."},{"fr":"Je vais prendre un kilo de tomates.","tgt":"我要一公斤西红柿。","ro":"Wǒ yào yì gōngjīn xīhóngshì."},{"fr":"Il vous faut un sac ?","tgt":"您要袋子吗？","ro":"Nín yào dàizi ma?"},{"fr":"Non merci, j'ai apporté le mien.","tgt":"不用了，我自己带了。","ro":"Bú yòng le, wǒ zìjǐ dài le."},{"fr":"Il y a une longue file à la caisse.","tgt":"收银台排队的人很多。","ro":"Shōuyíntái páiduì de rén hěn duō."},{"fr":"On peut se faire livrer les courses à la maison.","tgt":"买的东西可以送到家。","ro":"Mǎi de dōngxi kěyǐ sòngdào jiā."},{"fr":"Ça me fait combien en tout ?","tgt":"一共多少钱？","ro":"Yígòng duōshao qián?"}]},{"title":"Le week-end dernier","phrases":[{"fr":"Qu'est-ce que tu as fait le week-end dernier ?","tgt":"上个周末你做什么了？","ro":"Shàng ge zhōumò nǐ zuò shénme le?"},{"fr":"Samedi, je suis allé me promener sur le Bund.","tgt":"星期六我去外滩散步了。","ro":"Xīngqīliù wǒ qù Wàitān sànbù le."},{"fr":"Il y avait un monde fou.","tgt":"人多得不得了。","ro":"Rén duō de bùdéliǎo."},{"fr":"Ensuite, on a mangé des xiaolongbao.","tgt":"然后我们吃了小笼包。","ro":"Ránhòu wǒmen chīle xiǎolóngbāo."},{"fr":"Dimanche, je suis resté chez moi toute la journée.","tgt":"星期天我在家待了一整天。","ro":"Xīngqītiān wǒ zài jiā dāile yì zhěng tiān."},{"fr":"J'ai vu deux films et j'ai fait la grasse matinée.","tgt":"我看了两部电影，还睡了个懒觉。","ro":"Wǒ kànle liǎng bù diànyǐng, hái shuìle ge lǎnjiào."},{"fr":"Le soir, j'ai fait un appel vidéo avec mes parents en France.","tgt":"晚上我给在法国的父母打了视频电话。","ro":"Wǎnshang wǒ gěi zài Fǎguó de fùmǔ dǎle shìpín diànhuà."},{"fr":"Tu n'es pas sorti avec des amis ?","tgt":"你跟朋友出去玩儿了吗？","ro":"Nǐ gēn péngyou chūqu wánr le ma?"},{"fr":"Non, il a plu toute la journée de dimanche.","tgt":"没有，星期天下了一天的雨。","ro":"Méiyǒu, xīngqītiān xiàle yì tiān de yǔ."},{"fr":"C'était un week-end calme, mais bien agréable.","tgt":"那个周末过得很安静，也很舒服。","ro":"Nàge zhōumò guò de hěn ānjìng, yě hěn shūfu."}]},{"title":"Déjà fait ou fait hier ?","phrases":[{"fr":"Tu es déjà allé à Suzhou ?","tgt":"你去过苏州吗？","ro":"Nǐ qùguo Sūzhōu ma?"},{"fr":"Oui, j'y suis déjà allé deux fois.","tgt":"去过两次。","ro":"Qùguo liǎng cì."},{"fr":"Je n'ai jamais goûté au crabe chevelu.","tgt":"我从来没吃过大闸蟹。","ro":"Wǒ cónglái méi chīguo dàzháxiè."},{"fr":"Hier soir, j'en ai enfin mangé un.","tgt":"昨天晚上我终于吃了一只。","ro":"Zuótiān wǎnshang wǒ zhōngyú chīle yì zhī."},{"fr":"Tu as déjà pris le train à grande vitesse ?","tgt":"你坐过高铁吗？","ro":"Nǐ zuòguo gāotiě ma?"},{"fr":"Oui, la semaine dernière, je suis allé à Hangzhou en train rapide.","tgt":"坐过，上个星期我坐高铁去了杭州。","ro":"Zuòguo, shàng ge xīngqī wǒ zuò gāotiě qùle Hángzhōu."},{"fr":"J'avais appris un peu de chinois avant de venir.","tgt":"来之前我学过一点儿中文。","ro":"Lái zhīqián wǒ xuéguo yìdiǎnr Zhōngwén."},{"fr":"Ce matin, je me suis acheté un vélo neuf.","tgt":"今天早上我买了一辆新自行车。","ro":"Jīntiān zǎoshang wǒ mǎile yí liàng xīn zìxíngchē."},{"fr":"Ce film, tu l'as déjà vu ?","tgt":"这部电影你看过吗？","ro":"Zhè bù diànyǐng nǐ kànguo ma?"},{"fr":"Non, mais beaucoup de gens m'en ont parlé.","tgt":"没看过，不过听很多人说过。","ro":"Méi kànguo, búguò tīng hěn duō rén shuōguo."}],"tip":{"title":"« Guo » et « le » : bien choisir entre expérience et accompli","example":"Oui, la semaine dernière, je suis allé à Hangzhou en train rapide. — 坐<b>过</b>，上个星期我坐高铁去<b>了</b>杭州。","body":"Les deux petits mots « guo » et « le » se placent juste après le verbe, mais ils ne racontent pas la même chose. « Guo » dit que vous avez déjà vécu l'expérience au moins une fois dans votre vie : « Nǐ qùguo Sūzhōu ma ? », es-tu déjà allé à Suzhou ? « Le » dit qu'une action précise s'est accomplie, à un moment précis : « Zuótiān wǎnshang wǒ zhōngyú chīle yì zhī », hier soir, j'en ai enfin mangé un. Dans « Zuòguo, shàng ge xīngqī wǒ zuò gāotiě qùle Hángzhōu », on répond d'abord avec « guo », oui, ça m'est déjà arrivé, puis on raconte le voyage précis avec « le ». À la négation, « guo » reste : « méi chīguo », je n'en ai jamais mangé, mais « le » disparaît : « méi chī », je n'ai pas mangé. Astuce : « guo » répond à « déjà dans ta vie ? », et « le » répond à « et alors, que s'est-il passé ? ».","exampleRo":"Zuòguo, shàng ge xīngqī wǒ zuò gāotiě qùle Hángzhōu.","lit":"prendre · [expérience] · semaine dernière · je · prendre · train rapide · aller · [accompli] · Hangzhou","say":{"Guo":"过","le":"了","guo":"过","Nǐ qùguo Sūzhōu ma ?":"你去过苏州吗？","Le":"了","Zuótiān wǎnshang wǒ zhōngyú chīle yì zhī":"昨天晚上我终于吃了一只","Zuòguo, shàng ge xīngqī wǒ zuò gāotiě qùle Hángzhōu":"坐过，上个星期我坐高铁去了杭州","méi chīguo":"没吃过","méi chī":"没吃"}}},{"title":"Souvenirs d'enfance","phrases":[{"fr":"Quand j'étais petit, j'habitais à la campagne.","tgt":"我小时候住在农村。","ro":"Wǒ xiǎoshíhou zhù zài nóngcūn."},{"fr":"À cette époque, c'est ma grand-mère qui s'occupait de moi.","tgt":"那时候是奶奶照顾我。","ro":"Nà shíhou shì nǎinai zhàogù wǒ."},{"fr":"Chaque été, on allait au bord de la mer.","tgt":"每年夏天我们都去海边。","ro":"Měi nián xiàtiān wǒmen dōu qù hǎibiān."},{"fr":"J'adorais nager et attraper des crabes.","tgt":"我特别喜欢游泳和抓螃蟹。","ro":"Wǒ tèbié xǐhuan yóuyǒng hé zhuā pángxiè."},{"fr":"À l'école, je n'étais pas très sage.","tgt":"上学的时候，我不太听话。","ro":"Shàngxué de shíhou, wǒ bú tài tīnghuà."},{"fr":"Mon meilleur ami habitait juste à côté.","tgt":"我最好的朋友就住在隔壁。","ro":"Wǒ zuì hǎo de péngyou jiù zhù zài gébì."},{"fr":"Enfant, tu as appris à jouer d'un instrument ?","tgt":"你小时候学过乐器吗？","ro":"Nǐ xiǎoshíhou xuéguo yuèqì ma?"},{"fr":"J'ai fait cinq ans de piano.","tgt":"我学了五年钢琴。","ro":"Wǒ xuéle wǔ nián gāngqín."},{"fr":"Je détestais faire mes devoirs.","tgt":"我一点儿也不喜欢写作业。","ro":"Wǒ yìdiǎnr yě bù xǐhuan xiě zuòyè."},{"fr":"Ce sont de très beaux souvenirs.","tgt":"那些都是很美好的回忆。","ro":"Nàxiē dōu shì hěn měihǎo de huíyì."}]},{"title":"Le métro aux heures de pointe","phrases":[{"fr":"Tous les matins, je vais au travail en métro.","tgt":"我每天早上坐地铁上班。","ro":"Wǒ měi tiān zǎoshang zuò dìtiě shàngbān."},{"fr":"À huit heures, les wagons sont bondés.","tgt":"八点的时候，车厢里挤满了人。","ro":"Bā diǎn de shíhou, chēxiāng li jǐ mǎnle rén."},{"fr":"Je dois changer de ligne à la place du Peuple.","tgt":"我要在人民广场换乘。","ro":"Wǒ yào zài Rénmín Guǎngchǎng huànchéng."},{"fr":"Il faut environ quarante minutes.","tgt":"大概要四十分钟。","ro":"Dàgài yào sìshí fēnzhōng."},{"fr":"Pardon, je descends à la prochaine station.","tgt":"不好意思，我下一站下车。","ro":"Bù hǎoyìsi, wǒ xià yí zhàn xià chē."},{"fr":"Excusez-moi, vous pouvez me laisser passer ?","tgt":"麻烦让一下。","ro":"Máfan ràng yíxià."},{"fr":"Ce matin, j'ai raté ma station.","tgt":"今天早上我坐过站了。","ro":"Jīntiān zǎoshang wǒ zuò guò zhàn le."},{"fr":"Je suis arrivé au bureau avec dix minutes de retard.","tgt":"我到公司晚了十分钟。","ro":"Wǒ dào gōngsī wǎnle shí fēnzhōng."},{"fr":"Le soir, je rentre parfois en vélo partagé.","tgt":"晚上我有时候骑共享单车回家。","ro":"Wǎnshang wǒ yǒushíhou qí gòngxiǎng dānchē huí jiā."},{"fr":"C'est un peu plus lent, mais bien plus agréable.","tgt":"虽然慢一点儿，但是舒服多了。","ro":"Suīrán màn yìdiǎnr, dànshì shūfu duō le."}]},{"title":"Une fuite dans la salle de bains","phrases":[{"fr":"Il y a une fuite d'eau dans la salle de bains.","tgt":"卫生间漏水了。","ro":"Wèishēngjiān lòu shuǐ le."},{"fr":"Ça goutte sans arrêt sous le lavabo.","tgt":"水池下面一直在滴水。","ro":"Shuǐchí xiàmian yìzhí zài dī shuǐ."},{"fr":"J'ai déjà coupé l'arrivée d'eau.","tgt":"我已经把总阀门关了。","ro":"Wǒ yǐjīng bǎ zǒng fámén guān le."},{"fr":"Je vais appeler le gardien de la résidence.","tgt":"我给物业打个电话。","ro":"Wǒ gěi wùyè dǎ ge diànhuà."},{"fr":"Le réparateur peut passer cet après-midi ?","tgt":"修理工今天下午能来吗？","ro":"Xiūlǐgōng jīntiān xiàwǔ néng lái ma?"},{"fr":"Il sera là vers trois heures.","tgt":"他三点左右到。","ro":"Tā sān diǎn zuǒyòu dào."},{"fr":"Le tuyau est trop vieux, il faut le remplacer.","tgt":"管子太旧了，得换一根新的。","ro":"Guǎnzi tài jiù le, děi huàn yì gēn xīn de."},{"fr":"Combien coûte la réparation ?","tgt":"修一下多少钱？","ro":"Xiū yíxià duōshao qián?"},{"fr":"C'est au propriétaire de payer.","tgt":"这个钱应该房东出。","ro":"Zhège qián yīnggāi fángdōng chū."},{"fr":"Voilà, tout est revenu à la normale.","tgt":"好了，现在一切正常了。","ro":"Hǎo le, xiànzài yíqiè zhèngcháng le."}]},{"title":"La salle de sport","phrases":[{"fr":"Je me suis abonné à une salle de sport près de chez moi.","tgt":"我在家附近的健身房办了张卡。","ro":"Wǒ zài jiā fùjìn de jiànshēnfáng bànle zhāng kǎ."},{"fr":"L'abonnement d'un an coûte deux mille yuans.","tgt":"年卡两千块。","ro":"Niánkǎ liǎngqiān kuài."},{"fr":"J'y vais trois fois par semaine.","tgt":"我一个星期去三次。","ro":"Wǒ yí ge xīngqī qù sān cì."},{"fr":"Aujourd'hui, j'ai couru cinq kilomètres.","tgt":"今天我跑了五公里。","ro":"Jīntiān wǒ pǎole wǔ gōnglǐ."},{"fr":"Je suis trop fatigué, je ne peux plus courir.","tgt":"我太累了，跑不动了。","ro":"Wǒ tài lèi le, pǎo bu dòng le."},{"fr":"Le coach m'a appris un nouvel exercice.","tgt":"教练教了我一个新动作。","ro":"Jiàoliàn jiāole wǒ yí ge xīn dòngzuò."},{"fr":"Tu fais du yoga ?","tgt":"你练瑜伽吗？","ro":"Nǐ liàn yújiā ma?"},{"fr":"Je préfère la natation, c'est meilleur pour le dos.","tgt":"我更喜欢游泳，对腰好。","ro":"Wǒ gèng xǐhuan yóuyǒng, duì yāo hǎo."},{"fr":"Après le sport, j'ai toujours une faim de loup.","tgt":"运动完以后，我总是特别饿。","ro":"Yùndòng wán yǐhòu, wǒ zǒngshì tèbié è."},{"fr":"Depuis un mois, je dors beaucoup mieux.","tgt":"这一个月我睡得好多了。","ro":"Zhè yí ge yuè wǒ shuì de hǎo duō le."}]},{"title":"Le tri des déchets à Shanghai","phrases":[{"fr":"À Shanghai, trier ses déchets est obligatoire.","tgt":"在上海，垃圾分类是必须的。","ro":"Zài Shànghǎi, lājī fēnlèi shì bìxū de."},{"fr":"Il existe quatre sortes de poubelles.","tgt":"垃圾桶有四种。","ro":"Lājītǒng yǒu sì zhǒng."},{"fr":"Les restes de repas vont dans les déchets humides.","tgt":"剩饭剩菜是湿垃圾。","ro":"Shèngfàn shèngcài shì shī lājī."},{"fr":"Le papier et les bouteilles se recyclent.","tgt":"纸和瓶子是可回收物。","ro":"Zhǐ hé píngzi shì kě huíshōu wù."},{"fr":"Les piles sont des déchets dangereux.","tgt":"电池是有害垃圾。","ro":"Diànchí shì yǒuhài lājī."},{"fr":"Et les mouchoirs usagés, ça va où ?","tgt":"用过的纸巾扔哪儿？","ro":"Yòngguo de zhǐjīn rēng nǎr?"},{"fr":"Ça, ce sont des déchets secs.","tgt":"那是干垃圾。","ro":"Nà shì gān lājī."},{"fr":"On ne peut sortir les poubelles que le matin et le soir.","tgt":"只能早上和晚上扔垃圾。","ro":"Zhǐ néng zǎoshang hé wǎnshang rēng lājī."},{"fr":"Un bénévole contrôle à côté des bacs.","tgt":"垃圾桶旁边有志愿者检查。","ro":"Lājītǒng pángbiān yǒu zhìyuànzhě jiǎnchá."},{"fr":"Au début, je me trompais tout le temps.","tgt":"刚开始的时候，我老是分错。","ro":"Gāng kāishǐ de shíhou, wǒ lǎoshì fēn cuò."}]},{"title":"Un dîner chez des amis","phrases":[{"fr":"Un collègue m'a invité à dîner chez lui samedi.","tgt":"同事请我星期六去他家吃饭。","ro":"Tóngshì qǐng wǒ xīngqīliù qù tā jiā chī fàn."},{"fr":"Qu'est-ce que je devrais apporter ?","tgt":"我应该带点儿什么？","ro":"Wǒ yīnggāi dài diǎnr shénme?"},{"fr":"Un panier de fruits, ce sera parfait.","tgt":"带一篮水果就很好。","ro":"Dài yì lán shuǐguǒ jiù hěn hǎo."},{"fr":"Entre vite, assieds-toi où tu veux.","tgt":"快请进，随便坐。","ro":"Kuài qǐng jìn, suíbiàn zuò."},{"fr":"Ça sent vraiment bon !","tgt":"好香啊！","ro":"Hǎo xiāng a!"},{"fr":"C'est ma femme qui a préparé tous ces plats.","tgt":"这些菜都是我太太做的。","ro":"Zhèxiē cài dōu shì wǒ tàitai zuò de."},{"fr":"Goûte ce poisson, c'est une recette de Shanghai.","tgt":"尝尝这条鱼，这是上海菜。","ro":"Chángchang zhè tiáo yú, zhè shì Shànghǎi cài."},{"fr":"J'ai bien mangé, je ne peux vraiment plus rien avaler.","tgt":"我吃饱了，真的吃不下了。","ro":"Wǒ chī bǎo le, zhēn de chī bu xià le."},{"fr":"Trinquons à notre amitié !","tgt":"为我们的友谊干杯！","ro":"Wèi wǒmen de yǒuyì gānbēi!"},{"fr":"Merci à vous, on a passé une soirée formidable.","tgt":"谢谢你们，今天晚上太开心了。","ro":"Xièxie nǐmen, jīntiān wǎnshang tài kāixīn le."}]},{"title":"Le typhon arrive","phrases":[{"fr":"Un typhon arrive sur Shanghai ce soir.","tgt":"今天晚上台风要来上海了。","ro":"Jīntiān wǎnshang táifēng yào lái Shànghǎi le."},{"fr":"Ne sors pas, c'est dangereux.","tgt":"别出门，太危险了。","ro":"Bié chūmén, tài wēixiǎn le."},{"fr":"Ne laisse rien sur le balcon.","tgt":"阳台上别放东西。","ro":"Yángtái shang bié fàng dōngxi."},{"fr":"Ferme bien toutes les fenêtres.","tgt":"把窗户都关好。","ro":"Bǎ chuānghu dōu guān hǎo."},{"fr":"Ne prends pas le métro, plusieurs lignes sont arrêtées.","tgt":"不要坐地铁，有几条线停了。","ro":"Búyào zuò dìtiě, yǒu jǐ tiáo xiàn tíng le."},{"fr":"Demain, il n'y a pas école.","tgt":"明天学校停课。","ro":"Míngtiān xuéxiào tíngkè."},{"fr":"Ne t'inquiète pas, on a assez à manger à la maison.","tgt":"别担心，家里吃的够了。","ro":"Bié dānxīn, jiā li chī de gòu le."},{"fr":"Ne reste pas sous les arbres.","tgt":"不要站在树下面。","ro":"Búyào zhàn zài shù xiàmian."},{"fr":"Évitez de marcher dans l'eau, s'il vous plaît.","tgt":"请不要在水里走。","ro":"Qǐng búyào zài shuǐ li zǒu."},{"fr":"Le vent est tombé, le typhon est passé.","tgt":"风小了，台风过去了。","ro":"Fēng xiǎo le, táifēng guòqu le."}],"tip":{"title":"« Bié » et « bùyào » : l'interdiction","example":"Ne sors pas, c'est dangereux. — <b>别</b>出门，太危险了。","body":"Pour dire à quelqu'un de ne pas faire quelque chose, on place « bié » ou « búyào » juste devant le verbe, sans rien changer d'autre. « Bié chūmén, tài wēixiǎn le » signifie ne sors pas, c'est trop dangereux : « bié », ne pas, « chūmén », sortir, « tài wēixiǎn le », trop dangereux. Attention à la prononciation : le dictionnaire donne « bùyào », mais on dit « búyào », car « bù » monte devant un quatrième ton. « Bié » est court et familier, parfait entre proches, tandis que « búyào » sonne plus net, et avec « qǐng » devant, « Qǐng búyào », il devient poli, comme dans les annonces. Deux formules à retenir : « Bié dānxīn », ne t'inquiète pas, et « Bié kèqi », ne fais pas de manières. Astuce : entendez « bié » comme un petit coup de frein donné juste avant le verbe.","exampleRo":"Bié chūmén, tài wēixiǎn le.","lit":"ne pas · sortir · trop · dangereux · [changement]","say":{"Bié":"别","bùyào":"不要","bié":"别","búyào":"不要","Bié chūmén, tài wēixiǎn le":"别出门，太危险了","chūmén":"出门","tài wēixiǎn le":"太危险了","bù":"不","qǐng":"请","Qǐng búyào":"请不要","Bié dānxīn":"别担心","Bié kèqi":"别客气"}}},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ton chinois a fait de gros progrès.","tgt":"你的中文进步很大。","ro":"Nǐ de Zhōngwén jìnbù hěn dà."},{"fr":"Maintenant, je sais raconter ma journée.","tgt":"现在我能说说自己一天做了什么。","ro":"Xiànzài wǒ néng shuōshuo zìjǐ yì tiān zuòle shénme."},{"fr":"À la banque comme à la pharmacie, je me débrouille seul.","tgt":"在银行和药店，我都能自己办事了。","ro":"Zài yínháng hé yàodiàn, wǒ dōu néng zìjǐ bànshì le."},{"fr":"Je comprends de plus en plus ce que disent mes voisins.","tgt":"邻居说的话，我能听懂的越来越多了。","ro":"Línjū shuō de huà, wǒ néng tīng dǒng de yuè lái yuè duō le."},{"fr":"Les phrases avec « bǎ » restent un peu difficiles pour moi.","tgt":"把字句对我来说还有点儿难。","ro":"Bǎzìjù duì wǒ lái shuō hái yǒudiǎnr nán."},{"fr":"Je mélange parfois « guo » et « le ».","tgt":"我有时候会把“过”和“了”弄混。","ro":"Wǒ yǒushíhou huì bǎ \"guo\" hé \"le\" nòng hùn."},{"fr":"Il faut que je m'entraîne tous les jours.","tgt":"我得每天练习。","ro":"Wǒ děi měi tiān liànxí."},{"fr":"Bavarder avec les gens reste la meilleure méthode.","tgt":"跟人聊天是最好的办法。","ro":"Gēn rén liáotiān shì zuì hǎo de bànfǎ."},{"fr":"Le module suivant parle de voyage.","tgt":"下一个单元讲旅行。","ro":"Xià yí ge dānyuán jiǎng lǚxíng."},{"fr":"J'ai très envie de partir découvrir tout le pays.","tgt":"我很想去全国各地走走。","ro":"Wǒ hěn xiǎng qù quánguó gè dì zǒuzou."}]}]},{"id":2,"name":"En voyage","desc":"Des situations de voyage plus variées et plus complexes.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Kunming, la ville du printemps","phrases":[{"fr":"Kunming, on l'appelle aussi la ville du printemps.","tgt":"昆明也叫春城。","ro":"Kūnmíng yě jiào Chūnchéng."},{"fr":"Ici, il ne fait ni trop froid ni trop chaud toute l'année.","tgt":"这里一年四季都不太冷也不太热。","ro":"Zhèlǐ yì nián sìjì dōu bú tài lěng yě bú tài rè."},{"fr":"Nous sommes arrivés à Kunming à huit heures du soir.","tgt":"我们晚上八点到了昆明。","ro":"Wǒmen wǎnshang bā diǎn dàole Kūnmíng."},{"fr":"Je change d'abord un peu d'argent, puis je vais à l'hôtel.","tgt":"我先换点儿钱，然后去酒店。","ro":"Wǒ xiān huàn diǎnr qián, ránhòu qù jiǔdiàn."},{"fr":"Combien de temps faut-il de l'aéroport au centre-ville ?","tgt":"从机场到市中心要多长时间？","ro":"Cóng jīchǎng dào shì zhōngxīn yào duō cháng shíjiān?"},{"fr":"En métro, il faut environ quarante minutes.","tgt":"坐地铁大概四十分钟。","ro":"Zuò dìtiě dàgài sìshí fēnzhōng."},{"fr":"Sur le plateau, le soleil tape fort, n'oublie pas ton chapeau.","tgt":"高原上的阳光特别强，别忘了戴帽子。","ro":"Gāoyuán shang de yángguāng tèbié qiáng, bié wàngle dài màozi."},{"fr":"Les nouilles de riz de Kunming sont célèbres, tu dois absolument goûter.","tgt":"昆明的米线很有名，你一定要尝尝。","ro":"Kūnmíng de mǐxiàn hěn yǒumíng, nǐ yídìng yào chángchang."},{"fr":"Allons nous promener au parc du lac Vert demain.","tgt":"我们明天去翠湖公园散步吧。","ro":"Wǒmen míngtiān qù Cuìhú Gōngyuán sànbù ba."},{"fr":"Deux jours à Kunming, ça suffit largement.","tgt":"在昆明待两天就够了。","ro":"Zài Kūnmíng dāi liǎng tiān jiù gòu le."}]},{"title":"Une journée à la Forêt de pierre","phrases":[{"fr":"La Forêt de pierre est à environ cent kilomètres de Kunming.","tgt":"石林离昆明大概一百公里。","ro":"Shílín lí Kūnmíng dàgài yìbǎi gōnglǐ."},{"fr":"Nous avons acheté deux billets à la gare routière.","tgt":"我们在汽车站买了两张票。","ro":"Wǒmen zài qìchēzhàn mǎile liǎng zhāng piào."},{"fr":"Ces rochers ont plus de deux cents millions d'années.","tgt":"这些石头有两亿多年了。","ro":"Zhèxiē shítou yǒu liǎng yì duō nián le."},{"fr":"Beaucoup de ces rochers portent un nom.","tgt":"很多石头都有名字。","ro":"Hěn duō shítou dōu yǒu míngzi."},{"fr":"Regarde, est-ce que ce rocher ressemble à une personne ?","tgt":"你看，那块石头像不像一个人？","ro":"Nǐ kàn, nà kuài shítou xiàng bu xiàng yí ge rén?"},{"fr":"Les petits chemins sont étroits, et il y a beaucoup de monde.","tgt":"这里的小路很窄，人也很多。","ro":"Zhèlǐ de xiǎolù hěn zhǎi, rén yě hěn duō."},{"fr":"Nous avons pris une guide, elle appartient à l'ethnie Yi.","tgt":"我们请了一个导游，她是彝族人。","ro":"Wǒmen qǐngle yí ge dǎoyóu, tā shì Yízú rén."},{"fr":"Elle nous a raconté la légende d'Ashima.","tgt":"她给我们讲了阿诗玛的故事。","ro":"Tā gěi wǒmen jiǎngle Āshīmǎ de gùshi."},{"fr":"Après trois heures de marche, j'ai les jambes un peu fatiguées.","tgt":"走了三个小时，我的腿有点儿累。","ro":"Zǒule sān ge xiǎoshí, wǒ de tuǐ yǒudiǎnr lèi."},{"fr":"Cette excursion d'une journée valait vraiment le coup.","tgt":"这次一日游真值得。","ro":"Zhè cì yírìyóu zhēn zhíde."}]},{"title":"En car vers Dali","phrases":[{"fr":"Le car est là, montons vite !","tgt":"大巴来了，我们快上去吧！","ro":"Dàbā lái le, wǒmen kuài shàngqu ba!"},{"fr":"Mettez la grosse valise dans la soute, s'il vous plaît.","tgt":"请把大箱子放进去。","ro":"Qǐng bǎ dà xiāngzi fàng jìnqu."},{"fr":"Monte d'abord, je t'attends dans le car.","tgt":"你先上来，我在车上等你。","ro":"Nǐ xiān shànglai, wǒ zài chē shang děng nǐ."},{"fr":"Il fait trop chaud dehors, entre vite.","tgt":"外面太热了，快进来吧。","ro":"Wàimiàn tài rè le, kuài jìnlai ba."},{"fr":"À midi, le car s'arrête et tout le monde descend manger.","tgt":"中午车停了，大家都下去吃饭。","ro":"Zhōngwǔ chē tíng le, dàjiā dōu xiàqu chīfàn."},{"fr":"J'ai oublié ma bouteille d'eau dans le car, je dois retourner la chercher.","tgt":"我把水忘在车上了，得回去拿。","ro":"Wǒ bǎ shuǐ wàng zài chē shang le, děi huíqu ná."},{"fr":"Regarde, le soleil sort de derrière la montagne.","tgt":"你看，太阳从山后面出来了。","ro":"Nǐ kàn, tàiyáng cóng shān hòumiàn chūlai le."},{"fr":"Il a sorti la carte de son sac.","tgt":"他把地图从包里拿出来了。","ro":"Tā bǎ dìtú cóng bāo li ná chūlai le."},{"fr":"Arrivés à Dali, on descend du car, puis on y va à pied.","tgt":"到了大理，我们先下车，再走过去。","ro":"Dàole Dàlǐ, wǒmen xiān xià chē, zài zǒu guòqu."},{"fr":"Une amie attend à l'entrée de la vieille ville, on va la rejoindre.","tgt":"朋友在古城门口等，我们过去找她。","ro":"Péngyou zài gǔchéng ménkǒu děng, wǒmen guòqu zhǎo tā."}],"tip":{"title":"Le complément de direction : « lái » et « qù »","example":"Monte d'abord, je t'attends dans le car. — 你先<b>上来</b>，我在车上等你。","body":"En chinois, après un verbe de mouvement, on ajoute souvent « lái » ou « qù » pour dire dans quel sens va l'action par rapport à celui qui parle. « Lái » veut dire « vers moi », et « qù » veut dire « loin de moi ». Si je suis déjà dans le car et que je t'appelle, je dis « shànglai », monte jusqu'à moi ; si nous sommes dehors tous les deux, je dis « shàngqu », montons là-bas. Décomposons « Nǐ xiān shànglai » : « nǐ », toi, « xiān », d'abord, « shàng », monter, et « lai », vers moi. Même logique avec « jìnlai », entre ici, « xiàqu », descends, ou « huíqu », retourne là-bas ; dans ces mots, « lai » et « qu » se prononcent légers, sans ton marqué. Pour retenir, imaginez-vous au centre de la scène : « lái » vient vers vous, « qù » s'éloigne de vous.","exampleRo":"Nǐ xiān shànglai, wǒ zài chē shang děng nǐ.","lit":"toi · d'abord · monter-vers moi · je · à · car-dessus · attendre · toi","say":{"lái":"来","qù":"去","Lái":"来","shànglai":"上来","shàngqu":"上去","Nǐ xiān shànglai":"你先上来","nǐ":"你","xiān":"先","shàng":"上","jìnlai":"进来","xiàqu":"下去","huíqu":"回去","lai":"来"}}},{"title":"Flâner dans la vieille ville de Dali","phrases":[{"fr":"Les rues de la vieille ville de Dali sont propres et calmes.","tgt":"大理古城的街道又干净又安静。","ro":"Dàlǐ gǔchéng de jiēdào yòu gānjìng yòu ānjìng."},{"fr":"Au loin, c'est le mont Cang, il reste de la neige au sommet.","tgt":"远处就是苍山，山顶上还有雪。","ro":"Yuǎnchù jiù shì Cāngshān, shāndǐng shang hái yǒu xuě."},{"fr":"Beaucoup de Bai vivent ici.","tgt":"这里住着很多白族人。","ro":"Zhèlǐ zhùzhe hěn duō Báizú rén."},{"fr":"Les maisons bai ont des murs blancs, c'est très joli.","tgt":"白族的房子都是白墙，很好看。","ro":"Báizú de fángzi dōu shì bái qiáng, hěn hǎokàn."},{"fr":"Je voudrais goûter le thé des trois saveurs de la région.","tgt":"我想尝尝这里的三道茶。","ro":"Wǒ xiǎng chángchang zhèlǐ de sān dào chá."},{"fr":"La première tasse est amère, la deuxième est sucrée.","tgt":"第一道是苦的，第二道是甜的。","ro":"Dì yī dào shì kǔ de, dì èr dào shì tián de."},{"fr":"Il y a plein de petits cafés dans cette rue.","tgt":"这条街上有很多小咖啡馆。","ro":"Zhè tiáo jiē shang yǒu hěn duō xiǎo kāfēiguǎn."},{"fr":"Patron, combien coûte cette écharpe ?","tgt":"老板，这条围巾多少钱？","ro":"Lǎobǎn, zhè tiáo wéijīn duōshao qián?"},{"fr":"Quatre-vingts kuais, c'est trop cher, cinquante, ça vous va ?","tgt":"八十块，太贵了，五十块行吗？","ro":"Bāshí kuài, tài guì le, wǔshí kuài xíng ma?"},{"fr":"Le soir, la vieille ville est encore plus animée que la journée.","tgt":"晚上的古城比白天更热闹。","ro":"Wǎnshang de gǔchéng bǐ báitiān gèng rènao."}]},{"title":"Le tour du lac Erhai à vélo","phrases":[{"fr":"On a loué deux vélos, on est sur le point de partir.","tgt":"我们租了两辆自行车，要出发了。","ro":"Wǒmen zūle liǎng liàng zìxíngchē, yào chūfā le."},{"fr":"La caution est de deux cents kuais, on te la rend avec le vélo.","tgt":"押金是两百块，还车的时候退给你。","ro":"Yājīn shì liǎngbǎi kuài, huán chē de shíhou tuì gěi nǐ."},{"fr":"Regarde vite, le soleil va se coucher !","tgt":"快看，太阳要下山了！","ro":"Kuài kàn, tàiyáng yào xiàshān le!"},{"fr":"Il va bientôt faire nuit, il faut pédaler plus vite.","tgt":"天要黑了，我们得快点儿骑。","ro":"Tiān yào hēi le, wǒmen děi kuài diǎnr qí."},{"fr":"Mon téléphone va bientôt être à plat.","tgt":"我的手机快要没电了。","ro":"Wǒ de shǒujī kuài yào méi diàn le."},{"fr":"L'eau du lac Erhai est vraiment bleue !","tgt":"洱海的水真蓝啊！","ro":"Ěrhǎi de shuǐ zhēn lán a!"},{"fr":"Il y a un village devant, arrêtons-nous pour souffler un peu.","tgt":"前面有个村子，我们停下来休息一下吧。","ro":"Qiánmiàn yǒu ge cūnzi, wǒmen tíng xiàlai xiūxi yíxià ba."},{"fr":"On dirait qu'il va pleuvoir, tu as pris un imperméable ?","tgt":"好像要下雨了，带雨衣了吗？","ro":"Hǎoxiàng yào xià yǔ le, dài yǔyī le ma?"},{"fr":"On a parcouru plus de cinquante kilomètres à vélo !","tgt":"我们骑了五十多公里！","ro":"Wǒmen qíle wǔshí duō gōnglǐ!"},{"fr":"Le loueur va fermer, dépêchons-nous de rendre les vélos.","tgt":"租车店要关门了，赶快回去还车吧。","ro":"Zūchēdiàn yào guānmén le, gǎnkuài huíqu huán chē ba."}],"tip":{"title":"« Yào... le » : être sur le point de","example":"Regarde vite, le soleil va se coucher ! — 快看，太阳<b>要</b>下山<b>了</b>！","body":"Pour dire qu'une chose va arriver très bientôt, le chinois encadre le verbe entre « yào » et un petit « le » final. Décomposons « tàiyáng yào xiàshān le » : « tàiyáng », le soleil, « yào », va, « xiàshān », descendre derrière la montagne, et « le », qui annonce un changement imminent. C'est l'équivalent de notre « être sur le point de » ou « aller bientôt ». On peut renforcer avec « kuài » devant : « kuài yào xià yǔ le », il va pleuvoir d'une minute à l'autre. Autres exemples utiles en voyage : « yào chūfā le », on va partir, ou « tiān yào hēi le », il va faire nuit. Astuce : voyez « yào » comme une flèche vers le futur proche, et le « le » final comme une petite sonnette qui dit : attention, c'est pour tout de suite.","exampleRo":"Kuài kàn, tàiyáng yào xiàshān le!","lit":"vite · regarder · soleil · [bientôt] · descendre-montagne · [changement] !","say":{"Yào... le":"要……了","yào":"要","le":"了","tàiyáng yào xiàshān le":"太阳要下山了","tàiyáng":"太阳","xiàshān":"下山","kuài":"快","kuài yào xià yǔ le":"快要下雨了","yào chūfā le":"要出发了","tiān yào hēi le":"天要黑了"}}},{"title":"Une auberge dans la vieille ville de Lijiang","phrases":[{"fr":"Notre auberge se trouve dans la vieille ville de Lijiang.","tgt":"我们的客栈在丽江古城里面。","ro":"Wǒmen de kèzhàn zài Lìjiāng gǔchéng lǐmiàn."},{"fr":"Bonjour, j'ai réservé une chambre double sur internet.","tgt":"你好，我在网上订了一个双人间。","ro":"Nǐ hǎo, wǒ zài wǎngshang dìngle yí ge shuāngrénjiān."},{"fr":"Pourriez-vous me montrer votre passeport ?","tgt":"请给我看一下您的护照。","ro":"Qǐng gěi wǒ kàn yíxià nín de hùzhào."},{"fr":"La chambre est au premier étage, il n'y a pas d'ascenseur, désolé.","tgt":"房间在二楼，没有电梯，不好意思。","ro":"Fángjiān zài èr lóu, méiyǒu diàntī, bù hǎoyìsi."},{"fr":"Le petit-déjeuner commence à sept heures et demie, on le prend dans la cour.","tgt":"早饭从七点半开始，在院子里吃。","ro":"Zǎofàn cóng qī diǎn bàn kāishǐ, zài yuànzi li chī."},{"fr":"Le soir, la cour est calme, on peut regarder les étoiles.","tgt":"晚上院子里很安静，可以看星星。","ro":"Wǎnshang yuànzi li hěn ānjìng, kěyǐ kàn xīngxing."},{"fr":"L'eau chaude n'est pas très chaude, vous pouvez venir voir ?","tgt":"热水不太热，可以帮我看看吗？","ro":"Rèshuǐ bú tài rè, kěyǐ bāng wǒ kànkan ma?"},{"fr":"Le patron nous conseille d'aller écouter la musique ancienne naxi.","tgt":"老板推荐我们去听纳西古乐。","ro":"Lǎobǎn tuījiàn wǒmen qù tīng Nàxī gǔyuè."},{"fr":"Est-ce qu'on peut laisser nos bagages ici ?","tgt":"在这里可以寄存行李吗？","ro":"Zài zhèlǐ kěyǐ jìcún xíngli ma?"},{"fr":"Cette auberge est si confortable que j'ai envie de rester une nuit de plus.","tgt":"这家客栈很舒服，我想多住一晚。","ro":"Zhè jiā kèzhàn hěn shūfu, wǒ xiǎng duō zhù yì wǎn."}]},{"title":"Randonnée dans les gorges du Saut du Tigre","phrases":[{"fr":"Les gorges du Saut du Tigre sont parmi les plus profondes de Chine.","tgt":"虎跳峡是中国最深的峡谷之一。","ro":"Hǔtiào Xiá shì Zhōngguó zuì shēn de xiágǔ zhī yī."},{"fr":"Le sentier de randonnée se fait en deux jours.","tgt":"徒步路线一共要走两天。","ro":"Túbù lùxiàn yígòng yào zǒu liǎng tiān."},{"fr":"Ne charge pas trop ton sac, il suffit d'avoir assez d'eau.","tgt":"背包别太重，带够水就行。","ro":"Bēibāo bié tài zhòng, dài gòu shuǐ jiù xíng."},{"fr":"Ce passage est très raide, vas-y doucement.","tgt":"这段路特别陡，慢慢走。","ro":"Zhè duàn lù tèbié dǒu, mànmàn zǒu."},{"fr":"Je n'en peux plus, faisons une pause de cinq minutes.","tgt":"我爬不动了，休息五分钟吧。","ro":"Wǒ pá bu dòng le, xiūxi wǔ fēnzhōng ba."},{"fr":"Le grondement du fleuve en contrebas est impressionnant.","tgt":"下面的江水声音真大。","ro":"Xiàmiàn de jiāngshuǐ shēngyīn zhēn dà."},{"fr":"Il y a beaucoup de chevaux sur le sentier, fais attention.","tgt":"路上有很多马，要小心。","ro":"Lù shang yǒu hěn duō mǎ, yào xiǎoxīn."},{"fr":"Ce soir, on dort dans une auberge à flanc de montagne.","tgt":"今晚我们住在半山腰的客栈。","ro":"Jīnwǎn wǒmen zhù zài bànshānyāo de kèzhàn."},{"fr":"D'ici, la vue sur les sommets enneigés est superbe.","tgt":"从这儿看雪山，美极了。","ro":"Cóng zhèr kàn xuěshān, měi jí le."},{"fr":"On est enfin arrivés au bout du sentier !","tgt":"我们终于走到了！","ro":"Wǒmen zhōngyú zǒudào le!"}]},{"title":"La météo au mont du Dragon de Jade","phrases":[{"fr":"Demain, nous voulons aller au mont du Dragon de Jade.","tgt":"明天我们想去玉龙雪山。","ro":"Míngtiān wǒmen xiǎng qù Yùlóng Xuěshān."},{"fr":"S'il fait beau, on monte en téléphérique.","tgt":"如果天气好，我们就坐索道上去。","ro":"Rúguǒ tiānqì hǎo, wǒmen jiù zuò suǒdào shàngqu."},{"fr":"S'il pleut fort, le téléphérique fermera.","tgt":"如果下大雨，索道就会关。","ro":"Rúguǒ xià dà yǔ, suǒdào jiù huì guān."},{"fr":"Il fait très froid là-haut ; si tu n'as pas de veste épaisse, loues-en une sur place.","tgt":"山上很冷，如果你没有厚外套，就在那儿租一件。","ro":"Shān shang hěn lěng, rúguǒ nǐ méiyǒu hòu wàitào, jiù zài nàr zū yí jiàn."},{"fr":"La météo annonce des orages pour l'après-midi.","tgt":"天气预报说下午有雷阵雨。","ro":"Tiānqì yùbào shuō xiàwǔ yǒu léizhènyǔ."},{"fr":"Si on y va le matin, on évitera la pluie.","tgt":"如果早上去，就不会遇到雨。","ro":"Rúguǒ zǎoshang qù, jiù bú huì yùdào yǔ."},{"fr":"Au sommet, l'altitude est très élevée, il faut marcher lentement.","tgt":"山顶海拔很高，走路要慢一点儿。","ro":"Shāndǐng hǎibá hěn gāo, zǒulù yào màn yìdiǎnr."},{"fr":"Si tu as mal à la tête, dis-le-moi tout de suite.","tgt":"如果你觉得头疼，就马上告诉我。","ro":"Rúguǒ nǐ juéde tóuténg, jiù mǎshàng gàosu wǒ."},{"fr":"Il y a trop de nuages, on ne voit rien du tout.","tgt":"云太多了，什么都看不见。","ro":"Yún tài duō le, shénme dōu kàn bu jiàn."},{"fr":"Si demain c'est encore couvert, on ira plutôt à la vallée de la Lune bleue.","tgt":"如果明天还是阴天，我们就改去蓝月谷。","ro":"Rúguǒ míngtiān háishi yīntiān, wǒmen jiù gǎi qù Lányuè Gǔ."}],"tip":{"title":"« Rúguǒ... jiù... » : si... alors...","example":"S'il fait beau, on monte en téléphérique. — <b>如果</b>天气好，我们<b>就</b>坐索道上去。","body":"Pour poser une condition, on ouvre la phrase avec « rúguǒ », si, et on introduit la conséquence avec « jiù », alors. Attention à la place de « jiù » : il se met juste avant le verbe, donc après le sujet, jamais en tête de la deuxième partie. Décomposons « Rúguǒ tiānqì hǎo, wǒmen jiù zuò suǒdào shàngqu » : si le temps est bon, nous alors prenons le téléphérique pour monter. En français, on laisse souvent tomber le « alors », mais en chinois « jiù » rend la phrase beaucoup plus naturelle à l'oreille. Autres exemples : « rúguǒ xià yǔ, wǒmen jiù bú qù », s'il pleut, on n'y va pas, ou « rúguǒ nǐ lèi, jiù xiūxi ba », si tu es fatigué, repose-toi. Astuce : retenez le rythme « rúguǒ », une petite pause, puis « jiù », comme les deux plateaux d'une balance.","exampleRo":"Rúguǒ tiānqì hǎo, wǒmen jiù zuò suǒdào shàngqu.","lit":"si · temps · bon · nous · alors · prendre · téléphérique · monter-là-bas","say":{"Rúguǒ... jiù...":"如果……就……","rúguǒ":"如果","jiù":"就","Rúguǒ tiānqì hǎo, wǒmen jiù zuò suǒdào shàngqu":"如果天气好，我们就坐索道上去","rúguǒ xià yǔ, wǒmen jiù bú qù":"如果下雨，我们就不去","rúguǒ nǐ lèi, jiù xiūxi ba":"如果你累，就休息吧"}}},{"title":"Le train de nuit vers Guilin","phrases":[{"fr":"Nous avons acheté des billets en couchette pour Guilin.","tgt":"我们买了去桂林的卧铺票。","ro":"Wǒmen mǎile qù Guìlín de wòpù piào."},{"fr":"La couchette confort était trop chère, on a pris la couchette standard.","tgt":"软卧太贵了，我们要了硬卧。","ro":"Ruǎnwò tài guì le, wǒmen yàole yìngwò."},{"fr":"J'ai la couchette du haut, toi celle du bas.","tgt":"我是上铺，你是下铺。","ro":"Wǒ shì shàngpù, nǐ shì xiàpù."},{"fr":"Le train part de Kunming à neuf heures du soir.","tgt":"火车晚上九点从昆明出发。","ro":"Huǒchē wǎnshang jiǔ diǎn cóng Kūnmíng chūfā."},{"fr":"Il y a de l'eau chaude dans la voiture, on peut se faire des nouilles instantanées.","tgt":"车厢里有热水，可以泡方便面。","ro":"Chēxiāng li yǒu rèshuǐ, kěyǐ pào fāngbiànmiàn."},{"fr":"La dame d'en face nous a donné des mandarines.","tgt":"对面的阿姨给了我们一些橘子。","ro":"Duìmiàn de āyí gěile wǒmen yìxiē júzi."},{"fr":"Après dix heures, on éteint la lumière dans la voiture.","tgt":"十点以后车厢里就关灯了。","ro":"Shí diǎn yǐhòu chēxiāng li jiù guān dēng le."},{"fr":"Le train secoue trop, je n'arrive pas à dormir.","tgt":"火车太晃了，我睡不着。","ro":"Huǒchē tài huàng le, wǒ shuì bu zháo."},{"fr":"On arrive à Guilin demain à sept heures du matin.","tgt":"明天早上七点到桂林。","ro":"Míngtiān zǎoshang qī diǎn dào Guìlín."},{"fr":"Au réveil, derrière la vitre, il n'y a que des montagnes vertes.","tgt":"醒来的时候，窗外都是绿色的山。","ro":"Xǐnglái de shíhou, chuāng wài dōu shì lǜsè de shān."}]},{"title":"Premiers pas à Guilin","phrases":[{"fr":"« Les paysages de Guilin sont les plus beaux sous le ciel », tu connais ce dicton ?","tgt":"桂林山水甲天下，这句话你听过吗？","ro":"Guìlín shānshuǐ jiǎ tiānxià, zhè jù huà nǐ tīngguo ma?"},{"fr":"Ici, les collines se dressent une à une, avec des formes étonnantes.","tgt":"这里的山一座一座的，形状很特别。","ro":"Zhèlǐ de shān yí zuò yí zuò de, xíngzhuàng hěn tèbié."},{"fr":"Allons d'abord voir la colline en Trompe d'éléphant.","tgt":"我们先去看象鼻山吧。","ro":"Wǒmen xiān qù kàn Xiàngbí Shān ba."},{"fr":"Cette colline ressemble vraiment à un éléphant qui boit.","tgt":"那座山真的像一头大象在喝水。","ro":"Nà zuò shān zhēn de xiàng yì tóu dàxiàng zài hē shuǐ."},{"fr":"Les nouilles de riz de Guilin, c'est le matin qu'on les mange.","tgt":"桂林米粉早上吃最好。","ro":"Guìlín mǐfěn zǎoshang chī zuì hǎo."},{"fr":"Un bol de nouilles ne coûte que huit kuais, c'est donné.","tgt":"一碗米粉才八块钱，真便宜。","ro":"Yì wǎn mǐfěn cái bā kuài qián, zhēn piányi."},{"fr":"J'en voudrais un bol pas épicé.","tgt":"我要一碗不辣的。","ro":"Wǒ yào yì wǎn bú là de."},{"fr":"Le soir, on fait un tour en bateau sur les Deux Rivières et Quatre Lacs.","tgt":"晚上我们去两江四湖坐船。","ro":"Wǎnshang wǒmen qù Liǎngjiāng Sìhú zuò chuán."},{"fr":"L'été, à Guilin, il fait très chaud et il pleut souvent.","tgt":"桂林夏天特别热，也经常下雨。","ro":"Guìlín xiàtiān tèbié rè, yě jīngcháng xià yǔ."},{"fr":"De cet hôtel, la rivière est à cinq minutes à pied.","tgt":"这家酒店走到江边只要五分钟。","ro":"Zhè jiā jiǔdiàn zǒu dào jiāngbiān zhǐ yào wǔ fēnzhōng."}]},{"title":"Descendre la rivière Li","phrases":[{"fr":"Le bateau sur la rivière Li part à neuf heures du matin.","tgt":"漓江游船早上九点开。","ro":"Líjiāng yóuchuán zǎoshang jiǔ diǎn kāi."},{"fr":"De Guilin à Yangshuo en bateau, il faut plus de quatre heures.","tgt":"从桂林坐船到阳朔要四个多小时。","ro":"Cóng Guìlín zuò chuán dào Yángshuò yào sì ge duō xiǎoshí."},{"fr":"On peut aussi prendre un radeau de bambou, c'est plus paisible.","tgt":"我们也可以坐竹筏，更安静。","ro":"Wǒmen yě kěyǐ zuò zhúfá, gèng ānjìng."},{"fr":"Les paysages des deux rives ressemblent à une peinture chinoise.","tgt":"两岸的风景像一幅中国画。","ro":"Liǎng'àn de fēngjǐng xiàng yì fú Zhōngguó huà."},{"fr":"Regarde, c'est le paysage du billet de vingt yuans !","tgt":"你看，那是二十块钱背面的风景！","ro":"Nǐ kàn, nà shì èrshí kuài qián bèimiàn de fēngjǐng!"},{"fr":"Sur la rivière, il y a un pêcheur avec ses cormorans.","tgt":"江上有个渔民和他的鸬鹚。","ro":"Jiāng shang yǒu ge yúmín hé tā de lúcí."},{"fr":"Est-ce qu'on vend à déjeuner sur le bateau ?","tgt":"船上卖午饭吗？","ro":"Chuán shang mài wǔfàn ma?"},{"fr":"Je vais à l'avant du bateau pour prendre des photos.","tgt":"我想站到船头去拍照。","ro":"Wǒ xiǎng zhàn dào chuántóu qù pāizhào."},{"fr":"Il y a un peu de vent, tiens bien ton chapeau.","tgt":"风有点儿大，把帽子拿好。","ro":"Fēng yǒudiǎnr dà, bǎ màozi náhǎo."},{"fr":"C'est la plus belle rivière que j'aie jamais vue.","tgt":"这是我见过最美的江。","ro":"Zhè shì wǒ jiànguo zuì měi de jiāng."}]},{"title":"Yangshuo à vélo","phrases":[{"fr":"Il pédale très vite, je n'arrive pas à suivre.","tgt":"他骑车骑得很快，我跟不上。","ro":"Tā qí chē qí de hěn kuài, wǒ gēn bu shàng."},{"fr":"Tu roules trop vite, ralentis un peu !","tgt":"你骑得太快了，慢一点儿！","ro":"Nǐ qí de tài kuài le, màn yìdiǎnr!"},{"fr":"Le chemin le long de la rivière Yulong est bien aménagé.","tgt":"遇龙河边的小路修得很好。","ro":"Yùlóng Hé biān de xiǎolù xiū de hěn hǎo."},{"fr":"Le loueur de vélos parle très lentement, j'ai tout compris.","tgt":"租车店的老板说话说得很慢，我都听懂了。","ro":"Zūchēdiàn de lǎobǎn shuōhuà shuō de hěn màn, wǒ dōu tīngdǒng le."},{"fr":"Tu parles chinois de mieux en mieux.","tgt":"你的中文说得越来越好了。","ro":"Nǐ de Zhōngwén shuō de yuè lái yuè hǎo le."},{"fr":"À Yangshuo, je dors comme un bébé chaque nuit.","tgt":"在阳朔我每天都睡得很香。","ro":"Zài Yángshuò wǒ měi tiān dōu shuì de hěn xiāng."},{"fr":"On s'arrête au pied de la colline de la Lune.","tgt":"我们在月亮山下面停下来。","ro":"Wǒmen zài Yuèliang Shān xiàmiàn tíng xiàlai."},{"fr":"Ici, le poisson à la bière est particulièrement bien cuisiné.","tgt":"这里的啤酒鱼做得特别好吃。","ro":"Zhèlǐ de píjiǔyú zuò de tèbié hǎochī."},{"fr":"Tes photos sont vraiment réussies, envoie-les-moi.","tgt":"你拍得真好看，发给我吧。","ro":"Nǐ pāi de zhēn hǎokàn, fā gěi wǒ ba."},{"fr":"On a passé une super journée à vélo.","tgt":"骑了一天车，我们玩得很开心。","ro":"Qíle yì tiān chē, wǒmen wán de hěn kāixīn."}],"tip":{"title":"Le complément de degré : « pǎo de hěn kuài »","example":"Il pédale très vite, je n'arrive pas à suivre. — 他骑车骑<b>得很快</b>，我跟不上。","body":"Pour dire comment on fait quelque chose, le chinois place l'appréciation après le verbe, reliée par le petit mot « de », prononcé léger : « pǎo de hěn kuài », courir de manière très rapide, donc courir très vite. Décomposons « Tā qí chē qí de hěn kuài » : « tā », il, « qí chē », faire du vélo, puis on répète « qí », pédaler, ensuite « de », et enfin « hěn kuài », très vite. Quand le verbe a un complément, comme « qí chē » ou « shuōhuà », on répète le verbe avant « de » : c'est un réflexe à prendre à l'oral. Sans complément, c'est plus simple : « nǐ qí de tài kuài le », tu roules trop vite, ou « wǒmen wán de hěn kāixīn », on s'est bien amusés. Astuce : posez-vous la question « comment ? », et la réponse arrive toujours juste après « de ».","exampleRo":"Tā qí chē qí de hěn kuài, wǒ gēn bu shàng.","lit":"il · monter-vélo · pédaler · [degré] · très · vite · je · suivre · pas · arriver","say":{"de":"得","pǎo de hěn kuài":"跑得很快","Tā qí chē qí de hěn kuài":"他骑车骑得很快","tā":"他","qí chē":"骑车","qí":"骑","hěn kuài":"很快","shuōhuà":"说话","nǐ qí de tài kuài le":"你骑得太快了","wǒmen wán de hěn kāixīn":"我们玩得很开心"}}},{"title":"Les rizières en terrasses de Longji","phrases":[{"fr":"Les rizières de Longji sont à deux heures de route de Guilin.","tgt":"龙脊梯田离桂林两个小时车程。","ro":"Lóngjǐ Tītián lí Guìlín liǎng ge xiǎoshí chēchéng."},{"fr":"Ces terrasses existent depuis plusieurs siècles.","tgt":"这些梯田已经有几百年的历史了。","ro":"Zhèxiē tītián yǐjīng yǒu jǐ bǎi nián de lìshǐ le."},{"fr":"Dans les villages vivent des Zhuang et des Yao.","tgt":"村子里住着壮族和瑶族。","ro":"Cūnzi li zhùzhe Zhuàngzú hé Yáozú."},{"fr":"Les femmes yao ont des cheveux extrêmement longs.","tgt":"瑶族女人的头发特别长。","ro":"Yáozú nǚrén de tóufa tèbié cháng."},{"fr":"Ce soir, nous dormons dans une maison en bois sur la montagne.","tgt":"我们今晚住在山上的木楼里。","ro":"Wǒmen jīnwǎn zhù zài shān shang de mùlóu li."},{"fr":"Les bagages sont trop lourds, on peut payer quelqu'un pour les porter là-haut.","tgt":"行李太重了，可以请人帮忙背上去。","ro":"Xíngli tài zhòng le, kěyǐ qǐng rén bāngmáng bēi shàngqu."},{"fr":"Au printemps, les terrasses sont pleines d'eau, comme des miroirs.","tgt":"春天梯田里有水，像镜子一样。","ro":"Chūntiān tītián li yǒu shuǐ, xiàng jìngzi yíyàng."},{"fr":"En automne, les terrasses deviennent toutes dorées.","tgt":"秋天的时候，梯田都变成了金色。","ro":"Qiūtiān de shíhou, tītián dōu biànchéngle jīnsè."},{"fr":"Le riz cuit dans un tube de bambou est délicieux ici.","tgt":"这里的竹筒饭很香。","ro":"Zhèlǐ de zhútǒngfàn hěn xiāng."},{"fr":"Au sommet, devant le coucher du soleil, tout le monde se tait.","tgt":"在山顶上看日落，大家都不说话了。","ro":"Zài shāndǐng shang kàn rìluò, dàjiā dōu bù shuōhuà le."}]},{"title":"Un cours de cuisine à Yangshuo","phrases":[{"fr":"Ce matin, nous avons suivi un cours de cuisine.","tgt":"今天上午我们参加了一个烹饪课。","ro":"Jīntiān shàngwǔ wǒmen cānjiāle yí ge pēngrèn kè."},{"fr":"La prof nous emmène d'abord acheter les légumes au marché.","tgt":"老师先带我们去菜市场买菜。","ro":"Lǎoshī xiān dài wǒmen qù càishìchǎng mǎi cài."},{"fr":"Comment s'appelle ce légume vert ?","tgt":"这种绿色的菜叫什么名字？","ro":"Zhè zhǒng lǜsè de cài jiào shénme míngzi?"},{"fr":"On a appris à faire les œufs sautés aux tomates.","tgt":"我们学了做番茄炒蛋。","ro":"Wǒmen xuéle zuò fānqié chǎo dàn."},{"fr":"On met d'abord l'huile, et quand elle est chaude, on ajoute les œufs.","tgt":"先放油，油热了再放鸡蛋。","ro":"Xiān fàng yóu, yóu rè le zài fàng jīdàn."},{"fr":"Le feu est trop fort, baisse-le un peu.","tgt":"火太大了，关小一点儿。","ro":"Huǒ tài dà le, guān xiǎo yìdiǎnr."},{"fr":"Combien de sel faut-il ? Une toute petite pincée suffit.","tgt":"要放多少盐？一点点就够了。","ro":"Yào fàng duōshao yán? Yìdiǎndiǎn jiù gòu le."},{"fr":"Je coupe les légumes beaucoup trop lentement.","tgt":"我切菜切得太慢了。","ro":"Wǒ qiē cài qiē de tài màn le."},{"fr":"Les plats qu'on prépare soi-même ont un goût particulier.","tgt":"自己做的菜特别香。","ro":"Zìjǐ zuò de cài tèbié xiāng."},{"fr":"De retour en France, je le cuisinerai pour ma famille.","tgt":"回法国以后，我要做给家人吃。","ro":"Huí Fǎguó yǐhòu, wǒ yào zuò gěi jiārén chī."}]},{"title":"En route pour les Montagnes jaunes","phrases":[{"fr":"Nous prenons le train à grande vitesse de Guilin à Huangshan.","tgt":"我们从桂林坐高铁去黄山。","ro":"Wǒmen cóng Guìlín zuò gāotiě qù Huángshān."},{"fr":"La gare est hors de la ville, il faut une demi-heure en taxi.","tgt":"高铁站在城外，打车要半个小时。","ro":"Gāotiězhàn zài chéng wài, dǎchē yào bàn ge xiǎoshí."},{"fr":"Pour entrer en gare, il faut montrer son passeport au personnel.","tgt":"进站的时候要给工作人员看护照。","ro":"Jìn zhàn de shíhou yào gěi gōngzuò rényuán kàn hùzhào."},{"fr":"Nous sommes dans la voiture sept, côté fenêtre.","tgt":"我们在七号车厢，靠窗的座位。","ro":"Wǒmen zài qī hào chēxiāng, kào chuāng de zuòwèi."},{"fr":"Ce train est rapide et ne secoue pas, c'est encore plus pratique que l'avion.","tgt":"高铁又快又稳，比飞机还方便。","ro":"Gāotiě yòu kuài yòu wěn, bǐ fēijī hái fāngbiàn."},{"fr":"Peut-on commander un plateau-repas à bord ?","tgt":"车上可以订盒饭吗？","ro":"Chē shang kěyǐ dìng héfàn ma?"},{"fr":"À la gare de Huangshan Nord, on prendra un car jusqu'au pied de la montagne.","tgt":"到了黄山北站，我们再坐大巴去山下。","ro":"Dàole Huángshān Běi Zhàn, wǒmen zài zuò dàbā qù shān xià."},{"fr":"Le bourg au pied de la montagne s'appelle Tangkou.","tgt":"山下的小镇叫汤口。","ro":"Shān xià de xiǎozhèn jiào Tāngkǒu."},{"fr":"On peut laisser les grosses valises à l'hôtel et monter avec un petit sac.","tgt":"大箱子可以放在酒店，只带小包上山。","ro":"Dà xiāngzi kěyǐ fàng zài jiǔdiàn, zhǐ dài xiǎo bāo shàng shān."},{"fr":"Couche-toi tôt, demain on se lève à cinq heures.","tgt":"早点儿睡，明天五点就要起床。","ro":"Zǎo diǎnr shuì, míngtiān wǔ diǎn jiù yào qǐchuáng."}]},{"title":"L'ascension de Huangshan","phrases":[{"fr":"Bien qu'il y ait un téléphérique, nous voulons monter à pied.","tgt":"虽然有索道，但是我们想走上去。","ro":"Suīrán yǒu suǒdào, dànshì wǒmen xiǎng zǒu shàngqu."},{"fr":"Il y a énormément de marches, mais le paysage est magnifique.","tgt":"虽然台阶很多，但是风景特别美。","ro":"Suīrán táijiē hěn duō, dànshì fēngjǐng tèbié měi."},{"fr":"Tout est cher là-haut, et pourtant tout le monde achète.","tgt":"山上的东西虽然贵，但是大家都买。","ro":"Shān shang de dōngxi suīrán guì, dànshì dàjiā dōu mǎi."},{"fr":"Une bouteille d'eau coûte quinze kuais, car tout est monté à dos de porteur.","tgt":"一瓶水要十五块，因为都是挑夫背上来的。","ro":"Yì píng shuǐ yào shíwǔ kuài, yīnwèi dōu shì tiāofū bēi shànglai de."},{"fr":"Ces porteurs ont beau être lourdement chargés, ils marchent plus vite que nous.","tgt":"那些挑夫虽然背得很重，但是走得比我们快。","ro":"Nàxiē tiāofū suīrán bēi de hěn zhòng, dànshì zǒu de bǐ wǒmen kuài."},{"fr":"Le pin qui accueille les visiteurs est juste devant.","tgt":"迎客松就在前面。","ro":"Yíngkè Sōng jiù zài qiánmiàn."},{"fr":"Je suis épuisé, mais je ne veux pas abandonner.","tgt":"虽然我很累，但是我不想放弃。","ro":"Suīrán wǒ hěn lèi, dànshì wǒ bù xiǎng fàngqì."},{"fr":"L'hôtel du sommet est très simple, mais il est idéalement situé.","tgt":"山顶的酒店虽然很简单，但是位置很好。","ro":"Shāndǐng de jiǔdiàn suīrán hěn jiǎndān, dànshì wèizhì hěn hǎo."},{"fr":"Quand les jambes font mal, on sort le bâton de marche.","tgt":"腿疼的时候，就用登山杖。","ro":"Tuǐ téng de shíhou, jiù yòng dēngshānzhàng."},{"fr":"Il nous a fallu six heures de montée pour atteindre le sommet.","tgt":"我们爬了六个小时才到山顶。","ro":"Wǒmen pále liù ge xiǎoshí cái dào shāndǐng."}],"tip":{"title":"« Suīrán... dànshì... » : bien que, mais","example":"Je suis épuisé, mais je ne veux pas abandonner. — <b>虽然</b>我很累，<b>但是</b>我不想放弃。","body":"Pour opposer deux idées, le chinois utilise volontiers une paire de mots : « suīrán » au début, bien que, et « dànshì » dans la deuxième partie, mais. En français, on évite de dire « bien que » et « mais » dans la même phrase, alors qu'en chinois c'est tout à fait normal, et même plus naturel. Décomposons « Suīrán wǒ hěn lèi, dànshì wǒ bù xiǎng fàngqì » : bien que je sois très fatigué, mais je ne veux pas abandonner. « Suīrán » peut aussi se placer après le sujet : « wǒ suīrán hěn lèi », moi, bien que fatigué. À l'oral, on raccourcit souvent « dànshì » en « dàn », ou on le remplace par « kěshì ». Astuce : pensez à un pont, « suīrán » pose le pied sur la première rive, « dànshì » vous fait passer de l'autre côté.","exampleRo":"Suīrán wǒ hěn lèi, dànshì wǒ bù xiǎng fàngqì.","lit":"bien que · je · très · fatigué · mais · je · ne pas · vouloir · abandonner","say":{"Suīrán... dànshì...":"虽然……但是……","suīrán":"虽然","dànshì":"但是","Suīrán wǒ hěn lèi, dànshì wǒ bù xiǎng fàngqì":"虽然我很累，但是我不想放弃","Suīrán":"虽然","wǒ suīrán hěn lèi":"我虽然很累","dàn":"但","kěshì":"可是"}}},{"title":"Lever de soleil sur la mer de nuages","phrases":[{"fr":"Le réveil a sonné dès quatre heures et demie.","tgt":"闹钟四点半就响了。","ro":"Nàozhōng sì diǎn bàn jiù xiǎng le."},{"fr":"Il fait froid dehors, mets plusieurs couches.","tgt":"外面很冷，多穿几件衣服。","ro":"Wàimiàn hěn lěng, duō chuān jǐ jiàn yīfu."},{"fr":"L'hôtel loue des manteaux épais.","tgt":"酒店可以租厚棉衣。","ro":"Jiǔdiàn kěyǐ zū hòu miányī."},{"fr":"Le point de vue pour le lever du soleil est déjà noir de monde.","tgt":"看日出的地方已经站满了人。","ro":"Kàn rìchū de dìfang yǐjīng zhànmǎnle rén."},{"fr":"L'horizon rougit peu à peu.","tgt":"天边慢慢变红了。","ro":"Tiānbiān mànmàn biàn hóng le."},{"fr":"Le voilà ! Tout le monde sort son appareil photo.","tgt":"太阳出来了！大家都在拍照。","ro":"Tàiyáng chūlai le! Dàjiā dōu zài pāizhào."},{"fr":"En dessous, ce ne sont que des nuages, comme un océan.","tgt":"下面全是云，像大海一样。","ro":"Xiàmiàn quán shì yún, xiàng dàhǎi yíyàng."},{"fr":"Voilà la fameuse mer de nuages de Huangshan.","tgt":"这就是有名的黄山云海。","ro":"Zhè jiù shì yǒumíng de Huángshān yúnhǎi."},{"fr":"On a vraiment de la chance, hier il pleuvait encore.","tgt":"我们运气真好，昨天还下雨呢。","ro":"Wǒmen yùnqi zhēn hǎo, zuótiān hái xià yǔ ne."},{"fr":"Ce moment-là, je ne l'oublierai jamais.","tgt":"这一刻我永远不会忘记。","ro":"Zhè yí kè wǒ yǒngyuǎn bú huì wàngjì."}]},{"title":"Un imprévu : le train est annulé","phrases":[{"fr":"À cause des pluies torrentielles, notre train est annulé.","tgt":"因为暴雨，我们的火车取消了。","ro":"Yīnwèi bàoyǔ, wǒmen de huǒchē qǔxiāo le."},{"fr":"Excusez-moi, est-ce que je peux changer mon billet ?","tgt":"请问，我可以改签吗？","ro":"Qǐngwèn, wǒ kěyǐ gǎiqiān ma?"},{"fr":"Tout est complet pour aujourd'hui, il ne reste que demain.","tgt":"今天的票都卖完了，只有明天的。","ro":"Jīntiān de piào dōu màiwán le, zhǐ yǒu míngtiān de."},{"fr":"Y a-t-il des frais pour se faire rembourser ?","tgt":"退票要手续费吗？","ro":"Tuì piào yào shǒuxùfèi ma?"},{"fr":"Cette fois, c'est à cause de la météo, le remboursement est intégral.","tgt":"这次是天气原因，可以全额退款。","ro":"Zhè cì shì tiānqì yuányīn, kěyǐ quán'é tuìkuǎn."},{"fr":"Alors on doit dormir ici une nuit de plus.","tgt":"那我们得在这里再住一晚。","ro":"Nà wǒmen děi zài zhèlǐ zài zhù yì wǎn."},{"fr":"J'appelle l'hôtel pour savoir s'il reste des chambres.","tgt":"我给酒店打个电话，问问还有没有房间。","ro":"Wǒ gěi jiǔdiàn dǎ ge diànhuà, wènwen hái yǒu méiyǒu fángjiān."},{"fr":"On peut aussi prendre le car longue distance, mais ça prend huit heures.","tgt":"我们也可以坐长途汽车，不过要八个小时。","ro":"Wǒmen yě kěyǐ zuò chángtú qìchē, búguò yào bā ge xiǎoshí."},{"fr":"Ne t'inquiète pas, on finit toujours par trouver une solution.","tgt":"别着急，总会有办法的。","ro":"Bié zháojí, zǒng huì yǒu bànfǎ de."},{"fr":"Profiter d'une journée de plus, ce n'est pas si mal.","tgt":"多玩一天，也不是坏事。","ro":"Duō wán yì tiān, yě bú shì huài shì."}]},{"title":"Un petit souci de santé en voyage","phrases":[{"fr":"Hier soir, j'ai mangé des brochettes dans la rue, et maintenant j'ai mal au ventre.","tgt":"我昨天晚上吃了路边的烤串，现在肚子疼。","ro":"Wǒ zuótiān wǎnshang chīle lùbiān de kǎochuàn, xiànzài dùzi téng."},{"fr":"La réception de l'hôtel dit que la pharmacie est juste au coin.","tgt":"酒店前台说，药店就在拐角。","ro":"Jiǔdiàn qiántái shuō, yàodiàn jiù zài guǎijiǎo."},{"fr":"Vous avez mal où, exactement ?","tgt":"您哪儿不舒服？","ro":"Nín nǎr bù shūfu?"},{"fr":"J'ai la diarrhée et un peu de fièvre.","tgt":"我拉肚子，还有点儿发烧。","ro":"Wǒ lā dùzi, hái yǒudiǎnr fāshāo."},{"fr":"Ce médicament se prend trois fois par jour, après les repas.","tgt":"这个药一天吃三次，饭后吃。","ro":"Zhège yào yì tiān chī sān cì, fàn hòu chī."},{"fr":"Ces jours-ci, évite les plats épicés et bois beaucoup d'eau chaude.","tgt":"这两天别吃辣的，多喝热水。","ro":"Zhè liǎng tiān bié chī là de, duō hē rèshuǐ."},{"fr":"Si ça ne va pas mieux demain, va consulter à l'hôpital.","tgt":"如果明天还不好，就去医院看看。","ro":"Rúguǒ míngtiān hái bù hǎo, jiù qù yīyuàn kànkan."},{"fr":"Les moustiques m'ont piqué de partout.","tgt":"蚊子咬得我全身都是包。","ro":"Wénzi yǎo de wǒ quánshēn dōu shì bāo."},{"fr":"Vous avez une pommade contre les démangeaisons ?","tgt":"有没有止痒的药膏？","ro":"Yǒu méiyǒu zhǐyǎng de yàogāo?"},{"fr":"Après une journée de repos, je me sens beaucoup mieux.","tgt":"休息了一天，我感觉好多了。","ro":"Xiūxile yì tiān, wǒ gǎnjué hǎo duō le."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Dans ce module, nous sommes allés du Yunnan jusqu'aux Montagnes jaunes.","tgt":"这个单元我们从云南一直走到了黄山。","ro":"Zhège dānyuán wǒmen cóng Yúnnán yìzhí zǒudàole Huángshān."},{"fr":"Nous savons demander le chemin, réserver une chambre et changer un billet.","tgt":"我们学会了问路、订房和改签车票。","ro":"Wǒmen xuéhuìle wèn lù, dìng fáng hé gǎiqiān chēpiào."},{"fr":"Maintenant, je sais indiquer la direction avec « lái » et « qù ».","tgt":"现在我会用“来”和“去”说方向了。","ro":"Xiànzài wǒ huì yòng \"lái\" hé \"qù\" shuō fāngxiàng le."},{"fr":"Face à un imprévu, je stresse beaucoup moins.","tgt":"如果遇到问题，我就不那么紧张了。","ro":"Rúguǒ yùdào wèntí, wǒ jiù bú nàme jǐnzhāng le."},{"fr":"Les tons sont encore difficiles, mais j'ai fait de gros progrès.","tgt":"虽然声调还很难，但是我进步了很多。","ro":"Suīrán shēngdiào hái hěn nán, dànshì wǒ jìnbùle hěn duō."},{"fr":"Je parle chinois plus couramment qu'avant.","tgt":"我说中文说得比以前流利了。","ro":"Wǒ shuō Zhōngwén shuō de bǐ yǐqián liúlì le."},{"fr":"Chaque étape m'a appris quelque chose de nouveau.","tgt":"每一站都教会了我新的东西。","ro":"Měi yí zhàn dōu jiāohuìle wǒ xīn de dōngxi."},{"fr":"Le prochain module va commencer, avec encore plus de sujets de conversation.","tgt":"下一个单元要开始了，我们要聊更多的话题。","ro":"Xià yí ge dānyuán yào kāishǐ le, wǒmen yào liáo gèng duō de huàtí."},{"fr":"Repose-toi un peu, tu as fait du très bon travail !","tgt":"先休息一下，你做得很好！","ro":"Xiān xiūxi yíxià, nǐ zuò de hěn hǎo!"},{"fr":"On se retrouve au prochain module !","tgt":"我们下个单元见！","ro":"Wǒmen xià ge dānyuán jiàn!"}]}]},{"id":3,"name":"Conversation sociale","desc":"Des échanges sociaux plus nuancés et plus naturels.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Un dim sum à Canton","phrases":[{"fr":"On va boire le thé du matin ce dimanche ?","tgt":"这个星期天去喝早茶吗？","ro":"Zhège xīngqītiān qù hē zǎochá ma?"},{"fr":"Ce salon de thé est toujours bondé le week-end.","tgt":"这家茶楼周末总是坐满了人。","ro":"Zhè jiā chálóu zhōumò zǒngshì zuòmǎn le rén."},{"fr":"Il faut arriver avant huit heures pour avoir une table.","tgt":"得八点以前到，才有位子。","ro":"Děi bā diǎn yǐqián dào, cái yǒu wèizi."},{"fr":"Je commande des raviolis aux crevettes, tu veux quoi d'autre ?","tgt":"我点虾饺，你还想吃什么？","ro":"Wǒ diǎn xiājiǎo, nǐ hái xiǎng chī shénme?"},{"fr":"Les brioches au porc laqué d'ici sont excellentes.","tgt":"这里的叉烧包特别好吃。","ro":"Zhèlǐ de chāshāobāo tèbié hǎochī."},{"fr":"Tu bois du thé pu-erh ou du thé au chrysanthème ?","tgt":"你喝普洱茶还是菊花茶？","ro":"Nǐ hē pǔ'ěrchá háishi júhuāchá?"},{"fr":"Quand on te sert du thé, tapote la table avec deux doigts.","tgt":"别人给你倒茶的时候，用两根手指敲敲桌子。","ro":"Biérén gěi nǐ dào chá de shíhou, yòng liǎng gēn shǒuzhǐ qiāoqiao zhuōzi."},{"fr":"C'est une façon de dire merci sans parler.","tgt":"这样表示谢谢，不用说话。","ro":"Zhèyàng biǎoshì xièxie, búyòng shuōhuà."},{"fr":"On a commandé beaucoup trop, je n'en peux plus.","tgt":"我们点得太多了，我吃不下了。","ro":"Wǒmen diǎn de tài duō le, wǒ chī bu xià le."},{"fr":"Cette fois, c'est moi qui invite !","tgt":"这次我请客！","ro":"Zhè cì wǒ qǐngkè!"}]},{"title":"Le registre familier entre amis","phrases":[{"fr":"Salut, ça fait un bail !","tgt":"嘿，好久不见啦！","ro":"Hēi, hǎojiǔ bú jiàn la!"},{"fr":"Alors, quoi de neuf ces temps-ci ?","tgt":"最近怎么样啊？","ro":"Zuìjìn zěnmeyàng a?"},{"fr":"Bof, ça va, toujours pareil.","tgt":"还行吧，老样子。","ro":"Hái xíng ba, lǎo yàngzi."},{"fr":"Allez, viens, on va manger !","tgt":"走，吃饭去！","ro":"Zǒu, chī fàn qù!"},{"fr":"T'inquiète, c'est rien.","tgt":"没事没事，别担心。","ro":"Méi shì méi shì, bié dānxīn."},{"fr":"Ce film était super bien !","tgt":"那部电影超好看的！","ro":"Nà bù diànyǐng chāo hǎokàn de!"},{"fr":"Il est plutôt sympa, ton colocataire.","tgt":"你室友挺好的嘛。","ro":"Nǐ shìyǒu tǐng hǎo de ma."},{"fr":"Bah, on n'a qu'à y aller à pied.","tgt":"那就走过去呗。","ro":"Nà jiù zǒu guòqu bei."},{"fr":"Sérieux ? Je n'y crois pas !","tgt":"真的假的？我不信！","ro":"Zhēn de jiǎ de? Wǒ bú xìn!"},{"fr":"Bon, j'y vais, à plus !","tgt":"好啦，我先走了，回头见！","ro":"Hǎo la, wǒ xiān zǒu le, huítóu jiàn!"}],"tip":{"title":"Le registre familier entre amis","example":"Bah, on n'a qu'à y aller à pied. — 那就走过去<b>呗</b>。","body":"Entre amis, le chinois parlé se détend beaucoup, et ce sont surtout de petites particules en fin de phrase qui donnent le ton. « La » rend la phrase joyeuse et légère, comme dans « hǎo la », bon, d'accord. « Bei » veut dire à peu près « bah, c'est évident » : « nà jiù zǒu guòqu bei » se décompose en alors, donc, marcher, y aller, puis la petite particule qui hausse les épaules. On raccourcit aussi les phrases : « zǒu, chī fàn qù ! », allez, on va manger, ou « méi shì », c'est rien. Pour insister, on entend « chāo », super, et « tǐng », plutôt, à la place du plus neutre « hěn ». Ces particules se disent sans ton, très brèves, comme un souffle en fin de phrase. Astuce : pensez au « hein » ou au « quoi » du français familier, c'est exactement leur rôle.","exampleRo":"Nà jiù zǒu guòqu bei.","lit":"alors · donc · marcher · y-aller · [évidence]","say":{"La":"啦","hǎo la":"好啦","Bei":"呗","nà jiù zǒu guòqu bei":"那就走过去呗","zǒu, chī fàn qù !":"走，吃饭去！","méi shì":"没事","chāo":"超","tǐng":"挺","hěn":"很"}}},{"title":"Raconter son week-end","phrases":[{"fr":"Qu'est-ce que tu as fait de beau ce week-end ?","tgt":"你周末干什么了？","ro":"Nǐ zhōumò gàn shénme le?"},{"fr":"Je suis allé faire un tour à Shamian avec des amis.","tgt":"我跟朋友去沙面逛了逛。","ro":"Wǒ gēn péngyou qù Shāmiàn guàng le guàng."},{"fr":"Les vieilles maisons là-bas sont superbes en photo.","tgt":"那边的老房子拍照特别好看。","ro":"Nàbiān de lǎo fángzi pāizhào tèbié hǎokàn."},{"fr":"Le soir, on a mangé du riz cuit en pot d'argile.","tgt":"晚上我们吃了煲仔饭。","ro":"Wǎnshang wǒmen chī le bāozǎifàn."},{"fr":"Moi, je suis resté à la maison tout le samedi.","tgt":"我星期六一整天都待在家里。","ro":"Wǒ xīngqīliù yì zhěng tiān dōu dāi zài jiā li."},{"fr":"Il a plu sans arrêt, je n'avais pas envie de sortir.","tgt":"一直下雨，我不想出门。","ro":"Yìzhí xià yǔ, wǒ bù xiǎng chūmén."},{"fr":"Dimanche, j'ai enfin fait le ménage à fond.","tgt":"星期天我终于把家里打扫干净了。","ro":"Xīngqītiān wǒ zhōngyú bǎ jiā li dǎsǎo gānjìng le."},{"fr":"Tu as l'air en forme, tu as dû bien te reposer.","tgt":"你看起来精神不错，休息得挺好吧。","ro":"Nǐ kàn qilai jīngshen búcuò, xiūxi de tǐng hǎo ba."},{"fr":"La prochaine fois, appelle-moi, je viendrai avec vous.","tgt":"下次叫上我，我跟你们一起去。","ro":"Xià cì jiào shang wǒ, wǒ gēn nǐmen yìqǐ qù."},{"fr":"Promis, on t'appelle le week-end prochain.","tgt":"一定，下个周末叫你。","ro":"Yídìng, xià ge zhōumò jiào nǐ."}]},{"title":"Préparer la Fête du Printemps","phrases":[{"fr":"La Fête du Printemps approche, tu rentres dans ta ville natale ?","tgt":"快过年了，你回老家吗？","ro":"Kuài guònián le, nǐ huí lǎojiā ma?"},{"fr":"Oui, j'ai déjà acheté mon billet de train à grande vitesse.","tgt":"回，我已经买好高铁票了。","ro":"Huí, wǒ yǐjīng mǎi hǎo gāotiě piào le."},{"fr":"Chaque année, les billets partent en quelques minutes.","tgt":"每年车票几分钟就卖光了。","ro":"Měi nián chēpiào jǐ fēnzhōng jiù mài guāng le."},{"fr":"Avant la fête, chaque famille fait un grand ménage.","tgt":"过年前，家家都要大扫除。","ro":"Guònián qián, jiājiā dōu yào dàsǎochú."},{"fr":"Ce soir, ma mère veut aller flâner au marché aux fleurs.","tgt":"我妈今晚想去逛花市。","ro":"Wǒ mā jīnwǎn xiǎng qù guàng huāshì."},{"fr":"À Canton, on achète des mandariniers pour porter chance.","tgt":"在广州，大家买年桔图个吉利。","ro":"Zài Guǎngzhōu, dàjiā mǎi niánjú tú ge jílì."},{"fr":"On va coller des sentences de bon augure sur la porte.","tgt":"我们要在门上贴春联。","ro":"Wǒmen yào zài mén shang tiē chūnlián."},{"fr":"N'oublie pas de coller le signe du bonheur à l'envers !","tgt":"别忘了把福字倒着贴！","ro":"Bié wàng le bǎ fú zì dàozhe tiē!"},{"fr":"Mes grands-parents nous attendent avec impatience.","tgt":"爷爷奶奶早就盼着我们回去了。","ro":"Yéye nǎinai zǎo jiù pànzhe wǒmen huíqu le."},{"fr":"Cette année, je rapporte des pâtisseries cantonaises à toute la famille.","tgt":"今年我给全家带广式点心回去。","ro":"Jīnnián wǒ gěi quán jiā dài Guǎngshì diǎnxin huíqu."}]},{"title":"« Kěnéng » et « yěxǔ » : peut-être","phrases":[{"fr":"Ce soir, il va peut-être pleuvoir.","tgt":"今晚可能会下雨。","ro":"Jīnwǎn kěnéng huì xià yǔ."},{"fr":"Xiao Chen ne viendra peut-être pas, il fait des heures sup.","tgt":"小陈可能不来了，他要加班。","ro":"Xiǎo Chén kěnéng bù lái le, tā yào jiābān."},{"fr":"On devrait peut-être changer de restaurant.","tgt":"也许我们应该换一家饭馆。","ro":"Yěxǔ wǒmen yīnggāi huàn yì jiā fànguǎn."},{"fr":"C'est possible, mais je n'en suis pas très sûr.","tgt":"有可能，不过我不太确定。","ro":"Yǒu kěnéng, búguò wǒ bú tài quèdìng."},{"fr":"Il est peut-être déjà en chemin.","tgt":"他也许已经在路上了。","ro":"Tā yěxǔ yǐjīng zài lù shang le."},{"fr":"Impossible, il n'est jamais en retard !","tgt":"不可能，他从来不迟到！","ro":"Bù kěnéng, tā cónglái bù chídào!"},{"fr":"Il a peut-être oublié de prendre son téléphone.","tgt":"也许他忘带手机了。","ro":"Yěxǔ tā wàng dài shǒujī le."},{"fr":"On l'attend encore dix minutes ?","tgt":"我们再等他十分钟吧？","ro":"Wǒmen zài děng tā shí fēnzhōng ba?"},{"fr":"Le métro est peut-être bondé à cette heure-ci.","tgt":"这个时候地铁可能很挤。","ro":"Zhège shíhou dìtiě kěnéng hěn jǐ."},{"fr":"Ah, le voilà ! Il a fini par arriver.","tgt":"啊，他来了！终于到了。","ro":"À, tā lái le! Zhōngyú dào le."}],"tip":{"title":"« Kěnéng » et « yěxǔ » : peut-être","example":"On devrait peut-être changer de restaurant. — <b>也许</b>我们应该换一家饭馆。","body":"« Kěnéng » et « yěxǔ » veulent tous les deux dire peut-être, et ils se placent avant le verbe, jamais en fin de phrase. « Kěnéng » est le plus courant, et on l'accompagne souvent de « huì », qui annonce ce qui va arriver : « jīnwǎn kěnéng huì xià yǔ », mot à mot ce soir, peut-être, aller, tomber la pluie. « Yěxǔ » est un peu plus doux et hésitant, et il peut ouvrir la phrase : « yěxǔ wǒmen yīnggāi huàn yì jiā fànguǎn », peut-être que nous devrions changer de restaurant. « Kěnéng » s'emploie aussi tout seul : « yǒu kěnéng », c'est possible, et « bù kěnéng ! », impossible ! Astuce pour retenir : « kě », pouvoir, et « néng », être capable, s'additionnent pour donner possible.","exampleRo":"Yěxǔ wǒmen yīnggāi huàn yì jiā fànguǎn.","lit":"peut-être · nous · devoir · changer · un · [classificateur] · restaurant","say":{"Kěnéng":"可能","yěxǔ":"也许","huì":"会","jīnwǎn kěnéng huì xià yǔ":"今晚可能会下雨","Yěxǔ":"也许","yěxǔ wǒmen yīnggāi huàn yì jiā fànguǎn":"也许我们应该换一家饭馆","yǒu kěnéng":"有可能","bù kěnéng !":"不可能！","kě":"可","néng":"能"}}},{"title":"Le repas du réveillon","phrases":[{"fr":"Le soir du réveillon, toute la famille dîne ensemble.","tgt":"除夕晚上，全家人一起吃年夜饭。","ro":"Chúxī wǎnshang, quán jiā rén yìqǐ chī niányèfàn."},{"fr":"Ma grand-mère est aux fourneaux depuis ce matin.","tgt":"奶奶从早上就开始做饭了。","ro":"Nǎinai cóng zǎoshang jiù kāishǐ zuò fàn le."},{"fr":"Il y a toujours un poisson, symbole d'abondance chaque année.","tgt":"桌上一定有鱼，表示年年有余。","ro":"Zhuō shang yídìng yǒu yú, biǎoshì niánnián yǒu yú."},{"fr":"Dans le Sud, on mange moins de raviolis que dans le Nord.","tgt":"南方人过年吃饺子比北方人少。","ro":"Nánfāngrén guònián chī jiǎozi bǐ běifāngrén shǎo."},{"fr":"Chez nous, on prépare plutôt un poulet poché à la cantonaise.","tgt":"我们家一般做白切鸡。","ro":"Wǒmen jiā yìbān zuò báiqiējī."},{"fr":"Mon oncle me demande encore quand je vais me marier !","tgt":"我舅舅又问我什么时候结婚！","ro":"Wǒ jiùjiu yòu wèn wǒ shénme shíhou jiéhūn!"},{"fr":"Vite, je lui sers à boire et je change de sujet.","tgt":"我赶紧给他倒酒，换个话题。","ro":"Wǒ gǎnjǐn gěi tā dào jiǔ, huàn ge huàtí."},{"fr":"Après le dîner, on regarde le grand gala du Nouvel An à la télé.","tgt":"吃完饭，大家一起看春晚。","ro":"Chī wán fàn, dàjiā yìqǐ kàn Chūnwǎn."},{"fr":"À minuit, tout le monde échange ses vœux.","tgt":"到了半夜十二点，大家互相拜年。","ro":"Dào le bànyè shí'èr diǎn, dàjiā hùxiāng bàinián."},{"fr":"C'est le repas le plus important de toute l'année.","tgt":"这是一年里最重要的一顿饭。","ro":"Zhè shì yì nián li zuì zhòngyào de yí dùn fàn."}]},{"title":"Enveloppes rouges et vœux","phrases":[{"fr":"Bonne année et prospérité !","tgt":"恭喜发财！","ro":"Gōngxǐ fācái!"},{"fr":"Je vous souhaite une excellente santé !","tgt":"祝您身体健康！","ro":"Zhù nín shēntǐ jiànkāng!"},{"fr":"Ce que les enfants attendent le plus, ce sont les enveloppes rouges.","tgt":"孩子们最期待的就是红包。","ro":"Háizimen zuì qīdài de jiù shì hóngbāo."},{"fr":"À Canton, les gens mariés en donnent aux célibataires.","tgt":"在广州，结了婚的人要给单身的人发红包。","ro":"Zài Guǎngzhōu, jié le hūn de rén yào gěi dānshēn de rén fā hóngbāo."},{"fr":"On n'ouvre pas l'enveloppe devant la personne qui la donne.","tgt":"不要当着别人的面打开红包。","ro":"Búyào dāngzhe biérén de miàn dǎkāi hóngbāo."},{"fr":"Mon petit cousin a reçu plus de mille yuans cette année !","tgt":"我表弟今年收了一千多块红包！","ro":"Wǒ biǎodì jīnnián shōu le yìqiān duō kuài hóngbāo!"},{"fr":"Maintenant, on en envoie aussi par téléphone.","tgt":"现在大家也用手机发红包。","ro":"Xiànzài dàjiā yě yòng shǒujī fā hóngbāo."},{"fr":"Dans le groupe de la famille, tout le monde se jette sur les enveloppes.","tgt":"家里的群里，大家都在抢红包。","ro":"Jiā li de qún li, dàjiā dōu zài qiǎng hóngbāo."},{"fr":"J'ai été le plus rapide, j'ai gagné huit yuans quatre-vingt-huit !","tgt":"我手最快，抢到了八块八毛八！","ro":"Wǒ shǒu zuì kuài, qiǎng dào le bā kuài bā máo bā!"},{"fr":"Que tous tes souhaits se réalisent !","tgt":"祝你万事如意！","ro":"Zhù nǐ wànshì rúyì!"}]},{"title":"Une soirée karaoké","phrases":[{"fr":"Samedi soir, on va chanter au karaoké ?","tgt":"星期六晚上一起去唱歌吧？","ro":"Xīngqīliù wǎnshang yìqǐ qù chànggē ba?"},{"fr":"J'ai réservé une salle privée pour six personnes.","tgt":"我订了一个六个人的包间。","ro":"Wǒ dìng le yí ge liù ge rén de bāojiān."},{"fr":"Je chante faux, je préfère vous écouter.","tgt":"我唱歌跑调，还是听你们唱吧。","ro":"Wǒ chànggē pǎodiào, háishi tīng nǐmen chàng ba."},{"fr":"Allez, chante au moins une chanson !","tgt":"来嘛，至少唱一首！","ro":"Lái ma, zhìshǎo chàng yì shǒu!"},{"fr":"Cette vieille chanson, tout le monde sait la chanter.","tgt":"这首老歌大家都会唱。","ro":"Zhè shǒu lǎo gē dàjiā dōu huì chàng."},{"fr":"Tu chantes vraiment bien, tu as pris des cours ?","tgt":"你唱得真好，学过吗？","ro":"Nǐ chàng de zhēn hǎo, xué guo ma?"},{"fr":"Non, je m'entraîne juste sous la douche.","tgt":"没有，我就是洗澡的时候练练。","ro":"Méiyǒu, wǒ jiù shì xǐzǎo de shíhou liànlian."},{"fr":"Qui a le micro ? C'est mon tour !","tgt":"谁拿着话筒呢？该我了！","ro":"Shéi názhe huàtǒng ne? Gāi wǒ le!"},{"fr":"On chante celle-ci en duo ?","tgt":"我们一起合唱吧？","ro":"Wǒmen yìqǐ héchàng ba?"},{"fr":"Il est déjà deux heures du matin, on rentre ?","tgt":"已经凌晨两点了，回家吧？","ro":"Yǐjīng língchén liǎng diǎn le, huí jiā ba?"}]},{"title":"Parler de séries","phrases":[{"fr":"Tu suis quelle série en ce moment ?","tgt":"你最近在追什么剧？","ro":"Nǐ zuìjìn zài zhuī shénme jù?"},{"fr":"Je suis une série en costumes, je suis complètement accro.","tgt":"我在追一部古装剧，特别上瘾。","ro":"Wǒ zài zhuī yí bù gǔzhuāngjù, tèbié shàngyǐn."},{"fr":"Ça raconte quoi ?","tgt":"讲的是什么故事？","ro":"Jiǎng de shì shénme gùshi?"},{"fr":"L'histoire d'une famille de commerçants cantonais il y a cent ans.","tgt":"讲一百年前广州一家商人的故事。","ro":"Jiǎng yìbǎi nián qián Guǎngzhōu yì jiā shāngrén de gùshi."},{"fr":"Il y a combien d'épisodes en tout ?","tgt":"一共有多少集？","ro":"Yígòng yǒu duōshao jí?"},{"fr":"Plus de quarante, et j'en ai vu la moitié.","tgt":"四十多集，我看了一半了。","ro":"Sìshí duō jí, wǒ kàn le yíbàn le."},{"fr":"Hier soir, j'ai enchaîné cinq épisodes d'un coup.","tgt":"昨晚我一口气看了五集。","ro":"Zuówǎn wǒ yìkǒuqì kàn le wǔ jí."},{"fr":"Surtout, ne me raconte pas la fin !","tgt":"千万别告诉我结局！","ro":"Qiānwàn bié gàosu wǒ jiéjú!"},{"fr":"L'actrice principale joue vraiment bien.","tgt":"女主角演得特别好。","ro":"Nǚ zhǔjué yǎn de tèbié hǎo."},{"fr":"Envoie-moi le titre, je la regarderai ce week-end.","tgt":"把剧名发给我，我周末看。","ro":"Bǎ jùmíng fā gěi wǒ, wǒ zhōumò kàn."}]},{"title":"La mi-automne et les gâteaux de lune","phrases":[{"fr":"La fête de la mi-automne tombe le quinze du huitième mois lunaire.","tgt":"中秋节是农历八月十五。","ro":"Zhōngqiū Jié shì nónglì bāyuè shíwǔ."},{"fr":"Ce soir-là, la lune est la plus ronde de l'année.","tgt":"那天晚上的月亮是一年里最圆的。","ro":"Nà tiān wǎnshang de yuèliang shì yì nián li zuì yuán de."},{"fr":"Tu aimes les gâteaux de lune au jaune d'œuf salé ?","tgt":"你喜欢吃咸蛋黄月饼吗？","ro":"Nǐ xǐhuan chī xiándànhuáng yuèbǐng ma?"},{"fr":"Moi, je préfère ceux à la pâte de lotus.","tgt":"我更喜欢莲蓉的。","ro":"Wǒ gèng xǐhuan liánróng de."},{"fr":"Ils sont très sucrés, alors on les coupe en petits morceaux.","tgt":"月饼很甜，我们切成小块吃。","ro":"Yuèbǐng hěn tián, wǒmen qiē chéng xiǎo kuài chī."},{"fr":"Mon entreprise a offert une boîte de gâteaux de lune à chaque employé.","tgt":"公司给每个员工发了一盒月饼。","ro":"Gōngsī gěi měi ge yuángōng fā le yì hé yuèbǐng."},{"fr":"Le soir, on va se promener au parc avec des lanternes.","tgt":"晚上我们提着灯笼去公园散步。","ro":"Wǎnshang wǒmen tízhe dēnglong qù gōngyuán sànbù."},{"fr":"Les enfants adorent les lanternes en forme de lapin.","tgt":"孩子们最喜欢兔子灯笼。","ro":"Háizimen zuì xǐhuan tùzi dēnglong."},{"fr":"On boit du thé sur le toit en admirant la lune.","tgt":"我们在楼顶上喝茶赏月。","ro":"Wǒmen zài lóudǐng shang hē chá shǎng yuè."},{"fr":"Cette fête, c'est surtout l'occasion d'être réunis en famille.","tgt":"中秋节最重要的是一家人团圆。","ro":"Zhōngqiū Jié zuì zhòngyào de shì yì jiā rén tuányuán."}]},{"title":"Un anniversaire surprise","phrases":[{"fr":"Samedi, c'est l'anniversaire de Xiaoli.","tgt":"星期六是小丽的生日。","ro":"Xīngqīliù shì Xiǎo Lì de shēngrì."},{"fr":"Et si on lui organisait une fête surprise ?","tgt":"我们给她准备一个惊喜派对吧？","ro":"Wǒmen gěi tā zhǔnbèi yí ge jīngxǐ pàiduì ba?"},{"fr":"Toi, ne lui en parle surtout pas !","tgt":"这件事你可别跟她说！","ro":"Zhè jiàn shì nǐ kě bié gēn tā shuō!"},{"fr":"Je m'occupe du gâteau, toi de la décoration.","tgt":"我负责蛋糕，你负责布置。","ro":"Wǒ fùzé dàngāo, nǐ fùzé bùzhì."},{"fr":"Elle a quel âge cette année ?","tgt":"她今年多大了？","ro":"Tā jīnnián duō dà le?"},{"fr":"Elle fête ses vingt-huit ans.","tgt":"她今年二十八岁。","ro":"Tā jīnnián èrshíbā suì."},{"fr":"Éteins vite la lumière, elle arrive !","tgt":"快关灯，她来了！","ro":"Kuài guān dēng, tā lái le!"},{"fr":"Joyeux anniversaire ! Vite, fais un vœu !","tgt":"生日快乐！快许个愿！","ro":"Shēngrì kuàilè! Kuài xǔ ge yuàn!"},{"fr":"Souffle toutes les bougies d'un seul coup !","tgt":"一口气把蜡烛吹灭！","ro":"Yìkǒuqì bǎ làzhú chuīmiè!"},{"fr":"Tu ne t'en doutais vraiment pas du tout ?","tgt":"你真的一点都没猜到吗？","ro":"Nǐ zhēn de yìdiǎn dōu méi cāidào ma?"}]},{"title":"« Tīngshuō » : j'ai entendu dire que","phrases":[{"fr":"Il paraît qu'un nouveau salon de thé a ouvert près d'ici.","tgt":"听说附近新开了一家茶楼。","ro":"Tīngshuō fùjìn xīn kāi le yì jiā chálóu."},{"fr":"J'ai entendu dire que leurs tartelettes aux œufs sont délicieuses.","tgt":"听说他们的蛋挞特别好吃。","ro":"Tīngshuō tāmen de dàntà tèbié hǎochī."},{"fr":"Qui t'a raconté ça ?","tgt":"你听谁说的？","ro":"Nǐ tīng shéi shuō de?"},{"fr":"C'est ma collègue qui me l'a dit.","tgt":"我听同事说的。","ro":"Wǒ tīng tóngshì shuō de."},{"fr":"Il paraît que Xiao Wang va se marier !","tgt":"听说小王要结婚了！","ro":"Tīngshuō Xiǎo Wáng yào jiéhūn le!"},{"fr":"C'est vrai ? Avec qui ?","tgt":"真的吗？跟谁啊？","ro":"Zhēn de ma? Gēn shéi a?"},{"fr":"J'ai entendu dire que c'est une camarade de fac.","tgt":"听说是他的大学同学。","ro":"Tīngshuō shì tā de dàxué tóngxué."},{"fr":"J'ai aussi entendu qu'il allait déménager à Shenzhen.","tgt":"我还听说他要搬到深圳去。","ro":"Wǒ hái tīngshuō tā yào bān dào Shēnzhèn qù."},{"fr":"Ce ne sont que des rumeurs, attendons qu'il nous le dise lui-même.","tgt":"这只是传言，等他自己告诉我们吧。","ro":"Zhè zhǐ shì chuányán, děng tā zìjǐ gàosu wǒmen ba."},{"fr":"Tu as raison, arrêtons de faire courir des bruits.","tgt":"你说得对，我们别乱传了。","ro":"Nǐ shuō de duì, wǒmen bié luàn chuán le."}],"tip":{"title":"« Tīngshuō » : j'ai entendu dire que","example":"Il paraît que Xiao Wang va se marier ! — <b>听说</b>小王要结婚了！","body":"« Tīngshuō », littéralement écouter-dire, est l'équivalent de « il paraît que » ou « j'ai entendu dire que ». On le place simplement en tête de phrase, puis on enchaîne avec la nouvelle : « tīngshuō Xiǎo Wáng yào jiéhūn le », mot à mot il paraît, petit Wang, aller, se marier. Pour préciser la source, on coupe le mot en deux et on glisse la personne au milieu : « wǒ tīng tóngshì shuō de », je l'ai entendu de ma collègue, mot à mot moi écouter collègue dire. Et pour demander d'où vient la nouvelle : « nǐ tīng shéi shuō de ? », tu l'as entendu de qui ? La première syllabe est haute et plate, la seconde descend franchement, comme une nouvelle qu'on lâche d'un coup. Astuce : c'est le mot préféré des bavards du quartier, idéal pour toutes les rumeurs.","exampleRo":"Tīngshuō Xiǎo Wáng yào jiéhūn le!","lit":"entendre-dire · petit · Wang · aller · se-marier · [changement] !","say":{"Tīngshuō":"听说","tīngshuō Xiǎo Wáng yào jiéhūn le":"听说小王要结婚了","wǒ tīng tóngshì shuō de":"我听同事说的","nǐ tīng shéi shuō de ?":"你听谁说的？"}}},{"title":"Donner son avis","phrases":[{"fr":"Et toi, qu'est-ce que tu en penses ?","tgt":"你觉得呢？","ro":"Nǐ juéde ne?"},{"fr":"À mon avis, la cuisine cantonaise est la meilleure.","tgt":"我觉得粤菜最好吃。","ro":"Wǒ juéde yuècài zuì hǎochī."},{"fr":"Je ne suis pas tout à fait d'accord.","tgt":"我不太同意。","ro":"Wǒ bú tài tóngyì."},{"fr":"Je trouve que la cuisine du Sichuan a plus de caractère.","tgt":"我觉得川菜味道更足。","ro":"Wǒ juéde chuāncài wèidao gèng zú."},{"fr":"Pour moi, c'est beaucoup trop épicé.","tgt":"对我来说太辣了。","ro":"Duì wǒ lái shuō tài là le."},{"fr":"En fait, chacun a ses goûts.","tgt":"其实每个人口味不一样。","ro":"Qíshí měi ge rén kǒuwèi bù yíyàng."},{"fr":"Sur ce point, tu as entièrement raison.","tgt":"这一点你说得完全对。","ro":"Zhè yì diǎn nǐ shuō de wánquán duì."},{"fr":"Moi, je vois les choses un peu autrement.","tgt":"我的看法有点不一样。","ro":"Wǒ de kànfǎ yǒudiǎn bù yíyàng."},{"fr":"Pour être honnête, ce n'est pas si mauvais.","tgt":"说实话，也没那么差。","ro":"Shuō shíhuà, yě méi nàme chà."},{"fr":"Le mieux, c'est de goûter les deux et de comparer.","tgt":"最好两种都尝尝，比一比。","ro":"Zuìhǎo liǎng zhǒng dōu chángchang, bǐ yi bǐ."}]},{"title":"« Yìbiān... yìbiān... » : faire deux choses à la fois","phrases":[{"fr":"Il aime manger en regardant la télé.","tgt":"他喜欢一边吃饭一边看电视。","ro":"Tā xǐhuan yìbiān chī fàn yìbiān kàn diànshì."},{"fr":"On a papoté tout l'après-midi en buvant du thé.","tgt":"我们一边喝茶一边聊天，聊了一下午。","ro":"Wǒmen yìbiān hē chá yìbiān liáotiān, liáo le yí xiàwǔ."},{"fr":"Ne regarde pas ton téléphone en marchant !","tgt":"别一边走路一边看手机！","ro":"Bié yìbiān zǒulù yìbiān kàn shǒujī!"},{"fr":"Ma petite sœur révise en écoutant de la musique.","tgt":"我妹妹一边听音乐一边学习。","ro":"Wǒ mèimei yìbiān tīng yīnyuè yìbiān xuéxí."},{"fr":"Moi, je n'arrive pas à faire deux choses à la fois.","tgt":"我做不到同时做两件事。","ro":"Wǒ zuò bu dào tóngshí zuò liǎng jiàn shì."},{"fr":"Le cuisinier chantait en préparant les nouilles.","tgt":"师傅一边做面一边唱歌。","ro":"Shīfu yìbiān zuò miàn yìbiān chànggē."},{"fr":"On a bavardé en se promenant au bord de la rivière des Perles.","tgt":"我们一边在珠江边散步，一边聊天。","ro":"Wǒmen yìbiān zài Zhūjiāng biān sànbù, yìbiān liáotiān."},{"fr":"Il travaille tout en faisant des études.","tgt":"他一边工作一边读书。","ro":"Tā yìbiān gōngzuò yìbiān dúshū."},{"fr":"C'est épuisant, mais il ne se plaint jamais.","tgt":"很累，但是他从来不抱怨。","ro":"Hěn lèi, dànshì tā cónglái bú bàoyuàn."},{"fr":"Mange d'abord, on en parlera après.","tgt":"先吃饭，吃完再说。","ro":"Xiān chī fàn, chī wán zài shuō."}],"tip":{"title":"« Yìbiān... yìbiān... » : faire deux choses à la fois","example":"Il aime manger en regardant la télé. — 他喜欢<b>一边</b>吃饭<b>一边</b>看电视。","body":"Pour dire qu'on fait deux choses en même temps, le chinois répète « yìbiān » devant chacun des deux verbes. Exemple : « tā xǐhuan yìbiān chī fàn yìbiān kàn diànshì », mot à mot il, aimer, d'un côté manger, d'un côté regarder la télé. Là où le français emploie le gérondif, « en regardant », le chinois met les deux actions à égalité, comme les deux plateaux d'une balance. On l'entend partout : « yìbiān hē chá yìbiān liáotiān », bavarder en buvant le thé, ou « bié yìbiān zǒulù yìbiān kàn shǒujī », ne regarde pas ton téléphone en marchant. Côté prononciation, « yì » descend, et « biān » reste haut et plat. Astuce : « biān » veut dire côté, alors imaginez une action dans chaque main.","exampleRo":"Tā xǐhuan yìbiān chī fàn yìbiān kàn diànshì.","lit":"il · aimer · d'un-côté · manger · d'un-côté · regarder · télévision","say":{"Yìbiān... yìbiān...":"一边……一边……","yìbiān":"一边","tā xǐhuan yìbiān chī fàn yìbiān kàn diànshì":"他喜欢一边吃饭一边看电视","yìbiān hē chá yìbiān liáotiān":"一边喝茶一边聊天","bié yìbiān zǒulù yìbiān kàn shǒujī":"别一边走路一边看手机","biān":"边"}}},{"title":"Souvenirs d'enfance","phrases":[{"fr":"Quand j'étais petit, j'habitais dans une vieille rue de Xiguan.","tgt":"我小时候住在西关的一条老街上。","ro":"Wǒ xiǎoshíhou zhù zài Xīguān de yì tiáo lǎo jiē shang."},{"fr":"Le soir, les voisins dînaient tous dehors ensemble.","tgt":"晚上邻居们都在外面一起吃饭。","ro":"Wǎnshang línjūmen dōu zài wàimiàn yìqǐ chī fàn."},{"fr":"Je jouais souvent au volant avec les enfants du quartier.","tgt":"我常跟街坊的小孩踢毽子。","ro":"Wǒ cháng gēn jiēfang de xiǎohái tī jiànzi."},{"fr":"Mon grand-père m'emmenait boire le thé tous les matins.","tgt":"爷爷每天早上带我去喝早茶。","ro":"Yéye měi tiān zǎoshang dài wǒ qù hē zǎochá."},{"fr":"Je me souviens encore du goût de la soupe de ma grand-mère.","tgt":"我还记得奶奶煲的汤的味道。","ro":"Wǒ hái jìde nǎinai bāo de tāng de wèidao."},{"fr":"Tu es retourné dans cette rue depuis ?","tgt":"你后来回过那条街吗？","ro":"Nǐ hòulái huí guo nà tiáo jiē ma?"},{"fr":"Oui, mais tout a énormément changé.","tgt":"回过，可是变化太大了。","ro":"Huí guo, kěshì biànhuà tài dà le."},{"fr":"La petite boutique de bonbons n'existe plus.","tgt":"那家小糖果店已经没有了。","ro":"Nà jiā xiǎo tángguǒ diàn yǐjīng méiyǒu le."},{"fr":"À l'époque, la vie était simple mais heureuse.","tgt":"那时候生活很简单，但是很快乐。","ro":"Nà shíhou shēnghuó hěn jiǎndān, dànshì hěn kuàilè."},{"fr":"Quand j'y repense, j'ai un peu la nostalgie du passé.","tgt":"想起这些，我有点怀念过去。","ro":"Xiǎngqǐ zhèxiē, wǒ yǒudiǎn huáiniàn guòqù."}]},{"title":"Une soirée sur la rivière des Perles","phrases":[{"fr":"Ce soir, on fait une croisière de nuit sur la rivière des Perles ?","tgt":"今晚去坐珠江夜游船吧？","ro":"Jīnwǎn qù zuò Zhūjiāng yèyóu chuán ba?"},{"fr":"Les lumières de la tour de Canton changent sans cesse de couleur.","tgt":"广州塔的灯光一直在变颜色。","ro":"Guǎngzhōu Tǎ de dēngguāng yìzhí zài biàn yánsè."},{"fr":"Les Cantonais la surnomment « la taille de guêpe ».","tgt":"广州人叫它“小蛮腰”。","ro":"Guǎngzhōurén jiào tā \"Xiǎo Mányāo\"."},{"fr":"Le vent est agréable sur le bateau.","tgt":"船上的风很舒服。","ro":"Chuán shang de fēng hěn shūfu."},{"fr":"Prends-moi en photo avec la tour.","tgt":"帮我跟广州塔拍张合影吧。","ro":"Bāng wǒ gēn Guǎngzhōu Tǎ pāi zhāng héyǐng ba."},{"fr":"Il y a un peu de brume ce soir, c'est dommage.","tgt":"今晚有点雾，太可惜了。","ro":"Jīnwǎn yǒudiǎn wù, tài kěxī le."},{"fr":"Tout à l'heure, on va manger un en-cas de nuit ?","tgt":"等一下去吃宵夜吧？","ro":"Děng yíxià qù chī xiāoyè ba?"},{"fr":"Je connais une échoppe de congee qui reste ouverte tard.","tgt":"我知道一家粥店开到很晚。","ro":"Wǒ zhīdào yì jiā zhōu diàn kāi dào hěn wǎn."},{"fr":"Un bol de congee chaud le soir, quel bonheur.","tgt":"晚上喝一碗热粥，真舒服。","ro":"Wǎnshang hē yì wǎn rè zhōu, zhēn shūfu."},{"fr":"Canton la nuit a vraiment du charme.","tgt":"广州的夜晚真有味道。","ro":"Guǎngzhōu de yèwǎn zhēn yǒu wèidao."}]},{"title":"Recevoir des amis chez soi","phrases":[{"fr":"Venez dîner chez moi vendredi soir !","tgt":"星期五晚上来我家吃饭吧！","ro":"Xīngqīwǔ wǎnshang lái wǒ jiā chī fàn ba!"},{"fr":"Qu'est-ce qu'on peut apporter ?","tgt":"我们带点什么去？","ro":"Wǒmen dài diǎn shénme qù?"},{"fr":"Rien du tout, venez juste les mains vides.","tgt":"什么都不用带，人来就行。","ro":"Shénme dōu búyòng dài, rén lái jiù xíng."},{"fr":"Entrez vite, faites comme chez vous !","tgt":"快进来，别客气！","ro":"Kuài jìnlai, bié kèqi!"},{"fr":"Pas besoin de changer de chaussures.","tgt":"不用换鞋。","ro":"Búyòng huàn xié."},{"fr":"Asseyez-vous, je vous sers du thé.","tgt":"请坐，我给你们倒茶。","ro":"Qǐng zuò, wǒ gěi nǐmen dào chá."},{"fr":"Ton appartement est vraiment lumineux.","tgt":"你家真亮堂。","ro":"Nǐ jiā zhēn liàngtang."},{"fr":"J'ai fait mijoter une soupe cantonaise pendant quatre heures.","tgt":"我煲了四个小时的老火汤。","ro":"Wǒ bāo le sì ge xiǎoshí de lǎohuǒtāng."},{"fr":"Servez-vous bien, mangez tant que c'est chaud.","tgt":"大家多吃点，趁热吃。","ro":"Dàjiā duō chī diǎn, chèn rè chī."},{"fr":"Merci pour l'accueil, la prochaine fois c'est chez nous.","tgt":"谢谢款待，下次来我们家。","ro":"Xièxie kuǎndài, xià cì lái wǒmen jiā."}]},{"title":"Les formules de politesse : nín, qǐngwèn, guìxìng","phrases":[{"fr":"Bonjour monsieur, ravi de faire votre connaissance.","tgt":"叔叔您好，很高兴认识您。","ro":"Shūshu nín hǎo, hěn gāoxìng rènshi nín."},{"fr":"Puis-je vous demander votre nom ?","tgt":"请问您贵姓？","ro":"Qǐngwèn nín guìxìng?"},{"fr":"Mon nom de famille est Li. Et vous ?","tgt":"我姓李。您呢？","ro":"Wǒ xìng Lǐ. Nín ne?"},{"fr":"Excusez-moi, où se trouvent les toilettes ?","tgt":"请问，洗手间在哪里？","ro":"Qǐngwèn, xǐshǒujiān zài nǎlǐ?"},{"fr":"Vous avez fait un long trajet, merci d'être venu.","tgt":"您一路辛苦了。","ro":"Nín yílù xīnkǔ le."},{"fr":"Je vous en prie, asseyez-vous ici.","tgt":"您请坐这边。","ro":"Nín qǐng zuò zhèbiān."},{"fr":"Excusez-moi, cette place est-elle prise ?","tgt":"请问这里有人吗？","ro":"Qǐngwèn zhèlǐ yǒu rén ma?"},{"fr":"Grand-mère, puis-je vous demander votre âge ?","tgt":"奶奶，请问您今年高寿？","ro":"Nǎinai, qǐngwèn nín jīnnián gāoshòu?"},{"fr":"Merci de nous avoir reçus, vous êtes trop aimable.","tgt":"谢谢您的招待，您太客气了。","ro":"Xièxie nín de zhāodài, nín tài kèqi le."},{"fr":"Prenez bien soin de vous, nous reviendrons vous voir.","tgt":"您多保重，我们下次再来看您。","ro":"Nín duō bǎozhòng, wǒmen xià cì zài lái kàn nín."}],"tip":{"title":"Les formules de politesse : « nín, qǐngwèn, guìxìng »","example":"Puis-je vous demander votre nom ? — <b>请问</b><b>您</b><b>贵姓</b>？","body":"Le chinois a une façon très simple de marquer le respect : on remplace « nǐ », tu, par « nín », vous, pour parler à une personne âgée, à un client ou à quelqu'un qu'on veut honorer. Attention au ton : « nǐ » descend puis remonte, alors que « nín » monte simplement, avec un n final bien net. On ouvre aussi une question avec « qǐngwèn », mot à mot s'il vous plaît demander, l'équivalent de excusez-moi : « qǐngwèn, xǐshǒujiān zài nǎlǐ ? ». Pour demander poliment le nom de famille, la formule figée est « qǐngwèn nín guìxìng ? », mot à mot permettez-moi de demander, vous, honorable nom. On ne dit jamais « guì » pour soi-même : on répond simplement « wǒ xìng Lǐ », mon nom est Li. Astuce : « nín », c'est « nǐ » avec un petit n en plus, comme une révérence glissée dans le mot.","exampleRo":"Qǐngwèn nín guìxìng?","lit":"s'il-vous-plaît-demander · vous · honorable-nom ?","say":{"nǐ":"你","nín":"您","qǐngwèn":"请问","qǐngwèn, xǐshǒujiān zài nǎlǐ ?":"请问，洗手间在哪里？","qǐngwèn nín guìxìng ?":"请问您贵姓？","guì":"贵","wǒ xìng Lǐ":"我姓李","nín, qǐngwèn, guìxìng":"您、请问、贵姓"}}},{"title":"Dire au revoir à un ami","phrases":[{"fr":"Tu pars vraiment travailler à Shanghai le mois prochain ?","tgt":"你下个月真的要去上海工作了？","ro":"Nǐ xià ge yuè zhēn de yào qù Shànghǎi gōngzuò le?"},{"fr":"Oui, c'est une belle occasion pour moi.","tgt":"是啊，这是个好机会。","ro":"Shì a, zhè shì ge hǎo jīhuì."},{"fr":"Tu vas beaucoup nous manquer.","tgt":"我们会很想你的。","ro":"Wǒmen huì hěn xiǎng nǐ de."},{"fr":"On a passé tellement de bons moments ensemble.","tgt":"我们一起度过了那么多快乐的时光。","ro":"Wǒmen yìqǐ dùguò le nàme duō kuàilè de shíguāng."},{"fr":"Tu te souviens de notre tout premier thé du matin ?","tgt":"你还记得我们第一次喝早茶吗？","ro":"Nǐ hái jìde wǒmen dì-yī cì hē zǎochá ma?"},{"fr":"Bien sûr, tu avais commandé vingt plats !","tgt":"当然记得，你点了二十个菜！","ro":"Dāngrán jìde, nǐ diǎn le èrshí ge cài!"},{"fr":"On s'appelle en vidéo chaque semaine, d'accord ?","tgt":"我们每个星期视频一次，好不好？","ro":"Wǒmen měi ge xīngqī shìpín yí cì, hǎo bu hǎo?"},{"fr":"Et pense à revenir nous voir pour le Nouvel An.","tgt":"过年记得回来看我们。","ro":"Guònián jìde huílai kàn wǒmen."},{"fr":"Bonne route, et prends bien soin de toi !","tgt":"一路顺风，照顾好自己！","ro":"Yílù shùnfēng, zhàogù hǎo zìjǐ!"},{"fr":"Les vrais amis restent proches, même de loin.","tgt":"真正的朋友，离得再远也很近。","ro":"Zhēnzhèng de péngyou, lí de zài yuǎn yě hěn jìn."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Ce module nous a appris à bavarder entre amis en chinois.","tgt":"这个单元我们学会了用中文跟朋友聊天。","ro":"Zhège dānyuán wǒmen xuéhuì le yòng Zhōngwén gēn péngyou liáotiān."},{"fr":"Du thé du matin au karaoké, on a découvert la vie des Cantonais.","tgt":"从早茶到唱歌，我们了解了广州人的生活。","ro":"Cóng zǎochá dào chànggē, wǒmen liǎojiě le Guǎngzhōurén de shēnghuó."},{"fr":"On sait maintenant présenter ses vœux du Nouvel An.","tgt":"现在我们会说拜年的话了。","ro":"Xiànzài wǒmen huì shuō bàinián de huà le."},{"fr":"Des petits mots comme « peut-être » rendent le chinois plus naturel.","tgt":"像“可能”、“也许”这样的词让说话更自然。","ro":"Xiàng \"kěnéng\", \"yěxǔ\" zhèyàng de cí ràng shuōhuà gèng zìrán."},{"fr":"On sait aussi quand dire « nín » pour être poli.","tgt":"我们也知道什么时候该用“您”。","ro":"Wǒmen yě zhīdào shénme shíhou gāi yòng \"nín\"."},{"fr":"Le deuxième niveau s'achève ici.","tgt":"第二级到这里就结束了。","ro":"Dì-èr jí dào zhèlǐ jiù jiéshù le."},{"fr":"Bravo, tu as fait un super travail !","tgt":"你辛苦了，做得很棒！","ro":"Nǐ xīnkǔ le, zuò de hěn bàng!"},{"fr":"Au niveau suivant, on apprendra un chinois plus authentique.","tgt":"下一级我们会学更地道的中文。","ro":"Xià yì jí wǒmen huì xué gèng dìdao de Zhōngwén."},{"fr":"Repose-toi un peu, tu l'as bien mérité.","tgt":"好好休息一下吧，这是你应得的。","ro":"Hǎohǎo xiūxi yíxià ba, zhè shì nǐ yīngdé de."},{"fr":"On se retrouve au dernier niveau !","tgt":"最后一级见！","ro":"Zuìhòu yì jí jiàn!"}]}]}]},{"id":3,"name":"Niveau 3","freeLessonsPerModule":{"1":3,"2":0,"3":0},"modules":[{"id":1,"name":"Le quotidien","desc":"Une vie quotidienne installée en Chine, avec ses subtilités.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Un dossier égaré au bureau","phrases":[{"fr":"Mon ordinateur portable a été pris par erreur par un collègue.","tgt":"我的笔记本电脑被同事拿错了。","ro":"Wǒ de bǐjìběn diànnǎo bèi tóngshì ná cuò le."},{"fr":"Le dossier du client a été égaré par la stagiaire.","tgt":"客户的资料被实习生弄丢了。","ro":"Kèhù de zīliào bèi shíxíshēng nòng diū le."},{"fr":"Ce matin, j'ai été appelé dans le bureau de mon chef.","tgt":"今天早上我被老板叫到办公室去了。","ro":"Jīntiān zǎoshang wǒ bèi lǎobǎn jiào dào bàngōngshì qù le."},{"fr":"Il paraît que le projet a été annulé par la direction.","tgt":"听说这个项目被公司领导取消了。","ro":"Tīngshuō zhège xiàngmù bèi gōngsī lǐngdǎo qǔxiāo le."},{"fr":"Mon vélo a été volé juste devant l'immeuble de l'entreprise.","tgt":"我的自行车在公司楼下被偷了。","ro":"Wǒ de zìxíngchē zài gōngsī lóu xià bèi tōu le."},{"fr":"Le fichier a été effacé par erreur, il faut tout refaire.","tgt":"文件被误删了，得全部重做。","ro":"Wénjiàn bèi wù shān le, děi quánbù chóng zuò."},{"fr":"Ne t'inquiète pas, tu ne seras pas critiqué pour cette histoire.","tgt":"别担心，你不会因为这件事被批评的。","ro":"Bié dānxīn, nǐ bú huì yīnwèi zhè jiàn shì bèi pīpíng de."},{"fr":"Le dossier a finalement été retrouvé par la femme de ménage.","tgt":"资料最后被保洁阿姨找到了。","ro":"Zīliào zuìhòu bèi bǎojié āyí zhǎo dào le."},{"fr":"Heureusement, mon idée a été acceptée par toute l'équipe.","tgt":"幸好我的想法被整个团队接受了。","ro":"Xìnghǎo wǒ de xiǎngfǎ bèi zhěnggè tuánduì jiēshòu le."},{"fr":"Désormais, je range les documents importants dans un tiroir fermé à clé.","tgt":"以后我会把重要文件都锁在抽屉里。","ro":"Yǐhòu wǒ huì bǎ zhòngyào wénjiàn dōu suǒ zài chōuti lǐ."}],"tip":{"title":"Le passif avec « bèi »","example":"Le dossier du client a été égaré par la stagiaire. — 客户的资料<b>被</b>实习生弄丢了。","body":"En chinois, le passif se construit avec le petit mot « bèi ». L'ordre est toujours le même : d'abord la chose qui subit, puis « bèi », puis celui qui agit, et enfin le verbe avec son résultat. Dans « Kèhù de zīliào bèi shíxíshēng nòng diū le », on dit mot à mot : le dossier du client, subi par la stagiaire, rendu perdu. Contrairement au français, ce passif sert surtout pour les événements désagréables, comme « bèi tōu le », avoir été volé, ou « bèi pīpíng », être critiqué. Si on ne sait pas qui a agi, on enchaîne directement « bèi » et le verbe : « Wénjiàn bèi wù shān le », le fichier a été effacé par erreur. Pour retenir, pensez que « bèi » sonne comme un petit soupir de victime.","exampleRo":"Kèhù de zīliào bèi shíxíshēng nòng diū le.","lit":"client · [possessif] · dossier · [passif] · stagiaire · rendre-perdu · [accompli]","say":{"bèi":"被","Kèhù de zīliào bèi shíxíshēng nòng diū le":"客户的资料被实习生弄丢了","bèi tōu le":"被偷了","bèi pīpíng":"被批评","Wénjiàn bèi wù shān le":"文件被误删了"}}},{"title":"Premier jour dans une entreprise de Shenzhen","phrases":[{"fr":"Je commence aujourd'hui dans une entreprise de technologie à Shenzhen.","tgt":"我今天开始在深圳一家科技公司上班。","ro":"Wǒ jīntiān kāishǐ zài Shēnzhèn yì jiā kējì gōngsī shàngbān."},{"fr":"La réception m'a remis un badge d'accès.","tgt":"前台给了我一张门禁卡。","ro":"Qiántái gěi le wǒ yì zhāng ménjìnkǎ."},{"fr":"Mon poste de travail est au dix-huitième étage, près de la fenêtre.","tgt":"我的工位在十八楼，靠窗。","ro":"Wǒ de gōngwèi zài shíbā lóu, kào chuāng."},{"fr":"La responsable des ressources humaines m'a fait visiter les locaux.","tgt":"人事经理带我参观了办公室。","ro":"Rénshì jīnglǐ dài wǒ cānguān le bàngōngshì."},{"fr":"Ici, presque tout le monde déjeune à la cantine de l'entreprise.","tgt":"这里几乎每个人都在公司食堂吃午饭。","ro":"Zhèlǐ jīhū měi ge rén dōu zài gōngsī shítáng chī wǔfàn."},{"fr":"On m'a tout de suite ajouté au groupe de messagerie de l'équipe.","tgt":"他们马上把我拉进了团队的工作群。","ro":"Tāmen mǎshàng bǎ wǒ lā jìn le tuánduì de gōngzuò qún."},{"fr":"Mes nouveaux collègues ont l'air sympathiques et très efficaces.","tgt":"新同事看起来很友好，工作效率也很高。","ro":"Xīn tóngshì kàn qǐlai hěn yǒuhǎo, gōngzuò xiàolǜ yě hěn gāo."},{"fr":"Je dois encore m'habituer au rythme de travail d'ici.","tgt":"我还得慢慢适应这里的工作节奏。","ro":"Wǒ hái děi mànmàn shìyìng zhèlǐ de gōngzuò jiézòu."},{"fr":"Mon tuteur m'a conseillé de lui poser directement mes questions.","tgt":"我的导师建议我有问题就直接问他。","ro":"Wǒ de dǎoshī jiànyì wǒ yǒu wèntí jiù zhíjiē wèn tā."},{"fr":"Pour un premier jour, tout s'est passé mieux que je ne l'imaginais.","tgt":"第一天一切都比我想象的顺利。","ro":"Dì yī tiān yíqiè dōu bǐ wǒ xiǎngxiàng de shùnlì."}]},{"title":"Organiser une réunion d'équipe","phrases":[{"fr":"Mon chef m'a demandé d'organiser la réunion de lundi.","tgt":"老板让我组织周一的会议。","ro":"Lǎobǎn ràng wǒ zǔzhī zhōuyī de huìyì."},{"fr":"Je vais demander à Xiao Li de réserver la salle de réunion.","tgt":"我去叫小李订一下会议室。","ro":"Wǒ qù jiào Xiǎo Lǐ dìng yíxià huìyìshì."},{"fr":"Laisse-moi d'abord regarder l'agenda de tout le monde.","tgt":"让我先看一下大家的日程。","ro":"Ràng wǒ xiān kàn yíxià dàjiā de rìchéng."},{"fr":"La directrice nous a fait préparer un rapport pour vendredi.","tgt":"总监让我们周五之前准备好一份报告。","ro":"Zǒngjiān ràng wǒmen zhōuwǔ zhīqián zhǔnbèi hǎo yí fèn bàogào."},{"fr":"Ne fais pas attendre les clients, ils sont déjà arrivés.","tgt":"别让客户等，他们已经到了。","ro":"Bié ràng kèhù děng, tāmen yǐjīng dào le."},{"fr":"Son intervention a fait rire tout le monde.","tgt":"他的发言让大家都笑了。","ro":"Tā de fāyán ràng dàjiā dōu xiào le."},{"fr":"Le manager m'a dit de prendre des notes pendant la réunion.","tgt":"经理叫我开会的时候做记录。","ro":"Jīnglǐ jiào wǒ kāihuì de shíhou zuò jìlù."},{"fr":"Cette nouvelle m'a beaucoup inquiété.","tgt":"这个消息让我很担心。","ro":"Zhège xiāoxi ràng wǒ hěn dānxīn."},{"fr":"Tu peux dire à tout le monde d'apporter son ordinateur ?","tgt":"你能叫大家带上电脑吗？","ro":"Nǐ néng jiào dàjiā dài shang diànnǎo ma?"},{"fr":"La réunion a duré deux heures, mais tout a été clarifié.","tgt":"会开了两个小时，不过把问题都说清楚了。","ro":"Huì kāi le liǎng ge xiǎoshí, búguò bǎ wèntí dōu shuō qīngchu le."}],"tip":{"title":"Faire faire : « ràng » et « jiào »","example":"Mon chef m'a demandé d'organiser la réunion de lundi. — 老板<b>让</b>我组织周一的会议。","body":"Pour dire « faire faire » ou « demander à quelqu'un de faire », le chinois place « ràng » ou « jiào » juste devant la personne qui va agir. La structure ne bouge pas : qui demande, puis « ràng », puis qui fait, puis l'action. « Lǎobǎn ràng wǒ zǔzhī zhōuyī de huìyì » se décompose ainsi : patron, faire, moi, organiser la réunion de lundi. « Jiào » a presque le même sens mais sonne plus direct et plus familier, comme dans « Wǒ qù jiào Xiǎo Lǐ dìng yíxià huìyìshì ». « Ràng » sert aussi pour les émotions, « Zhège xiāoxi ràng wǒ hěn dānxīn », cette nouvelle m'inquiète, et pour proposer : « Ràng wǒ xiān kàn yíxià », laisse-moi d'abord regarder. Astuce : « ràng » veut aussi dire céder le passage, on laisse la place à quelqu'un d'autre pour agir.","exampleRo":"Lǎobǎn ràng wǒ zǔzhī zhōuyī de huìyì.","lit":"patron · faire · moi · organiser · lundi · [possessif] · réunion","say":{"ràng":"让","jiào":"叫","Lǎobǎn ràng wǒ zǔzhī zhōuyī de huìyì":"老板让我组织周一的会议","Jiào":"叫","Wǒ qù jiào Xiǎo Lǐ dìng yíxià huìyìshì":"我去叫小李订一下会议室","Ràng":"让","Zhège xiāoxi ràng wǒ hěn dānxīn":"这个消息让我很担心","Ràng wǒ xiān kàn yíxià":"让我先看一下"}}},{"title":"Négocier avec un fournisseur","phrases":[{"fr":"Le prix que vous proposez dépasse notre budget.","tgt":"您报的价格超出了我们的预算。","ro":"Nín bào de jiàgé chāochū le wǒmen de yùsuàn."},{"fr":"Si nous commandons en grande quantité, pouvez-vous faire une remise ?","tgt":"如果我们大量订购，能不能打个折？","ro":"Rúguǒ wǒmen dàliàng dìnggòu, néng bu néng dǎ ge zhé?"},{"fr":"Nous devons recevoir la marchandise avant la fin du mois.","tgt":"我们需要月底之前收到货。","ro":"Wǒmen xūyào yuèdǐ zhīqián shōu dào huò."},{"fr":"Un de vos concurrents nous a fait une offre plus intéressante.","tgt":"你们的一个竞争对手给了我们更好的报价。","ro":"Nǐmen de yí ge jìngzhēng duìshǒu gěi le wǒmen gèng hǎo de bàojià."},{"fr":"Sur le délai, nous pouvons céder, mais pas sur la qualité.","tgt":"交货时间我们可以让步，但质量不能让步。","ro":"Jiāohuò shíjiān wǒmen kěyǐ ràngbù, dàn zhìliàng bù néng ràngbù."},{"fr":"Le paiement se fera en deux fois, avec la moitié à la commande.","tgt":"付款分两次，下单时先付一半。","ro":"Fùkuǎn fēn liǎng cì, xiàdān shí xiān fù yíbàn."},{"fr":"Je dois d'abord consulter ma hiérarchie avant de vous répondre.","tgt":"我得先跟上级商量一下，再给您答复。","ro":"Wǒ děi xiān gēn shàngjí shāngliang yíxià, zài gěi nín dáfù."},{"fr":"Quinze pour cent de remise, c'est notre dernière offre.","tgt":"打八五折，这是我们最后的报价。","ro":"Dǎ bā wǔ zhé, zhè shì wǒmen zuìhòu de bàojià."},{"fr":"Je pense qu'on peut trouver une solution acceptable pour les deux parties.","tgt":"我觉得我们可以找到一个双方都能接受的方案。","ro":"Wǒ juéde wǒmen kěyǐ zhǎo dào yí ge shuāngfāng dōu néng jiēshòu de fāng'àn."},{"fr":"Marché conclu, nous vous envoyons le contrat demain.","tgt":"那就这么定了，我们明天把合同发给您。","ro":"Nà jiù zhème dìng le, wǒmen míngtiān bǎ hétong fā gěi nín."}]},{"title":"Signer un contrat de travail","phrases":[{"fr":"Il suffit que vous signiez ici et le contrat prend effet.","tgt":"只要您在这里签字，合同就生效了。","ro":"Zhǐyào nín zài zhèlǐ qiānzì, hétong jiù shēngxiào le."},{"fr":"C'est seulement après la période d'essai que tu seras titularisé.","tgt":"只有过了试用期，你才能转正。","ro":"Zhǐyǒu guò le shìyòngqī, nǐ cái néng zhuǎnzhèng."},{"fr":"La période d'essai dure trois mois.","tgt":"试用期是三个月。","ro":"Shìyòngqī shì sān ge yuè."},{"fr":"Du moment que tu atteins tes objectifs, tu touches une prime.","tgt":"只要完成目标，你就能拿到奖金。","ro":"Zhǐyào wánchéng mùbiāo, nǐ jiù néng ná dào jiǎngjīn."},{"fr":"Ce n'est qu'avec un contrat écrit que tes droits sont protégés.","tgt":"只有签了书面合同，你的权益才有保障。","ro":"Zhǐyǒu qiān le shūmiàn hétong, nǐ de quányì cái yǒu bǎozhàng."},{"fr":"Le salaire est versé le dix de chaque mois.","tgt":"工资每个月十号发。","ro":"Gōngzī měi ge yuè shí hào fā."},{"fr":"Tant que tu préviens un mois à l'avance, tu peux démissionner.","tgt":"只要提前一个月通知，你就可以辞职。","ro":"Zhǐyào tíqián yí ge yuè tōngzhī, nǐ jiù kěyǐ cízhí."},{"fr":"L'entreprise cotise pour la retraite et l'assurance maladie des employés.","tgt":"公司给员工交养老保险和医疗保险。","ro":"Gōngsī gěi yuángōng jiāo yǎnglǎo bǎoxiǎn hé yīliáo bǎoxiǎn."},{"fr":"Seul le directeur général peut approuver ce genre d'exception.","tgt":"只有总经理才能批准这种例外。","ro":"Zhǐyǒu zǒngjīnglǐ cái néng pīzhǔn zhè zhǒng lìwài."},{"fr":"Avant de signer, relisez bien chaque clause.","tgt":"签字之前，请仔细看一下每一条。","ro":"Qiānzì zhīqián, qǐng zǐxì kàn yíxià měi yì tiáo."}],"tip":{"title":"« Zhǐyào... jiù... » et « zhǐyǒu... cái... »","example":"Il suffit que vous signiez ici et le contrat prend effet. — <b>只要</b>您在这里签字，合同<b>就</b>生效了。","body":"Ces deux structures expriment une condition, mais avec des nuances opposées. « Zhǐyào... jiù... » veut dire « il suffit que... et alors... » : la condition est facile, et le résultat suit tout seul. On l'entend dans « Zhǐyào nín zài zhèlǐ qiānzì, hétong jiù shēngxiào le » : il suffit que vous signiez ici, alors le contrat prend effet. « Zhǐyǒu... cái... » veut dire au contraire « seulement si... alors seulement » : la condition est indispensable, comme dans « Zhǐyǒu guò le shìyòngqī, nǐ cái néng zhuǎnzhèng », c'est seulement après la période d'essai que tu seras titularisé. À l'oral, on appuie légèrement sur « jiù » et sur « cái », qui portent tout le sens de la phrase. Astuce : « jiù », c'est la porte grande ouverte, « cái », c'est le passage étroit.","exampleRo":"Zhǐyào nín zài zhèlǐ qiānzì, hétong jiù shēngxiào le.","lit":"il-suffit-que · vous · à · ici · signer · , · contrat · alors · prendre-effet · [accompli]","say":{"Zhǐyào... jiù...":"只要……就……","zhǐyǒu... cái...":"只有……才……","Zhǐyào nín zài zhèlǐ qiānzì, hétong jiù shēngxiào le":"只要您在这里签字，合同就生效了","Zhǐyǒu... cái...":"只有……才……","Zhǐyǒu guò le shìyòngqī, nǐ cái néng zhuǎnzhèng":"只有过了试用期，你才能转正","jiù":"就","cái":"才"}}},{"title":"Choisir une assurance santé","phrases":[{"fr":"La sécurité sociale ne rembourse pas tous les frais médicaux.","tgt":"社保不能报销所有的医疗费用。","ro":"Shèbǎo bù néng bàoxiāo suǒyǒu de yīliáo fèiyòng."},{"fr":"Beaucoup de gens souscrivent en plus une assurance privée.","tgt":"很多人会再买一份商业保险。","ro":"Hěn duō rén huì zài mǎi yí fèn shāngyè bǎoxiǎn."},{"fr":"Cette formule couvre aussi les soins dentaires.","tgt":"这个方案也包括牙科治疗。","ro":"Zhège fāng'àn yě bāokuò yákē zhìliáo."},{"fr":"La cotisation annuelle s'élève à trois mille yuans.","tgt":"每年的保费是三千元。","ro":"Měi nián de bǎofèi shì sānqiān yuán."},{"fr":"En cas de maladie, combien de temps faut-il pour être indemnisé ?","tgt":"如果生病了，多久能拿到理赔？","ro":"Rúguǒ shēngbìng le, duō jiǔ néng ná dào lǐpéi?"},{"fr":"Mieux vaut comparer plusieurs compagnies avant de se décider.","tgt":"最好多比较几家再做决定。","ro":"Zuìhǎo duō bǐjiào jǐ jiā zài zuò juédìng."},{"fr":"Le conseiller m'a expliqué les conditions en détail.","tgt":"保险顾问给我详细解释了条款。","ro":"Bǎoxiǎn gùwèn gěi wǒ xiángxì jiěshì le tiáokuǎn."},{"fr":"Attention aux maladies que le contrat ne couvre pas.","tgt":"要注意合同里不保的疾病。","ro":"Yào zhùyì hétong lǐ bù bǎo de jíbìng."},{"fr":"J'ai finalement choisi une formule plus simple mais moins chère.","tgt":"最后我选了一个简单一点但便宜一点的方案。","ro":"Zuìhòu wǒ xuǎn le yí ge jiǎndān yìdiǎn dàn piányi yìdiǎn de fāng'àn."},{"fr":"Avec une bonne assurance, on se sent beaucoup plus serein.","tgt":"有了保险，心里踏实多了。","ro":"Yǒu le bǎoxiǎn, xīnli tāshi duō le."}]},{"title":"Déménager à Nanshan","phrases":[{"fr":"Le mois prochain, nous déménageons dans le quartier de Nanshan.","tgt":"我们下个月搬到南山区。","ro":"Wǒmen xià ge yuè bān dào Nánshān Qū."},{"fr":"Le nouvel appartement est plus près de mon bureau.","tgt":"新房子离我公司更近。","ro":"Xīn fángzi lí wǒ gōngsī gèng jìn."},{"fr":"J'ai réservé une société de déménagement pour samedi matin.","tgt":"我约了一家搬家公司周六上午来。","ro":"Wǒ yuē le yì jiā bānjiā gōngsī zhōuliù shàngwǔ lái."},{"fr":"Toute la vaisselle doit être emballée dans du papier journal.","tgt":"所有的碗盘都得用报纸包好。","ro":"Suǒyǒu de wǎnpán dōu děi yòng bàozhǐ bāo hǎo."},{"fr":"Les déménageurs ont monté les meubles par le monte-charge.","tgt":"搬家师傅用货梯把家具搬上去了。","ro":"Bānjiā shīfu yòng huòtī bǎ jiājù bān shàngqu le."},{"fr":"Un des cartons a été écrasé pendant le transport.","tgt":"有一个箱子在路上被压坏了。","ro":"Yǒu yí ge xiāngzi zài lùshang bèi yā huài le."},{"fr":"Je dois encore aller changer mon adresse à la banque.","tgt":"我还得去银行改地址。","ro":"Wǒ hái děi qù yínháng gǎi dìzhǐ."},{"fr":"L'agent de sécurité de la résidence nous a remis les clés et la carte d'accès.","tgt":"小区保安把钥匙和门卡交给了我们。","ro":"Xiǎoqū bǎo'ān bǎ yàoshi hé ménkǎ jiāo gěi le wǒmen."},{"fr":"Il faudra plusieurs jours pour tout déballer et ranger.","tgt":"把东西全部拆开整理好，得好几天。","ro":"Bǎ dōngxi quánbù chāi kāi zhěnglǐ hǎo, děi hǎo jǐ tiān."},{"fr":"Le week-end prochain, on invite des amis pour pendre la crémaillère.","tgt":"下个周末我们请朋友来暖房。","ro":"Xià ge zhōumò wǒmen qǐng péngyou lái nuǎnfáng."}]},{"title":"Les transports aux heures de pointe","phrases":[{"fr":"À huit heures, le métro est si bondé qu'on ne peut même pas bouger.","tgt":"早上八点地铁挤得连动都动不了。","ro":"Zǎoshang bā diǎn dìtiě jǐ de lián dòng dōu dòng bu liǎo."},{"fr":"Ce matin, je n'ai même pas eu le temps de boire un café.","tgt":"今天早上我连喝杯咖啡的时间都没有。","ro":"Jīntiān zǎoshang wǒ lián hē bēi kāfēi de shíjiān dōu méiyǒu."},{"fr":"Quand il pleut, même les taxis sont introuvables.","tgt":"下雨的时候连出租车都打不到。","ro":"Xià yǔ de shíhou lián chūzūchē dōu dǎ bu dào."},{"fr":"Même mon patron prend le métro pour venir travailler.","tgt":"连我老板都坐地铁上班。","ro":"Lián wǒ lǎobǎn dōu zuò dìtiě shàngbān."},{"fr":"Je prends la ligne un jusqu'à Futian, puis je change.","tgt":"我坐一号线到福田，然后换乘。","ro":"Wǒ zuò yī hào xiàn dào Fútián, ránhòu huànchéng."},{"fr":"Avec les embouteillages, le bus met parfois une heure.","tgt":"堵车的时候，公交车有时候要开一个小时。","ro":"Dǔchē de shíhou, gōngjiāochē yǒushíhou yào kāi yí ge xiǎoshí."},{"fr":"Je n'ai même pas trouvé d'endroit pour garer mon vélo.","tgt":"我连停自行车的地方都没找到。","ro":"Wǒ lián tíng zìxíngchē de dìfang dōu méi zhǎo dào."},{"fr":"Beaucoup de gens vont travailler en vélo partagé.","tgt":"很多人骑共享单车上班。","ro":"Hěn duō rén qí gòngxiǎng dānchē shàngbān."},{"fr":"Même un enfant sait payer le bus avec son téléphone.","tgt":"连小孩都会用手机坐公交。","ro":"Lián xiǎohái dōu huì yòng shǒujī zuò gōngjiāo."},{"fr":"En partant un peu plus tôt, le trajet devient beaucoup moins pénible.","tgt":"早点出门，路上就轻松多了。","ro":"Zǎo diǎn chūmén, lùshang jiù qīngsōng duō le."}],"tip":{"title":"« Lián... dōu... » : même","example":"Même mon patron prend le métro pour venir travailler. — <b>连</b>我老板<b>都</b>坐地铁上班。","body":"Pour dire « même », le chinois encadre le mot qu'on veut souligner entre « lián » et « dōu », parfois « lián » et « yě ». On place « lián » juste avant l'élément surprenant, puis « dōu » juste avant le verbe. « Lián wǒ lǎobǎn dōu zuò dìtiě shàngbān » se décompose ainsi : même, mon patron, tous, prendre le métro, aller travailler. Avec une négation, on obtient « même pas » : « Wǒ lián hē bēi kāfēi de shíjiān dōu méiyǒu », je n'ai même pas le temps de boire un café. La structure ajoute beaucoup d'expressivité, presque de l'exagération, comme dans « jǐ de lián dòng dōu dòng bu liǎo », tellement serré qu'on ne peut même pas bouger. Astuce : imaginez « lián » et « dōu » comme deux mains qui soulèvent le mot important pour le montrer à tout le monde.","exampleRo":"Lián wǒ lǎobǎn dōu zuò dìtiě shàngbān.","lit":"même · moi · patron · tous · prendre · métro · aller-au-travail","say":{"Lián... dōu...":"连……都……","lián":"连","dōu":"都","yě":"也","Lián wǒ lǎobǎn dōu zuò dìtiě shàngbān":"连我老板都坐地铁上班","Wǒ lián hē bēi kāfēi de shíjiān dōu méiyǒu":"我连喝杯咖啡的时间都没有","jǐ de lián dòng dōu dòng bu liǎo":"挤得连动都动不了"}}},{"title":"Le télétravail","phrases":[{"fr":"Depuis cette année, je travaille de chez moi deux jours par semaine.","tgt":"从今年开始，我每周在家办公两天。","ro":"Cóng jīnnián kāishǐ, wǒ měi zhōu zài jiā bàngōng liǎng tiān."},{"fr":"Je me suis installé un petit coin bureau dans le salon.","tgt":"我在客厅里弄了一个小小的办公区。","ro":"Wǒ zài kètīng lǐ nòng le yí ge xiǎoxiǎo de bàngōngqū."},{"fr":"Les visioconférences commencent souvent à neuf heures pile.","tgt":"视频会议常常九点整就开始。","ro":"Shìpín huìyì chángcháng jiǔ diǎn zhěng jiù kāishǐ."},{"fr":"Sans le trajet, je gagne presque deux heures par jour.","tgt":"不用通勤，我每天能省下差不多两个小时。","ro":"Bú yòng tōngqín, wǒ měi tiān néng shěng xià chàbuduō liǎng ge xiǎoshí."},{"fr":"Le plus difficile, c'est de séparer le travail et la vie privée.","tgt":"最难的是把工作和生活分开。","ro":"Zuì nán de shì bǎ gōngzuò hé shēnghuó fēnkāi."},{"fr":"Parfois, la connexion coupe en pleine réunion.","tgt":"有时候开会开到一半网就断了。","ro":"Yǒushíhou kāihuì kāi dào yíbàn wǎng jiù duàn le."},{"fr":"Je ne vois presque plus mes collègues en personne.","tgt":"我现在很少见到同事本人了。","ro":"Wǒ xiànzài hěn shǎo jiàn dào tóngshì běnrén le."},{"fr":"Tant que je rends mon travail à temps, mon chef se moque de l'endroit où je suis.","tgt":"只要按时完成任务，老板就不会管我在哪儿工作。","ro":"Zhǐyào ànshí wánchéng rènwu, lǎobǎn jiù bú huì guǎn wǒ zài nǎr gōngzuò."},{"fr":"À midi, je sors marcher un peu pour faire une pause.","tgt":"中午我会出去走走，休息一下。","ro":"Zhōngwǔ wǒ huì chūqu zǒuzou, xiūxi yíxià."},{"fr":"Dans l'ensemble, le travail à domicile me convient très bien.","tgt":"总的来说，在家办公很适合我。","ro":"Zǒng de lái shuō, zài jiā bàngōng hěn shìhé wǒ."}]},{"title":"Ouvrir un compte en banque","phrases":[{"fr":"Je voudrais ouvrir un compte pour recevoir mon salaire.","tgt":"我想开个账户，用来收工资。","ro":"Wǒ xiǎng kāi ge zhànghù, yònglái shōu gōngzī."},{"fr":"Quels documents est-ce que je dois apporter ?","tgt":"我需要带哪些材料？","ro":"Wǒ xūyào dài nǎxiē cáiliào?"},{"fr":"Il faut votre passeport, votre contrat de travail et un numéro de portable local.","tgt":"需要护照、劳动合同和本地手机号。","ro":"Xūyào hùzhào, láodòng hétong hé běndì shǒujīhào."},{"fr":"Prenez un ticket et revenez quand on appelle votre numéro.","tgt":"请先取号，等叫到您的号再过来。","ro":"Qǐng xiān qǔ hào, děng jiào dào nín de hào zài guòlai."},{"fr":"L'employé du guichet m'a fait remplir trois formulaires.","tgt":"柜员让我填了三张表。","ro":"Guìyuán ràng wǒ tián le sān zhāng biǎo."},{"fr":"Je dois aussi relier cette carte au paiement sur mon téléphone.","tgt":"我还要把这张卡绑定到手机支付上。","ro":"Wǒ hái yào bǎ zhè zhāng kǎ bǎngdìng dào shǒujī zhīfù shang."},{"fr":"La carte bancaire sera prête dans une semaine.","tgt":"银行卡一个星期以后就能拿到。","ro":"Yínhángkǎ yí ge xīngqī yǐhòu jiù néng ná dào."},{"fr":"Ensuite, il faut déclarer son logement au poste de police du quartier.","tgt":"然后还得去派出所办住宿登记。","ro":"Ránhòu hái děi qù pàichūsuǒ bàn zhùsù dēngjì."},{"fr":"Toutes ces formalités prennent vraiment beaucoup de temps.","tgt":"这些手续真的很花时间。","ro":"Zhèxiē shǒuxù zhēn de hěn huā shíjiān."},{"fr":"Heureusement, une collègue chinoise m'a accompagné.","tgt":"幸好有一位中国同事陪我一起去。","ro":"Xìnghǎo yǒu yí wèi Zhōngguó tóngshì péi wǒ yìqǐ qù."}]},{"title":"Un désaccord avec un collègue","phrases":[{"fr":"Un collègue s'est attribué le mérite de mon travail.","tgt":"有个同事把我的功劳算到了自己头上。","ro":"Yǒu ge tóngshì bǎ wǒ de gōngláo suàn dào le zìjǐ tóu shang."},{"fr":"Au début, j'ai choisi de ne rien dire.","tgt":"一开始我选择什么都不说。","ro":"Yì kāishǐ wǒ xuǎnzé shénme dōu bù shuō."},{"fr":"Mais l'ambiance devenait de plus en plus tendue.","tgt":"但是气氛越来越紧张了。","ro":"Dànshì qìfēn yuè lái yuè jǐnzhāng le."},{"fr":"Finalement, je l'ai invité à prendre un café.","tgt":"后来我约他一起喝了杯咖啡。","ro":"Hòulái wǒ yuē tā yìqǐ hē le bēi kāfēi."},{"fr":"Nous avons parlé franchement, sans nous accuser l'un l'autre.","tgt":"我们坦诚地聊了聊，没有互相指责。","ro":"Wǒmen tǎnchéng de liáo le liáo, méiyǒu hùxiāng zhǐzé."},{"fr":"Il a reconnu qu'il aurait dû mentionner mon nom.","tgt":"他承认应该提到我的名字。","ro":"Tā chéngrèn yīnggāi tí dào wǒ de míngzi."},{"fr":"En Chine, on évite de faire perdre la face à quelqu'un devant les autres.","tgt":"在中国，人们一般不会当众让别人丢面子。","ro":"Zài Zhōngguó, rénmen yìbān bú huì dāngzhòng ràng biérén diū miànzi."},{"fr":"C'est pour ça que j'ai préféré lui parler en privé.","tgt":"所以我选择私下跟他谈。","ro":"Suǒyǐ wǒ xuǎnzé sīxià gēn tā tán."},{"fr":"Depuis, nous travaillons beaucoup mieux ensemble.","tgt":"从那以后，我们合作得好多了。","ro":"Cóng nà yǐhòu, wǒmen hézuò de hǎo duō le."},{"fr":"Comme on dit en chinois, on réduit les grands problèmes et on efface les petits.","tgt":"俗话说，大事化小，小事化了。","ro":"Súhuà shuō, dà shì huà xiǎo, xiǎo shì huà liǎo."}]},{"title":"Présenter les résultats à la direction","phrases":[{"fr":"Bonjour à tous, merci d'être venus malgré vos emplois du temps chargés.","tgt":"大家好，感谢各位在百忙之中抽空参加。","ro":"Dàjiā hǎo, gǎnxiè gèwèi zài bǎi máng zhī zhōng chōukòng cānjiā."},{"fr":"Permettez-moi de vous présenter brièvement les résultats du trimestre.","tgt":"请允许我简单介绍一下本季度的业绩。","ro":"Qǐng yǔnxǔ wǒ jiǎndān jièshào yíxià běn jìdù de yèjì."},{"fr":"Comme vous pouvez le constater, le chiffre d'affaires est en hausse.","tgt":"正如大家所看到的，营业额有所增长。","ro":"Zhèng rú dàjiā suǒ kàn dào de, yíngyè'é yǒu suǒ zēngzhǎng."},{"fr":"Nous avons rencontré quelques difficultés du côté de la logistique.","tgt":"我们在物流方面遇到了一些困难。","ro":"Wǒmen zài wùliú fāngmiàn yù dào le yìxiē kùnnan."},{"fr":"Je tiens à vous remercier pour votre soutien et votre confiance.","tgt":"感谢大家的支持和信任。","ro":"Gǎnxiè dàjiā de zhīchí hé xìnrèn."},{"fr":"Si vous avez des remarques, n'hésitez pas à m'en faire part.","tgt":"如有任何意见，欢迎随时提出。","ro":"Rú yǒu rènhé yìjiàn, huānyíng suíshí tíchū."},{"fr":"Je me permets de vous recontacter au sujet de notre collaboration.","tgt":"冒昧再次联系您，是关于我们合作的事情。","ro":"Màomèi zàicì liánxì nín, shì guānyú wǒmen hézuò de shìqing."},{"fr":"Nous vous prions de bien vouloir nous répondre avant vendredi.","tgt":"烦请您在周五之前给予答复。","ro":"Fánqǐng nín zài zhōuwǔ zhīqián jǐyǔ dáfù."},{"fr":"Je vous présente toutes mes excuses pour ce retard.","tgt":"对于这次延误，我深表歉意。","ro":"Duìyú zhè cì yánwù, wǒ shēn biǎo qiànyì."},{"fr":"Voilà pour mon rapport, merci à tous.","tgt":"以上就是我的汇报，谢谢大家。","ro":"Yǐshàng jiù shì wǒ de huìbào, xièxie dàjiā."}],"tip":{"title":"Le langage du bureau : les formules formelles","example":"Bonjour à tous, merci d'être venus malgré vos emplois du temps chargés. — 大家好，<b>感谢各位</b>在<b>百忙之中</b>抽空参加。","body":"Au bureau, le chinois change de ton dès qu'on parle en réunion, en présentation ou à un client. On remplace « dàjiā », tout le monde, par « gèwèi », mesdames et messieurs, et le simple « xièxie » par « gǎnxiè », remercier. La formule « zài bǎi máng zhī zhōng chōukòng », mot à mot au milieu de cent occupations trouver le temps, sert à remercier quelqu'un d'être venu malgré son emploi du temps. Pour faire une demande polie, on commence par « fánqǐng », je vous prie de bien vouloir, et pour s'excuser, on dit « shēn biǎo qiànyì », j'exprime mes profonds regrets. Ces expressions courtes, souvent en quatre syllabes, donnent tout de suite une image sérieuse et respectueuse. Astuce : apprenez-les comme des blocs figés, à prononcer calmement et d'une seule traite.","exampleRo":"Dàjiā hǎo, gǎnxiè gèwèi zài bǎi máng zhī zhōng chōukòng cānjiā.","lit":"tout-le-monde · bien · , · remercier · vous-tous · à · cent-occupations · au-milieu-de · trouver-le-temps · participer","say":{"dàjiā":"大家","gèwèi":"各位","xièxie":"谢谢","gǎnxiè":"感谢","zài bǎi máng zhī zhōng chōukòng":"在百忙之中抽空","fánqǐng":"烦请","shēn biǎo qiànyì":"深表歉意"}}},{"title":"Une consultation à l'hôpital","phrases":[{"fr":"Il faut prendre rendez-vous en ligne la veille.","tgt":"要提前一天在网上挂号。","ro":"Yào tíqián yì tiān zài wǎngshàng guàhào."},{"fr":"Je ne sais pas dans quel service je dois m'inscrire.","tgt":"我不知道该挂哪个科。","ro":"Wǒ bù zhīdào gāi guà nǎge kē."},{"fr":"L'infirmière m'a envoyé en médecine interne.","tgt":"护士让我去内科。","ro":"Hùshi ràng wǒ qù nèikē."},{"fr":"Le médecin m'a fait faire une prise de sang.","tgt":"医生让我去验血。","ro":"Yīshēng ràng wǒ qù yànxuè."},{"fr":"Les résultats seront disponibles dans deux heures.","tgt":"结果两个小时以后出来。","ro":"Jiéguǒ liǎng ge xiǎoshí yǐhòu chūlai."},{"fr":"À chaque étape, on peut payer directement avec son téléphone.","tgt":"每一步都可以直接用手机付钱。","ro":"Měi yí bù dōu kěyǐ zhíjiē yòng shǒujī fù qián."},{"fr":"La borne n'arrive pas à lire ma carte d'assurance maladie.","tgt":"机器识别不了我的医保卡。","ro":"Jīqì shíbié bu liǎo wǒ de yībǎokǎ."},{"fr":"Il y avait tellement de monde qu'il n'y avait même pas une chaise libre.","tgt":"人多得连座位都没有。","ro":"Rén duō de lián zuòwèi dōu méiyǒu."},{"fr":"Le médecin m'a prescrit des médicaments pour une semaine.","tgt":"医生给我开了一个星期的药。","ro":"Yīshēng gěi wǒ kāi le yí ge xīngqī de yào."},{"fr":"Je dois demander un certificat d'arrêt maladie pour mon entreprise.","tgt":"我得请医生开一张病假条给公司。","ro":"Wǒ děi qǐng yīshēng kāi yì zhāng bìngjiàtiáo gěi gōngsī."}]},{"title":"Un dîner d'affaires","phrases":[{"fr":"Le client nous a invités dans un restaurant cantonais.","tgt":"客户请我们去一家粤菜馆吃饭。","ro":"Kèhù qǐng wǒmen qù yì jiā Yuècàiguǎn chīfàn."},{"fr":"L'invité le plus important s'assoit face à la porte.","tgt":"最重要的客人坐在正对门的位置。","ro":"Zuì zhòngyào de kèrén zuò zài zhèng duì mén de wèizhì."},{"fr":"Il est poli de servir les autres avant de se servir soi-même.","tgt":"先给别人夹菜，再给自己夹，这样比较礼貌。","ro":"Xiān gěi biérén jiā cài, zài gěi zìjǐ jiā, zhèyàng bǐjiào lǐmào."},{"fr":"Quand on trinque, on tient son verre un peu plus bas que celui du client.","tgt":"碰杯的时候，杯子要比客户的低一点。","ro":"Pèngbēi de shíhou, bēizi yào bǐ kèhù de dī yìdiǎn."},{"fr":"Je ne bois pas d'alcool, est-ce que je peux trinquer avec du thé ?","tgt":"我不喝酒，能以茶代酒吗？","ro":"Wǒ bù hē jiǔ, néng yǐ chá dài jiǔ ma?"},{"fr":"Pendant le repas, on parle rarement du contrat directement.","tgt":"吃饭的时候，大家很少直接谈合同。","ro":"Chīfàn de shíhou, dàjiā hěn shǎo zhíjiē tán hétong."},{"fr":"Ces plats ont l'air délicieux, vous savez vraiment bien commander.","tgt":"这些菜看起来很好吃，您真会点菜。","ro":"Zhèxiē cài kàn qǐlai hěn hǎochī, nín zhēn huì diǎn cài."},{"fr":"À notre future collaboration !","tgt":"为我们今后的合作干杯！","ro":"Wèi wǒmen jīnhòu de hézuò gānbēi!"},{"fr":"À la fin, nous nous sommes disputé l'addition très poliment.","tgt":"最后，我们客客气气地抢着买单。","ro":"Zuìhòu, wǒmen kèkeqìqì de qiǎng zhe mǎidān."},{"fr":"Ce dîner a beaucoup rapproché nos deux équipes.","tgt":"这顿饭让我们两个团队的关系近了很多。","ro":"Zhè dùn fàn ràng wǒmen liǎng ge tuánduì de guānxi jìn le hěn duō."}]},{"title":"Un litige avec le propriétaire","phrases":[{"fr":"Le climatiseur est en panne depuis une semaine.","tgt":"空调坏了一个星期了。","ro":"Kōngtiáo huài le yí ge xīngqī le."},{"fr":"Le propriétaire dit que ce n'est pas à lui de payer la réparation.","tgt":"房东说修理费不该由他出。","ro":"Fángdōng shuō xiūlǐfèi bù gāi yóu tā chū."},{"fr":"Pourtant, c'est clairement écrit dans le bail.","tgt":"可是租房合同上写得很清楚。","ro":"Kěshì zūfáng hétong shang xiě de hěn qīngchu."},{"fr":"L'été à Shenzhen, impossible de vivre sans climatisation.","tgt":"深圳的夏天，没有空调根本没法住。","ro":"Shēnzhèn de xiàtiān, méiyǒu kōngtiáo gēnběn méi fǎ zhù."},{"fr":"Je lui ai envoyé des photos et une copie du contrat.","tgt":"我给他发了照片和合同的复印件。","ro":"Wǒ gěi tā fā le zhàopiàn hé hétong de fùyìnjiàn."},{"fr":"Il m'a répondu qu'il passerait voir demain.","tgt":"他回复说明天过来看看。","ro":"Tā huífù shuō míngtiān guòlai kànkan."},{"fr":"S'il ne fait toujours rien, je m'adresserai à l'agence immobilière.","tgt":"要是他还不管，我就去找中介。","ro":"Yàoshi tā hái bù guǎn, wǒ jiù qù zhǎo zhōngjiè."},{"fr":"Je ne veux pas perdre ma caution à cause de ça.","tgt":"我不想因为这件事拿不回押金。","ro":"Wǒ bù xiǎng yīnwèi zhè jiàn shì ná bu huí yājīn."},{"fr":"Finalement, chacun a payé la moitié des frais.","tgt":"最后我们一人出了一半。","ro":"Zuìhòu wǒmen yì rén chū le yíbàn."},{"fr":"Il vaut mieux tout mettre par écrit dès le départ.","tgt":"最好一开始就把所有事情都写清楚。","ro":"Zuìhǎo yì kāishǐ jiù bǎ suǒyǒu shìqing dōu xiě qīngchu."}]},{"title":"Demander une augmentation","phrases":[{"fr":"Ça fait deux ans que mon salaire n'a pas bougé.","tgt":"我已经两年没涨工资了。","ro":"Wǒ yǐjīng liǎng nián méi zhǎng gōngzī le."},{"fr":"J'ai demandé un entretien avec ma responsable.","tgt":"我约了我的主管谈一谈。","ro":"Wǒ yuē le wǒ de zhǔguǎn tán yi tán."},{"fr":"Cette année, j'ai pris en charge trois projets importants.","tgt":"今年我负责了三个重要的项目。","ro":"Jīnnián wǒ fùzé le sān ge zhòngyào de xiàngmù."},{"fr":"Tout le monde peut voir mes résultats.","tgt":"我的业绩大家都看得到。","ro":"Wǒ de yèjì dàjiā dōu kàn de dào."},{"fr":"Sur le marché, ce poste est généralement mieux payé.","tgt":"在市场上，这个职位的工资一般更高。","ro":"Zài shìchǎng shang, zhège zhíwèi de gōngzī yìbān gèng gāo."},{"fr":"Elle m'a dit qu'elle en parlerait au service du personnel.","tgt":"她说会跟人事部门沟通一下。","ro":"Tā shuō huì gēn rénshì bùmén gōutōng yíxià."},{"fr":"On n'obtient une augmentation que si l'évaluation annuelle est bonne.","tgt":"只有考核合格，才能加薪。","ro":"Zhǐyǒu kǎohé hégé, cái néng jiāxīn."},{"fr":"Pour l'instant, j'ai obtenu deux jours de congé en plus.","tgt":"目前我先多争取到了两天年假。","ro":"Mùqián wǒ xiān duō zhēngqǔ dào le liǎng tiān niánjià."},{"fr":"Il ne faut jamais avoir peur de se battre pour soi.","tgt":"永远不要害怕为自己争取。","ro":"Yǒngyuǎn bú yào hàipà wèi zìjǐ zhēngqǔ."},{"fr":"Au final, mon salaire augmentera de dix pour cent en janvier.","tgt":"最后，一月份我的工资会涨百分之十。","ro":"Zuìhòu, yīyuèfèn wǒ de gōngzī huì zhǎng bǎi fēn zhī shí."}]},{"title":"Un déplacement à Canton","phrases":[{"fr":"Demain, je vais à Canton pour visiter une usine.","tgt":"我明天去广州参观一家工厂。","ro":"Wǒ míngtiān qù Guǎngzhōu cānguān yì jiā gōngchǎng."},{"fr":"En train à grande vitesse, il faut moins d'une demi-heure.","tgt":"坐高铁不到半个小时。","ro":"Zuò gāotiě bú dào bàn ge xiǎoshí."},{"fr":"L'entreprise rembourse le billet et l'hôtel.","tgt":"公司报销车票和酒店。","ro":"Gōngsī bàoxiāo chēpiào hé jiǔdiàn."},{"fr":"N'oublie pas de garder toutes les factures.","tgt":"别忘了保留好所有的发票。","ro":"Bié wàng le bǎoliú hǎo suǒyǒu de fāpiào."},{"fr":"Le directeur de l'usine viendra nous chercher à la gare.","tgt":"工厂的厂长会来车站接我们。","ro":"Gōngchǎng de chǎngzhǎng huì lái chēzhàn jiē wǒmen."},{"fr":"Ils nous ont fait visiter toutes les chaînes de production.","tgt":"他们带我们参观了所有的生产线。","ro":"Tāmen dài wǒmen cānguān le suǒyǒu de shēngchǎnxiàn."},{"fr":"La qualité des produits nous a vraiment impressionnés.","tgt":"产品的质量让我们印象很深。","ro":"Chǎnpǐn de zhìliàng ràng wǒmen yìnxiàng hěn shēn."},{"fr":"Nous avons échangé nos cartes de visite à deux mains.","tgt":"我们用双手交换了名片。","ro":"Wǒmen yòng shuāngshǒu jiāohuàn le míngpiàn."},{"fr":"Le soir, j'ai rédigé un compte rendu pour mon chef.","tgt":"晚上我给老板写了一份报告。","ro":"Wǎnshang wǒ gěi lǎobǎn xiě le yí fèn bàogào."},{"fr":"Je rentre à Shenzhen demain soir par le dernier train.","tgt":"我明天晚上坐最后一班车回深圳。","ro":"Wǒ míngtiān wǎnshang zuò zuìhòu yì bān chē huí Shēnzhèn."}]},{"title":"Une panne à la maison","phrases":[{"fr":"Le chauffe-eau ne marche plus depuis ce matin.","tgt":"热水器从今天早上开始就坏了。","ro":"Rèshuǐqì cóng jīntiān zǎoshang kāishǐ jiù huài le."},{"fr":"J'ai appelé le gestionnaire de la résidence pour signaler la panne.","tgt":"我给物业打电话报修了。","ro":"Wǒ gěi wùyè dǎ diànhuà bàoxiū le."},{"fr":"Ils m'ont dit qu'un technicien passerait cet après-midi.","tgt":"他们说下午会派师傅过来。","ro":"Tāmen shuō xiàwǔ huì pài shīfu guòlai."},{"fr":"Le technicien a vérifié et a trouvé une pièce cassée.","tgt":"师傅检查了一下，发现有个零件坏了。","ro":"Shīfu jiǎnchá le yíxià, fāxiàn yǒu ge língjiàn huài le."},{"fr":"Il ne peut pas réparer aujourd'hui, il doit d'abord commander la pièce.","tgt":"今天修不好，得先订零件。","ro":"Jīntiān xiū bu hǎo, děi xiān dìng língjiàn."},{"fr":"En attendant, je vais prendre ma douche chez le voisin.","tgt":"这几天我先去邻居家洗澡。","ro":"Zhè jǐ tiān wǒ xiān qù línjū jiā xǐzǎo."},{"fr":"Combien coûtera la réparation au total ?","tgt":"修好一共要多少钱？","ro":"Xiū hǎo yígòng yào duōshao qián?"},{"fr":"La main-d'œuvre coûte deux cents yuans, la pièce est en plus.","tgt":"人工费两百块，零件另算。","ro":"Réngōngfèi liǎngbǎi kuài, língjiàn lìng suàn."},{"fr":"Est-ce que ce genre de problème est couvert par la garantie ?","tgt":"这种问题在保修范围内吗？","ro":"Zhè zhǒng wèntí zài bǎoxiū fànwéi nèi ma?"},{"fr":"Deux jours plus tard, j'avais enfin de l'eau chaude.","tgt":"两天以后，终于有热水了。","ro":"Liǎng tiān yǐhòu, zhōngyú yǒu rèshuǐ le."}]},{"title":"Trouver l'équilibre entre travail et vie privée","phrases":[{"fr":"Dans certaines entreprises, on fait souvent des heures supplémentaires.","tgt":"有些公司经常加班。","ro":"Yǒuxiē gōngsī jīngcháng jiābān."},{"fr":"Désormais, je ne réponds plus aux messages de travail après dix heures du soir.","tgt":"现在晚上十点以后的工作消息我都不回了。","ro":"Xiànzài wǎnshang shí diǎn yǐhòu de gōngzuò xiāoxi wǒ dōu bù huí le."},{"fr":"Le week-end, je vais faire de la randonnée sur le mont Wutong.","tgt":"周末我会去梧桐山爬山。","ro":"Zhōumò wǒ huì qù Wútóng Shān pá shān."},{"fr":"Le sport m'aide à évacuer le stress de la semaine.","tgt":"运动能帮我释放一周的压力。","ro":"Yùndòng néng bāng wǒ shìfàng yì zhōu de yālì."},{"fr":"Ma femme dit que je n'ai que le travail en tête.","tgt":"我太太说我脑子里全是工作。","ro":"Wǒ tàitai shuō wǒ nǎozi lǐ quán shì gōngzuò."},{"fr":"Nous essayons de dîner ensemble au moins trois soirs par semaine.","tgt":"我们尽量每周至少一起吃三次晚饭。","ro":"Wǒmen jǐnliàng měi zhōu zhìshǎo yìqǐ chī sān cì wǎnfàn."},{"fr":"Prendre des vacances n'est pas un luxe, c'est une nécessité.","tgt":"休假不是奢侈，而是必需。","ro":"Xiūjià bú shì shēchǐ, ér shì bìxū."},{"fr":"Le soir, même mon téléphone a besoin de se reposer.","tgt":"晚上连我的手机都需要休息。","ro":"Wǎnshang lián wǒ de shǒujī dōu xūyào xiūxi."},{"fr":"Mon entreprise propose maintenant des horaires flexibles.","tgt":"我们公司现在可以弹性上班了。","ro":"Wǒmen gōngsī xiànzài kěyǐ tánxìng shàngbān le."},{"fr":"Depuis que je dors mieux, je suis plus efficace au travail.","tgt":"自从睡眠变好了，我的工作效率也提高了。","ro":"Zìcóng shuìmián biàn hǎo le, wǒ de gōngzuò xiàolǜ yě tígāo le."}]},{"title":"Fin du module : un bilan","phrases":[{"fr":"Dans ce module, j'ai appris à parler de mon travail en chinois.","tgt":"在这个单元里，我学会了用中文谈工作。","ro":"Zài zhège dānyuán lǐ, wǒ xuéhuì le yòng Zhōngwén tán gōngzuò."},{"fr":"Maintenant, je sais construire des phrases au passif.","tgt":"现在我会用被字句了。","ro":"Xiànzài wǒ huì yòng bèi zì jù le."},{"fr":"Les formules formelles du bureau m'impressionnent beaucoup moins.","tgt":"办公室里的正式用语，我现在不那么怕了。","ro":"Bàngōngshì lǐ de zhèngshì yòngyǔ, wǒ xiànzài bú nàme pà le."},{"fr":"Quand je négocie un prix, je ne suis plus nerveux.","tgt":"现在谈价格的时候，我不会紧张了。","ro":"Xiànzài tán jiàgé de shíhou, wǒ bú huì jǐnzhāng le."},{"fr":"Même les formalités administratives me font moins peur.","tgt":"连办手续都没那么可怕了。","ro":"Lián bàn shǒuxù dōu méi nàme kěpà le."},{"fr":"Mes collègues trouvent que mon chinois a beaucoup progressé.","tgt":"同事们说我的中文进步很大。","ro":"Tóngshìmen shuō wǒ de Zhōngwén jìnbù hěn dà."},{"fr":"Je dois encore travailler mes tons.","tgt":"我的声调还需要再练练。","ro":"Wǒ de shēngdiào hái xūyào zài liànlian."},{"fr":"Tant que je m'entraîne un peu chaque jour, je progresse.","tgt":"只要每天练一点，我就会有进步。","ro":"Zhǐyào měi tiān liàn yìdiǎn, wǒ jiù huì yǒu jìnbù."},{"fr":"Comme dit le proverbe chinois, c'est en forgeant qu'on devient forgeron.","tgt":"俗话说，熟能生巧。","ro":"Súhuà shuō, shú néng shēng qiǎo."},{"fr":"Je suis prêt à passer au module suivant.","tgt":"我准备好进入下一个单元了。","ro":"Wǒ zhǔnbèi hǎo jìnrù xià yí ge dānyuán le."}]}]},{"id":2,"name":"En voyage","desc":"Des aventures de voyage plus poussées et plus authentiques.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Arrivée à Harbin en plein hiver","phrases":[{"fr":"À Harbin, il fait souvent moins trente degrés en hiver.","tgt":"哈尔滨冬天经常零下三十度。","ro":"Hā'ěrbīn dōngtiān jīngcháng língxià sānshí dù."},{"fr":"Dès que je suis descendu de l'avion, j'ai tremblé de froid.","tgt":"一下飞机，我就冷得直发抖。","ro":"Yí xià fēijī, wǒ jiù lěng de zhí fādǒu."},{"fr":"Il faut absolument porter un bonnet et des gants épais.","tgt":"一定要戴帽子和厚手套。","ro":"Yídìng yào dài màozi hé hòu shǒutào."},{"fr":"Le chauffeur de taxi nous a conseillé de ne pas rester dehors trop longtemps.","tgt":"出租车司机劝我们别在外面待太久。","ro":"Chūzūchē sījī quàn wǒmen bié zài wàimiàn dāi tài jiǔ."},{"fr":"Les rues sont couvertes d'une épaisse couche de neige.","tgt":"街上积了厚厚的一层雪。","ro":"Jiē shang jīle hòuhòu de yì céng xuě."},{"fr":"La rue Centrale est bordée de vieux bâtiments de chaque côté.","tgt":"中央大街两边都是老建筑。","ro":"Zhōngyāng Dàjiē liǎngbiān dōu shì lǎo jiànzhù."},{"fr":"Les gens d'ici mangent des glaces dehors même en hiver.","tgt":"这里的人冬天也在外面吃冰棍。","ro":"Zhèlǐ de rén dōngtiān yě zài wàimiàn chī bīnggùn."},{"fr":"Heureusement, notre hôtel est bien chauffé.","tgt":"还好，我们的酒店暖气很足。","ro":"Hái hǎo, wǒmen de jiǔdiàn nuǎnqì hěn zú."},{"fr":"Avec ce froid, la batterie de mon téléphone semble se vider très vite.","tgt":"天太冷，手机的电好像掉得特别快。","ro":"Tiān tài lěng, shǒujī de diàn hǎoxiàng diào de tèbié kuài."},{"fr":"Ce soir, on va manger une fondue chinoise pour se réchauffer.","tgt":"今晚我们去吃火锅暖暖身子。","ro":"Jīnwǎn wǒmen qù chī huǒguō nuǎnnuan shēnzi."}]},{"title":"Le festival de glace de Harbin","phrases":[{"fr":"Les sculptures qu'on voit ici sont toutes faites de vraie glace.","tgt":"这里看到的雕塑都是用真冰做的。","ro":"Zhèlǐ kàndào de diāosù dōu shì yòng zhēn bīng zuò de."},{"fr":"Les blocs de glace qu'ils utilisent viennent du fleuve Songhua.","tgt":"他们用的冰块是从松花江里取来的。","ro":"Tāmen yòng de bīngkuài shì cóng Sōnghuā Jiāng li qǔlái de."},{"fr":"Le château qui brille au loin mesure près de cinquante mètres.","tgt":"远处那座发光的城堡差不多有五十米高。","ro":"Yuǎnchù nà zuò fāguāng de chéngbǎo chàbuduō yǒu wǔshí mǐ gāo."},{"fr":"Les artisans qui sculptent la glace travaillent dehors toute la nuit.","tgt":"雕冰的师傅们整夜都在外面干活。","ro":"Diāo bīng de shīfumen zhěng yè dōu zài wàimiàn gànhuó."},{"fr":"Le toboggan de glace que tout le monde veut essayer est par là.","tgt":"大家都想玩的冰滑梯在那边。","ro":"Dàjiā dōu xiǎng wán de bīng huátī zài nàbiān."},{"fr":"Les lumières qui changent sans cesse de couleur font du lieu un vrai conte de fées.","tgt":"不断变色的灯光让整个场面像童话一样。","ro":"Búduàn biànsè de dēngguāng ràng zhěnggè chǎngmiàn xiàng tónghuà yíyàng."},{"fr":"La personne qui nous a vendu les billets nous a conseillé de venir le soir.","tgt":"卖票给我们的那个人建议我们晚上来。","ro":"Mài piào gěi wǒmen de nàge rén jiànyì wǒmen wǎnshang lái."},{"fr":"Les photos que j'ai prises hier soir sont un peu floues.","tgt":"我昨晚拍的照片有点儿模糊。","ro":"Wǒ zuówǎn pāi de zhàopiàn yǒudiǎnr móhu."},{"fr":"C'est le plus grand festival de glace que j'aie jamais vu.","tgt":"这是我见过的最大的冰雪节。","ro":"Zhè shì wǒ jiànguo de zuì dà de bīngxuějié."},{"fr":"Les visiteurs qui viennent de loin restent en général trois ou quatre jours.","tgt":"从远方来的游客一般待三四天。","ro":"Cóng yuǎnfāng lái de yóukè yìbān dāi sān sì tiān."}],"tip":{"title":"Les relatives avec « de » : le nom à la fin","example":"Les photos que j'ai prises hier soir sont un peu floues. — 我昨晚拍<b>的</b>照片有点儿模糊。","body":"En français, on dit d'abord le nom, puis on le décrit : « les photos que j'ai prises ». En chinois, c'est l'inverse : toute la description vient d'abord, puis le petit mot « de », et le nom arrive tout à la fin. Mot à mot, « wǒ zuówǎn pāi de zhàopiàn » donne « moi, hier soir, photographier, de, photos », c'est-à-dire les photos que j'ai prises hier soir. Même logique pour « wǒ mǎi de piào », le billet que j'ai acheté, ou « mài piào de rén », la personne qui vend les billets. Pas besoin de « qui » ni de « que » : le « de », prononcé très léger et sans ton, fait tout le travail. Astuce pour parler : racontez d'abord la petite histoire, posez « de » comme une charnière, puis lâchez le nom comme la chute d'une blague.","exampleRo":"Wǒ zuówǎn pāi de zhàopiàn yǒudiǎnr móhu.","lit":"je · hier soir · photographier · [de] · photo · un peu · flou","say":{"de":"的","wǒ zuówǎn pāi de zhàopiàn":"我昨晚拍的照片","wǒ mǎi de piào":"我买的票","mài piào de rén":"卖票的人"}}},{"title":"Sur les prairies de Mongolie-Intérieure","phrases":[{"fr":"Les prairies s'étendent à perte de vue.","tgt":"草原一眼望不到边。","ro":"Cǎoyuán yì yǎn wàng bu dào biān."},{"fr":"On a roulé quatre heures depuis Hohhot pour arriver ici.","tgt":"我们从呼和浩特开了四个小时的车才到这儿。","ro":"Wǒmen cóng Hūhéhàotè kāile sì ge xiǎoshí de chē cái dào zhèr."},{"fr":"En été, l'herbe est verte et l'air est incroyablement pur.","tgt":"夏天草是绿的，空气特别清新。","ro":"Xiàtiān cǎo shì lǜ de, kōngqì tèbié qīngxīn."},{"fr":"Des troupeaux de moutons traversent tranquillement la route.","tgt":"一群群的羊慢悠悠地穿过公路。","ro":"Yì qúnqún de yáng mànyōuyōu de chuānguò gōnglù."},{"fr":"Notre hôte nous a appris à monter à cheval.","tgt":"主人教会了我们骑马。","ro":"Zhǔrén jiāohuìle wǒmen qí mǎ."},{"fr":"Le cheval que je montais était plutôt docile.","tgt":"我骑的那匹马挺温顺的。","ro":"Wǒ qí de nà pǐ mǎ tǐng wēnshùn de."},{"fr":"Le soir, on a bu du thé au lait salé autour du feu.","tgt":"晚上我们围着火喝咸奶茶。","ro":"Wǎnshang wǒmen wéizhe huǒ hē xián nǎichá."},{"fr":"Ici, la viande de mouton se mange avec les mains.","tgt":"这里的羊肉是用手抓着吃的。","ro":"Zhèlǐ de yángròu shì yòng shǒu zhuāzhe chī de."},{"fr":"La nuit, on voit la Voie lactée à l'œil nu.","tgt":"晚上用肉眼就能看到银河。","ro":"Wǎnshang yòng ròuyǎn jiù néng kàndào Yínhé."},{"fr":"Je ne pensais pas que le silence pouvait être aussi beau.","tgt":"没想到安静也可以这么美。","ro":"Méi xiǎngdào ānjìng yě kěyǐ zhème měi."}]},{"title":"Une nuit dans une yourte","phrases":[{"fr":"Pour vivre comme les éleveurs nomades, nous dormons dans une yourte.","tgt":"为了体验牧民的生活，我们住在蒙古包里。","ro":"Wèile tǐyàn mùmín de shēnghuó, wǒmen zhù zài ménggǔbāo li."},{"fr":"Pour garder la chaleur, il faut remettre du bois dans le poêle toute la nuit.","tgt":"为了保暖，晚上要不停地往炉子里加柴。","ro":"Wèile bǎonuǎn, wǎnshang yào bù tíng de wǎng lúzi li jiā chái."},{"fr":"Pour voir le lever du soleil, il faut se lever à quatre heures et demie.","tgt":"为了看日出，得四点半起床。","ro":"Wèile kàn rìchū, děi sì diǎn bàn qǐchuáng."},{"fr":"Pour nous accueillir, notre hôte a préparé un vrai festin.","tgt":"主人为了欢迎我们，准备了一大桌菜。","ro":"Zhǔrén wèile huānyíng wǒmen, zhǔnbèile yí dà zhuō cài."},{"fr":"Pour ne pas déranger les autres, on parle à voix basse.","tgt":"为了不打扰别人，我们说话很小声。","ro":"Wèile bù dǎrǎo biérén, wǒmen shuōhuà hěn xiǎoshēng."},{"fr":"La yourte est ronde, c'est pour mieux résister au vent.","tgt":"蒙古包是圆的，是为了更好地挡风。","ro":"Ménggǔbāo shì yuán de, shì wèile gèng hǎo de dǎng fēng."},{"fr":"Il n'y a pas de douche, mais on s'y habitue vite.","tgt":"这里没有淋浴，不过很快就习惯了。","ro":"Zhèlǐ méiyǒu línyù, búguò hěn kuài jiù xíguàn le."},{"fr":"Le toit a une ouverture pour laisser sortir la fumée.","tgt":"顶上开了个口，是为了让烟出去。","ro":"Dǐng shang kāile ge kǒu, shì wèile ràng yān chūqu."},{"fr":"Pour cette seule nuit, on a fait trois heures de route.","tgt":"为了这一个晚上，我们开了三个小时的车。","ro":"Wèile zhè yí ge wǎnshang, wǒmen kāile sān ge xiǎoshí de chē."},{"fr":"Cette nuit-là valait vraiment le déplacement.","tgt":"那个晚上真是不虚此行。","ro":"Nàge wǎnshang zhēn shì bù xū cǐ xíng."}],"tip":{"title":"« Wèile » : pour, afin de","example":"Pour voir le lever du soleil, il faut se lever à quatre heures et demie. — <b>为了</b>看日出，得四点半起床。","body":"Pour dire le but d'une action, on place « wèile » tout au début, avant l'action principale : d'abord le but, ensuite ce qu'on fait. « Wèile kàn rìchū, děi sì diǎn bàn qǐchuáng » se décompose en « pour voir lever-du-soleil, devoir quatre heures et demie se lever ». On peut aussi l'annoncer après coup avec « shì wèile », c'est pour : « shì wèile dǎng fēng », c'est pour arrêter le vent. Pour un but négatif, on ajoute simplement « bù » : « wèile bù dǎrǎo biérén », pour ne pas déranger les autres. Côté prononciation, « wèi » est ici au quatrième ton, une voix qui tombe franchement, suivie d'un « le » tout léger. Astuce : imaginez « wèile » comme un panneau indicateur que l'on plante avant de se mettre en route.","exampleRo":"Wèile kàn rìchū, děi sì diǎn bàn qǐchuáng.","lit":"pour · voir · lever du soleil · devoir · quatre heures · demie · se lever","say":{"Wèile":"为了","wèile":"为了","Wèile kàn rìchū, děi sì diǎn bàn qǐchuáng":"为了看日出，得四点半起床","shì wèile":"是为了","shì wèile dǎng fēng":"是为了挡风","bù":"不","wèile bù dǎrǎo biérén":"为了不打扰别人","wèi":"为"}}},{"title":"Le train de nuit vers Dunhuang","phrases":[{"fr":"On prend le train de nuit de Lanzhou à Dunhuang.","tgt":"我们从兰州坐夜车去敦煌。","ro":"Wǒmen cóng Lánzhōu zuò yèchē qù Dūnhuáng."},{"fr":"Le trajet dure près de quatorze heures.","tgt":"路上要差不多十四个小时。","ro":"Lù shang yào chàbuduō shísì ge xiǎoshí."},{"fr":"J'ai réservé une couchette du bas, c'est un peu plus pratique.","tgt":"我订了下铺，方便一点儿。","ro":"Wǒ dìngle xiàpù, fāngbiàn yìdiǎnr."},{"fr":"Par la fenêtre, il ne reste plus que du sable et des cailloux.","tgt":"窗外只剩下沙子和石头了。","ro":"Chuāng wài zhǐ shèngxia shāzi hé shítou le."},{"fr":"Une employée passe dans le couloir avec un chariot de fruits et de boissons.","tgt":"有个推车的服务员在过道里卖水果和饮料。","ro":"Yǒu ge tuī chē de fúwùyuán zài guòdào li mài shuǐguǒ hé yǐnliào."},{"fr":"Le monsieur de la couchette d'en face m'a offert des graines de tournesol.","tgt":"对面铺的大叔请我吃瓜子。","ro":"Duìmiàn pù de dàshū qǐng wǒ chī guāzǐ."},{"fr":"On a parlé de nos itinéraires jusque tard dans la soirée.","tgt":"我们聊旅行路线一直聊到很晚。","ro":"Wǒmen liáo lǚxíng lùxiàn yìzhí liáo dào hěn wǎn."},{"fr":"Les lumières du wagon s'éteignent dès dix heures.","tgt":"车厢里的灯十点就关了。","ro":"Chēxiāng li de dēng shí diǎn jiù guān le."},{"fr":"Je dors mal dans le train, mais j'adore cette ambiance.","tgt":"我在火车上睡不太好，可是很喜欢这种气氛。","ro":"Wǒ zài huǒchē shang shuì bu tài hǎo, kěshì hěn xǐhuan zhè zhǒng qìfēn."},{"fr":"À notre arrivée, un chauffeur nous attendait déjà à la gare.","tgt":"到站的时候，司机已经在车站等我们了。","ro":"Dào zhàn de shíhou, sījī yǐjīng zài chēzhàn děng wǒmen le."}]},{"title":"Dans le désert de Dunhuang","phrases":[{"fr":"Les dunes changent de couleur selon l'heure de la journée.","tgt":"沙丘的颜色会随着时间变化。","ro":"Shāqiū de yánsè huì suízhe shíjiān biànhuà."},{"fr":"On a fait une balade à dos de chameau au coucher du soleil.","tgt":"我们在日落时骑骆驼走了一圈。","ro":"Wǒmen zài rìluò shí qí luòtuo zǒule yì quān."},{"fr":"Les chameaux avancent lentement, les uns derrière les autres.","tgt":"骆驼排成一队，慢慢地往前走。","ro":"Luòtuo páichéng yí duì, mànmàn de wǎng qián zǒu."},{"fr":"Le sable est brûlant à midi, mais froid la nuit.","tgt":"中午沙子烫得很，晚上却很凉。","ro":"Zhōngwǔ shāzi tàng de hěn, wǎnshang què hěn liáng."},{"fr":"Il faut emporter assez d'eau et de la crème solaire.","tgt":"要带足够的水和防晒霜。","ro":"Yào dài zúgòu de shuǐ hé fángshàishuāng."},{"fr":"Le guide nous a demandé de ne pas nous disperser.","tgt":"导游让我们别走散了。","ro":"Dǎoyóu ràng wǒmen bié zǒusàn le."},{"fr":"Dévaler une dune sur une luge, c'est vraiment amusant.","tgt":"从沙丘上滑沙下来特别好玩。","ro":"Cóng shāqiū shang huá shā xiàlai tèbié hǎowán."},{"fr":"Autrefois, les caravanes de la route de la soie passaient justement par ici.","tgt":"以前丝绸之路上的商队就是从这里经过的。","ro":"Yǐqián Sīchóu zhī Lù shang de shāngduì jiù shì cóng zhèlǐ jīngguò de."},{"fr":"Au milieu du désert, il y a un petit lac qui semble irréel.","tgt":"沙漠中间有个小湖，看起来像假的一样。","ro":"Shāmò zhōngjiān yǒu ge xiǎo hú, kàn qilai xiàng jiǎ de yíyàng."},{"fr":"Ce silence-là, je m'en souviendrai longtemps.","tgt":"那种安静我会记很久。","ro":"Nà zhǒng ānjìng wǒ huì jì hěn jiǔ."}]},{"title":"Une visite guidée à Dunhuang","phrases":[{"fr":"Le guide parle vite, mais je comprends presque tout.","tgt":"导游说得很快，不过我差不多都听得懂。","ro":"Dǎoyóu shuō de hěn kuài, búguò wǒ chàbuduō dōu tīng de dǒng."},{"fr":"Il a un accent, il y a des mots que je ne comprends pas.","tgt":"他有口音，有些词我听不懂。","ro":"Tā yǒu kǒuyīn, yǒuxiē cí wǒ tīng bu dǒng."},{"fr":"Ces fresques sont si anciennes qu'on ne distingue plus bien les couleurs.","tgt":"这些壁画太老了，颜色都看不清楚了。","ro":"Zhèxiē bìhuà tài lǎo le, yánsè dōu kàn bu qīngchu le."},{"fr":"Il fait trop sombre à l'intérieur, je n'arrive pas à voir les détails.","tgt":"里面太暗了，细节我看不见。","ro":"Lǐmiàn tài àn le, xìjié wǒ kàn bu jiàn."},{"fr":"En haute saison, impossible d'acheter des billets pour le matin.","tgt":"旺季的时候，上午的票根本买不到。","ro":"Wàngjì de shíhou, shàngwǔ de piào gēnběn mǎi bu dào."},{"fr":"Heureusement, mon ami a réussi à en acheter deux en ligne.","tgt":"还好我朋友在网上买到了两张。","ro":"Hái hǎo wǒ péngyou zài wǎng shang mǎidàole liǎng zhāng."},{"fr":"Le groupe marche trop vite, je n'arrive pas à suivre.","tgt":"大家走得太快，我跟不上。","ro":"Dàjiā zǒu de tài kuài, wǒ gēn bu shàng."},{"fr":"Pouvez-vous parler un peu plus fort ? Au fond, on n'entend pas bien.","tgt":"您能大声一点儿吗？后面听不清楚。","ro":"Nín néng dàshēng yìdiǎnr ma? Hòumiàn tīng bu qīngchu."},{"fr":"Il y a tellement de choses à voir qu'on ne peut pas tout faire en une journée.","tgt":"要看的东西太多了，一天看不完。","ro":"Yào kàn de dōngxi tài duō le, yì tiān kàn bu wán."},{"fr":"Est-ce qu'on peut trouver un guide qui parle français, ici ?","tgt":"在这儿找得到会说法语的导游吗？","ro":"Zài zhèr zhǎo de dào huì shuō Fǎyǔ de dǎoyóu ma?"}],"tip":{"title":"Le complément potentiel : « kàn de dǒng, mǎi bu dào »","example":"En haute saison, impossible d'acheter des billets pour le matin. — 旺季的时候，上午的票根本<b>买不到</b>。","body":"Pour dire qu'on peut ou qu'on ne peut pas arriver à un résultat, le chinois glisse un petit mot entre le verbe et son résultat. Avec « de », c'est possible : « tīng de dǒng », écouter et arriver à comprendre, donc je comprends ce que j'entends. Avec « bu », c'est impossible : « mǎi bu dào », mot à mot acheter, pas, arriver, autrement dit on n'arrive pas à en acheter. Là où le français dit « je n'arrive pas à », le chinois dit tout en trois syllabes : « kàn bu qīngchu », je ne vois pas bien, « kàn bu wán », impossible de tout voir, « gēn bu shàng », je n'arrive pas à suivre. À l'oral, « de » et « bu » sont très légers et presque sans ton, et le groupe se dit d'un seul souffle. Astuce : tendez l'oreille vers ce petit « bu » au milieu, c'est lui qui transforme une réussite en échec.","exampleRo":"Wàngjì de shíhou, shàngwǔ de piào gēnběn mǎi bu dào.","lit":"haute saison · [de] · moment · matin · [de] · billet · pas du tout · acheter · [pas] · arriver","say":{"de":"得","tīng de dǒng":"听得懂","mǎi bu dào":"买不到","kàn bu qīngchu":"看不清楚","kàn bu wán":"看不完","gēn bu shàng":"跟不上","kàn de dǒng, mǎi bu dào":"看得懂、买不到"}}},{"title":"Le marché de nuit de Dunhuang","phrases":[{"fr":"Le marché de nuit de Dunhuang ne s'anime qu'à la tombée de la nuit.","tgt":"敦煌的夜市天黑了才开始热闹。","ro":"Dūnhuáng de yèshì tiān hēile cái kāishǐ rènao."},{"fr":"Il y a des abricots secs et des noix partout.","tgt":"到处都是杏干和核桃。","ro":"Dàochù dōu shì xìnggān hé hétao."},{"fr":"Ce marchand nous a fait goûter cinq sortes de raisins secs.","tgt":"这个老板让我们尝了五种葡萄干。","ro":"Zhège lǎobǎn ràng wǒmen chángle wǔ zhǒng pútaogān."},{"fr":"Ici, les nouilles au bœuf sont étirées à la main sous nos yeux.","tgt":"这里的牛肉面是当着我们的面现拉的。","ro":"Zhèlǐ de niúròumiàn shì dāngzhe wǒmen de miàn xiàn lā de."},{"fr":"Excusez-moi, combien coûte ce foulard en soie ?","tgt":"请问，这条丝巾多少钱？","ro":"Qǐngwèn, zhè tiáo sījīn duōshao qián?"},{"fr":"Cent vingt kuai, c'est trop cher pour moi.","tgt":"一百二十块，对我来说太贵了。","ro":"Yìbǎi èrshí kuài, duì wǒ lái shuō tài guì le."},{"fr":"Pour quatre-vingts kuai, je le prends.","tgt":"八十块的话，我就买了。","ro":"Bāshí kuài dehuà, wǒ jiù mǎi le."},{"fr":"Le vendeur a fini par accepter en souriant.","tgt":"老板最后笑着答应了。","ro":"Lǎobǎn zuìhòu xiàozhe dāying le."},{"fr":"On a mangé des brochettes d'agneau très pimentées.","tgt":"我们吃了很辣的羊肉串。","ro":"Wǒmen chīle hěn là de yángròuchuàn."},{"fr":"L'ambiance ici est à la fois animée et détendue.","tgt":"这里的气氛又热闹又轻松。","ro":"Zhèlǐ de qìfēn yòu rènao yòu qīngsōng."}]},{"title":"Zhangjiajie, les montagnes dans les nuages","phrases":[{"fr":"Les pics rocheux de Zhangjiajie semblent flotter dans les nuages.","tgt":"张家界的石峰好像漂在云里一样。","ro":"Zhāngjiājiè de shífēng hǎoxiàng piāo zài yún li yíyàng."},{"fr":"On se croirait dans un décor de film.","tgt":"这儿的风景像电影里的一样。","ro":"Zhèr de fēngjǐng xiàng diànyǐng li de yíyàng."},{"fr":"Ce matin, un épais brouillard cachait complètement le sommet.","tgt":"今天早上大雾把山顶全挡住了。","ro":"Jīntiān zǎoshang dàwù bǎ shāndǐng quán dǎngzhù le."},{"fr":"Vers midi, le ciel s'est enfin dégagé.","tgt":"快中午的时候，天终于放晴了。","ro":"Kuài zhōngwǔ de shíhou, tiān zhōngyú fàngqíng le."},{"fr":"Le parc est immense, il faut au moins trois jours pour en faire le tour.","tgt":"景区特别大，至少要三天才能逛完。","ro":"Jǐngqū tèbié dà, zhìshǎo yào sān tiān cái néng guàngwán."},{"fr":"Des singes sauvages s'approchent des touristes pour leur voler à manger.","tgt":"野猴子会跑到游客身边抢吃的。","ro":"Yě hóuzi huì pǎo dào yóukè shēnbiān qiǎng chī de."},{"fr":"Surtout, ne donnez rien à manger aux singes.","tgt":"千万别喂猴子。","ro":"Qiānwàn bié wèi hóuzi."},{"fr":"Les marches sont raides, allez-y doucement.","tgt":"台阶很陡，慢慢走。","ro":"Táijiē hěn dǒu, mànmàn zǒu."},{"fr":"Un ascenseur panoramique monte le long de la falaise.","tgt":"有一部观光电梯沿着悬崖往上走。","ro":"Yǒu yí bù guānguāng diàntī yánzhe xuányá wǎng shàng zǒu."},{"fr":"Une fois là-haut, la vue est si belle qu'on en reste sans voix.","tgt":"到了上面，景色美得让人说不出话来。","ro":"Dàole shàngmiàn, jǐngsè měi de ràng rén shuō bu chū huà lái."}]},{"title":"Le pont de verre et le téléphérique","phrases":[{"fr":"Le pont de verre se trouve à trois cents mètres au-dessus du fond de la vallée.","tgt":"玻璃桥离谷底有三百米高。","ro":"Bōli qiáo lí gǔdǐ yǒu sānbǎi mǐ gāo."},{"fr":"En marchant dessus, j'avais les jambes en coton.","tgt":"走在上面，我腿都软了。","ro":"Zǒu zài shàngmiàn, wǒ tuǐ dōu ruǎn le."},{"fr":"Mon ami n'osait pas regarder en bas.","tgt":"我朋友不敢往下看。","ro":"Wǒ péngyou bù gǎn wǎng xià kàn."},{"fr":"Il faut enfiler des sur-chaussures pour protéger le verre.","tgt":"要穿鞋套，保护玻璃。","ro":"Yào chuān xiétào, bǎohù bōli."},{"fr":"C'est le plus long téléphérique que j'aie jamais pris.","tgt":"这是我坐过的最长的索道。","ro":"Zhè shì wǒ zuòguo de zuì cháng de suǒdào."},{"fr":"On a fait la queue pendant presque deux heures.","tgt":"排队排了差不多两个小时。","ro":"Páiduì páile chàbuduō liǎng ge xiǎoshí."},{"fr":"La cabine s'élève doucement au-dessus de la forêt.","tgt":"缆车慢慢地从树林上方往上升。","ro":"Lǎnchē mànmàn de cóng shùlín shàngfāng wǎng shàng shēng."},{"fr":"À mi-chemin, elle s'est arrêtée quelques minutes.","tgt":"走到一半，缆车停了几分钟。","ro":"Zǒu dào yíbàn, lǎnchē tíngle jǐ fēnzhōng."},{"fr":"Pour être honnête, j'ai eu un peu peur.","tgt":"说实话，我有点儿害怕。","ro":"Shuō shíhuà, wǒ yǒudiǎnr hàipà."},{"fr":"Quand on a le vertige, venir ici, c'est vraiment pas de chance.","tgt":"恐高的人来这儿真是倒霉。","ro":"Kǒnggāo de rén lái zhèr zhēn shì dǎoméi."}]},{"title":"Arrivée sur l'île de Hainan","phrases":[{"fr":"Trois heures d'avion, et on passe de l'hiver à l'été.","tgt":"坐三个小时飞机，就从冬天到了夏天。","ro":"Zuò sān ge xiǎoshí fēijī, jiù cóng dōngtiān dàole xiàtiān."},{"fr":"En décembre, il fait encore vingt-huit degrés à Haikou.","tgt":"十二月的海口还有二十八度。","ro":"Shí'èr yuè de Hǎikǒu hái yǒu èrshíbā dù."},{"fr":"Je peux enfin enlever mon gros manteau.","tgt":"我终于能把厚外套脱了。","ro":"Wǒ zhōngyú néng bǎ hòu wàitào tuō le."},{"fr":"Sur l'île, les cocotiers bordent toutes les routes.","tgt":"岛上的路边到处都是椰子树。","ro":"Dǎo shang de lù biān dàochù dōu shì yēzishù."},{"fr":"On boit l'eau de coco directement avec une paille plantée dans la noix.","tgt":"椰子水直接插根吸管喝。","ro":"Yēzishuǐ zhíjiē chā gēn xīguǎn hē."},{"fr":"Beaucoup de retraités du Nord viennent passer l'hiver ici.","tgt":"很多北方的老人来这儿过冬。","ro":"Hěn duō běifāng de lǎorén lái zhèr guòdōng."},{"fr":"On les surnomme les « oiseaux migrateurs ».","tgt":"大家叫他们“候鸟”。","ro":"Dàjiā jiào tāmen \"hòuniǎo\"."},{"fr":"Nous avons loué un scooter électrique pour nous déplacer.","tgt":"我们租了一辆电动车代步。","ro":"Wǒmen zūle yí liàng diàndòngchē dàibù."},{"fr":"Ici, le rythme de vie est beaucoup plus lent.","tgt":"这里的生活节奏慢多了。","ro":"Zhèlǐ de shēnghuó jiézòu màn duō le."},{"fr":"Le soir, toute la ville sort se promener au bord de la mer.","tgt":"晚上全城的人都到海边散步。","ro":"Wǎnshang quán chéng de rén dōu dào hǎibiān sànbù."}]},{"title":"Prendre le ferry","phrases":[{"fr":"Le ferry pour l'autre rive devrait partir à neuf heures.","tgt":"去对岸的轮渡应该九点出发。","ro":"Qù duì'àn de lúndù yīnggāi jiǔ diǎn chūfā."},{"fr":"Normalement, la traversée ne devrait pas dépasser une heure.","tgt":"过海应该用不了一个小时。","ro":"Guò hǎi yīnggāi yòng bu liǎo yí ge xiǎoshí."},{"fr":"On devrait arriver au port un peu en avance.","tgt":"我们应该早一点儿到码头。","ro":"Wǒmen yīnggāi zǎo yìdiǎnr dào mǎtou."},{"fr":"Pour acheter le billet, il faut sans doute montrer son passeport, non ?","tgt":"买票应该带护照吧？","ro":"Mǎi piào yīnggāi dài hùzhào ba?"},{"fr":"Normalement, les voitures embarquent en premier.","tgt":"汽车应该先上船。","ro":"Qìchē yīnggāi xiān shàng chuán."},{"fr":"Il est déjà neuf heures et demie, le bateau aurait dû partir depuis longtemps.","tgt":"已经九点半了，船早就应该开了。","ro":"Yǐjīng jiǔ diǎn bàn le, chuán zǎo jiù yīnggāi kāi le."},{"fr":"Le bateau tangue un peu, mais ça va.","tgt":"船有点儿晃，不过还行。","ro":"Chuán yǒudiǎnr huàng, búguò hái xíng."},{"fr":"Si tu as le mal de mer, tu devrais rester sur le pont.","tgt":"你要是晕船，应该待在甲板上。","ro":"Nǐ yàoshi yùnchuán, yīnggāi dāi zài jiǎbǎn shang."},{"fr":"D'après la carte, on devrait bientôt apercevoir la côte.","tgt":"看地图，应该快看到岸了。","ro":"Kàn dìtú, yīnggāi kuài kàndào àn le."},{"fr":"La prochaine fois, on devrait acheter les billets la veille.","tgt":"下次我们应该提前一天买票。","ro":"Xià cì wǒmen yīnggāi tíqián yì tiān mǎi piào."}],"tip":{"title":"« Yīnggāi » : normalement, ça devrait","example":"Le ferry pour l'autre rive devrait partir à neuf heures. — 去对岸的轮渡<b>应该</b>九点出发。","body":"« Yīnggāi » a deux visages, exactement comme « devrait » en français. Il exprime d'abord ce qui est logique ou prévu : « lúndù yīnggāi jiǔ diǎn chūfā », mot à mot ferry, normalement, neuf heures, partir. Il sert aussi à donner un conseil : « nǐ yīnggāi xiūxi », tu devrais te reposer. Il se place toujours après le sujet et juste avant le verbe, et il ne se conjugue jamais. Pour un reproche, on l'entoure de « zǎo jiù » et « le » : « chuán zǎo jiù yīnggāi kāi le », le bateau aurait dû partir depuis longtemps. Les deux syllabes « yīng » et « gāi » sont au premier ton, hautes et plates, comme une note tenue au violon. Astuce : quand vous hésitez, lancez le sujet puis « yīnggāi », et le reste de la phrase suivra.","exampleRo":"Qù duì'àn de lúndù yīnggāi jiǔ diǎn chūfā.","lit":"aller · rive d'en face · [de] · ferry · normalement · neuf heures · partir","say":{"Yīnggāi":"应该","lúndù yīnggāi jiǔ diǎn chūfā":"轮渡应该九点出发","nǐ yīnggāi xiūxi":"你应该休息","zǎo jiù":"早就","le":"了","chuán zǎo jiù yīnggāi kāi le":"船早就应该开了","yīng":"应","gāi":"该","yīnggāi":"应该"}}},{"title":"Un typhon bloque l'île","phrases":[{"fr":"Un typhon approche, tous les ferries sont suspendus.","tgt":"台风要来了，所有的轮渡都停了。","ro":"Táifēng yào lái le, suǒyǒu de lúndù dōu tíng le."},{"fr":"Le vent s'est levé d'un coup et la mer est devenue grise.","tgt":"突然起风了，海变成了灰色。","ro":"Tūrán qǐ fēng le, hǎi biànchéngle huīsè."},{"fr":"L'hôtel nous a prévenus de ne pas sortir.","tgt":"酒店通知我们不要出门。","ro":"Jiǔdiàn tōngzhī wǒmen búyào chūmén."},{"fr":"Toutes les vitres ont été renforcées avec du ruban adhésif.","tgt":"窗户都被贴上了胶带。","ro":"Chuānghu dōu bèi tiēshangle jiāodài."},{"fr":"Notre vol de retour a été repoussé de deux jours.","tgt":"我们回程的航班被推迟了两天。","ro":"Wǒmen huíchéng de hángbān bèi tuīchíle liǎng tiān."},{"fr":"On a fait des réserves d'eau et de nouilles instantanées.","tgt":"我们囤了些水和方便面。","ro":"Wǒmen túnle xiē shuǐ hé fāngbiànmiàn."},{"fr":"Toute la nuit, la pluie a frappé contre les fenêtres.","tgt":"雨整夜都在拍打窗户。","ro":"Yǔ zhěng yè dōu zài pāidǎ chuānghu."},{"fr":"Le lendemain matin, plusieurs arbres étaient tombés dans la rue.","tgt":"第二天早上，街上倒了好几棵树。","ro":"Dì èr tiān zǎoshang, jiē shang dǎole hǎo jǐ kē shù."},{"fr":"Personne n'a été blessé, c'est le plus important.","tgt":"没有人受伤，这是最重要的。","ro":"Méiyǒu rén shòushāng, zhè shì zuì zhòngyào de."},{"fr":"Ce contretemps nous a offert deux jours de repos en plus.","tgt":"这次意外让我们多休息了两天。","ro":"Zhè cì yìwài ràng wǒmen duō xiūxile liǎng tiān."}]},{"title":"Plongée et plage à Sanya","phrases":[{"fr":"La mer à Sanya est d'un bleu incroyable.","tgt":"三亚的海水蓝得不可思议。","ro":"Sānyà de hǎishuǐ lán de bù kě sīyì."},{"fr":"Ce matin, j'ai fait mon tout premier baptême de plongée.","tgt":"今天上午我第一次体验了潜水。","ro":"Jīntiān shàngwǔ wǒ dì yī cì tǐyànle qiánshuǐ."},{"fr":"Le moniteur m'a appris les signes de base sous l'eau.","tgt":"教练教了我水下的基本手势。","ro":"Jiàoliàn jiāole wǒ shuǐ xià de jīběn shǒushì."},{"fr":"Au début, j'avais du mal à respirer calmement.","tgt":"一开始我很难平静地呼吸。","ro":"Yì kāishǐ wǒ hěn nán píngjìng de hūxī."},{"fr":"Autour du corail, j'ai vu des poissons de toutes les couleurs.","tgt":"我看到珊瑚周围有各种颜色的鱼。","ro":"Wǒ kàndào shānhú zhōuwéi yǒu gè zhǒng yánsè de yú."},{"fr":"Ne touchez pas le corail, il est très fragile.","tgt":"别碰珊瑚，它很脆弱。","ro":"Bié pèng shānhú, tā hěn cuìruò."},{"fr":"Le soleil tape fort, mets donc un chapeau.","tgt":"太阳很毒，戴顶帽子吧。","ro":"Tàiyáng hěn dú, dài dǐng màozi ba."},{"fr":"On a loué deux transats et un parasol.","tgt":"我们租了两把躺椅和一把遮阳伞。","ro":"Wǒmen zūle liǎng bǎ tǎngyǐ hé yì bǎ zhēyángsǎn."},{"fr":"Les fruits de mer, on les choisit vivants au marché.","tgt":"海鲜要先在市场上挑活的。","ro":"Hǎixiān yào xiān zài shìchǎng shang tiāo huó de."},{"fr":"Ensuite, un petit restaurant d'à côté nous les cuisine.","tgt":"然后让旁边的小饭馆帮忙加工。","ro":"Ránhòu ràng pángbiān de xiǎo fànguǎn bāngmáng jiāgōng."}]},{"title":"Voyager de façon responsable","phrases":[{"fr":"Nous essayons de voyager de manière plus responsable.","tgt":"我们尽量用更负责任的方式旅行。","ro":"Wǒmen jǐnliàng yòng gèng fù zérèn de fāngshì lǚxíng."},{"fr":"J'ai toujours une gourde sur moi pour utiliser moins de bouteilles en plastique.","tgt":"我总是带着水壶，少用塑料瓶。","ro":"Wǒ zǒngshì dàizhe shuǐhú, shǎo yòng sùliàopíng."},{"fr":"Quand on peut prendre le train, on ne prend pas l'avion.","tgt":"能坐火车，就不坐飞机。","ro":"Néng zuò huǒchē, jiù bú zuò fēijī."},{"fr":"Nous ne laissons aucun déchet derrière nous.","tgt":"我们不留下任何垃圾。","ro":"Wǒmen bù liúxià rènhé lājī."},{"fr":"Loger chez l'habitant, c'est mieux que dans un grand hôtel.","tgt":"住在当地人家里比住大酒店更好。","ro":"Zhù zài dāngdì rén jiā li bǐ zhù dà jiǔdiàn gèng hǎo."},{"fr":"Acheter aux artisans locaux aide directement leurs familles.","tgt":"买当地手艺人的东西能直接帮到他们的家庭。","ro":"Mǎi dāngdì shǒuyìrén de dōngxi néng zhíjiē bāngdào tāmen de jiātíng."},{"fr":"On ne photographie jamais les gens sans leur demander d'abord.","tgt":"我们不会随便给别人拍照，要先问一下。","ro":"Wǒmen bú huì suíbiàn gěi biérén pāizhào, yào xiān wèn yíxià."},{"fr":"Il ne faut pas quitter les sentiers balisés.","tgt":"不要离开规定的路线。","ro":"Búyào líkāi guīdìng de lùxiàn."},{"fr":"Partir moins souvent mais rester plus longtemps, c'est aussi une solution.","tgt":"少出门，但每次多待一段时间，也是个办法。","ro":"Shǎo chūmén, dàn měi cì duō dāi yí duàn shíjiān, yě shì ge bànfǎ."},{"fr":"Pour protéger ces lieux, chaque petit geste compte.","tgt":"保护这些地方，每个小举动都很重要。","ro":"Bǎohù zhèxiē dìfang, měi ge xiǎo jǔdòng dōu hěn zhòngyào."}]},{"title":"Un guide local passionnant","phrases":[{"fr":"Notre guide est né dans un petit village de montagne.","tgt":"我们的导游是在山里的一个小村子出生的。","ro":"Wǒmen de dǎoyóu shì zài shān li de yí ge xiǎo cūnzi chūshēng de."},{"fr":"Il connaît chaque sentier et chaque plante de la région.","tgt":"这一带的每条小路、每种植物他都认识。","ro":"Zhè yídài de měi tiáo xiǎolù, měi zhǒng zhíwù tā dōu rènshi."},{"fr":"Il raconte les légendes locales avec beaucoup d'humour.","tgt":"他讲当地的传说讲得特别幽默。","ro":"Tā jiǎng dāngdì de chuánshuō jiǎng de tèbié yōumò."},{"fr":"Grâce à lui, on a découvert des coins sans aucun touriste.","tgt":"多亏了他，我们找到了一些没有游客的地方。","ro":"Duōkuīle tā, wǒmen zhǎodàole yìxiē méiyǒu yóukè de dìfang."},{"fr":"Il nous a emmenés déjeuner chez sa tante.","tgt":"他带我们去他姑姑家吃午饭。","ro":"Tā dài wǒmen qù tā gūgu jiā chī wǔfàn."},{"fr":"Il connaît aussi quelques phrases de français.","tgt":"他还会说几句法语。","ro":"Tā hái huì shuō jǐ jù Fǎyǔ."},{"fr":"Il nous a expliqué comment on cultive le thé par ici.","tgt":"他给我们讲了这里怎么种茶。","ro":"Tā gěi wǒmen jiǎngle zhèlǐ zěnme zhòng chá."},{"fr":"Pour chaque rocher, il a une histoire à raconter.","tgt":"每块石头他都能讲出一个故事来。","ro":"Měi kuài shítou tā dōu néng jiǎng chū yí ge gùshi lái."},{"fr":"À la fin, on lui a laissé un très bon avis en ligne.","tgt":"最后我们在网上给了他一个好评。","ro":"Zuìhòu wǒmen zài wǎng shang gěile tā yí ge hǎopíng."},{"fr":"Un bon guide peut transformer tout un voyage.","tgt":"一个好导游能改变整个旅行。","ro":"Yí ge hǎo dǎoyóu néng gǎibiàn zhěnggè lǚxíng."}]},{"title":"Un imprévu de santé en voyage","phrases":[{"fr":"Depuis hier soir, j'ai mal au ventre.","tgt":"从昨天晚上开始，我肚子就不舒服。","ro":"Cóng zuótiān wǎnshang kāishǐ, wǒ dùzi jiù bù shūfu."},{"fr":"J'ai peut-être mangé quelque chose de trop pimenté.","tgt":"可能是吃了太辣的东西。","ro":"Kěnéng shì chīle tài là de dōngxi."},{"fr":"Où se trouve la pharmacie la plus proche ?","tgt":"最近的药店在哪儿？","ro":"Zuì jìn de yàodiàn zài nǎr?"},{"fr":"Le pharmacien m'a demandé depuis combien de temps j'avais de la fièvre.","tgt":"药剂师问我发烧多久了。","ro":"Yàojìshī wèn wǒ fāshāo duō jiǔ le."},{"fr":"Ce remède, c'est trois fois par jour, après manger.","tgt":"这个药一天三次，饭后吃。","ro":"Zhège yào yì tiān sān cì, fàn hòu chī."},{"fr":"Par précaution, je préfère quand même aller voir un médecin.","tgt":"为了保险起见，我还是去看医生吧。","ro":"Wèile bǎoxiǎn qǐjiàn, wǒ háishi qù kàn yīshēng ba."},{"fr":"L'assurance voyage devrait rembourser ces frais.","tgt":"旅游保险应该能报销这些费用。","ro":"Lǚyóu bǎoxiǎn yīnggāi néng bàoxiāo zhèxiē fèiyòng."},{"fr":"Gardez bien tous les reçus, s'il vous plaît.","tgt":"请把所有的收据都保存好。","ro":"Qǐng bǎ suǒyǒu de shōujù dōu bǎocún hǎo."},{"fr":"Après deux jours de repos, je me sens beaucoup mieux.","tgt":"休息了两天，我感觉好多了。","ro":"Xiūxile liǎng tiān, wǒ gǎnjué hǎo duō le."},{"fr":"En voyage, la santé passe avant le programme.","tgt":"旅行的时候，身体比行程更重要。","ro":"Lǚxíng de shíhou, shēntǐ bǐ xíngchéng gèng zhòngyào."}]},{"title":"Une Chine qui voyage de plus en plus","phrases":[{"fr":"De plus en plus de Chinois voyagent dans leur propre pays.","tgt":"越来越多的中国人在国内旅游。","ro":"Yuè lái yuè duō de Zhōngguórén zài guónèi lǚyóu."},{"fr":"Le train à grande vitesse dessert des endroits de plus en plus lointains.","tgt":"高铁通到的地方越来越远。","ro":"Gāotiě tōng dào de dìfang yuè lái yuè yuǎn."},{"fr":"Payer avec son téléphone est de plus en plus pratique.","tgt":"用手机付钱越来越方便了。","ro":"Yòng shǒujī fù qián yuè lái yuè fāngbiàn le."},{"fr":"Les jeunes aiment de plus en plus les petites villes tranquilles.","tgt":"年轻人越来越喜欢安静的小城。","ro":"Niánqīngrén yuè lái yuè xǐhuan ānjìng de xiǎo chéng."},{"fr":"Plus on voyage, plus on a envie de repartir.","tgt":"越旅行越想再出发。","ro":"Yuè lǚxíng yuè xiǎng zài chūfā."},{"fr":"Au fil du voyage, mon chinois s'améliore de plus en plus.","tgt":"一路上我的中文越来越好了。","ro":"Yí lù shang wǒ de Zhōngwén yuè lái yuè hǎo le."},{"fr":"En été, les sites célèbres sont de plus en plus bondés.","tgt":"夏天，有名的景点越来越挤了。","ro":"Xiàtiān, yǒumíng de jǐngdiǎn yuè lái yuè jǐ le."},{"fr":"C'est pourquoi de plus en plus de gens partent hors saison.","tgt":"所以越来越多的人选择淡季出行。","ro":"Suǒyǐ yuè lái yuè duō de rén xuǎnzé dànjì chūxíng."},{"fr":"Plus un paysage est sauvage, plus il faut le protéger.","tgt":"风景越原始，越需要好好保护。","ro":"Fēngjǐng yuè yuánshǐ, yuè xūyào hǎohǎo bǎohù."},{"fr":"J'ai de plus en plus envie de repartir à l'aventure.","tgt":"我越来越想再出去走走了。","ro":"Wǒ yuè lái yuè xiǎng zài chūqu zǒuzou le."}],"tip":{"title":"« Yuè lái yuè » : de plus en plus","example":"Payer avec son téléphone est de plus en plus pratique. — 用手机付钱<b>越来越</b>方便了。","body":"Mot à mot, « yuè lái yuè » veut dire à peu près « dépasser, venir, dépasser » : une chose qui va toujours plus loin. On le place juste devant un adjectif ou un verbe de sentiment : « yuè lái yuè fāngbiàn », de plus en plus pratique, « yuè lái yuè xǐhuan », aimer de plus en plus. Pour dire « de plus en plus de gens », on dit « yuè lái yuè duō de rén », littéralement des gens de plus en plus nombreux. On ajoute souvent « le » en fin de phrase pour souligner que la situation a changé. Et la variante « yuè » suivi d'un premier élément puis « yuè » suivi d'un second donne « plus… plus… » : « yuè lǚxíng yuè xiǎng zài chūfā », plus on voyage, plus on a envie de repartir. Astuce : les deux « yuè » sont au quatrième ton, comme deux petits coups de tambour qui encadrent un « lái » qui monte.","exampleRo":"Yòng shǒujī fù qián yuè lái yuè fāngbiàn le.","lit":"utiliser · téléphone · payer · argent · de plus en plus · pratique · [changement]","say":{"Yuè lái yuè":"越来越","yuè lái yuè":"越来越","yuè lái yuè fāngbiàn":"越来越方便","yuè lái yuè xǐhuan":"越来越喜欢","yuè lái yuè duō de rén":"越来越多的人","le":"了","yuè":"越","yuè lǚxíng yuè xiǎng zài chūfā":"越旅行越想再出发","lái":"来"}}},{"title":"Les souvenirs à rapporter","phrases":[{"fr":"Je cherche un cadeau pour ma mère, qui adore le thé.","tgt":"我想给我妈妈买个礼物，她特别爱喝茶。","ro":"Wǒ xiǎng gěi wǒ māma mǎi ge lǐwù, tā tèbié ài hē chá."},{"fr":"Le café de Hainan est peu connu, mais il est délicieux.","tgt":"海南的咖啡没那么有名，但是很好喝。","ro":"Hǎinán de kāfēi méi nàme yǒumíng, dànshì hěn hǎohē."},{"fr":"Ces écharpes en laine viennent de Mongolie-Intérieure.","tgt":"这些羊毛围巾是从内蒙古来的。","ro":"Zhèxiē yángmáo wéijīn shì cóng Nèiménggǔ lái de."},{"fr":"Vous pouvez me faire un paquet cadeau ?","tgt":"能帮我包装一下吗？","ro":"Néng bāng wǒ bāozhuāng yíxià ma?"},{"fr":"Ma valise est déjà pleine à craquer.","tgt":"我的箱子已经塞得满满的了。","ro":"Wǒ de xiāngzi yǐjīng sāi de mǎnmǎn de le."},{"fr":"On dirait que je vais devoir acheter un sac de plus.","tgt":"看来得再买一个包了。","ro":"Kànlái děi zài mǎi yí ge bāo le."},{"fr":"Est-ce qu'on peut envoyer le colis directement en France ?","tgt":"能直接把包裹寄到法国吗？","ro":"Néng zhíjiē bǎ bāoguǒ jì dào Fǎguó ma?"},{"fr":"Ces fruits séchés se conservent plusieurs mois.","tgt":"这些果干能放好几个月。","ro":"Zhèxiē guǒgān néng fàng hǎo jǐ ge yuè."},{"fr":"Les meilleurs souvenirs, ce sont encore les photos et les gens rencontrés.","tgt":"最好的纪念，还是照片和遇到的人。","ro":"Zuì hǎo de jìniàn, háishi zhàopiàn hé yùdào de rén."},{"fr":"Ce que je rapporte le plus, ce sont des histoires.","tgt":"我带回去最多的是故事。","ro":"Wǒ dài huíqu zuì duō de shì gùshi."}]},{"title":"Fin du module : un bilan de voyage","phrases":[{"fr":"Ce module nous a menés du Nord glacé jusqu'aux plages du Sud.","tgt":"这个单元带我们从冰天雪地的北方走到了南方的海边。","ro":"Zhège dānyuán dài wǒmen cóng bīngtiān xuědì de běifāng zǒu dàole nánfāng de hǎibiān."},{"fr":"Harbin, les prairies, le désert, les montagnes et la mer : quel voyage inoubliable !","tgt":"哈尔滨、草原、沙漠、高山和大海，真是一趟难忘的旅行！","ro":"Hā'ěrbīn, cǎoyuán, shāmò, gāoshān hé dàhǎi, zhēn shì yí tàng nánwàng de lǚxíng!"},{"fr":"Maintenant, je sais demander mon chemin, marchander et me débrouiller seul en chinois.","tgt":"现在我会用中文问路、讲价，也能自己解决问题了。","ro":"Xiànzài wǒ huì yòng Zhōngwén wèn lù, jiǎngjià, yě néng zìjǐ jiějué wèntí le."},{"fr":"Les longues phrases avec « de » ne me font plus peur.","tgt":"带“的”的长句子已经难不倒我了。","ro":"Dài \"de\" de cháng jùzi yǐjīng nán bu dǎo wǒ le."},{"fr":"Je comprends de mieux en mieux ce qu'on me dit.","tgt":"别人说的话我越来越听得懂了。","ro":"Biérén shuō de huà wǒ yuè lái yuè tīng de dǒng le."},{"fr":"Bien sûr, il reste pas mal de mots que je ne saisis pas.","tgt":"当然，还是有不少词我听不出来。","ro":"Dāngrán, háishi yǒu bù shǎo cí wǒ tīng bu chūlái."},{"fr":"Mais je n'ai plus peur de parler avec des inconnus.","tgt":"但是我已经不怕跟陌生人说话了。","ro":"Dànshì wǒ yǐjīng bú pà gēn mòshēngrén shuōhuà le."},{"fr":"Faisons une petite pause avant de continuer.","tgt":"我们先休息一下，再继续吧。","ro":"Wǒmen xiān xiūxi yíxià, zài jìxù ba."},{"fr":"Le prochain module sera consacré à la conversation sociale.","tgt":"下一个单元讲的是社交对话。","ro":"Xià yí ge dānyuán jiǎng de shì shèjiāo duìhuà."},{"fr":"Merci pour tous ces efforts, et à la prochaine fois !","tgt":"辛苦了，我们下次再见！","ro":"Xīnkǔ le, wǒmen xià cì zàijiàn!"}]}]},{"id":3,"name":"Conversation sociale","desc":"Des conversations profondes : opinions, débats, émotions.","totalPhrases":200,"lessonsCount":20,"lessons":[{"title":"Travail et vie : trouver l'équilibre","phrases":[{"fr":"Je pars tôt, je rentre tard, je n'ai presque plus de vie à moi.","tgt":"我每天早出晚归，几乎没有自己的生活了。","ro":"Wǒ měi tiān zǎo chū wǎn guī, jīhū méiyǒu zìjǐ de shēnghuó le."},{"fr":"Les Chinois disent souvent qu'il faut alterner effort et repos.","tgt":"中国人常说，要劳逸结合。","ro":"Zhōngguórén cháng shuō, yào láo yì jiéhé."},{"fr":"Mon collègue travaille au point d'en oublier de manger et de dormir.","tgt":"我的同事工作起来废寝忘食。","ro":"Wǒ de tóngshì gōngzuò qǐlai fèi qǐn wàng shí."},{"fr":"À la longue, on finit par s'épuiser sans s'en rendre compte.","tgt":"时间长了，人会不知不觉地累垮。","ro":"Shíjiān cháng le, rén huì bù zhī bù jué de lèikuǎ."},{"fr":"Quand je travaille, je m'y consacre corps et âme.","tgt":"工作的时候，我全心全意地投入。","ro":"Gōngzuò de shíhou, wǒ quán xīn quán yì de tóurù."},{"fr":"Mais le week-end, j'ai vraiment besoin de souffler.","tgt":"可是到了周末，我真的想好好休息。","ro":"Kěshì dào le zhōumò, wǒ zhēn de xiǎng hǎohǎo xiūxi."},{"fr":"Faire du sport après le travail, c'est faire d'une pierre deux coups.","tgt":"下班后去运动，真是一举两得。","ro":"Xiàbān hòu qù yùndòng, zhēn shì yì jǔ liǎng dé."},{"fr":"Ça détend le corps et ça apaise l'esprit en même temps.","tgt":"既能放松身体，又能让心情平静下来。","ro":"Jì néng fàngsōng shēntǐ, yòu néng ràng xīnqíng píngjìng xiàlai."},{"fr":"Mon bureau est dans un désordre total, il faut que je range.","tgt":"我的办公桌乱七八糟的，得整理一下了。","ro":"Wǒ de bàngōngzhuō luàn qī bā zāo de, děi zhěnglǐ yíxià le."},{"fr":"Quand on travaille l'esprit serein, on est même plus efficace.","tgt":"心平气和地工作，效率反而更高。","ro":"Xīn píng qì hé de gōngzuò, xiàolǜ fǎn'ér gèng gāo."}],"tip":{"title":"Les « chéngyǔ » : les expressions en quatre syllabes","example":"Faire du sport après le travail, c'est faire d'une pierre deux coups. — 下班后去运动，真是<b>一举两得</b>。","body":"Les « chéngyǔ » sont des expressions figées de quatre syllabes, un peu comme nos proverbes en version raccourcie, et les Chinois les glissent partout dans la conversation. Leur secret, c'est le rythme : on les prononce en deux paires bien régulières, sans s'arrêter, comme un petit roulement de tambour. Prenons « yì jǔ liǎng dé » : mot à mot « un geste, deux gains », c'est exactement notre « faire d'une pierre deux coups ». Dans cette leçon, vous avez aussi « luàn qī bā zāo », littéralement « désordre sept huit », pour un fouillis total, et « bù zhī bù jué », « sans savoir, sans sentir », pour dire sans s'en rendre compte. Astuce : apprenez chaque « chéngyǔ » comme une mini-chanson en deux temps, puis placez-en un seul au bon moment dans une conversation, l'effet est garanti.","exampleRo":"Xiàbān hòu qù yùndòng, zhēn shì yì jǔ liǎng dé.","lit":"finir le travail · après · aller · faire du sport · vraiment · être · un · geste · deux · gains","say":{"chéngyǔ":"成语","yì jǔ liǎng dé":"一举两得","luàn qī bā zāo":"乱七八糟","bù zhī bù jué":"不知不觉"}}},{"title":"Vieillir en Chine aujourd'hui","phrases":[{"fr":"La population chinoise vieillit de plus en plus vite.","tgt":"中国的人口老龄化越来越快了。","ro":"Zhōngguó de rénkǒu lǎolínghuà yuè lái yuè kuài le."},{"fr":"Mes parents ont pris leur retraite l'an dernier.","tgt":"我父母去年退休了。","ro":"Wǒ fùmǔ qùnián tuìxiū le."},{"fr":"Depuis, ils gardent leur petit-fils tous les jours.","tgt":"从那以后，他们每天帮忙带孙子。","ro":"Cóng nà yǐhòu, tāmen měi tiān bāngmáng dài sūnzi."},{"fr":"Le matin, beaucoup de retraités dansent sur les places publiques.","tgt":"早上，很多退休老人在广场上跳舞。","ro":"Zǎoshang, hěn duō tuìxiū lǎorén zài guǎngchǎng shang tiàowǔ."},{"fr":"Ma grand-mère dit que la danse l'empêche de se sentir seule.","tgt":"我奶奶说，跳舞让她不觉得孤单。","ro":"Wǒ nǎinai shuō, tiàowǔ ràng tā bù juéde gūdān."},{"fr":"En vieillissant, ce dont on a le plus besoin, c'est de compagnie.","tgt":"人老了，最需要的是有人陪伴。","ro":"Rén lǎo le, zuì xūyào de shì yǒu rén péibàn."},{"fr":"Beaucoup de jeunes travaillent très loin de leurs parents.","tgt":"很多年轻人在离父母很远的地方工作。","ro":"Hěn duō niánqīngrén zài lí fùmǔ hěn yuǎn de dìfang gōngzuò."},{"fr":"Je les appelle en vidéo chaque dimanche soir.","tgt":"我每个星期天晚上都跟他们视频。","ro":"Wǒ měi ge xīngqītiān wǎnshang dōu gēn tāmen shìpín."},{"fr":"S'occuper de ses parents âgés reste une tradition importante.","tgt":"照顾年迈的父母仍然是很重要的传统。","ro":"Zhàogù niánmài de fùmǔ réngrán shì hěn zhòngyào de chuántǒng."},{"fr":"J'espère vieillir avec autant de sérénité qu'eux.","tgt":"我希望自己老了以后也能像他们一样从容。","ro":"Wǒ xīwàng zìjǐ lǎo le yǐhòu yě néng xiàng tāmen yíyàng cóngróng."}]},{"title":"Les petites formules qui réchauffent","phrases":[{"fr":"Bonjour madame Wang, vous avez déjà mangé ?","tgt":"王阿姨好，吃了吗？","ro":"Wáng āyí hǎo, chī le ma?"},{"fr":"Oui, c'est fait, et toi ?","tgt":"吃了，你呢？","ro":"Chī le, nǐ ne?"},{"fr":"En fait, on ne vous demande pas vraiment si vous avez mangé.","tgt":"其实，这不是真的在问你吃没吃饭。","ro":"Qíshí, zhè bú shì zhēn de zài wèn nǐ chī méi chī fàn."},{"fr":"C'est juste une façon chaleureuse de dire bonjour.","tgt":"这只是一种亲切的打招呼方式。","ro":"Zhè zhǐ shì yì zhǒng qīnqiè de dǎ zhāohu fāngshì."},{"fr":"Mangez tranquillement, prenez votre temps !","tgt":"您慢慢吃！","ro":"Nín mànmàn chī!"},{"fr":"Mon hôte s'est levé de table en me disant de prendre mon temps.","tgt":"主人先离开饭桌，还让我慢慢吃。","ro":"Zhǔrén xiān líkāi fànzhuō, hái ràng wǒ mànmàn chī."},{"fr":"Tu passes ton examen demain ? Bon courage !","tgt":"你明天考试吗？加油！","ro":"Nǐ míngtiān kǎoshì ma? Jiāyóu!"},{"fr":"Allez, tiens bon encore un peu, tu y es presque !","tgt":"加油，再坚持一下，快到了！","ro":"Jiāyóu, zài jiānchí yíxià, kuài dào le!"},{"fr":"Les supporters crient tous ensemble pour encourager leur équipe.","tgt":"球迷们一起大声喊加油。","ro":"Qiúmímen yìqǐ dàshēng hǎn jiāyóu."},{"fr":"Ces petites formules rendent les échanges bien plus chaleureux.","tgt":"这些小小的客套话让交流变得更温暖。","ro":"Zhèxiē xiǎoxiǎo de kètàohuà ràng jiāoliú biàn de gèng wēnnuǎn."}],"tip":{"title":"Les expressions du quotidien : « chī le ma, mànmàn chī, jiāyóu »","example":"Tu passes ton examen demain ? Bon courage ! — 你明天考试吗？<b>加油</b>！","body":"Certaines petites formules reviennent sans cesse dans la bouche des Chinois, et elles ne se comprennent pas mot à mot. « Chī le ma ? », littéralement « manger, accompli, question », veut dire « tu as mangé ? », mais c'est surtout une salutation amicale : on répond simplement « chī le, nǐ ne ? », « oui, et toi ? ». « Mànmàn chī », « lentement lentement manger », se dit à table pour souhaiter bon appétit, ou quand on se lève avant les autres. Enfin « jiāyóu », « ajouter de l'huile », signifie « allez, courage ! », comme si l'on remettait du carburant dans le moteur. Prononcez-les avec le sourire et une intonation chantante : c'est ce ton chaleureux qui compte, bien plus que le sens des mots.","exampleRo":"Nǐ míngtiān kǎoshì ma? Jiāyóu!","lit":"toi · demain · passer un examen · [question] ? ajouter · huile !","say":{"Chī le ma ?":"吃了吗？","chī le, nǐ ne ?":"吃了，你呢？","Mànmàn chī":"慢慢吃","jiāyóu":"加油","chī le ma, mànmàn chī, jiāyóu":"吃了吗、慢慢吃、加油"}}},{"title":"Tradition et modernité","phrases":[{"fr":"Pékin mêle de vieilles ruelles et des tours ultramodernes.","tgt":"北京既有古老的胡同，也有现代化的高楼。","ro":"Běijīng jì yǒu gǔlǎo de hútòng, yě yǒu xiàndàihuà de gāolóu."},{"fr":"Beaucoup de ces vieilles ruelles ont été démolies.","tgt":"很多老胡同都被拆掉了。","ro":"Hěn duō lǎo hútòng dōu bèi chāidiào le."},{"fr":"Certains trouvent ça dommage, d'autres y voient un progrès.","tgt":"有人觉得可惜，也有人认为这是进步。","ro":"Yǒu rén juéde kěxī, yě yǒu rén rènwéi zhè shì jìnbù."},{"fr":"Les jeunes se remettent à porter des vêtements traditionnels.","tgt":"现在的年轻人又开始穿传统服装了。","ro":"Xiànzài de niánqīngrén yòu kāishǐ chuān chuántǒng fúzhuāng le."},{"fr":"On paie tout avec son téléphone, même au marché aux légumes.","tgt":"买什么都用手机付钱，连菜市场也不例外。","ro":"Mǎi shénme dōu yòng shǒujī fù qián, lián càishìchǎng yě bú lìwài."},{"fr":"Ma grand-mère, en revanche, préfère toujours payer en liquide.","tgt":"不过我奶奶还是更喜欢用现金。","ro":"Búguò wǒ nǎinai háishi gèng xǐhuan yòng xiànjīn."},{"fr":"La modernité ne devrait pas nous faire oublier nos racines.","tgt":"现代化不应该让人忘记自己的根。","ro":"Xiàndàihuà bù yīnggāi ràng rén wàngjì zìjǐ de gēn."},{"fr":"En Chine, les fêtes traditionnelles restent très animées.","tgt":"在中国，传统节日仍然很热闹。","ro":"Zài Zhōngguó, chuántǒng jiérì réngrán hěn rènao."},{"fr":"À mon avis, tradition et modernité peuvent très bien coexister.","tgt":"我觉得传统和现代完全可以共存。","ro":"Wǒ juéde chuántǒng hé xiàndài wánquán kěyǐ gòngcún."},{"fr":"L'essentiel, c'est de préserver ce qui a de la valeur.","tgt":"关键是要把有价值的东西保留下来。","ro":"Guānjiàn shì yào bǎ yǒu jiàzhí de dōngxi bǎoliú xiàlai."}]},{"title":"Parler de calligraphie","phrases":[{"fr":"On dirait que tu t'intéresses beaucoup à la calligraphie.","tgt":"你好像对书法很感兴趣。","ro":"Nǐ hǎoxiàng duì shūfǎ hěn gǎn xìngqù."},{"fr":"Oui, ça fait six mois que j'apprends avec un vieux maître.","tgt":"对，我跟一位老先生学了半年了。","ro":"Duì, wǒ gēn yí wèi lǎo xiānsheng xué le bàn nián le."},{"fr":"Ce caractère a l'air de danser sur le papier.","tgt":"这个字好像在纸上跳舞一样。","ro":"Zhège zì hǎoxiàng zài zhǐ shang tiàowǔ yíyàng."},{"fr":"Le maître ne semble jamais pressé.","tgt":"老师似乎从来都不着急。","ro":"Lǎoshī sìhū cónglái dōu bù zháojí."},{"fr":"La calligraphie semble aider à apaiser l'esprit.","tgt":"写书法似乎能让人静下心来。","ro":"Xiě shūfǎ sìhū néng ràng rén jìng xià xīn lai."},{"fr":"On dirait qu'il va pleuvoir, restons à l'intérieur pour nous exercer.","tgt":"好像要下雨了，我们在屋里练字吧。","ro":"Hǎoxiàng yào xià yǔ le, wǒmen zài wū li liàn zì ba."},{"fr":"Tes traits ont l'air bien plus assurés qu'avant.","tgt":"你的笔画好像比以前有力多了。","ro":"Nǐ de bǐhuà hǎoxiàng bǐ yǐqián yǒulì duō le."},{"fr":"Pour moi, c'est avant tout un art du geste et du souffle.","tgt":"对我来说，这首先是一种关于动作和呼吸的艺术。","ro":"Duì wǒ lái shuō, zhè shǒuxiān shì yì zhǒng guānyú dòngzuò hé hūxī de yìshù."},{"fr":"Les jeunes semblent de nouveau s'y intéresser.","tgt":"年轻人似乎又开始对它感兴趣了。","ro":"Niánqīngrén sìhū yòu kāishǐ duì tā gǎn xìngqù le."},{"fr":"Je n'écris pas encore bien, mais j'adore regarder les autres écrire.","tgt":"我还写不好，可是我特别喜欢看别人写。","ro":"Wǒ hái xiě bu hǎo, kěshì wǒ tèbié xǐhuan kàn biérén xiě."}],"tip":{"title":"« Hǎoxiàng » et « sìhū » : on dirait que","example":"On dirait que tu t'intéresses beaucoup à la calligraphie. — 你<b>好像</b>对书法很感兴趣。","body":"Pour dire « on dirait que » ou « il semble que », le chinois a deux mots très pratiques : « hǎoxiàng », celui de tous les jours, et « sìhū », un peu plus soutenu, qu'on entend dans une conversation posée. Les deux se placent juste après le sujet, devant le verbe ou l'adjectif : « nǐ hǎoxiàng duì shūfǎ hěn gǎn xìngqù », mot à mot « toi sembler envers calligraphie très ressentir intérêt », donc « on dirait que tu t'intéresses à la calligraphie ». Sans sujet, il ouvre simplement la phrase : « hǎoxiàng yào xià yǔ le », « on dirait qu'il va pleuvoir ». Pour une image, ajoutez « yíyàng » à la fin : « hǎoxiàng zài tiàowǔ yíyàng », « comme s'il dansait ». Astuce : « xiàng » veut dire « ressembler », pensez donc à « ça ressemble bien à... ».","exampleRo":"Nǐ hǎoxiàng duì shūfǎ hěn gǎn xìngqù.","lit":"toi · sembler · envers · calligraphie · très · ressentir · intérêt","say":{"Hǎoxiàng":"好像","sìhū":"似乎","hǎoxiàng":"好像","nǐ hǎoxiàng duì shūfǎ hěn gǎn xìngqù":"你好像对书法很感兴趣","hǎoxiàng yào xià yǔ le":"好像要下雨了","yíyàng":"一样","hǎoxiàng zài tiàowǔ yíyàng":"好像在跳舞一样","xiàng":"像"}}},{"title":"Une soirée à l'opéra de Pékin","phrases":[{"fr":"Hier soir, des amis m'ont emmené voir l'opéra de Pékin.","tgt":"昨天晚上，朋友带我去看了京剧。","ro":"Zuótiān wǎnshang, péngyou dài wǒ qù kàn le jīngjù."},{"fr":"Au début, ces voix très aiguës m'ont un peu surpris.","tgt":"一开始，那种很高的唱腔让我有点儿吃惊。","ro":"Yì kāishǐ, nà zhǒng hěn gāo de chàngqiāng ràng wǒ yǒudiǎnr chījīng."},{"fr":"Les costumes et les maquillages étaient splendides.","tgt":"服装和脸谱都漂亮极了。","ro":"Fúzhuāng hé liǎnpǔ dōu piàoliang jí le."},{"fr":"Chaque couleur de maquillage représente un caractère.","tgt":"脸谱的每种颜色都代表一种性格。","ro":"Liǎnpǔ de měi zhǒng yánsè dōu dàibiǎo yì zhǒng xìnggé."},{"fr":"Le rouge symbolise la loyauté et le courage.","tgt":"红色代表忠诚和勇敢。","ro":"Hóngsè dàibiǎo zhōngchéng hé yǒnggǎn."},{"fr":"Je n'ai pas compris toutes les paroles, mais j'ai suivi l'histoire.","tgt":"歌词我没全听懂，不过故事我看明白了。","ro":"Gēcí wǒ méi quán tīngdǒng, búguò gùshi wǒ kàn míngbai le."},{"fr":"Les acrobaties des acteurs m'ont laissé bouche bée.","tgt":"演员的武打动作让我看得目瞪口呆。","ro":"Yǎnyuán de wǔdǎ dòngzuò ràng wǒ kàn de mù dèng kǒu dāi."},{"fr":"Mes amis chinois ne vont presque jamais à l'opéra.","tgt":"我的中国朋友几乎从来不去看京剧。","ro":"Wǒ de Zhōngguó péngyou jīhū cónglái bú qù kàn jīngjù."},{"fr":"Pour eux, c'est plutôt un loisir de personnes âgées.","tgt":"他们说这更像是老年人的爱好。","ro":"Tāmen shuō zhè gèng xiàng shì lǎoniánrén de àihào."},{"fr":"Pourtant, ce soir-là, la salle était pleine de jeunes.","tgt":"可是那天晚上，剧场里坐满了年轻人。","ro":"Kěshì nà tiān wǎnshang, jùchǎng li zuòmǎn le niánqīngrén."}]},{"title":"L'art du thé","phrases":[{"fr":"Dans une maison de thé, personne n'est pressé.","tgt":"在茶馆里，大家都不着急。","ro":"Zài cháguǎn li, dàjiā dōu bù zháojí."},{"fr":"Le patron nous a fait goûter du thé Longjing de Hangzhou.","tgt":"老板请我们尝了尝杭州的龙井茶。","ro":"Lǎobǎn qǐng wǒmen cháng le cháng Hángzhōu de lóngjǐngchá."},{"fr":"Il faut d'abord rincer les feuilles à l'eau chaude.","tgt":"先要用热水把茶叶洗一遍。","ro":"Xiān yào yòng rèshuǐ bǎ cháyè xǐ yí biàn."},{"fr":"Pour le thé vert, l'eau ne doit pas être trop brûlante.","tgt":"泡绿茶的水不能太烫。","ro":"Pào lǜchá de shuǐ bù néng tài tàng."},{"fr":"Quand on vous sert, vous pouvez tapoter la table avec deux doigts pour remercier.","tgt":"别人给你倒茶时，可以用两个手指轻轻敲桌子表示感谢。","ro":"Biérén gěi nǐ dào chá shí, kěyǐ yòng liǎng ge shǒuzhǐ qīngqīng qiāo zhuōzi biǎoshì gǎnxiè."},{"fr":"En général, on ne remplit pas la tasse jusqu'au bord.","tgt":"倒茶一般不倒满。","ro":"Dào chá yìbān bú dàomǎn."},{"fr":"Le thé se savoure à petites gorgées, jamais d'un trait.","tgt":"茶要一小口一小口地品，不能一口喝完。","ro":"Chá yào yì xiǎo kǒu yì xiǎo kǒu de pǐn, bù néng yì kǒu hēwán."},{"fr":"Pour beaucoup de Chinois, boire du thé est une manière de vivre.","tgt":"对很多中国人来说，喝茶是一种生活态度。","ro":"Duì hěn duō Zhōngguórén lái shuō, hē chá shì yì zhǒng shēnghuó tàidù."},{"fr":"Partager une théière, c'est aussi partager une conversation.","tgt":"一起喝一壶茶，也是一起聊聊天。","ro":"Yìqǐ hē yì hú chá, yě shì yìqǐ liáoliao tiān."},{"fr":"J'ai acheté un petit service à thé en argile pour le rapporter en France.","tgt":"我买了一套小紫砂茶具，打算带回法国。","ro":"Wǒ mǎi le yí tào xiǎo zǐshā chájù, dǎsuàn dài huí Fǎguó."}]},{"title":"Entre ville et campagne","phrases":[{"fr":"Mon ami a été obligé de quitter son village pour trouver du travail.","tgt":"我朋友为了找工作，不得不离开了老家。","ro":"Wǒ péngyou wèile zhǎo gōngzuò, bùdébù líkāi le lǎojiā."},{"fr":"En ville, il a dû tout recommencer de zéro.","tgt":"在城里，他不得不一切从头开始。","ro":"Zài chéng li, tā bùdébù yíqiè cóngtóu kāishǐ."},{"fr":"Le loyer était si cher qu'il a dû habiter loin du centre.","tgt":"房租太贵，他不得不住在离市中心很远的地方。","ro":"Fángzū tài guì, tā bùdébú zhù zài lí shì zhōngxīn hěn yuǎn de dìfang."},{"fr":"Ses enfants sont restés à la campagne avec leurs grands-parents.","tgt":"他的孩子留在农村，跟爷爷奶奶一起生活。","ro":"Tā de háizi liú zài nóngcūn, gēn yéye nǎinai yìqǐ shēnghuó."},{"fr":"Chaque année, à la Fête du printemps, il fait le voyage jusqu'à son village.","tgt":"每年春节，他都会回老家一趟。","ro":"Měi nián Chūnjié, tā dōu huì huí lǎojiā yí tàng."},{"fr":"Les trains sont bondés, on est obligé de réserver très tôt.","tgt":"火车特别挤，大家不得不很早就订票。","ro":"Huǒchē tèbié jǐ, dàjiā bùdébù hěn zǎo jiù dìng piào."},{"fr":"À la campagne, l'air est pur et la vie est plus lente.","tgt":"农村空气新鲜，生活节奏也慢一些。","ro":"Nóngcūn kōngqì xīnxiān, shēnghuó jiézòu yě màn yìxiē."},{"fr":"Mais il n'y a pas assez d'écoles ni d'hôpitaux.","tgt":"可是学校和医院都不够。","ro":"Kěshì xuéxiào hé yīyuàn dōu bú gòu."},{"fr":"Je dois bien avouer que la ville a aussi ses avantages.","tgt":"我不得不承认，城市也有它的好处。","ro":"Wǒ bùdébù chéngrèn, chéngshì yě yǒu tā de hǎochù."},{"fr":"Aujourd'hui, certains jeunes choisissent de retourner vivre à la campagne.","tgt":"现在，有些年轻人选择回到农村。","ro":"Xiànzài, yǒuxiē niánqīngrén xuǎnzé huídào nóngcūn."}],"tip":{"title":"« Bùdébù » : être obligé de","example":"Je dois bien avouer que la ville a aussi ses avantages. — 我<b>不得不</b>承认，城市也有它的好处。","body":"« Bùdébù » est une double négation : mot à mot « ne pas pouvoir ne pas », autrement dit, on n'a pas le choix. Il se place devant le verbe, exactement comme notre « être obligé de » : « tā bùdébù líkāi lǎojiā », « il a été obligé de quitter son village natal ». Il exprime une contrainte qu'on subit un peu à contrecœur, plus forte que le simple « děi », « devoir ». Côté prononciation, attention au dernier « bù » : devant un quatrième ton, il remonte et devient « bú », comme dans « bùdébú zhù », « être obligé d'habiter ». On l'emploie aussi pour reconnaître quelque chose sans enthousiasme : « wǒ bùdébù chéngrèn », « je dois bien avouer ». Astuce : dites « bù dé bù » comme trois pas décidés, et la formule restera gravée.","exampleRo":"Wǒ bùdébù chéngrèn, chéngshì yě yǒu tā de hǎochù.","lit":"je · ne pas · pouvoir · ne pas · reconnaître , ville · aussi · avoir · elle · [possessif] · avantage","say":{"Bùdébù":"不得不","tā bùdébù líkāi lǎojiā":"他不得不离开老家","děi":"得","bù":"不","bùdébú zhù":"不得不住","wǒ bùdébù chéngrèn":"我不得不承认","bù dé bù":"不得不"}}},{"title":"Une amitié solide","phrases":[{"fr":"On s'est connus à l'université, ça fait quinze ans.","tgt":"我们是大学同学，认识十五年了。","ro":"Wǒmen shì dàxué tóngxué, rènshi shíwǔ nián le."},{"fr":"Un vrai ami, c'est celui qui reste à tes côtés dans les moments durs.","tgt":"真正的朋友，是在你困难的时候陪在你身边的人。","ro":"Zhēnzhèng de péngyou, shì zài nǐ kùnnan de shíhou péi zài nǐ shēnbiān de rén."},{"fr":"Même sans se voir pendant un an, rien ne change entre nous.","tgt":"就算一年不见面，我们之间也什么都没变。","ro":"Jiùsuàn yì nián bú jiànmiàn, wǒmen zhījiān yě shénme dōu méi biàn."},{"fr":"Entre nous, pas besoin de faire des manières.","tgt":"我们之间不用客气。","ro":"Wǒmen zhījiān búyòng kèqi."},{"fr":"En Chine, les amis se disputent souvent pour payer l'addition.","tgt":"在中国，朋友吃饭常常抢着买单。","ro":"Zài Zhōngguó, péngyou chī fàn chángcháng qiǎngzhe mǎidān."},{"fr":"La dernière fois, c'est toi qui as invité, cette fois c'est mon tour.","tgt":"上次你请的客，这次该我了。","ro":"Shàng cì nǐ qǐng de kè, zhè cì gāi wǒ le."},{"fr":"Il m'a beaucoup aidé quand je venais d'arriver à Pékin.","tgt":"我刚到北京的时候，他帮了我很多忙。","ro":"Wǒ gāng dào Běijīng de shíhou, tā bāng le wǒ hěn duō máng."},{"fr":"Je n'oublierai jamais sa gentillesse.","tgt":"他的好意我永远不会忘记。","ro":"Tā de hǎoyì wǒ yǒngyuǎn bú huì wàngjì."},{"fr":"L'amitié se construit petit à petit, avec le temps.","tgt":"友谊是一点一点慢慢建立起来的。","ro":"Yǒuyì shì yìdiǎn yìdiǎn mànmàn jiànlì qǐlai de."},{"fr":"Comme on dit, un ami de plus, c'est une route de plus.","tgt":"多一个朋友，多一条路。","ro":"Duō yí ge péngyou, duō yì tiáo lù."}]},{"title":"La famille et ses attentes","phrases":[{"fr":"Mes parents me demandent sans arrêt quand je vais me marier.","tgt":"我爸妈老是问我什么时候结婚。","ro":"Wǒ bà mā lǎo shì wèn wǒ shénme shíhou jiéhūn."},{"fr":"Dès qu'arrivent les fêtes, toute la famille s'en mêle.","tgt":"一到过节，全家人都来关心这件事。","ro":"Yí dào guòjié, quán jiā rén dōu lái guānxīn zhè jiàn shì."},{"fr":"Je comprends leur inquiétude, mais j'ai mon propre rythme.","tgt":"我理解他们的担心，可是我有自己的节奏。","ro":"Wǒ lǐjiě tāmen de dānxīn, kěshì wǒ yǒu zìjǐ de jiézòu."},{"fr":"Pour eux, fonder une famille passe avant tout.","tgt":"对他们来说，成家是最重要的事。","ro":"Duì tāmen lái shuō, chéngjiā shì zuì zhòngyào de shì."},{"fr":"Pour moi, réussir d'abord dans mon travail compte davantage.","tgt":"对我来说，先把工作做好更重要。","ro":"Duì wǒ lái shuō, xiān bǎ gōngzuò zuòhǎo gèng zhòngyào."},{"fr":"Beaucoup de jeunes subissent la même pression.","tgt":"很多年轻人都面临同样的压力。","ro":"Hěn duō niánqīngrén dōu miànlín tóngyàng de yālì."},{"fr":"Un soir, à table, on a fini par en parler franchement.","tgt":"有一天晚上，我们在饭桌上把话说开了。","ro":"Yǒu yì tiān wǎnshang, wǒmen zài fànzhuō shang bǎ huà shuōkāi le."},{"fr":"Ma mère a avoué qu'elle voulait surtout me voir heureux.","tgt":"我妈承认，她最希望的是我过得幸福。","ro":"Wǒ mā chéngrèn, tā zuì xīwàng de shì wǒ guò de xìngfú."},{"fr":"Depuis ce jour-là, elle ne me presse presque plus.","tgt":"从那以后，她就不怎么催我了。","ro":"Cóng nà yǐhòu, tā jiù bù zěnme cuī wǒ le."},{"fr":"Se parler sincèrement en famille n'est pas toujours facile.","tgt":"在家里坦诚地沟通并不总是容易的。","ro":"Zài jiā li tǎnchéng de gōutōng bìng bù zǒngshì róngyì de."}]},{"title":"La Fête du printemps en famille","phrases":[{"fr":"Cette année, j'ai passé la Fête du printemps dans une famille chinoise.","tgt":"今年春节，我是在一个中国家庭过的。","ro":"Jīnnián Chūnjié, wǒ shì zài yí ge Zhōngguó jiātíng guò de."},{"fr":"Le soir du réveillon, toute la famille a préparé des raviolis ensemble.","tgt":"除夕那天，全家人一起包饺子。","ro":"Chúxī nà tiān, quán jiā rén yìqǐ bāo jiǎozi."},{"fr":"On a caché une pièce dans un ravioli pour porter chance.","tgt":"我们在一个饺子里包了一枚硬币，说是能带来好运。","ro":"Wǒmen zài yí ge jiǎozi li bāo le yì méi yìngbì, shuō shì néng dàilái hǎoyùn."},{"fr":"C'est moi qui suis tombé dessus, et tout le monde a applaudi !","tgt":"结果被我吃到了，大家都鼓起掌来！","ro":"Jiéguǒ bèi wǒ chīdào le, dàjiā dōu gǔ qǐ zhǎng lai!"},{"fr":"À minuit, le ciel était couvert de feux d'artifice.","tgt":"到了半夜十二点，满天都是烟花。","ro":"Dào le bànyè shí'èr diǎn, mǎn tiān dōu shì yānhuā."},{"fr":"Les enfants ont reçu des enveloppes rouges de leurs aînés.","tgt":"孩子们从长辈那里收到了红包。","ro":"Háizimen cóng zhǎngbèi nàli shōudào le hóngbāo."},{"fr":"On se souhaite une bonne année et que tout se passe bien.","tgt":"大家互相祝福新年快乐、万事如意。","ro":"Dàjiā hùxiāng zhùfú xīnnián kuàilè, wànshì rúyì."},{"fr":"Pour beaucoup, c'est le seul moment de l'année où ils peuvent rentrer chez eux.","tgt":"对很多人来说，这是一年里唯一能回家的时候。","ro":"Duì hěn duō rén lái shuō, zhè shì yì nián li wéiyī néng huí jiā de shíhou."},{"fr":"Ils m'ont traité comme un membre de la famille, j'étais très ému.","tgt":"他们把我当成家里人，我特别感动。","ro":"Tāmen bǎ wǒ dàngchéng jiā li rén, wǒ tèbié gǎndòng."},{"fr":"Je me souviendrai très longtemps de cette soirée.","tgt":"那个晚上我会记很久很久。","ro":"Nàge wǎnshang wǒ huì jì hěn jiǔ hěn jiǔ."}]},{"title":"La sagesse des proverbes","phrases":[{"fr":"Mon grand-père glisse souvent des proverbes dans la conversation.","tgt":"我爷爷说话常常用俗语。","ro":"Wǒ yéye shuōhuà chángcháng yòng súyǔ."},{"fr":"Quand j'ai envie d'abandonner, il me dit : quand on veut, on peut.","tgt":"我想放弃的时候，他总说：有志者事竟成。","ro":"Wǒ xiǎng fàngqì de shíhou, tā zǒng shuō: Yǒu zhì zhě shì jìng chéng."},{"fr":"Un voyage de mille lieues commence par un premier pas.","tgt":"千里之行，始于足下。","ro":"Qiān lǐ zhī xíng, shǐ yú zú xià."},{"fr":"Trois simples cordonniers valent bien un grand stratège.","tgt":"三个臭皮匠，顶个诸葛亮。","ro":"Sān ge chòu píjiang, dǐng ge Zhūgě Liàng."},{"fr":"Autrement dit, en réfléchissant ensemble, on trouve toujours une solution.","tgt":"也就是说，大家一起想，总会有办法的。","ro":"Yě jiù shì shuō, dàjiā yìqǐ xiǎng, zǒng huì yǒu bànfǎ de."},{"fr":"Un ami me répète que c'est en forgeant qu'on devient forgeron.","tgt":"朋友对我说：熟能生巧。","ro":"Péngyou duì wǒ shuō: Shú néng shēng qiǎo."},{"fr":"Avec une langue, inutile de se presser : qui va trop vite n'arrive pas.","tgt":"学语言不能急，欲速则不达。","ro":"Xué yǔyán bù néng jí, yù sù zé bù dá."},{"fr":"Comme dit le vieil adage, à force de patience, une barre de fer devient aiguille.","tgt":"老话说：只要功夫深，铁杵磨成针。","ro":"Lǎohuà shuō: Zhǐyào gōngfu shēn, tiě chǔ mó chéng zhēn."},{"fr":"Ces proverbes résument des siècles de sagesse en quelques mots.","tgt":"这些俗语用几个字就讲出了几百年的智慧。","ro":"Zhèxiē súyǔ yòng jǐ ge zì jiù jiǎngchū le jǐ bǎi nián de zhìhuì."},{"fr":"En placer un au bon moment impressionne toujours les Chinois.","tgt":"在合适的时候用上一句，中国人总会觉得你很厉害。","ro":"Zài héshì de shíhou yòngshang yí jù, Zhōngguórén zǒng huì juéde nǐ hěn lìhai."}],"tip":{"title":"Les proverbes chinois","example":"Un voyage de mille lieues commence par un premier pas. — <b>千里之行，始于足下</b>。","body":"Les Chinois aiment appuyer leurs propos sur un proverbe, souvent introduit par « lǎohuà shuō », « comme dit le vieil adage ». Beaucoup de proverbes sont construits en deux moitiés qui se répondent, avec une petite pause au milieu : « qiān lǐ zhī xíng, shǐ yú zú xià », mot à mot « mille li de voyage, commence sous le pied », c'est-à-dire que tout grand projet commence par un premier pas. D'autres sont très courts, comme « shú néng shēng qiǎo », « l'habitude fait naître l'habileté », notre « c'est en forgeant qu'on devient forgeron ». Leur langue est ancienne et très concise, alors ne cherchez pas à les décortiquer : apprenez-les en bloc, avec leur rythme. Astuce : choisissez-en deux ou trois qui vous plaisent et répétez-les à voix haute jusqu'à ce qu'ils sortent tout seuls.","exampleRo":"Qiān lǐ zhī xíng, shǐ yú zú xià.","lit":"mille · li · [possessif] · voyage , commencer · à · pied · dessous","say":{"lǎohuà shuō":"老话说","qiān lǐ zhī xíng, shǐ yú zú xià":"千里之行，始于足下","shú néng shēng qiǎo":"熟能生巧"}}},{"title":"La table, un art de vivre","phrases":[{"fr":"En Chine, tous les plats sont posés au milieu et on partage.","tgt":"在中国，菜都放在桌子中间，大家一起吃。","ro":"Zài Zhōngguó, cài dōu fàng zài zhuōzi zhōngjiān, dàjiā yìqǐ chī."},{"fr":"L'hôte ne cesse de servir ses invités avec ses baguettes.","tgt":"主人不停地给客人夹菜。","ro":"Zhǔrén bù tíng de gěi kèrén jiā cài."},{"fr":"Laisser un peu de nourriture montre qu'on a assez mangé.","tgt":"剩一点儿菜，说明客人吃饱了。","ro":"Shèng yìdiǎnr cài, shuōmíng kèrén chībǎo le."},{"fr":"Chaque région a sa propre cuisine et ses spécialités.","tgt":"每个地方都有自己的菜系和特色。","ro":"Měi ge dìfang dōu yǒu zìjǐ de càixì hé tèsè."},{"fr":"Les gens du Sichuan ne peuvent pas se passer de piment.","tgt":"四川人吃饭离不开辣椒。","ro":"Sìchuānrén chī fàn lí bu kāi làjiāo."},{"fr":"Dans le Sud, on préfère des saveurs plus légères et un peu sucrées.","tgt":"南方人更喜欢清淡一点儿、甜一点儿的口味。","ro":"Nánfāngrén gèng xǐhuan qīngdàn yìdiǎnr, tián yìdiǎnr de kǒuwèi."},{"fr":"Pour les Chinois, un repas est d'abord un moment d'échange.","tgt":"对中国人来说，吃饭首先是一种交流。","ro":"Duì Zhōngguórén lái shuō, chī fàn shǒuxiān shì yì zhǒng jiāoliú."},{"fr":"Beaucoup d'affaires se concluent autour d'une table.","tgt":"很多事情都是在饭桌上谈成的。","ro":"Hěn duō shìqing dōu shì zài fànzhuō shang tánchéng de."},{"fr":"Je n'arrive toujours pas à manger aussi épicé qu'eux.","tgt":"我到现在还是吃不了他们那么辣的菜。","ro":"Wǒ dào xiànzài háishi chī bu liǎo tāmen nàme là de cài."},{"fr":"En revanche, j'ai appris à cuisiner quelques plats familiaux.","tgt":"不过我学会了做几道家常菜。","ro":"Búguò wǒ xuéhuì le zuò jǐ dào jiāchángcài."}]},{"title":"Prendre soin de soi à la chinoise","phrases":[{"fr":"Tous les matins, des gens pratiquent le tai-chi dans le parc.","tgt":"每天早上，公园里都有人打太极拳。","ro":"Měi tiān zǎoshang, gōngyuán li dōu yǒu rén dǎ tàijíquán."},{"fr":"Un vieux monsieur m'a invité à m'entraîner avec eux.","tgt":"一位老大爷邀请我跟他们一起练。","ro":"Yí wèi lǎo dàye yāoqǐng wǒ gēn tāmen yìqǐ liàn."},{"fr":"Les mouvements ont beau être lents, ils demandent une grande concentration.","tgt":"动作虽然很慢，但是需要高度集中。","ro":"Dòngzuò suīrán hěn màn, dànshì xūyào gāodù jízhōng."},{"fr":"Après une semaine, je dors déjà beaucoup mieux.","tgt":"练了一个星期，我睡觉已经好多了。","ro":"Liàn le yí ge xīngqī, wǒ shuìjiào yǐjīng hǎo duō le."},{"fr":"Les Chinois accordent beaucoup d'importance à l'entretien de leur santé.","tgt":"中国人很重视养生。","ro":"Zhōngguórén hěn zhòngshì yǎngshēng."},{"fr":"On conseille souvent de boire chaud plutôt que glacé.","tgt":"大家常建议多喝热水，少喝冰水。","ro":"Dàjiā cháng jiànyì duō hē rèshuǐ, shǎo hē bīngshuǐ."},{"fr":"Au début, ce conseil me faisait plutôt sourire.","tgt":"一开始，我听到这个建议觉得挺好笑的。","ro":"Yì kāishǐ, wǒ tīngdào zhège jiànyì juéde tǐng hǎoxiào de."},{"fr":"Aujourd'hui, j'ai moi-même pris cette habitude.","tgt":"现在，我自己也养成了这个习惯。","ro":"Xiànzài, wǒ zìjǐ yě yǎngchéng le zhège xíguàn."},{"fr":"Bien manger, bien dormir et marcher un peu chaque jour, voilà le secret.","tgt":"吃好、睡好、每天走走路，这就是秘诀。","ro":"Chī hǎo, shuì hǎo, měi tiān zǒuzou lù, zhè jiù shì mìjué."},{"fr":"La santé du corps et celle de l'esprit vont toujours ensemble.","tgt":"身体健康和心理健康是分不开的。","ro":"Shēntǐ jiànkāng hé xīnlǐ jiànkāng shì fēn bu kāi de."}]},{"title":"Débattre du bonheur et de la réussite","phrases":[{"fr":"Selon toi, qu'est-ce qu'une vie réussie ?","tgt":"你觉得什么才算是成功的人生？","ro":"Nǐ juéde shénme cái suàn shì chénggōng de rénshēng?"},{"fr":"Beaucoup pensent d'abord à l'argent et à un bon poste.","tgt":"很多人首先想到的是钱和好工作。","ro":"Hěn duō rén shǒuxiān xiǎngdào de shì qián hé hǎo gōngzuò."},{"fr":"Mon cousin gagne très bien sa vie, mais il est stressé en permanence.","tgt":"我表哥挣得很多，可是压力一直很大。","ro":"Wǒ biǎogē zhèng de hěn duō, kěshì yālì yìzhí hěn dà."},{"fr":"Je ne suis pas certain que l'argent rende vraiment heureux.","tgt":"我不太确定钱能不能让人真正快乐。","ro":"Wǒ bú tài quèdìng qián néng bu néng ràng rén zhēnzhèng kuàilè."},{"fr":"Pour moi, le bonheur tient souvent à de petites choses.","tgt":"对我来说，幸福往往来自一些小事。","ro":"Duì wǒ lái shuō, xìngfú wǎngwǎng láizì yìxiē xiǎoshì."},{"fr":"Un bon repas entre amis suffit à me rendre joyeux toute la journée.","tgt":"跟朋友吃一顿好饭，就能让我开心一整天。","ro":"Gēn péngyou chī yí dùn hǎo fàn, jiù néng ràng wǒ kāixīn yì zhěng tiān."},{"fr":"Mon amie n'est pas d'accord, elle me trouve trop idéaliste.","tgt":"我朋友不同意，她觉得我太理想主义了。","ro":"Wǒ péngyou bù tóngyì, tā juéde wǒ tài lǐxiǎng zhǔyì le."},{"fr":"Sans sécurité matérielle, dit-elle, difficile d'avoir l'esprit tranquille.","tgt":"她说，没有物质保障，很难安心。","ro":"Tā shuō, méiyǒu wùzhì bǎozhàng, hěn nán ānxīn."},{"fr":"Au fond, nous avons chacun un peu raison.","tgt":"说到底，我们俩都有点儿道理。","ro":"Shuō dào dǐ, wǒmen liǎ dōu yǒudiǎnr dàoli."},{"fr":"L'important, c'est de savoir ce qui compte vraiment pour soi.","tgt":"重要的是知道自己真正在乎什么。","ro":"Zhòngyào de shì zhīdào zìjǐ zhēnzhèng zàihu shénme."}]},{"title":"Un débat sur l'éducation","phrases":[{"fr":"Les enfants chinois ont énormément de devoirs.","tgt":"中国的孩子作业特别多。","ro":"Zhōngguó de háizi zuòyè tèbié duō."},{"fr":"Le week-end, beaucoup vont encore à des cours de soutien.","tgt":"周末，很多孩子还要去上补习班。","ro":"Zhōumò, hěn duō háizi hái yào qù shàng bǔxíbān."},{"fr":"Le concours d'entrée à l'université décide en grande partie de l'avenir.","tgt":"高考在很大程度上决定一个人的未来。","ro":"Gāokǎo zài hěn dà chéngdù shang juédìng yí ge rén de wèilái."},{"fr":"Beaucoup de parents rêvent de voir leur enfant réussir brillamment.","tgt":"很多父母都望子成龙。","ro":"Hěn duō fùmǔ dōu wàng zǐ chéng lóng."},{"fr":"En France, les enfants ont peut-être plus de temps pour jouer.","tgt":"在法国，孩子玩的时间可能更多一些。","ro":"Zài Fǎguó, háizi wán de shíjiān kěnéng gèng duō yìxiē."},{"fr":"Mais les élèves chinois sont souvent très forts en maths.","tgt":"不过中国学生的数学往往特别好。","ro":"Búguò Zhōngguó xuésheng de shùxué wǎngwǎng tèbié hǎo."},{"fr":"Chaque façon d'éduquer a ses points forts et ses faiblesses.","tgt":"每种教育方式都有自己的长处和短处。","ro":"Měi zhǒng jiàoyù fāngshì dōu yǒu zìjǐ de chángchu hé duǎnchu."},{"fr":"Un ami professeur pense qu'il faut avant tout éveiller la curiosité.","tgt":"一个当老师的朋友认为，最重要的是培养孩子的好奇心。","ro":"Yí ge dāng lǎoshī de péngyou rènwéi, zuì zhòngyào de shì péiyǎng háizi de hàoqíxīn."},{"fr":"Les notes ne disent pas tout d'une personne.","tgt":"分数并不能说明一个人的全部。","ro":"Fēnshù bìng bù néng shuōmíng yí ge rén de quánbù."},{"fr":"Sur ce sujet, on pourrait discuter toute la nuit.","tgt":"这个话题，我们可以聊一整夜。","ro":"Zhège huàtí, wǒmen kěyǐ liáo yì zhěng yè."}]},{"title":"Vivre loin de chez soi","phrases":[{"fr":"Mes premiers mois en Chine, la France me manquait énormément.","tgt":"刚来中国的几个月，我特别想念法国。","ro":"Gāng lái Zhōngguó de jǐ ge yuè, wǒ tèbié xiǎngniàn Fǎguó."},{"fr":"Ce qui me manquait le plus, c'était le pain et le fromage.","tgt":"我最想的是面包和奶酪。","ro":"Wǒ zuì xiǎng de shì miànbāo hé nǎilào."},{"fr":"Petit à petit, je me suis fait au rythme de vie d'ici.","tgt":"慢慢地，我习惯了这里的生活节奏。","ro":"Mànmàn de, wǒ xíguàn le zhèli de shēnghuó jiézòu."},{"fr":"Désormais, ce sont plutôt les petits pains vapeur du matin qui me manqueront.","tgt":"现在，我反而会想念早上的包子。","ro":"Xiànzài, wǒ fǎn'ér huì xiǎngniàn zǎoshang de bāozi."},{"fr":"Mes voisins sont presque devenus une deuxième famille.","tgt":"我的邻居差不多成了我的第二个家人。","ro":"Wǒ de línjū chàbuduō chéng le wǒ de dì-èr ge jiārén."},{"fr":"Vivre loin de chez moi m'a appris à voir les choses autrement.","tgt":"在国外生活，让我学会了换个角度看问题。","ro":"Zài guówài shēnghuó, ràng wǒ xuéhuì le huàn ge jiǎodù kàn wèntí."},{"fr":"En même temps, on comprend mieux sa propre culture.","tgt":"同时，也会更了解自己的文化。","ro":"Tóngshí, yě huì gèng liǎojiě zìjǐ de wénhuà."},{"fr":"Aujourd'hui, je me sens un peu chez moi des deux côtés.","tgt":"现在我觉得两边都有点儿像家。","ro":"Xiànzài wǒ juéde liǎng biān dōu yǒudiǎnr xiàng jiā."},{"fr":"Avoir deux foyers, c'est une vraie chance pour moi.","tgt":"能有两个家，真是我的幸运。","ro":"Néng yǒu liǎng ge jiā, zhēn shì wǒ de xìngyùn."},{"fr":"Où que j'aille, je garderai un morceau de la Chine dans mon cœur.","tgt":"不管以后去哪儿，我心里都会有中国的一部分。","ro":"Bùguǎn yǐhòu qù nǎr, wǒ xīn li dōu huì yǒu Zhōngguó de yí bùfen."}]},{"title":"Le moment des adieux","phrases":[{"fr":"Dans une semaine, je rentre en France.","tgt":"再过一个星期，我就要回法国了。","ro":"Zài guò yí ge xīngqī, wǒ jiù yào huí Fǎguó le."},{"fr":"Mes amis m'ont invité à dîner pour me dire au revoir.","tgt":"朋友们请我吃饭，给我送行。","ro":"Péngyoumen qǐng wǒ chī fàn, gěi wǒ sòngxíng."},{"fr":"Comme on dit, toute fête finit un jour.","tgt":"天下没有不散的筵席。","ro":"Tiānxià méiyǒu bú sàn de yánxí."},{"fr":"Promets-moi que tu viendras me voir en France.","tgt":"答应我，你一定要来法国看我。","ro":"Dāying wǒ, nǐ yídìng yào lái Fǎguó kàn wǒ."},{"fr":"On restera en contact, c'est promis.","tgt":"我们一定会保持联系的，我保证。","ro":"Wǒmen yídìng huì bǎochí liánxì de, wǒ bǎozhèng."},{"fr":"Je n'aime pas les longs discours d'adieu, alors je serai bref.","tgt":"我不喜欢说太多告别的话，就简单说几句吧。","ro":"Wǒ bù xǐhuan shuō tài duō gàobié de huà, jiù jiǎndān shuō jǐ jù ba."},{"fr":"Merci de m'avoir accueilli comme l'un des vôtres.","tgt":"谢谢你们把我当成自己人。","ro":"Xièxie nǐmen bǎ wǒ dàngchéng zìjǐrén."},{"fr":"Ce n'est pas un adieu, seulement un au revoir.","tgt":"这不是永别，只是暂时说再见。","ro":"Zhè bú shì yǒngbié, zhǐ shì zànshí shuō zàijiàn."},{"fr":"Fais bon voyage, et envoie-nous un message en arrivant !","tgt":"一路平安，到了给我们发个消息！","ro":"Yílù píng'ān, dào le gěi wǒmen fā ge xiāoxi!"},{"fr":"Prends bien soin de toi, on se reverra vite.","tgt":"多保重，我们很快会再见面的。","ro":"Duō bǎozhòng, wǒmen hěn kuài huì zài jiànmiàn de."}]},{"title":"Regard en arrière sur mon parcours en chinois","phrases":[{"fr":"Au début, je n'arrivais pas du tout à distinguer les tons.","tgt":"刚开始的时候，我根本听不出声调。","ro":"Gāng kāishǐ de shíhou, wǒ gēnběn tīng bu chū shēngdiào."},{"fr":"Je confondais sans arrêt acheter et vendre.","tgt":"我老是把“买”和“卖”搞混。","ro":"Wǒ lǎo shì bǎ \"mǎi\" hé \"mài\" gǎohùn."},{"fr":"Aujourd'hui, je peux parler de presque tout en chinois.","tgt":"现在，我几乎什么话题都能用中文聊。","ro":"Xiànzài, wǒ jīhū shénme huàtí dōu néng yòng Zhōngwén liáo."},{"fr":"Je ne m'attendais pas à faire autant de progrès.","tgt":"我没想到自己会进步这么大。","ro":"Wǒ méi xiǎngdào zìjǐ huì jìnbù zhème dà."},{"fr":"Repenser à ma toute première phrase me fait sourire.","tgt":"现在想起我学的第一句话，我就想笑。","ro":"Xiànzài xiǎngqǐ wǒ xué de dì-yī jù huà, wǒ jiù xiǎng xiào."},{"fr":"M'entraîner à voix haute pendant mes trajets m'a énormément aidé.","tgt":"在路上大声练习说话，对我帮助很大。","ro":"Zài lù shang dàshēng liànxí shuōhuà, duì wǒ bāngzhù hěn dà."},{"fr":"Chaque petite conversation réussie m'a donné confiance.","tgt":"每一次成功的小对话，都让我更有信心。","ro":"Měi yí cì chénggōng de xiǎo duìhuà, dōu ràng wǒ gèng yǒu xìnxīn."},{"fr":"Même quand je faisais des fautes, mes amis chinois m'encourageaient.","tgt":"就算我说错了，中国朋友也总是鼓励我。","ro":"Jiùsuàn wǒ shuōcuò le, Zhōngguó péngyou yě zǒngshì gǔlì wǒ."},{"fr":"Apprendre le chinois m'a ouvert la porte d'un autre monde.","tgt":"学中文给我打开了一扇通往另一个世界的门。","ro":"Xué Zhōngwén gěi wǒ dǎkāi le yí shàn tōngwǎng lìng yí ge shìjiè de mén."},{"fr":"Je suis fier du chemin fait, mais il me reste beaucoup à apprendre.","tgt":"我为自己走过的路感到骄傲，但要学的还有很多。","ro":"Wǒ wèi zìjǐ zǒuguo de lù gǎndào jiāo'ào, dàn yào xué de hái yǒu hěn duō."}]},{"title":"Fin du parcours : un dernier bilan","phrases":[{"fr":"Ce dernier module nous a fait parler de culture et de société.","tgt":"最后这个单元，我们聊了文化和社会。","ro":"Zuìhòu zhège dānyuán, wǒmen liáo le wénhuà hé shèhuì."},{"fr":"Thé, opéra, calligraphie : on sait maintenant en discuter en chinois.","tgt":"茶、京剧、书法，我们现在都能用中文聊了。","ro":"Chá, jīngjù, shūfǎ, wǒmen xiànzài dōu néng yòng Zhōngwén liáo le."},{"fr":"Les expressions en quatre syllabes et les proverbes donnent du goût à nos phrases.","tgt":"成语和俗语让我们说的话更有味道。","ro":"Chéngyǔ hé súyǔ ràng wǒmen shuō de huà gèng yǒu wèidao."},{"fr":"Nous savons aussi dire « on dirait que » et « être obligé de ».","tgt":"我们还学会了用“好像”和“不得不”。","ro":"Wǒmen hái xuéhuì le yòng \"hǎoxiàng\" hé \"bùdébù\"."},{"fr":"Depuis notre tout premier bonjour, que de chemin parcouru !","tgt":"从第一句“你好”到现在，我们走了好远的路！","ro":"Cóng dì-yī jù \"nǐ hǎo\" dào xiànzài, wǒmen zǒu le hǎo yuǎn de lù!"},{"fr":"Les trois niveaux sont maintenant terminés.","tgt":"三个级别现在全部完成了。","ro":"Sān ge jíbié xiànzài quánbù wánchéng le."},{"fr":"Le chinois ne nous est plus du tout étranger.","tgt":"中文对我们来说，已经不再陌生了。","ro":"Zhōngwén duì wǒmen lái shuō, yǐjīng bú zài mòshēng le."},{"fr":"Continuez à parler chaque jour, même quelques minutes.","tgt":"每天都要继续说，哪怕只说几分钟。","ro":"Měi tiān dōu yào jìxù shuō, nǎpà zhǐ shuō jǐ fēnzhōng."},{"fr":"Bravo d'avoir tenu jusqu'au bout, vous pouvez être fiers !","tgt":"祝贺你们坚持到了最后，你们应该感到骄傲！","ro":"Zhùhè nǐmen jiānchí dào le zuìhòu, nǐmen yīnggāi gǎndào jiāo'ào!"},{"fr":"Courage pour la suite, tout le meilleur, et rendez-vous en Chine !","tgt":"加油，祝你们以后一切顺利，中国见！","ro":"Jiāyóu, zhù nǐmen yǐhòu yíqiè shùnlì, Zhōngguó jiàn!"}]}]}]}];
